    private static int[] buildExternalDmrRfCombinedWords() {
        int[] words = COMBINED_DUAL_COUNTER_WORDS.clone();
        int replacements = 0;
        for (int index = 0; index < words.length; index++) {
            if (words[index] == 0x20003081) {
                words[index] = EXTERNAL_DMR_RF_PREP_ENTRY;
                replacements++;
            }
        }
        if (replacements != 1) {
            throw new IllegalStateException("External DMR RF helper入口替换数异常");
        }
        return words;
    }
