    /**
     * 发射前无射频基础设施验收：只验证新SRAM窗、制品上传、RF关闭桩和恢复。
     * RF准备桩绝不执行；关闭桩只允许在active gate严格为0时执行。
     */
    ProbeResult runSoftwareAmbeProductionRfInfrastructurePreflightNoRf() {
        StringBuilder report = new StringBuilder();
        InputStream input = null;
        OutputStream output = null;
        byte[] originalPrep = null;
        byte[] originalOff = null;
        byte[] originalMarker = null;
        byte[] originalGate = null;
        byte[] originalVector = null;
        boolean mutationStarted = false;
        boolean restored = false;
        boolean success = false;
        boolean rfOffActiveGateZeroTested = false;
        boolean rebootRequired = false;
        String status = "FAIL: External DMR RF基础设施无射频预检";
        append(report, "模式", "External DMR RF基础设施无射频预检");
        append(report, "RF准备桩执行", "禁止");
        append(report, "RF关闭桩执行条件", "active gate严格为0");
        append(report, "DMOPTT/HPI/data36/PTT/频道变更", "禁止");
        try {
            byte[] prep = wordsToBytes(EXTERNAL_DMR_RF_PREP_WORDS);
            byte[] off = wordsToBytes(EXTERNAL_DMR_RF_OFF_WORDS);
            if (!EXTERNAL_DMR_RF_PREP_SHA256.equals(sha256(prep))
                    || !EXTERNAL_DMR_RF_OFF_SHA256.equals(sha256(off))) {
                throw new IOException("RF桩制品哈希不匹配");
            }
            File device = new File(DEVICE_PATH);
            if (!device.canRead() || !device.canWrite()) {
                throw new IOException("串口权限不足");
            }
            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);
            String connect = query(input, output, "AT+DMOCONNECT");
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "57600握手", printable(connect));
            append(report, "57600版本", printable(version));
            if (!containsExactAsciiLine(connect, "+DMOCONNECT:0")
                    || !containsExactAsciiLine(version,
                    "+DMOGETSOFTVERSION:" + EXPECTED_MODULE_VERSION)) {
                throw new IOException("57600文本基线失败");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "隐藏memread日志启用响应",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            originalPrep = readMemoryEvidenceBytes(input, output,
                    "rf_prep_pre_round1", EXTERNAL_DMR_RF_PREP_ADDRESS,
                    prep.length, report);
            byte[] prepRound2 = readMemoryEvidenceBytes(input, output,
                    "rf_prep_pre_round2", EXTERNAL_DMR_RF_PREP_ADDRESS,
                    prep.length, report);
            originalOff = readMemoryEvidenceBytes(input, output,
                    "rf_off_pre_round1", EXTERNAL_DMR_RF_OFF_ADDRESS,
                    off.length, report);
            byte[] offRound2 = readMemoryEvidenceBytes(input, output,
                    "rf_off_pre_round2", EXTERNAL_DMR_RF_OFF_ADDRESS,
                    off.length, report);
            originalMarker = readMemoryEvidenceBytes(input, output,
                    "rf_marker_pre_round1", EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                    4, report);
            byte[] markerRound2 = readMemoryEvidenceBytes(input, output,
                    "rf_marker_pre_round2", EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                    4, report);
            originalGate = readMemoryEvidenceBytes(input, output,
                    "rf_gate_pre_round1", EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                    4, report);
            byte[] gateRound2 = readMemoryEvidenceBytes(input, output,
                    "rf_gate_pre_round2", EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                    4, report);
            originalVector = readMemoryEvidenceBytes(input, output,
                    "rf_vector_pre_round1", RAM_VECTOR_SYSTICK, 4, report);
            byte[] vectorRound2 = readMemoryEvidenceBytes(input, output,
                    "rf_vector_pre_round2", RAM_VECTOR_SYSTICK, 4, report);
            preserveRawEvidence(report, "RF准备桩测前第一轮原件",
                    "external_dmr_rf_preflight_prep_pre_round1_", originalPrep);
            preserveRawEvidence(report, "RF准备桩测前第二轮原件",
                    "external_dmr_rf_preflight_prep_pre_round2_", prepRound2);
            preserveRawEvidence(report, "RF关闭桩测前第一轮原件",
                    "external_dmr_rf_preflight_off_pre_round1_", originalOff);
            preserveRawEvidence(report, "RF关闭桩测前第二轮原件",
                    "external_dmr_rf_preflight_off_pre_round2_", offRound2);
            preserveRawEvidence(report, "RF关闭标记测前第一轮原件",
                    "external_dmr_rf_preflight_marker_pre_round1_",
                    originalMarker);
            preserveRawEvidence(report, "RF关闭标记测前第二轮原件",
                    "external_dmr_rf_preflight_marker_pre_round2_",
                    markerRound2);
            preserveRawEvidence(report, "RF active gate测前第一轮原件",
                    "external_dmr_rf_preflight_gate_pre_round1_", originalGate);
            preserveRawEvidence(report, "RF active gate测前第二轮原件",
                    "external_dmr_rf_preflight_gate_pre_round2_", gateRound2);
            preserveRawEvidence(report, "SysTick测前第一轮原件",
                    "external_dmr_rf_preflight_vector_pre_round1_",
                    originalVector);
            preserveRawEvidence(report, "SysTick测前第二轮原件",
                    "external_dmr_rf_preflight_vector_pre_round2_",
                    vectorRound2);
            if (!Arrays.equals(originalPrep, prepRound2)
                    || !Arrays.equals(originalOff, offRound2)
                    || !Arrays.equals(originalMarker, markerRound2)
                    || !Arrays.equals(originalGate, gateRound2)
                    || !Arrays.equals(originalVector, vectorRound2)) {
                throw new IOException("RF新窗双读不稳定");
            }
            if (!allZero(originalPrep) || !allZero(originalOff)
                    || !allZero(originalMarker) || !allZero(originalGate)
                    || u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("RF新窗、active gate或SysTick基线不干净");
            }

            mutationStarted = true;
            restoreWords(input, output, EXTERNAL_DMR_RF_PREP_ADDRESS, prep);
            restoreWords(input, output, EXTERNAL_DMR_RF_OFF_ADDRESS, off);
            byte[] prepUploaded = readMemoryEvidenceBytes(input, output,
                    "rf_prep_uploaded", EXTERNAL_DMR_RF_PREP_ADDRESS,
                    prep.length, report);
            byte[] offUploaded = readMemoryEvidenceBytes(input, output,
                    "rf_off_uploaded", EXTERNAL_DMR_RF_OFF_ADDRESS,
                    off.length, report);
            preserveRawEvidence(report, "RF准备桩上传回读",
                    "external_dmr_rf_preflight_prep_uploaded_", prepUploaded);
            preserveRawEvidence(report, "RF关闭桩上传回读",
                    "external_dmr_rf_preflight_off_uploaded_", offUploaded);
            if (!Arrays.equals(prep, prepUploaded)
                    || !Arrays.equals(off, offUploaded)) {
                throw new IOException("RF桩上传逐字回读不一致");
            }
            byte[] gateBeforeOff = readMemoryEvidenceBytes(input, output,
                    "rf_gate_before_off", EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                    4, report);
            preserveRawEvidence(report, "关闭桩执行前active gate原件",
                    "external_dmr_rf_preflight_gate_before_off_",
                    gateBeforeOff);
            if (u32le(gateBeforeOff, 0) != 0) {
                throw new IOException("关闭桩无射频执行前active gate不是0");
            }
            writeMemoryWord(input, output,
                    EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    EXTERNAL_DMR_RF_OFF_ENTRY);
            SystemClock.sleep(100);
            byte[] markerAfter = readMemoryEvidenceBytes(input, output,
                    "rf_marker_after_off", EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                    4, report);
            byte[] gateAfter = readMemoryEvidenceBytes(input, output,
                    "rf_gate_after_off", EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                    4, report);
            byte[] vectorAfter = readMemoryEvidenceBytes(input, output,
                    "rf_vector_after_off", RAM_VECTOR_SYSTICK, 4, report);
            preserveRawEvidence(report, "关闭桩无射频执行后标记",
                    "external_dmr_rf_preflight_marker_after_", markerAfter);
            preserveRawEvidence(report, "关闭桩无射频执行后active gate",
                    "external_dmr_rf_preflight_gate_after_", gateAfter);
            preserveRawEvidence(report, "关闭桩无射频执行后SysTick",
                    "external_dmr_rf_preflight_vector_after_", vectorAfter);
            if (u32le(markerAfter, 0) != EXTERNAL_DMR_RF_OFF_MARKER
                    || u32le(gateAfter, 0) != 0
                    || u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("关闭桩无射频执行闭环失败");
            }
            rfOffActiveGateZeroTested = true;

            restoreWords(input, output, EXTERNAL_DMR_RF_PREP_ADDRESS,
                    originalPrep);
            restoreWords(input, output, EXTERNAL_DMR_RF_OFF_ADDRESS,
                    originalOff);
            restoreWords(input, output, EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                    originalMarker);
            restoreWords(input, output, EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                    originalGate);
            byte[] prepRestored = readMemoryEvidenceBytes(input, output,
                    "rf_prep_restored", EXTERNAL_DMR_RF_PREP_ADDRESS,
                    originalPrep.length, report);
            byte[] offRestored = readMemoryEvidenceBytes(input, output,
                    "rf_off_restored", EXTERNAL_DMR_RF_OFF_ADDRESS,
                    originalOff.length, report);
            byte[] markerRestored = readMemoryEvidenceBytes(input, output,
                    "rf_marker_restored", EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                    4, report);
            byte[] gateRestored = readMemoryEvidenceBytes(input, output,
                    "rf_gate_restored", EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                    4, report);
            byte[] vectorRestored = readMemoryEvidenceBytes(input, output,
                    "rf_vector_restored", RAM_VECTOR_SYSTICK, 4, report);
            preserveRawEvidence(report, "RF准备桩恢复回读",
                    "external_dmr_rf_preflight_prep_restored_", prepRestored);
            preserveRawEvidence(report, "RF关闭桩恢复回读",
                    "external_dmr_rf_preflight_off_restored_", offRestored);
            preserveRawEvidence(report, "RF关闭标记恢复回读",
                    "external_dmr_rf_preflight_marker_restored_", markerRestored);
            preserveRawEvidence(report, "RF active gate恢复回读",
                    "external_dmr_rf_preflight_gate_restored_", gateRestored);
            preserveRawEvidence(report, "SysTick恢复回读",
                    "external_dmr_rf_preflight_vector_restored_",
                    vectorRestored);
            restored = Arrays.equals(originalPrep, prepRestored)
                    && Arrays.equals(originalOff, offRestored)
                    && Arrays.equals(originalMarker, markerRestored)
                    && Arrays.equals(originalGate, gateRestored)
                    && Arrays.equals(originalVector, vectorRestored);
            if (!restored) {
                throw new IOException("RF新窗恢复逐字不一致");
            }
            mutationStarted = false;
            success = true;
            status = "PASS: RF准备桩未执行；关闭桩在active gate=0下闭环；"
                    + "新SRAM窗逐字恢复；全程无DMOPTT/HPI/data36/射频";
        } catch (Throwable error) {
            append(report, "错误", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            status = "FAIL: External DMR RF基础设施无射频预检 "
                    + error.getMessage();
        } finally {
            if (mutationStarted && input != null && output != null
                    && originalPrep != null && originalOff != null
                    && originalMarker != null && originalGate != null
                    && originalVector != null) {
                try {
                    writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                            u32le(originalVector, 0));
                    restoreWords(input, output, EXTERNAL_DMR_RF_PREP_ADDRESS,
                            originalPrep);
                    restoreWords(input, output, EXTERNAL_DMR_RF_OFF_ADDRESS,
                            originalOff);
                    restoreWords(input, output,
                            EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, originalMarker);
                    restoreWords(input, output,
                            EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, originalGate);
                    byte[] emergencyPrep = readMemoryEvidenceBytes(input,
                            output, "rf_emergency_prep_restored",
                            EXTERNAL_DMR_RF_PREP_ADDRESS, originalPrep.length,
                            report);
                    byte[] emergencyOff = readMemoryEvidenceBytes(input,
                            output, "rf_emergency_off_restored",
                            EXTERNAL_DMR_RF_OFF_ADDRESS, originalOff.length,
                            report);
                    byte[] emergencyMarker = readMemoryEvidenceBytes(input,
                            output, "rf_emergency_marker_restored",
                            EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4, report);
                    byte[] emergencyGate = readMemoryEvidenceBytes(input,
                            output, "rf_emergency_gate_restored",
                            EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4, report);
                    byte[] emergencyVector = readMemoryEvidenceBytes(input,
                            output, "rf_emergency_vector_restored",
                            RAM_VECTOR_SYSTICK, 4, report);
                    preserveRawEvidence(report, "异常恢复RF准备桩回读",
                            "external_dmr_rf_preflight_emergency_prep_restored_",
                            emergencyPrep);
                    preserveRawEvidence(report, "异常恢复RF关闭桩回读",
                            "external_dmr_rf_preflight_emergency_off_restored_",
                            emergencyOff);
                    preserveRawEvidence(report, "异常恢复RF关闭标记回读",
                            "external_dmr_rf_preflight_emergency_marker_restored_",
                            emergencyMarker);
                    preserveRawEvidence(report, "异常恢复RF active gate回读",
                            "external_dmr_rf_preflight_emergency_gate_restored_",
                            emergencyGate);
                    preserveRawEvidence(report, "异常恢复SysTick回读",
                            "external_dmr_rf_preflight_emergency_vector_restored_",
                            emergencyVector);
                    restored = Arrays.equals(originalPrep, emergencyPrep)
                            && Arrays.equals(originalOff, emergencyOff)
                            && Arrays.equals(originalMarker, emergencyMarker)
                            && Arrays.equals(originalGate, emergencyGate)
                            && Arrays.equals(originalVector, emergencyVector);
                } catch (Throwable restoreError) {
                    restored = false;
                    append(report, "finally恢复失败", restoreError.getMessage());
                }
            }
            rebootRequired = mutationStarted && !restored;
            synchronized (lock) {
                closeLocked(report);
            }
            writeAtomicProbeSessionResult(success && restored, rebootRequired,
                    status, "TEXT_CONFIRMED", restored, true,
                    "rf_prepare_executed=false\n"
                            + "rf_off_active_gate_zero_tested="
                            + rfOffActiveGateZeroTested + "\n"
                            + "rf_window_restored=" + restored + "\n"
                            + "dmoptt_forbidden=true\n"
                            + "hpi_written=false\n"
                            + "data36_written=false\n"
                            + "rf_command_count=0\n");
        }
        return finish(success && restored, report, status);
    }

    private ProbeResult blockedLegacySoftwareAmbeRfMode(String mode) {
        StringBuilder report = new StringBuilder();
        append(report, "模式", mode);
        append(report, "串口已打开", false);
        append(report, "射频命令数", 0);
        append(report, "阻断原因",
                "v3.82已证明普通AT+DMOPTT麦克风路径与外部编码DMR会话冲突；"
                        + "必须先实现生产同构的非麦克风外部编码发射入口");
        return finish(false, report,
                "BLOCKED: 已知会进入普通麦克风PTT的旧射频入口已冻结");
    }

