    /**
     * v1.77/v1.84 阶段 A：只读转储 combined 临时窗 / 会话标量 / 工作队列。
     * <b>禁止</b> 清零、arm、setup、VLC、data36、bridge、频道变更。
     * 将完整原始字节落盘，并按 clean-zero / exact-known-artifact / unknown 分类。
     * 同时只读转储禁止区 0x20001700 与生产 config 头，供对照（不写）。
     */
    ProbeResult runExternalDmrCombinedWindowReadonlyDump57600() {
        return runExternalDmrCombinedWindowReadonlyDump57600(false);
    }

    private ProbeResult runExternalDmrCombinedWindowReadonlyDump57600(
            boolean auditedZeroAfterDump) {
        if (auditedZeroAfterDump) {
            return runExternalDmrAuditedZeroCombinedWindow57600();
        }
        StringBuilder report = new StringBuilder();
        InputStream input = null;
        OutputStream output = null;
        boolean success = false;
        boolean rebootRequired = false;
        String status = "FAIL: combined 窗只读转储";
        String residualClass = "unknown";
        append(report, "Mode", auditedZeroAfterDump
                ? "External DMR combined 窗 dump后可审计清零 @57600（无arm/无VLC）"
                : "External DMR combined 窗只读转储 @57600（无写/无bridge/无VLC）");
        append(report, "Probe build", probeBuildName());
        append(report, "Device", DEVICE_PATH);
        append(report, "Baud", BAUD_RATE);
        append(report, "HPI/WORK_MODE/VLC/data36/PTT/GPIO", "禁止");
        append(report, "force-zero without dump", "禁止");
        append(report, "audited zero after dump", auditedZeroAfterDump);
        append(report, "Combined dual-counter expected SHA-256",
                COMBINED_DUAL_COUNTER_SHA256);
        try {
            byte[] combinedHandler = wordsToBytes(COMBINED_DUAL_COUNTER_WORDS);
            if (!COMBINED_DUAL_COUNTER_SHA256.equals(sha256(combinedHandler))) {
                throw new IOException("Embedded combined dual-counter hash mismatch");
            }
            File device = new File(DEVICE_PATH);
            if (!device.canRead() || !device.canWrite()) {
                throw new IOException("Serial device permission denied");
            }
            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);

            String connect = query(input, output, "AT+DMOCONNECT");
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Handshake @57600", printable(connect));
            append(report, "Version @57600", printable(version));
            if (!containsExactAsciiLine(connect, "+DMOCONNECT:0")
                    || !containsExactAsciiLine(version,
                    "+DMOGETSOFTVERSION:" + EXPECTED_MODULE_VERSION)) {
                throw new IOException("Text baseline failed @57600");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            // v1.78：连续两轮只读，要求代码/元数据/队列/标量逐字节一致后再分类。
            byte[] code = null;
            byte[] prepMarker = null;
            byte[] prepCounter = null;
            byte[] absCounter = null;
            byte[] exitMarker = null;
            byte[] prepPhase = null;
            byte[] prepCursor = null;
            byte[] bridgeFlag = null;
            byte[] systick = null;
            byte[] dataGate = null;
            byte[] sessionState = null;
            byte[] ptrA = null;
            byte[] ptrB = null;
            byte[] flag1c = null;
            byte[] count = null;
            byte[] queueA = null;
            byte[] queueB = null;
            long stamp = SystemClock.elapsedRealtime();
            for (int round = 1; round <= 2; round++) {
                byte[] codeR = readMemory(input, output,
                        COMBINED_DUAL_COUNTER_CODE_ADDRESS, combinedHandler.length);
                byte[] prepMarkerR = readMemory(input, output,
                        COMBINED_PREP_MARKER_ADDRESS, 4);
                byte[] prepCounterR = readMemory(input, output,
                        COMBINED_PREP_COUNTER_ADDRESS, 4);
                byte[] absCounterR = readMemory(input, output,
                        COMBINED_ABS_COUNTER_ADDRESS, 4);
                byte[] exitMarkerR = readMemory(input, output,
                        COMBINED_EXIT_MARKER_ADDRESS, 4);
                byte[] prepPhaseR = readMemory(input, output,
                        COMBINED_PREP_PHASE_ADDRESS, 4);
                byte[] prepCursorR = readMemory(input, output,
                        COMBINED_PREP_CURSOR_ADDRESS, 4);
                byte[] bridgeFlagR = readMemory(input, output,
                        UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
                byte[] systickR = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
                byte[] dataGateR = readMemory(input, output,
                        EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
                byte[] sessionStateR = readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
                byte[] ptrAR = readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
                byte[] ptrBR = readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
                byte[] flag1cR = readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
                byte[] countR = readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
                byte[] queueAR = readMemory(input, output,
                        EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                        EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH);
                byte[] queueBR = readMemory(input, output,
                        EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                        EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH);
                persistResidualDump(report,
                        "r" + round + "_combined_code_" + stamp, codeR,
                        COMBINED_DUAL_COUNTER_CODE_ADDRESS);
                persistResidualDump(report,
                        "r" + round + "_queue_a_" + stamp, queueAR,
                        EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS);
                persistResidualDump(report,
                        "r" + round + "_queue_b_" + stamp, queueBR,
                        EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS);
                persistResidualDump(report,
                        "r" + round + "_meta_bundle_" + stamp,
                        concatBytes(prepMarkerR, prepCounterR, absCounterR,
                                exitMarkerR, prepPhaseR, prepCursorR),
                        COMBINED_PREP_MARKER_ADDRESS);
                append(report, "round" + round + " code SHA-256", sha256(codeR));
                append(report, "round" + round + " queueA SHA-256", sha256(queueAR));
                append(report, "round" + round + " queueB SHA-256", sha256(queueBR));
                if (round == 1) {
                    code = codeR;
                    prepMarker = prepMarkerR;
                    prepCounter = prepCounterR;
                    absCounter = absCounterR;
                    exitMarker = exitMarkerR;
                    prepPhase = prepPhaseR;
                    prepCursor = prepCursorR;
                    bridgeFlag = bridgeFlagR;
                    systick = systickR;
                    dataGate = dataGateR;
                    sessionState = sessionStateR;
                    ptrA = ptrAR;
                    ptrB = ptrBR;
                    flag1c = flag1cR;
                    count = countR;
                    queueA = queueAR;
                    queueB = queueBR;
                } else {
                    if (!Arrays.equals(code, codeR)
                            || !Arrays.equals(prepMarker, prepMarkerR)
                            || !Arrays.equals(prepCounter, prepCounterR)
                            || !Arrays.equals(absCounter, absCounterR)
                            || !Arrays.equals(exitMarker, exitMarkerR)
                            || !Arrays.equals(prepPhase, prepPhaseR)
                            || !Arrays.equals(prepCursor, prepCursorR)
                            || !Arrays.equals(bridgeFlag, bridgeFlagR)
                            || !Arrays.equals(systick, systickR)
                            || !Arrays.equals(dataGate, dataGateR)
                            || !Arrays.equals(sessionState, sessionStateR)
                            || !Arrays.equals(ptrA, ptrAR)
                            || !Arrays.equals(ptrB, ptrBR)
                            || !Arrays.equals(flag1c, flag1cR)
                            || !Arrays.equals(count, countR)
                            || !Arrays.equals(queueA, queueAR)
                            || !Arrays.equals(queueB, queueBR)) {
                        throw new IOException(
                                "双轮只读不一致；残留不稳定，禁止分类为恢复基线");
                    }
                    append(report, "dual-read stable", true);
                    Log.i(TAG, "READONLY_RESIDUAL dual-read stable");
                }
            }
            // 稳定基线再落一份 canonical 文件名，便于宿主 pull 与台账引用
            persistResidualDump(report, "combined_code_" + stamp, code,
                    COMBINED_DUAL_COUNTER_CODE_ADDRESS);
            persistResidualDump(report, "combined_meta_prep_marker_" + stamp,
                    prepMarker, COMBINED_PREP_MARKER_ADDRESS);
            persistResidualDump(report, "combined_meta_prep_counter_" + stamp,
                    prepCounter, COMBINED_PREP_COUNTER_ADDRESS);
            persistResidualDump(report, "combined_meta_abs_counter_" + stamp,
                    absCounter, COMBINED_ABS_COUNTER_ADDRESS);
            persistResidualDump(report, "combined_meta_exit_marker_" + stamp,
                    exitMarker, COMBINED_EXIT_MARKER_ADDRESS);
            persistResidualDump(report, "combined_meta_prep_phase_" + stamp,
                    prepPhase, COMBINED_PREP_PHASE_ADDRESS);
            persistResidualDump(report, "combined_meta_prep_cursor_" + stamp,
                    prepCursor, COMBINED_PREP_CURSOR_ADDRESS);
            persistResidualDump(report, "queue_a_" + stamp, queueA,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS);
            persistResidualDump(report, "queue_b_" + stamp, queueB,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS);

            append(report, "bridge_flag", bridgeFlag[0] & 0xff);
            append(report, "systick_vector",
                    String.format(Locale.US, "0x%08x", u32le(systick, 0)));
            append(report, "dataGate", dataGate[0] & 0xff);
            append(report, "sessionState", sessionState[0] & 0xff);
            append(report, "ptrA",
                    String.format(Locale.US, "0x%08x", u32le(ptrA, 0)));
            append(report, "ptrB",
                    String.format(Locale.US, "0x%08x", u32le(ptrB, 0)));
            append(report, "flag1c", flag1c[0] & 0xff);
            append(report, "count", u32le(count, 0));
            append(report, "prep_marker_u32",
                    String.format(Locale.US, "0x%08x", u32le(prepMarker, 0)));
            append(report, "prep_counter_u32", u32le(prepCounter, 0));
            append(report, "abs_counter_u32", u32le(absCounter, 0));
            append(report, "exit_marker_u32",
                    String.format(Locale.US, "0x%08x", u32le(exitMarker, 0)));
            append(report, "prep_phase_u32", u32le(prepPhase, 0));
            append(report, "prep_cursor_u32", u32le(prepCursor, 0));

            int codeNz = firstNonZeroOffset(code);
            int metaNz = firstNonZeroOffset(concatBytes(
                    prepMarker, prepCounter, absCounter, exitMarker,
                    prepPhase, prepCursor));
            int queueANz = firstNonZeroOffset(queueA);
            int queueBNz = firstNonZeroOffset(queueB);
            append(report, "code first_nonzero_offset",
                    codeNz < 0 ? "none" : codeNz);
            if (codeNz >= 0) {
                append(report, "code first_nonzero_addr",
                        String.format(Locale.US, "0x%08x",
                                COMBINED_DUAL_COUNTER_CODE_ADDRESS + codeNz));
                append(report, "code first_nonzero_value",
                        String.format(Locale.US, "0x%02x", code[codeNz] & 0xff));
            }
            append(report, "meta first_nonzero_offset",
                    metaNz < 0 ? "none" : metaNz);
            append(report, "queueA first_nonzero_offset",
                    queueANz < 0 ? "none" : queueANz);
            append(report, "queueB first_nonzero_offset",
                    queueBNz < 0 ? "none" : queueBNz);

            boolean codeClean = allZero(code);
            boolean codeKnown = Arrays.equals(code, combinedHandler);
            boolean metaClean = allZero(prepMarker) && allZero(prepCounter)
                    && allZero(absCounter) && allZero(exitMarker)
                    && allZero(prepPhase) && allZero(prepCursor);
            boolean queuesClean = allZero(queueA) && allZero(queueB);
            boolean bridgeIdle = (bridgeFlag[0] & 0xff) == 0
                    && u32le(systick, 0) == ORIGINAL_SYSTICK_HANDLER;

            if (codeClean && metaClean) {
                residualClass = "clean-zero";
            } else if (codeKnown && metaClean) {
                residualClass = "exact-known-artifact";
            } else {
                residualClass = "unknown";
            }
            append(report, "residual_class", residualClass);
            append(report, "queues_all_zero", queuesClean);
            append(report, "bridge_idle_baseline", bridgeIdle);
            Log.i(TAG, "READONLY_RESIDUAL class=" + residualClass
                    + " codeSha=" + sha256(code)
                    + " queuesZero=" + queuesClean
                    + " bridgeIdle=" + bridgeIdle);

            // 只读成功：分类完成且文本基线健康。unknown 仍算 PASS（取证成功），
            // 但明确禁止后续 arm，直到人工/下一阶段可审计清理。
            success = true;
            if ("unknown".equals(residualClass)) {
                status = "PASS: 只读取证完成；residual=unknown；禁止 arm/force-zero";
            } else if ("exact-known-artifact".equals(residualClass)) {
                status = "PASS: 只读取证完成；residual=exact-known-artifact；"
                        + "允许后续可审计覆盖";
            } else {
                status = "PASS: 只读取证完成；residual=clean-zero；可进入严格隔离";
            }
            if (!bridgeIdle) {
                success = false;
                rebootRequired = true;
                status = "FAIL: bridge/SysTick 非空闲基线；要求 reboot 后重取证";
            }

            // v1.84：永久禁止 dump 后清零分支。
            if (success && auditedZeroAfterDump) {
                throw new IOException("audited-zero 已永久禁用");
            }
            // 额外只读：禁止区与生产 config 头（永不写入）
            if (success && input != null && output != null) {
                try {
                    byte[] forbidden = readMemory(input, output,
                            FORBIDDEN_PROD_WINDOW_BEGIN, 0x150);
                    byte[] prodCfg = readMemory(input, output,
                            PROD_CONFIG_STRUCT_ADDRESS, 64);
                    persistResidualDump(report,
                            "readonly_forbidden_01700_" + stamp, forbidden,
                            FORBIDDEN_PROD_WINDOW_BEGIN);
                    persistResidualDump(report,
                            "readonly_prod_config64_" + stamp, prodCfg,
                            PROD_CONFIG_STRUCT_ADDRESS);
                    append(report, "forbidden_01700 SHA-256", sha256(forbidden));
                    append(report, "prod_config64 SHA-256", sha256(prodCfg));
                } catch (Throwable roErr) {
                    append(report, "forbidden/prod readonly error",
                            roErr.getMessage());
                }
            }
        } catch (Throwable error) {
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            success = false;
            status = "FAIL: 只读/可审计清零异常 " + error.getMessage();
            Log.e(TAG, "readonly residual dump failed", error);
        } finally {
            if (input != null && output != null) {
                try {
                    disableLogLevel(input, output, report);
                } catch (Throwable logError) {
                    append(report, "Log restore error", logError.getMessage());
                }
            }
            close();
            writeAtomicProbeSessionResult(success, rebootRequired, status,
                    "TEXT_CONFIRMED", true, true);
            append(report, "residual_class_final", residualClass);
        }
        return finish(success, report, status);
    }

    /**
     * 步骤4：在完整前序+五 VLC 之后，仅下发 1 个步骤2冻结的 44 字节 data36，
     * 并以 vendor 短 credit（边界完整、body 首字节 0/1）作为模块响应格式门。
     * <p>
     * {@code OutputStream.write()}成功不得单独构成PASS；credit语义仅证明
     * 已确认的短响应形状，不证明射频注入或 AMBE 可听成功。
     */
    ProbeResult runExternalDmrOneData36CreditNoRfProof() {
        return executeExternalDmrVlcSessionNoRf(true, true, false, false,
                false);
    }

    private ProbeResult runExternalDmrGeneratedData36LowPowerProof(
            byte[] generatedPlain36) {
        return executeExternalDmrVlcSessionNoRf(true, true, false, false,
                false, null, generatedPlain36);
    }

    /**
     * v2.18：不进入 raw bridge、不发 HPI 请求，只由 SysTick 有界采样
     * GPIOF IDR bit10（HOBIB），完成后自动恢复生产 SysTick 向量。
     */
    ProbeResult runHobibObserverNoHpiNoRf() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalCode = null;
        byte[] originalMetadata = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        boolean stateChanged = false;
        boolean sramRestored = false;
        boolean controlRestored = false;
        boolean rebootRequired = false;
        boolean success = false;
        String status = "v2.18 HOBIB观察未完成";
        int initialLevel = -1;
        int finalLevel = -1;
        long sampleCount = 0;
        long highCount = 0;
        long lowCount = 0;
        long transitionCount = 0;
        int firstLevel = -1;
        int lastLevel = -1;
        long initialTicks = 0;

        append(report, "模式", "v2.18 HOBIB无HPI无射频有界观察");
        append(report, "探针构建", probeBuildName());
        append(report, "串口", "57600文本面");
        append(report, "唯一变量", "SysTick读取GPIOF IDR bit10并累计统计");
        append(report, "HPI请求", "禁止，实际计数0");
        append(report, "raw bridge", "禁止，bridge flag始终要求为0");
        append(report, "PCM/data36/WORK_MODE/PTT/PA/射频", "全部禁止");
        phase("PREFLIGHT", "检查基线", "无HPI、无射频");
        if (!device.canRead() || !device.canWrite()) {
            status = "串口设备权限不足";
            writeAtomicHobibObserverResult(false, false, status, false, false,
                    initialLevel, finalLevel, sampleCount, highCount, lowCount,
                    transitionCount, firstLevel, lastLevel, initialTicks);
            return finish(false, report, status);
        }

        try {
            byte[] handler = wordsToBytes(HOBIB_OBSERVER_HANDLER_WORDS);
            validateHobibObserverHandler(handler);
            append(report, "观察器字节数", handler.length);
            append(report, "观察器SHA-256", sha256(handler));

            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            append(report, "启动字节", printable(readResponse(input,
                    STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "模块连接", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("模块连接失败");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "模块版本", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("模块版本不符");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            byte[] printResponse = readBytes(input, SHORT_READ_TIMEOUT_MS);
            preserveRawEvidence(report, "日志开启响应",
                    "h13_hobib_print1_", printResponse);

            MemoryReadEvidence flagRound1 = readMemoryEvidence(input, output,
                    "hobib_pre_bridge_r1", UART_HPI_BRIDGE_FLAG_ADDRESS, 1,
                    report);
            MemoryReadEvidence vectorRound1 = readMemoryEvidence(input, output,
                    "hobib_pre_systick_r1", RAM_VECTOR_SYSTICK, 4, report);
            MemoryReadEvidence codeRound1 = readMemoryEvidence(input, output,
                    "hobib_pre_code_r1", HOBIB_OBSERVER_CODE_ADDRESS,
                    HOBIB_OBSERVER_CODE_LENGTH, report);
            MemoryReadEvidence metadataRound1 = readMemoryEvidence(input, output,
                    "hobib_pre_metadata_r1", HOBIB_OBSERVER_METADATA_ADDRESS,
                    HOBIB_OBSERVER_METADATA_LENGTH, report);
            SystemClock.sleep(120);
            MemoryReadEvidence flagRound2 = readMemoryEvidence(input, output,
                    "hobib_pre_bridge_r2", UART_HPI_BRIDGE_FLAG_ADDRESS, 1,
                    report);
            MemoryReadEvidence vectorRound2 = readMemoryEvidence(input, output,
                    "hobib_pre_systick_r2", RAM_VECTOR_SYSTICK, 4, report);
            MemoryReadEvidence codeRound2 = readMemoryEvidence(input, output,
                    "hobib_pre_code_r2", HOBIB_OBSERVER_CODE_ADDRESS,
                    HOBIB_OBSERVER_CODE_LENGTH, report);
            MemoryReadEvidence metadataRound2 = readMemoryEvidence(input, output,
                    "hobib_pre_metadata_r2", HOBIB_OBSERVER_METADATA_ADDRESS,
                    HOBIB_OBSERVER_METADATA_LENGTH, report);
            requireHobibStablePreimage(flagRound1.parsed, flagRound2.parsed,
                    vectorRound1.parsed, vectorRound2.parsed,
                    codeRound1.parsed, codeRound2.parsed,
                    metadataRound1.parsed, metadataRound2.parsed);
            originalFlag = flagRound2.parsed.clone();
            originalVector = vectorRound2.parsed.clone();
            originalCode = codeRound2.parsed.clone();
            originalMetadata = metadataRound2.parsed.clone();

            MemoryReadEvidence gpioBefore = readMemoryEvidence(input, output,
                    "hobib_gpiof_idr_before", GPIOF_IDR_ADDRESS, 4, report);
            initialLevel = hobibLevel(gpioBefore.parsed);
            append(report, "HOBIB初始电平", initialLevel);

            byte[] tickBefore = readMemoryEvidence(input, output,
                    "hobib_tick_before", MCU_TICK_COUNTER_ADDRESS, 4,
                    report).parsed;
            long tickStart = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickAfter = readMemoryEvidence(input, output,
                    "hobib_tick_after", MCU_TICK_COUNTER_ADDRESS, 4,
                    report).parsed;
            long tickElapsed = SystemClock.elapsedRealtime() - tickStart;
            long tickDelta = ((u32le(tickAfter, 0) & 0xffffffffL)
                    - (u32le(tickBefore, 0) & 0xffffffffL)) & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            if (tickRateHz < 10.0 || tickRateHz > 100000.0) {
                throw new IOException("MCU tick频率不可信");
            }
            initialTicks = Math.round(tickRateHz * HOBIB_OBSERVER_TARGET_MS
                    / 1000.0);
            if (initialTicks < 10 || initialTicks > 500000) {
                throw new IOException("HOBIB观察tick数越界");
            }
            append(report, "实测tick频率", String.format(Locale.US, "%.2f",
                    tickRateHz));
            append(report, "观察初始tick数", initialTicks);

            for (int offset = 0; offset < handler.length; offset += 4) {
                writeMemoryWord(input, output,
                        HOBIB_OBSERVER_CODE_ADDRESS + offset,
                        u32le(handler, offset));
            }
            stateChanged = true;
            byte[] uploaded = readMemoryEvidence(input, output,
                    "hobib_uploaded_code", HOBIB_OBSERVER_CODE_ADDRESS,
                    handler.length, report).parsed;
            if (!Arrays.equals(handler, uploaded)) {
                throw new IOException("HOBIB观察器写后回读不符");
            }
            writeMemoryWord(input, output, HOBIB_OBSERVER_COUNTER_ADDRESS,
                    (int) initialTicks);
            writeMemoryWord(input, output, HOBIB_OBSERVER_SAMPLE_COUNT_ADDRESS, 0);
            writeMemoryWord(input, output, HOBIB_OBSERVER_HIGH_COUNT_ADDRESS, 0);
            writeMemoryWord(input, output, HOBIB_OBSERVER_LOW_COUNT_ADDRESS, 0);
            writeMemoryWord(input, output,
                    HOBIB_OBSERVER_TRANSITION_COUNT_ADDRESS, 0);
            writeMemoryWord(input, output, HOBIB_OBSERVER_FIRST_LEVEL_ADDRESS,
                    HOBIB_OBSERVER_UNSET_LEVEL);
            writeMemoryWord(input, output, HOBIB_OBSERVER_LAST_LEVEL_ADDRESS,
                    HOBIB_OBSERVER_UNSET_LEVEL);
            writeMemoryWord(input, output, HOBIB_OBSERVER_MARKER_ADDRESS, 0);
            byte[] prepared = readMemoryEvidence(input, output,
                    "hobib_prepared_window", HOBIB_OBSERVER_CODE_ADDRESS,
                    HOBIB_OBSERVER_CODE_LENGTH + HOBIB_OBSERVER_METADATA_LENGTH,
                    report).parsed;
            if (!Arrays.equals(handler, Arrays.copyOf(prepared, handler.length))
                    || u32le(prepared, HOBIB_OBSERVER_CODE_LENGTH) != initialTicks) {
                throw new IOException("HOBIB观察器武装前制品门失败");
            }
            if ((readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1)[0] & 0xff) != 0) {
                throw new IOException("武装前bridge flag不为0");
            }

            phase("OBSERVING", "观察HOBIB", "不发送HPI，不进入bridge");
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    HOBIB_OBSERVER_ENTRY);
            byte[] vectorArmed = readMemoryEvidence(input, output,
                    "hobib_vector_armed", RAM_VECTOR_SYSTICK, 4, report).parsed;
            if (u32le(vectorArmed, 0) != HOBIB_OBSERVER_ENTRY) {
                throw new IOException("SysTick观察器武装失败");
            }
            SystemClock.sleep(HOBIB_OBSERVER_TARGET_MS
                    + HOBIB_OBSERVER_MARGIN_MS);

            byte[] postMetadata = readMemoryEvidence(input, output,
                    "hobib_completed_metadata", HOBIB_OBSERVER_METADATA_ADDRESS,
                    HOBIB_OBSERVER_METADATA_LENGTH, report).parsed;
            byte[] postCode = readMemoryEvidence(input, output,
                    "hobib_completed_code", HOBIB_OBSERVER_CODE_ADDRESS,
                    HOBIB_OBSERVER_CODE_LENGTH, report).parsed;
            byte[] postVector = readMemoryEvidence(input, output,
                    "hobib_completed_systick", RAM_VECTOR_SYSTICK, 4,
                    report).parsed;
            byte[] postFlag = readMemoryEvidence(input, output,
                    "hobib_completed_bridge", UART_HPI_BRIDGE_FLAG_ADDRESS, 1,
                    report).parsed;
            sampleCount = u32le(postMetadata, 4) & 0xffffffffL;
            highCount = u32le(postMetadata, 8) & 0xffffffffL;
            lowCount = u32le(postMetadata, 12) & 0xffffffffL;
            transitionCount = u32le(postMetadata, 16) & 0xffffffffL;
            firstLevel = u32le(postMetadata, 20);
            lastLevel = u32le(postMetadata, 24);
            validateHobibObservation(postMetadata, initialTicks,
                    u32le(postVector, 0), postFlag[0] & 0xff);
            if (!Arrays.equals(handler, postCode)) {
                throw new IOException("HOBIB观察完成后代码窗发生变化");
            }
            append(report, "采样数", sampleCount);
            append(report, "高电平样本数", highCount);
            append(report, "低电平样本数", lowCount);
            append(report, "电平变化次数", transitionCount);
            append(report, "首个采样电平", firstLevel);
            append(report, "末个采样电平", lastLevel);

            MemoryReadEvidence gpioAfter = readMemoryEvidence(input, output,
                    "hobib_gpiof_idr_after", GPIOF_IDR_ADDRESS, 4, report);
            finalLevel = hobibLevel(gpioAfter.parsed);
            append(report, "HOBIB最终电平", finalLevel);

            restoreWords(input, output, HOBIB_OBSERVER_CODE_ADDRESS, originalCode);
            restoreWords(input, output, HOBIB_OBSERVER_METADATA_ADDRESS,
                    originalMetadata);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    u32le(originalVector, 0));
            byte[] restoredCode = readMemoryEvidence(input, output,
                    "hobib_restored_code", HOBIB_OBSERVER_CODE_ADDRESS,
                    originalCode.length, report).parsed;
            byte[] restoredMetadata = readMemoryEvidence(input, output,
                    "hobib_restored_metadata", HOBIB_OBSERVER_METADATA_ADDRESS,
                    originalMetadata.length, report).parsed;
            byte[] restoredVector = readMemoryEvidence(input, output,
                    "hobib_restored_systick", RAM_VECTOR_SYSTICK, 4,
                    report).parsed;
            byte[] restoredFlag = readMemoryEvidence(input, output,
                    "hobib_restored_bridge", UART_HPI_BRIDGE_FLAG_ADDRESS, 1,
                    report).parsed;
            sramRestored = Arrays.equals(originalCode, restoredCode)
                    && Arrays.equals(originalMetadata, restoredMetadata)
                    && Arrays.equals(originalVector, restoredVector)
                    && Arrays.equals(originalFlag, restoredFlag);
            if (!sramRestored) {
                throw new IOException("临时SRAM或向量未逐字节恢复");
            }
            disableLogLevel(input, output, report);
            String connectAfter = query(input, output, "AT+DMOCONNECT");
            String versionAfter = query(input, output, "AT+DMOGETSOFTVERSION");
            controlRestored = connectAfter.contains("+DMOCONNECT:0")
                    && versionAfter.contains("+DMOGETSOFTVERSION:0.3.66");
            append(report, "恢复后模块连接", printable(connectAfter));
            append(report, "恢复后模块版本", printable(versionAfter));
            if (!controlRestored) {
                throw new IOException("恢复后文本控制面未确认");
            }
            success = true;
            status = "PASS：HOBIB有界观察和自动恢复完成";
        } catch (Throwable error) {
            Log.e(TAG, "HOBIB observer failed", error);
            append(report, "错误", error.getClass().getSimpleName() + ": "
                    + error.getMessage());
            status = "FAIL：" + (error.getMessage() == null
                    ? error.getClass().getSimpleName() : error.getMessage());
        } finally {
            if (stateChanged && !sramRestored && input != null && output != null) {
                try {
                    writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                            ORIGINAL_SYSTICK_HANDLER);
                    if (originalCode != null) {
                        restoreWords(input, output, HOBIB_OBSERVER_CODE_ADDRESS,
                                originalCode);
                    }
                    if (originalMetadata != null) {
                        restoreWords(input, output,
                                HOBIB_OBSERVER_METADATA_ADDRESS,
                                originalMetadata);
                    }
                    byte[] checkCode = readMemoryEvidence(input, output,
                            "hobib_finally_restored_code",
                            HOBIB_OBSERVER_CODE_ADDRESS,
                            originalCode.length, report).parsed;
                    byte[] checkMetadata = readMemoryEvidence(input, output,
                            "hobib_finally_restored_metadata",
                            HOBIB_OBSERVER_METADATA_ADDRESS,
                            originalMetadata.length, report).parsed;
                    byte[] checkVector = readMemoryEvidence(input, output,
                            "hobib_finally_restored_systick",
                            RAM_VECTOR_SYSTICK, 4, report).parsed;
                    byte[] checkFlag = readMemoryEvidence(input, output,
                            "hobib_finally_bridge", UART_HPI_BRIDGE_FLAG_ADDRESS,
                            1, report).parsed;
                    sramRestored = Arrays.equals(originalCode, checkCode)
                            && Arrays.equals(originalMetadata, checkMetadata)
                            && u32le(checkVector, 0) == ORIGINAL_SYSTICK_HANDLER
                            && (checkFlag[0] & 0xff) == 0;
                } catch (Throwable restoreError) {
                    append(report, "finally恢复错误", restoreError.getMessage());
                    rebootRequired = true;
                }
            }
            if (stateChanged && (!sramRestored || !controlRestored)) {
                rebootRequired = true;
            }
            writeAtomicHobibObserverResult(success, rebootRequired, status,
                    sramRestored, controlRestored, initialLevel, finalLevel,
                    sampleCount, highCount, lowCount, transitionCount,
                    firstLevel, lastLevel, initialTicks);
            close();
        }
        return finish(success, report, status);
    }

    private void writeAtomicHobibObserverResult(boolean success,
            boolean rebootRequired, String status, boolean sramRestored,
            boolean controlRestored, int initialLevel, int finalLevel,
            long sampleCount, long highCount, long lowCount,
            long transitionCount, int firstLevel, int lastLevel,
            long initialTicks) {
        String extra = "hobib_gpio=PF10\n"
                + "hobib_gpiof_idr_address=0x48000810\n"
                + "hobib_bit=10\n"
                + "hobib_initial_level=" + initialLevel + "\n"
                + "hobib_final_level=" + finalLevel + "\n"
                + "hobib_first_level=" + firstLevel + "\n"
                + "hobib_last_level=" + lastLevel + "\n"
                + "hobib_sample_count=" + sampleCount + "\n"
                + "hobib_high_count=" + highCount + "\n"
                + "hobib_low_count=" + lowCount + "\n"
                + "hobib_transition_count=" + transitionCount + "\n"
                + "hobib_initial_ticks=" + initialTicks + "\n"
                + "hobib_marker=0x44424f48\n"
                + "hpi_request_count=0\n"
                + "hpi_write_count=0\n"
                + "hpi_read_count=0\n"
                + "raw_bridge_armed=false\n"
                + "pcm_written=false\n"
                + "data36_written=false\n"
                + "work_mode_written=false\n"
                + "ptt_written=false\n"
                + "pa_written=false\n"
                + "rf_command_count=0\n"
                + "channel_mutated=false\n";
        writeAtomicProbeSessionResult(success, rebootRequired, status,
                controlRestored ? "TEXT_CONFIRMED" : "UNCERTAIN",
                sramRestored, controlRestored, extra);
    }

    static void validateHobibObserverHandler(byte[] handler) throws IOException {
        if (handler == null || handler.length != HOBIB_OBSERVER_CODE_LENGTH
                || !HOBIB_OBSERVER_HANDLER_SHA256.equals(requireSha256(handler))) {
            throw new IOException("HOBIB观察器制品哈希或长度不符");
        }
        int[] forbidden = {0x08010561, 0x0800ffc9, UART_HPI_BRIDGE_FLAG_ADDRESS};
        for (int value : forbidden) {
            byte[] literal = le32(value);
            if (containsBytes(handler, literal)) {
                throw new IOException("HOBIB观察器包含禁止HPI/bridge常量");
            }
        }
        if (!containsBytes(handler, le32(GPIOF_IDR_ADDRESS))
                || !containsBytes(handler, le32(RAM_VECTOR_SYSTICK))
                || !containsBytes(handler, le32(ORIGINAL_SYSTICK_HANDLER))
                || !containsBytes(handler, le32(HOBIB_OBSERVER_MARKER))) {
            throw new IOException("HOBIB观察器关键常量缺失");
        }
    }

    static void requireHobibStablePreimage(byte[] flag1, byte[] flag2,
            byte[] vector1, byte[] vector2, byte[] code1, byte[] code2,
            byte[] metadata1, byte[] metadata2) throws IOException {
        if (flag1 == null || flag1.length != 1 || flag2 == null
                || flag2.length != 1 || (flag1[0] & 0xff) != 0
                || !Arrays.equals(flag1, flag2)) {
            throw new IOException("bridge flag基线不稳定或非0");
        }
        if (vector1 == null || vector1.length != 4 || vector2 == null
                || vector2.length != 4 || !Arrays.equals(vector1, vector2)
                || u32le(vector1, 0) != ORIGINAL_SYSTICK_HANDLER) {
            throw new IOException("SysTick向量基线不稳定或非生产值");
        }
        if (code1 == null || code1.length != HOBIB_OBSERVER_CODE_LENGTH
                || code2 == null || !Arrays.equals(code1, code2)
                || metadata1 == null
                || metadata1.length != HOBIB_OBSERVER_METADATA_LENGTH
                || metadata2 == null || !Arrays.equals(metadata1, metadata2)) {
            throw new IOException("HOBIB临时窗两轮原像不稳定");
        }
    }

    static int hobibLevel(byte[] gpiofIdr) throws IOException {
        if (gpiofIdr == null || gpiofIdr.length != 4) {
            throw new IOException("GPIOF IDR长度不符");
        }
        return (u32le(gpiofIdr, 0) >>> HOBIB_GPIO_BIT) & 1;
    }

    static void validateHobibObservation(byte[] metadata, long initialTicks,
            int vector, int bridgeFlag) throws IOException {
        if (metadata == null || metadata.length != HOBIB_OBSERVER_METADATA_LENGTH) {
            throw new IOException("HOBIB统计区长度不符");
        }
        long remaining = u32le(metadata, 0) & 0xffffffffL;
        long samples = u32le(metadata, 4) & 0xffffffffL;
        long high = u32le(metadata, 8) & 0xffffffffL;
        long low = u32le(metadata, 12) & 0xffffffffL;
        long transitions = u32le(metadata, 16) & 0xffffffffL;
        int first = u32le(metadata, 20);
        int last = u32le(metadata, 24);
        int marker = u32le(metadata, 28);
        if (remaining != 0 || samples != initialTicks || high + low != samples
                || transitions > Math.max(0, samples - 1)
                || (first != 0 && first != 1) || (last != 0 && last != 1)
                || marker != HOBIB_OBSERVER_MARKER
                || vector != ORIGINAL_SYSTICK_HANDLER || bridgeFlag != 0) {
            throw new IOException("HOBIB观察统计、marker、向量或bridge门不符");
        }
    }

    /**
     * v2.02：在第三个实时27字节DMR单元完整到达的读取循环内，立即重组并
     * 只写出一个36字节单元；vlc1后允许一次有界接收窗，仍须在vlc2上线前
     * 完成写出，并在所有后续窗口收集唯一短credit。
     */
    ProbeResult runExternalDmrRealtimeRelayData36CreditProof() {
        return executeExternalDmrVlcSessionNoRf(false, true, false, false,
                true);
    }

    /**
     * v2.05：仍由第三个本次实时27字节单元触发，但只发送APK冻结资产unit 0。
     * 实时流只用于时机和负对照，严禁回填为发送载荷。
     */
    ProbeResult runExternalDmrFixedAssetRealtimeTriggerData36CreditProof(
            byte[] packagedAsset) {
        return executeExternalDmrVlcSessionNoRf(false, true, false, false,
                true, packagedAsset);
    }

    /**
     * 离线夹具合同（单测/离线握手）。设备路径必须用
     * {@link #createContractFromMeasuredRuntime(byte[])}。
     */
    static ExternalDmrStep0Contract createPinnedExternalDmrRuntimeContract() {
        return ExternalDmrStep0Contract.forProducer080177b0(
                13, 99, ExternalDmrStep0Contract.CALL_TYPE_GROUP,
                0, 0, true, ExternalDmrStep0Contract.OUTPUT_SLOT1,
                1, EXTERNAL_DMR_OFFLINE_FIXTURE_FLAGS[1] & 0xff,
                EXTERNAL_DMR_OFFLINE_FIXTURE_FLAGS[2] & 0xff,
                EXTERNAL_DMR_OFFLINE_FIXTURE_MI);
    }

    /**
     * 由预检实测14字节构造步骤0合同：
     * flags@0x2000040C(4) + dataGate@0x2000045C(1) + session@0x20004CCE(9)。
     * signaling0d/0e 取 flags[1]/flags[2]；VLC sessionAddress 取 session[5..8]
     *（对应 0x20004CD3..D6）。
     */
    static ExternalDmrStep0Contract createContractFromMeasuredRuntime(
            byte[] runtime14) {
        if (runtime14 == null || runtime14.length
                != EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH) {
            throw new IllegalArgumentException("实测运行快照必须为14字节");
        }
        return ExternalDmrStep0Contract.forProducer080177b0(
                13, 99, ExternalDmrStep0Contract.CALL_TYPE_GROUP,
                0, 0, true, ExternalDmrStep0Contract.OUTPUT_SLOT1,
                1, runtime14[1] & 0xff, runtime14[2] & 0xff,
                Arrays.copyOfRange(runtime14, 10, 14));
    }

    static byte[] offlineFixturePrivacyRuntime14() {
        return concatBytes(concatBytes(EXTERNAL_DMR_OFFLINE_FIXTURE_FLAGS,
                new byte[] {(byte) EXTERNAL_DMR_PRIVACY_DATA_GATE_EXPECTED}),
                EXTERNAL_DMR_OFFLINE_FIXTURE_SESSION);
    }

    /**
     * 生产 0x08024F42 在两条 9 字节 VLC 前的本地会话就绪硬门。
     * 预检 privacy-on 空闲快照 dataGate=0 时不得进入 VLC。
     */
    static boolean isExternalDmrSendSessionReady(byte[] dataGate,
            byte[] sessionState, byte[] ptrA, byte[] ptrB, byte[] flag1c,
            byte[] count, byte[] queueA, byte[] queueB) {
        return dataGate != null && dataGate.length == 1
                && (dataGate[0] & 0xff) == 1
                && sessionState != null && sessionState.length == 1
                && (sessionState[0] & 0xff) == 1
                && ptrA != null && ptrA.length == 4 && u32le(ptrA, 0) == 0
                && ptrB != null && ptrB.length == 4 && u32le(ptrB, 0) == 0
                && flag1c != null && flag1c.length == 1
                && (flag1c[0] & 0xff) == 0
                && count != null && count.length == 4 && u32le(count, 0) == 0
                && queueA != null && queueA.length == EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH
                && allZero(queueA)
                && queueB != null && queueB.length == EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH
                && allZero(queueB);
    }

    static void requireExternalDmrSendSessionReady(byte[] dataGate,
            byte[] sessionState, byte[] ptrA, byte[] ptrB, byte[] flag1c,
            byte[] count, byte[] queueA, byte[] queueB) throws IOException {
        if (!isExternalDmrSendSessionReady(dataGate, sessionState, ptrA, ptrB,
                flag1c, count, queueA, queueB)) {
            throw new IOException(
                    "生产发送会话状态未就绪（缺 0x08024F42 本地准备或回读不符）");
        }
    }

    /**
     * bridge 自动退桥并恢复临时 SRAM 后，强制重建文本面。
     * v1.61 真机：3A setup 成功后，大批量 fire-and-forget memwrite 再 memread
     * dataGate 失败；退桥后重握手可把「文本面失步」与「目标地址写坏」分开。
     */
    private void rearmTextFaceAfterBridgeExit(InputStream input,
            OutputStream output, StringBuilder report, String phaseLabel)
            throws Exception {
        append(report, phaseLabel + " text rearm",
                "print 1 + AT+DMOCONNECT + version");
        drainAvailable(input);
        writeCommand(output, LOG_ENABLE_COMMAND);
        appendRaw(report, phaseLabel + " log enable",
                readBytes(input, SHORT_READ_TIMEOUT_MS));
        String connect = query(input, output, "AT+DMOCONNECT");
        append(report, phaseLabel + " CONNECT", printable(connect));
        String version = query(input, output, "AT+DMOGETSOFTVERSION");
        append(report, phaseLabel + " version", printable(version));
        if (!containsExactAsciiLine(connect, "+DMOCONNECT:0")
                || !containsExactAsciiLine(version,
                "+DMOGETSOFTVERSION:" + EXPECTED_MODULE_VERSION)) {
            throw new IOException(phaseLabel
                    + " 文本面重握手失败（CONNECT/version）");
        }
        // 轻量 memread 探针：bridge flag 必须仍为 0
        byte[] flag = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
        append(report, phaseLabel + " bridge flag after rearm",
                flag[0] & 0xff);
        if ((flag[0] & 0xff) != 0) {
            throw new IOException(phaseLabel + " 重握手后 bridge flag 非零");
        }
    }

    /**
     * 文本面复现 0x08024F42 中 setup 与 VLC 之间的本地 RAM 准备。
     * v1.62：分步写+立即回读；队列清零按小块进行，块间探针，避免 70+ 次
     * 无校验 memwrite 拖垮文本面（v1.61 真机失败点）。
     */
    private void prepareExternalDmrSendSessionState(InputStream input,
            OutputStream output, StringBuilder report) throws Exception {
        append(report, "Send-session prep",
                "分步 memwrite+回读 复现 0x08024F42（dataGate/0x0801D744 等价/分块清队列）");

        // 阶段 A：仅 dataGate=1
        writeMemoryByte(input, output, EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
        byte[] dataGateStep = readMemory(input, output,
                EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
        if ((dataGateStep[0] & 0xff) != 1) {
            throw new IOException("阶段A dataGate 回读必须为 1，实为 "
                    + (dataGateStep[0] & 0xff));
        }
        append(report, "Send-session step A dataGate", 1);
        preserveRawEvidence(report, "Send-session dataGate stepA",
                "h13_ext_dmr_send_session_datagate_a_", dataGateStep);

        // 阶段 B：0x0801D744 前半（state=2, ptr 清零）
        writeMemoryByte(input, output, EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 2);
        writeMemoryWord(input, output, EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 0);
        writeMemoryWord(input, output, EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 0);
        byte[] stateB = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
        byte[] ptrAB = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
        byte[] ptrBB = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
        if ((stateB[0] & 0xff) != 2 || u32le(ptrAB, 0) != 0
                || u32le(ptrBB, 0) != 0) {
            throw new IOException("阶段B session 前半回读不符 state="
                    + (stateB[0] & 0xff));
        }
        append(report, "Send-session step B state", 2);

        // 阶段 C：队列 A 分块清零
        zeroSramRegionChunked(input, output, report,
                EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH, "queueA");

        // 阶段 D：state=1 / flag / count
        writeMemoryByte(input, output, EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
        writeMemoryByte(input, output, EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 0);
        writeMemoryWord(input, output, EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 0);
        byte[] stateD = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
        byte[] flagD = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
        byte[] countD = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
        if ((stateD[0] & 0xff) != 1 || (flagD[0] & 0xff) != 0
                || u32le(countD, 0) != 0) {
            throw new IOException("阶段D session 后半回读不符 state="
                    + (stateD[0] & 0xff));
        }
        append(report, "Send-session step D state", 1);

        // 阶段 E：队列 B 分块清零
        zeroSramRegionChunked(input, output, report,
                EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH, "queueB");

        // 终检：小块读队列，避免单次 memread 112/168 字节过长
        byte[] dataGate = readMemory(input, output,
                EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
        byte[] sessionState = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
        byte[] ptrA = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
        byte[] ptrB = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
        byte[] flag1c = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
        byte[] count = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
        byte[] queueA = readMemoryChunked(input, output,
                EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH, 16);
        byte[] queueB = readMemoryChunked(input, output,
                EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH, 16);
        preserveRawEvidence(report, "Send-session dataGate",
                "h13_ext_dmr_send_session_datagate_", dataGate);
        preserveRawEvidence(report, "Send-session state",
                "h13_ext_dmr_send_session_state_", sessionState);
        requireExternalDmrSendSessionReady(dataGate, sessionState, ptrA, ptrB,
                flag1c, count, queueA, queueB);
        append(report, "Send-session prep verified", true);
        append(report, "Send-session dataGate", dataGate[0] & 0xff);
        append(report, "Send-session state@0x20000410",
                sessionState[0] & 0xff);
    }

    /**
     * 工作队列基址 0x20004B56 / 0x20004BC6 为半字对齐、非 4 字节对齐。
     * v1.62 真机：dataGate@0x2000045C 分步成功后，对 0x20004B56 做 memwrite4/memread4
     * 立即失败。必须用 memwrite1 + 单字节回读，禁止 memwrite4/字回读。
     */
    private static final int SEND_SESSION_ZERO_CHUNK_BYTES = 8;

    private void zeroSramRegionChunked(InputStream input, OutputStream output,
            StringBuilder report, int address, int length, String label)
            throws Exception {
        if (length < 0) {
            throw new IllegalArgumentException("zeroSramRegionChunked length invalid");
        }
        // 显式拒绝把非对齐队列误当成字窗口
        if ((address & 3) == 0 && (length & 3) == 0) {
            append(report, "Send-session " + label + " align",
                    "word-aligned；仍用字节写以统一路径");
        } else {
            append(report, "Send-session " + label + " align",
                    String.format(Locale.US,
                            "非字对齐 addr=0x%08x len=%d → 强制 memwrite1",
                            address, length));
        }
        int chunks = 0;
        for (int offset = 0; offset < length; ) {
            int chunkLen = Math.min(SEND_SESSION_ZERO_CHUNK_BYTES, length - offset);
            int chunkAddr = address + offset;
            boolean ok = false;
            IOException last = null;
            for (int attempt = 1; attempt <= 2 && !ok; attempt++) {
                try {
                    for (int b = 0; b < chunkLen; b++) {
                        writeMemoryByte(input, output, chunkAddr + b, 0);
                    }
                    byte[] probe = readMemory(input, output, chunkAddr, 1);
                    if ((probe[0] & 0xff) != 0) {
                        throw new IOException(label + " 块@"
                                + String.format(Locale.US, "0x%08x", chunkAddr)
                                + " 首字节回读非零");
                    }
                    ok = true;
                } catch (IOException error) {
                    last = error;
                    append(report, "Send-session " + label + " chunk retry",
                            String.format(Locale.US, "addr=0x%08x attempt=%d err=%s",
                                    chunkAddr, attempt, error.getMessage()));
                    if (attempt == 1) {
                        rearmTextFaceAfterBridgeExit(input, output, report,
                                "Send-session " + label + " rearm");
                    }
                }
            }
            if (!ok) {
                throw last != null ? last
                        : new IOException(label + " 分块清零失败");
            }
            offset += chunkLen;
            chunks++;
        }
        append(report, "Send-session " + label + " zero chunks", chunks);
    }

    /** 固定External DMR频道合同为privacy-on、low，禁止任何功率覆盖。 */
    static void requirePinnedExternalDmrLowPowerChannel() throws IOException {
        String expected = "433550000,433550000,13,99,12345678,directmode,group,"
                + "slot1,slot1,on,low,8,2,2,99";
        if (!expected.equals(EXTERNAL_DMR_PRIVACY_ON_CHANNEL)
                || !SET_EXTERNAL_DMR_PRIVACY_ON_CHANNEL.equals(
                "AT+DMOSETDIGITALCH=" + expected)) {
            throw new IOException("External DMR频道合同必须固定为privacy-on、low");
        }
    }

    static byte[] externalDmrPreflightAttestationBytes(byte[] measuredRuntime14)
            throws IOException {
        requirePinnedExternalDmrLowPowerChannel();
        if (measuredRuntime14 == null || measuredRuntime14.length
                != EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH) {
            throw new IOException("预检凭证必须嵌入实测14字节运行快照");
        }
        String value = "构建=" + probeBuildName() + "\n"
                + "构建号=" + BuildConfig.VERSION_CODE + "\n"
                + "模块=" + EXPECTED_MODULE_VERSION + "\n"
                + "固件=" + EXPECTED_MODULE_FIRMWARE_SHA256 + "\n"
                + "目标频道=" + EXTERNAL_DMR_PRIVACY_ON_CHANNEL + "\n"
                + "恢复频道=" + EXPECTED_DIGITAL_CHANNEL + "\n"
                + "运行快照实测=" + hexCompact(measuredRuntime14) + "\n"
                + "运行快照SHA-256=" + requireSha256(measuredRuntime14) + "\n"
                + "结论=独立无HPI预检通过且privacy-off完整恢复；快照为本机实测\n";
        return value.getBytes(StandardCharsets.UTF_8);
    }

    private File externalDmrPreflightAttestationFile() {
        return new File(outputDirectory,
                EXTERNAL_DMR_PREFLIGHT_ATTESTATION_PREFIX
                        + probeBuildName() + ".txt");
    }

    boolean hasValidExternalDmrPreflightAttestation() {
        try {
            return loadMeasuredRuntimeFromPreflightAttestation() != null;
        } catch (Throwable error) {
            return false;
        }
    }

    /**
     * 读取同版本预检凭证中的实测14字节。无效则返回null。
     */
    byte[] loadMeasuredRuntimeFromPreflightAttestation() throws IOException {
        File file = externalDmrPreflightAttestationFile();
        if (!file.isFile() || file.length() <= 0 || file.length() > 4096) {
            return null;
        }
        return parseMeasuredRuntimeFromAttestationBytes(
                readBoundedFile(file, 4096));
    }

    static byte[] parseMeasuredRuntimeFromAttestationBytes(byte[] body)
            throws IOException {
        if (body == null || body.length == 0) {
            return null;
        }
        String text = new String(body, StandardCharsets.UTF_8);
        String build = null;
        String buildCode = null;
        String snapshotHex = null;
        String snapshotSha = null;
        String[] lines = text.replace('\r', '\n').split("\\n+");
        for (String line : lines) {
            String trimmed = line.trim();
            if (trimmed.startsWith("构建=")) {
                build = trimmed.substring("构建=".length());
            } else if (trimmed.startsWith("构建号=")) {
                buildCode = trimmed.substring("构建号=".length()).trim();
            } else if (trimmed.startsWith("运行快照实测=")) {
                snapshotHex = trimmed.substring("运行快照实测=".length())
                        .trim();
            } else if (trimmed.startsWith("运行快照SHA-256=")) {
                snapshotSha = trimmed.substring("运行快照SHA-256=".length())
                        .trim();
            }
        }
        if (build == null || !build.equals(probeBuildNameStatic())) {
            return null;
        }
        // 新凭证必须绑定 versionCode；旧凭证缺字段则拒绝（禁止改码后复用）。
        if (buildCode == null
                || !buildCode.equals(Integer.toString(BuildConfig.VERSION_CODE))) {
            return null;
        }
        byte[] measured = decodeEvenHex(snapshotHex);
        if (measured == null || measured.length
                != EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH) {
            return null;
        }
        if (snapshotSha == null
                || !snapshotSha.equalsIgnoreCase(requireSha256(measured))) {
            return null;
        }
        return measured;
    }

    /**
     * privacy预检只能约束fullprep后的六个VLC构造字段。
     * dataGate和session_state是fullprep结果，由调用处独立验证为1。
     */
    static boolean runtimeMirrorVlcFieldsMatchPreflight(
            byte[] expectedMeasuredRuntime14, byte[] runtimeMirror12) {
        if (expectedMeasuredRuntime14 == null || expectedMeasuredRuntime14.length != 14
                || runtimeMirror12 == null || runtimeMirror12.length != 12) {
            return false;
        }
        int[] preflightIndices = new int[] {1, 2, 10, 11, 12, 13};
        for (int index = 0; index < preflightIndices.length; index++) {
            if (runtimeMirror12[index]
                    != expectedMeasuredRuntime14[preflightIndices[index]]) {
                return false;
            }
        }
        return true;
    }

    private static String probeBuildNameStatic() {
        return BuildConfig.VERSION_NAME;
    }

    static byte[] decodeEvenHex(String hex) {
        if (hex == null) {
            return null;
        }
        String clean = hex.trim().replace(" ", "");
        if (clean.length() == 0 || (clean.length() & 1) != 0) {
            return null;
        }
        byte[] out = new byte[clean.length() / 2];
        for (int index = 0; index < out.length; index++) {
            int hi = Character.digit(clean.charAt(index * 2), 16);
            int lo = Character.digit(clean.charAt(index * 2 + 1), 16);
            if (hi < 0 || lo < 0) {
                return null;
            }
            out[index] = (byte) ((hi << 4) | lo);
        }
        return out;
    }

    private void persistExternalDmrPreflightAttestation(StringBuilder report,
            byte[] measuredRuntime14) throws Exception {
        byte[] expected = externalDmrPreflightAttestationBytes(measuredRuntime14);
        File file = externalDmrPreflightAttestationFile();
        File temporary = new File(outputDirectory,
                file.getName() + ".refresh.tmp");
        if (temporary.exists() && !temporary.delete()) {
            throw new IOException("无法清理privacy预检凭证临时文件");
        }
        try (FileOutputStream stream = new FileOutputStream(temporary, false)) {
            stream.write(expected);
            stream.getFD().sync();
        }
        try {
            replaceFileAtomically(temporary, file);
        } catch (Throwable moveError) {
            // 原子替换是新鲜度证据合同的一部分；不允许降级为删除后覆盖。
            //noinspection ResultOfMethodCallIgnored
            temporary.delete();
            throw new IOException("privacy预检凭证原子替换失败", moveError);
        }
        byte[] written = readBoundedFile(file, 4096);
        if (!Arrays.equals(expected, written)) {
            throw new IOException("privacy预检凭证原子替换后逐字节回读不符");
        }
        if (!hasValidExternalDmrPreflightAttestation()) {
            throw new IOException("privacy预检凭证写后校验失败");
        }
        append(report, "Privacy预检凭证文件", file.getAbsolutePath());
        append(report, "Privacy预检凭证SHA-256", requireSha256(expected));
        append(report, "Privacy预检实测快照SHA-256",
                requireSha256(measuredRuntime14));
    }

    private static void replaceFileAtomically(File temporary, File target)
            throws Exception {
        if ("Dalvik".equals(System.getProperty("java.vm.name"))) {
            Os.rename(temporary.getAbsolutePath(), target.getAbsolutePath());
            return;
        }
        // 主代码不能静态引用Android API 26才提供的java.nio.file；
        // 本地JVM单测仍通过反射执行同等的原子替换语义。
        Class<?> pathClass = Class.forName("java.nio.file.Path");
        Class<?> copyOptionClass = Class.forName("java.nio.file.CopyOption");
        Class<?> standardCopyOptionClass = Class.forName(
                "java.nio.file.StandardCopyOption");
        Object sourcePath = File.class.getMethod("toPath").invoke(temporary);
        Object targetPath = File.class.getMethod("toPath").invoke(target);
        Object options = Array.newInstance(copyOptionClass, 2);
        Array.set(options, 0, standardCopyOptionClass
                .getField("ATOMIC_MOVE").get(null));
        Array.set(options, 1, standardCopyOptionClass
                .getField("REPLACE_EXISTING").get(null));
        Class.forName("java.nio.file.Files").getMethod("move",
                pathClass, pathClass, options.getClass()).invoke(null,
                sourcePath, targetPath, options);
    }

    private static long monotonicNowMs() {
        if ("Dalvik".equals(System.getProperty("java.vm.name"))) {
            return SystemClock.elapsedRealtime();
        }
        return System.nanoTime() / 1_000_000L;
    }

    private static long monotonicNowNanos() {
        if ("Dalvik".equals(System.getProperty("java.vm.name"))) {
            return SystemClock.elapsedRealtimeNanos();
        }
        return System.nanoTime();
    }

    private static void platformLogInfo(String message) {
        if ("Dalvik".equals(System.getProperty("java.vm.name"))) {
            Log.i(TAG, message);
        }
    }

    private static byte[] readBoundedFile(File file, int maximum)
            throws IOException {
        try (FileInputStream input = new FileInputStream(file);
                ByteArrayOutputStream output = new ByteArrayOutputStream()) {
            byte[] buffer = new byte[512];
            int count;
            while ((count = input.read(buffer)) >= 0) {
                if (count == 0) {
                    continue;
                }
                if (output.size() + count > maximum) {
                    throw new IOException("文件超过允许长度");
                }
                output.write(buffer, 0, count);
            }
            return output.toByteArray();
        }
    }

    private static String probeBuildName() {
        return BuildConfig.VERSION_NAME;
    }

    static boolean containsExactAsciiLine(String response, String expectedLine) {
        if (response == null || expectedLine == null || expectedLine.isEmpty()) {
            return false;
        }
        String[] lines = response.replace('\r', '\n').split("\\n+");
        for (String line : lines) {
            if (expectedLine.equals(line.trim())) {
                return true;
            }
        }
        return false;
    }

    /** 提取唯一、可安全回写的数字频道载荷；拒绝歧义、空字段和命令字符。 */
    static String extractDigitalChannelPayload(String response) {
        if (response == null) {
            return null;
        }
        final String prefix = "+DMOGETDIGITALCH:";
        String found = null;
        String[] lines = response.replace('\r', '\n').split("\\n+");
        for (String rawLine : lines) {
            String line = rawLine.trim();
            if (!line.startsWith(prefix)) {
                continue;
            }
            if (found != null) {
                return null;
            }
            String payload = line.substring(prefix.length());
            String[] fields = payload.split(",", -1);
            if (payload.isEmpty() || payload.length() > 256
                    || !payload.matches("[A-Za-z0-9,]+")
                    || fields.length != 15) {
                return null;
            }
            for (String field : fields) {
                if (field.isEmpty()) {
                    return null;
                }
            }
            found = payload;
        }
        return found;
    }

    static void requireExternalDmrFirmwareSlices(byte[][] slices)
            throws IOException {
        if (slices == null
                || slices.length != EXTERNAL_DMR_FIRMWARE_SLICE_SHA256.length) {
            throw new IOException("固件运行切片数量错误");
        }
        ByteArrayOutputStream combined = new ByteArrayOutputStream(4096);
        for (int index = 0; index < slices.length; index++) {
            if (slices[index] == null
                    || slices[index].length
                    != EXTERNAL_DMR_FIRMWARE_SLICE_LENGTHS[index]) {
                throw new IOException("固件运行切片长度错误 index=" + index);
            }
            String actual = requireSha256(slices[index]);
            if (!EXTERNAL_DMR_FIRMWARE_SLICE_SHA256[index].equals(actual)) {
                throw new IOException("固件运行切片哈希错误 index=" + index
                        + " actual=" + actual);
            }
            combined.write(slices[index], 0, slices[index].length);
        }
        String combinedHash = requireSha256(combined.toByteArray());
        if (!EXTERNAL_DMR_FIRMWARE_SLICES_COMBINED_SHA256.equals(combinedHash)) {
            throw new IOException("固件运行切片合并哈希错误: " + combinedHash);
        }
    }

    /**
     * 仅要求三轮14字节自身稳定，返回第一轮副本。
     * 不再硬编码合成 01 01…/12 34… 作为本机必达值。
     */
    static byte[] requireStableExternalDmrRuntimeSnapshots(byte[][] rounds)
            throws IOException {
        if (!isStableExternalDmrRuntimeSnapshots(rounds)) {
            throw new IOException("privacy运行快照不完整、不稳定或轮数错误");
        }
        return rounds[0].clone();
    }

    /** 三轮稳定且逐字节等于期望（期望来自预检实测凭证，非编译期假常量）。 */
    static void requireExternalDmrRuntimeSnapshotsEqual(byte[][] rounds,
            byte[] expected14) throws IOException {
        byte[] stable = requireStableExternalDmrRuntimeSnapshots(rounds);
        if (expected14 == null || expected14.length != stable.length
                || !Arrays.equals(stable, expected14)) {
            throw new IOException("privacy运行快照与期望实测不符 actual="
                    + hex(stable) + " expected="
                    + (expected14 == null ? "<null>" : hex(expected14)));
        }
    }

    /**
     * 离线夹具回归：稳定且等于 offlineFixturePrivacyRuntime14()。
     * 设备路径禁止用此方法代替实测。
     */
    static void requireExternalDmrPrivacyRuntimeSnapshots(byte[][] rounds)
            throws IOException {
        requireExternalDmrRuntimeSnapshotsEqual(rounds,
                offlineFixturePrivacyRuntime14());
    }

    /**
     * 严格：恢复快照必须逐字节等于进入前基线。离线回归用。
     * 真机设备路径请用 {@link #acceptExternalDmrPrivacyOffRuntimeRestore}。
     */
    static void requireExternalDmrPrivacyOffRuntimeRestored(byte[] baseline,
            byte[][] restoredRounds) throws IOException {
        int expectedLength = EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH;
        if (baseline == null || baseline.length != expectedLength) {
            throw new IOException("privacy-off运行基线长度错误");
        }
        if (!acceptExternalDmrPrivacyOffRuntimeRestore(baseline, restoredRounds)) {
            throw new IOException("privacy-off运行态未逐字节恢复 baseline="
                    + hex(baseline) + " actual=" + hex(restoredRounds[0]));
        }
    }

    /**
     * 真机恢复验收（v1.55–v1.57 四轮预检证据）：
     * SET encrypt=off 与 sct3258chgpro 0 均不能清除 privacy SRAM
     * （残留常见为 {@code 01 01 01 00 00 12 34 56 78 90 12 34 56 78}）。
     * <p>
     * 硬门：三轮快照自身稳定。若等于进入前基线返回 true；否则返回 false
     * 表示“频道已 off 时允许的稳定残留”，调用方不得因此失败关闭。
     */
    static boolean acceptExternalDmrPrivacyOffRuntimeRestore(byte[] baseline,
            byte[][] restoredRounds) throws IOException {
        if (!isStableExternalDmrRuntimeSnapshots(restoredRounds)) {
            throw new IOException("privacy-off恢复快照不完整、不稳定或轮数错误");
        }
        int expectedLength = EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH;
        if (baseline != null && baseline.length == expectedLength
                && Arrays.equals(baseline, restoredRounds[0])) {
            return true;
        }
        return false;
    }

    static final class ExternalDmrPrivacyTransactionState {
        boolean mutationMayHaveStarted;
        boolean privacyOnVerified;
        boolean privacyOffRestored;
        byte[] privacyOffBaselineRuntime = new byte[0];
        /** privacy-on 后本机实测或与凭证一致的 14 字节运行快照。 */
        byte[] measuredRuntime14 = new byte[0];
        final ExternalDmrPrivacyControlModel control =
                new ExternalDmrPrivacyControlModel();
    }

    static final class ExternalDmrPrivacyControlModel {
        enum Phase {
            NEW,
            BASELINE_VERIFIED,
            PRIVACY_SET_MAY_HAVE_STARTED,
            PRIVACY_SET_ACKED,
            PRIVACY_CHANNEL_VERIFIED,
            PRIVACY_RUNTIME_VERIFIED,
            RESTORE_SET_MAY_HAVE_STARTED,
            RESTORE_SET_ACKED,
            RESTORED,
            FAILED
        }

        private Phase phase = Phase.NEW;
        private boolean mutationMayHaveStarted;

        Phase phase() {
            return phase;
        }

        void baselineVerified() throws IOException {
            require(phase == Phase.NEW, "privacy基线状态重复或错序");
            phase = Phase.BASELINE_VERIFIED;
        }

        void beforePrivacySet() throws IOException {
            require(phase == Phase.BASELINE_VERIFIED,
                    "privacy SET前基线未验证");
            mutationMayHaveStarted = true;
            phase = Phase.PRIVACY_SET_MAY_HAVE_STARTED;
        }

        void privacySetAck(boolean accepted) throws IOException {
            require(phase == Phase.PRIVACY_SET_MAY_HAVE_STARTED,
                    "privacy SET ACK错序");
            if (!accepted) {
                fail("privacy SET ACK失败");
            }
            phase = Phase.PRIVACY_SET_ACKED;
        }

        void privacyChannelVerified(boolean accepted) throws IOException {
            require(phase == Phase.PRIVACY_SET_ACKED,
                    "privacy频道回读错序");
            if (!accepted) {
                fail("privacy频道完整回读失败");
            }
            phase = Phase.PRIVACY_CHANNEL_VERIFIED;
        }

        void privacyRuntimeVerified(boolean accepted) throws IOException {
            require(phase == Phase.PRIVACY_CHANNEL_VERIFIED,
                    "privacy运行快照错序");
            if (!accepted) {
                fail("privacy运行快照失败");
            }
            phase = Phase.PRIVACY_RUNTIME_VERIFIED;
        }

        boolean canEnterBridge() {
            return phase == Phase.PRIVACY_RUNTIME_VERIFIED;
        }

        boolean requiresRestore() {
            return mutationMayHaveStarted && phase != Phase.RESTORED;
        }

        void beforeRestoreSet() throws IOException {
            require(requiresRestore(), "privacy-off恢复没有待恢复事务");
            phase = Phase.RESTORE_SET_MAY_HAVE_STARTED;
        }

        void restoreSetAck(boolean accepted) throws IOException {
            require(phase == Phase.RESTORE_SET_MAY_HAVE_STARTED,
                    "privacy-off恢复SET ACK错序");
            if (!accepted) {
                fail("privacy-off恢复SET ACK失败");
            }
            phase = Phase.RESTORE_SET_ACKED;
        }

        void restoreChannelVerified(boolean accepted) throws IOException {
            require(phase == Phase.RESTORE_SET_ACKED,
                    "privacy-off恢复频道回读错序");
            if (!accepted) {
                fail("privacy-off恢复完整回读失败");
            }
            phase = Phase.RESTORED;
        }

        void restoredByValidatedReload() throws IOException {
            require(requiresRestore(), "控制面reload没有待恢复privacy事务");
            phase = Phase.RESTORED;
        }

        private void require(boolean condition, String message)
                throws IOException {
            if (!condition) {
                fail(message);
            }
        }

        private void fail(String message) throws IOException {
            phase = Phase.FAILED;
            throw new IOException(message);
        }
    }

    /**
     * 步骤3 离线基础设施证明：超时 handler 完整哈希、arm 地址门、
     * 五前序+五 VLC 有界交换、禁止 data36、退桥恢复策略声明。不打开串口。
     */
    static ProbeResult evaluateExternalDmrStep3InfrastructureOffline() {
        StringBuilder report = new StringBuilder();
        append(report, "Mode", "步骤3 离线基础设施 + 有界控制会话状态机");
        append(report, "Serial opened", false);
        append(report, "Device mutation", "无");
        append(report, "Data36", "禁止");
        append(report, "Baud", BAUD_RATE);
        try {
            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            String handlerSha = sha256(handler);
            append(report, "Timeout handler length", handler.length);
            append(report, "Timeout handler SHA-256", handlerSha);
            if (!UART_HPI_TIMEOUT_HANDLER_SHA256.equals(handlerSha)) {
                throw new IOException("超时 handler 哈希与已记录 v0.61 不符");
            }
            if (handler.length != 64) {
                throw new IOException("超时 handler 长度必须为 64 字节");
            }
            append(report, "Bridge flag address",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_BRIDGE_FLAG_ADDRESS));
            append(report, "SysTick vector address",
                    String.format(Locale.US, "0x%08x", RAM_VECTOR_SYSTICK));
            append(report, "Original SysTick",
                    String.format(Locale.US, "0x%08x",
                            ORIGINAL_SYSTICK_HANDLER));
            append(report, "Timeout code address",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_TIMEOUT_CODE_ADDRESS));
            append(report, "Timeout counter address",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_TIMEOUT_COUNTER_ADDRESS));
            append(report, "Timeout marker address",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_TIMEOUT_MARKER_ADDRESS));
            append(report, "Timeout entry",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_TIMEOUT_ENTRY));
            append(report, "Timeout marker value",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_TIMEOUT_MARKER));
            append(report, "Bridge target ms",
                    EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS);
            append(report, "Bridge margin ms",
                    EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS);
            append(report, "Bridge path worst-case ms",
                    externalDmrStep3WorstCaseMs());
            append(report, "Bridge budget accepted",
                    externalDmrStep3BudgetFitsBridgeWindow());
            if (!externalDmrStep3BudgetFitsBridgeWindow()) {
                throw new IOException("步骤3最坏路径超过bridge窗口");
            }

            // Clean baseline must pass; dirty windows must fail closed.
            UartHpiTimeoutArmGate.validateCleanBaseline(
                    new byte[] {0},
                    le32(ORIGINAL_SYSTICK_HANDLER),
                    new byte[handler.length],
                    new byte[4],
                    new byte[4],
                    handler);
            append(report, "Clean baseline arm gate", true);
            try {
                UartHpiTimeoutArmGate.validateCleanBaseline(
                        new byte[] {1},
                        le32(ORIGINAL_SYSTICK_HANDLER),
                        new byte[handler.length],
                        new byte[4],
                        new byte[4],
                        handler);
                throw new IOException("脏 bridge flag 未被 arm 门拒绝");
            } catch (IOException expected) {
                append(report, "Dirty flag rejected", expected.getMessage());
            }
            try {
                byte[] badHandler = handler.clone();
                badHandler[0] ^= 0x01;
                UartHpiTimeoutArmGate.validateCleanBaseline(
                        new byte[] {0},
                        le32(ORIGINAL_SYSTICK_HANDLER),
                        new byte[handler.length],
                        new byte[4],
                        new byte[4],
                        badHandler);
                throw new IOException("错误 handler 哈希未被 arm 门拒绝");
            } catch (IOException expected) {
                append(report, "Bad handler rejected", expected.getMessage());
            }

            ExternalDmrStep0Contract contract =
                    ExternalDmrStep0Contract.forProducer080177b0(
                            13, 99,
                            ExternalDmrStep0Contract.CALL_TYPE_GROUP,
                            0, 0, true,
                            ExternalDmrStep0Contract.OUTPUT_SLOT1,
                            1,
                            0x05, 0xa3,
                            new byte[] {0x11, 0x22, 0x33, 0x44});
            ExternalDmrTxModel model = new ExternalDmrTxModel(contract);
            append(report, "Signaling snapshot source",
                    "离线夹具，非本机运行时冻结值");
            append(report, "callslot",
                    String.format(Locale.US, "0x%02x", contract.callSlot()));

            int totalRequests = 0;
            for (int index = 0; index < contract.setupCount(); index++) {
                byte[] request = model.expectedRequest();
                if (request == null) {
                    throw new IOException("setup expectedRequest 为空 index="
                            + index);
                }
                if (looksLikeExternalData36Frame(request)) {
                    throw new IOException("setup 阶段出现 data36 帧");
                }
                totalRequests++;
                byte[] ack = createControlStatusAckFrame(
                        contract.setupPacketType(index),
                        contract.setupAckField(index));
                ExternalDmrTxModel.ExchangeWindow window =
                        model.openPostSendWindow(request,
                                offlineQuietWindowProof());
                if (window == null
                        || !model.acceptSetupExchange(window, ack)) {
                    throw new IOException("setup 交换失败 index=" + index);
                }
                append(report, "setup" + index + " window", window.sequence());
            }
            for (int index = 0; index < EXTERNAL_DMR_SESSION_ACK_COUNT; index++) {
                byte[] request = model.expectedRequest();
                if (request == null) {
                    throw new IOException("VLC expectedRequest 为空 index="
                            + index);
                }
                if (looksLikeExternalData36Frame(request)) {
                    throw new IOException("VLC 阶段出现 data36 帧");
                }
                totalRequests++;
                byte[] ack = createPaddedHpiFrame(5, new byte[] {0x43});
                ExternalDmrTxModel.ExchangeWindow window =
                        model.openPostSendWindow(request,
                                offlineQuietWindowProof());
                if (window == null
                        || !model.acceptVlcExchange(window, ack)) {
                    throw new IOException("VLC 交换失败 index=" + index);
                }
                append(report, "vlc" + index + " window", window.sequence());
            }
            if (model.phase() != ExternalDmrTxModel.Phase.COMPLETE) {
                throw new IOException("会话未完成 phase=" + model.phase());
            }
            if (model.canSerializeData36()) {
                throw new IOException("步骤3 不得允许 data36");
            }
            if (model.expectedRequest() != null) {
                throw new IOException("完成后仍能取出下一请求");
            }
            if (totalRequests != contract.setupCount()
                    + EXTERNAL_DMR_SESSION_ACK_COUNT) {
                throw new IOException("请求计数异常 total=" + totalRequests);
            }
            append(report, "setupAcks", model.setupAcks());
            append(report, "vlcAcks", model.vlcAcks());
            append(report, "Total control requests", totalRequests);
            append(report, "ASCII recovery while bridged", "禁止");
            append(report, "Bridge exit", "SysTick 自动超时 + marker/vector/SRAM 复核");
            append(report, "Result",
                    "通过：步骤3 离线基础设施与有界控制会话状态机");
            return new ProbeResult(true, report.toString());
        } catch (Throwable error) {
            append(report, "Error", error.getMessage());
            append(report, "Result", "失败：步骤3 离线基础设施 "
                    + error.getMessage());
            return new ProbeResult(false, report.toString());
        }
    }

    static String uartHpiTimeoutHandlerSha256() {
        return sha256ForLog(wordsToBytes(UART_HPI_TIMEOUT_WORDS));
    }

    /** 单次有界控制交换最坏占用（静默窗上限 + ACK 读窗）。 */
    static long externalDmrOneControlExchangeWorstCaseMs() {
        return EXTERNAL_DMR_VLC_SESSION_ACK_TIMEOUT_MS
                + EXTERNAL_DMR_PRE_SEND_QUIET_MAX_MS;
    }

    /**
     * v1.92 setup0-only：2000ms settle + 最多两次 setup0 交换 + 两次 late 窗。
     * 仍远小于 18s 绝对退桥目标。
     */
    static long externalDmrSetup0OnlyWorstCaseMs() {
        return EXTERNAL_DMR_POST_BRIDGE_SETTLE_SETUP0_ONLY_MS
                + 2L * (externalDmrOneControlExchangeWorstCaseMs()
                + EXTERNAL_DMR_POST_TIMEOUT_LATE_CAPTURE_MS)
                + EXTERNAL_DMR_VLC_SESSION_IN_MEMORY_ALLOWANCE_MS;
    }

    static boolean externalDmrSetup0OnlyBudgetFitsBridgeWindow() {
        return externalDmrSetup0OnlyWorstCaseMs()
                + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS
                < EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS;
    }

    /**
     * v2.03 实时主动路径成功所需的 setup 最坏时间：500ms settle，首次
     * setup0 双空含 late，一次成功重试，再完成 setup1-4。该值必须小于
     * 5s fullprep 延迟加 1.2s 裕量，因此不扩大 18s 绝对退桥窗口。
     */
    static long externalDmrRealtimeSetupPassWorstCaseMs() {
        long one = externalDmrOneControlExchangeWorstCaseMs();
        return EXTERNAL_DMR_POST_BRIDGE_SETTLE_MS
                + one + EXTERNAL_DMR_POST_TIMEOUT_LATE_CAPTURE_MS
                + one + 4L * one;
    }

    static boolean externalDmrRealtimeSetupFitsPrepGate() {
        return externalDmrRealtimeSetupPassWorstCaseMs()
                < MID_BRIDGE_DATAGATE_DELAY_MS
                + MID_BRIDGE_DATAGATE_POST_MARGIN_MS;
    }

    /** 兼容测试：旧 3A/3B 分项仍可查询（v1.64 主路径为单 bridge 合计）。 */
    static long externalDmrStep3aWorstCaseMs() {
        return EXTERNAL_DMR_SETUP_EXCHANGE_COUNT
                * externalDmrOneControlExchangeWorstCaseMs()
                + EXTERNAL_DMR_VLC_SESSION_IN_MEMORY_ALLOWANCE_MS;
    }

    static long externalDmrStep3bWorstCaseMs() {
        return EXTERNAL_DMR_SESSION_ACK_COUNT
                * externalDmrOneControlExchangeWorstCaseMs()
                + DATA_PLANE_CLEANUP_CAPTURE_MS
                + EXTERNAL_DMR_VLC_SESSION_HPI_EXIT_MS
                + EXTERNAL_DMR_VLC_SESSION_IN_MEMORY_ALLOWANCE_MS;
    }

    /**
     * 步骤3 预算门：取「经典十次交换」与「固定 prep 等待 + 五条 VLC + 清理」较大者。
     * v1.77：必须纳入 delay+postMargin，否则 5000+1200 等待被预算门漏计。
     */
    static long externalDmrStep3WorstCaseMs() {
        long one = externalDmrOneControlExchangeWorstCaseMs();
        long classicTenExchanges = EXTERNAL_DMR_VLC_SESSION_CONTROL_EXCHANGES * one
                + DATA_PLANE_CLEANUP_CAPTURE_MS
                + EXTERNAL_DMR_VLC_SESSION_HPI_EXIT_MS
                + EXTERNAL_DMR_VLC_SESSION_IN_MEMORY_ALLOWANCE_MS;
        // setup 与 prep 延迟重叠；VLC 仅在 delay+postMargin 之后开始。
        long prepAnchored = MID_BRIDGE_DATAGATE_DELAY_MS
                + MID_BRIDGE_DATAGATE_POST_MARGIN_MS
                + EXTERNAL_DMR_SESSION_ACK_COUNT * one
                + DATA_PLANE_CLEANUP_CAPTURE_MS
                + EXTERNAL_DMR_VLC_SESSION_HPI_EXIT_MS
                + EXTERNAL_DMR_VLC_SESSION_IN_MEMORY_ALLOWANCE_MS;
        return Math.max(classicTenExchanges, prepAnchored);
    }

    static boolean externalDmrStep3BudgetFitsBridgeWindow() {
        return externalDmrStep3WorstCaseMs()
                + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS
                < EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS;
    }

    /** 步骤4最坏路径 = 步骤3 + data36。 */
    static long externalDmrStep4WorstCaseMs() {
        return externalDmrStep3WorstCaseMs()
                + EXTERNAL_DMR_PRE_SEND_QUIET_MAX_MS
                + EXTERNAL_DMR_DATA36_CREDIT_TIMEOUT_MS
                + EXTERNAL_DMR_DATA36_TX_ALLOWANCE_MS;
    }

    static boolean externalDmrStep4BudgetFitsBridgeWindow() {
        return externalDmrStep4WorstCaseMs()
                + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS
                < EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS;
    }

    /** 完整摩尔斯不把26次credit上限相加；逐单元有界并受16秒绝对发送截止约束。 */
    static long softwareAmbeFullMorseSendDeadlineOffsetMs() {
        return EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS
                - SOFTWARE_AMBE_MORSE_BRIDGE_EXIT_GUARD_MS;
    }

    static long softwareAmbeFullMorseCleanupAllowanceMs() {
        return DATA_PLANE_CLEANUP_CAPTURE_MS
                + EXTERNAL_DMR_VLC_SESSION_HPI_EXIT_MS;
    }

    static boolean softwareAmbeFullMorseBudgetFitsBridgeAndWatchdog() {
        long sendDeadline = softwareAmbeFullMorseSendDeadlineOffsetMs();
        return sendDeadline > externalDmrStep3WorstCaseMs()
                && sendDeadline < EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS
                && SOFTWARE_AMBE_MORSE_BRIDGE_EXIT_GUARD_MS
                > softwareAmbeFullMorseCleanupAllowanceMs()
                && EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS
                + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS
                < SOFTWARE_AMBE_PTT_WATCHDOG_TIMEOUT_MS;
    }

    /** 实时relay没有独立发送前静默门，但增加vlc2前等待和写后观察窗。 */
    static long externalDmrRealtimeRelayWorstCaseMs() {
        return externalDmrStep3WorstCaseMs()
                + EXTERNAL_DMR_REALTIME_PRE_VLC2_WAIT_MS
                + EXTERNAL_DMR_DATA36_CREDIT_TIMEOUT_MS
                + EXTERNAL_DMR_DATA36_TX_ALLOWANCE_MS;
    }

    static boolean externalDmrRealtimeRelayBudgetFitsBridgeWindow() {
        return externalDmrRealtimeRelayWorstCaseMs()
                + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS
                < EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS;
    }

    private byte[][] captureExternalDmrRuntimeRounds(InputStream input,
            OutputStream output, String evidenceLabel, String evidencePrefix,
            StringBuilder report) throws Exception {
        byte[][] rounds = new byte[EXTERNAL_DMR_RUNTIME_SNAPSHOT_ROUNDS][];
        for (int round = 0; round < rounds.length; round++) {
            byte[] flags = readMemory(input, output,
                    EXTERNAL_DMR_SIGNALING_FLAGS_ADDRESS,
                    EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH);
            byte[] dataGate = readMemory(input, output,
                    EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
            byte[] session = readMemory(input, output,
                    EXTERNAL_DMR_SESSION_RECORD_ADDRESS,
                    EXTERNAL_DMR_SESSION_RECORD_LENGTH);
            rounds[round] = concatBytes(concatBytes(flags, dataGate), session);
            preserveRawEvidence(report, evidenceLabel + " round " + (round + 1),
                    evidencePrefix + (round + 1) + "_", rounds[round]);
            if (round + 1 < rounds.length) {
                SystemClock.sleep(EXTERNAL_DMR_RUNTIME_SNAPSHOT_GAP_MS);
            }
        }
        return rounds;
    }

    /**
     * @return true=与进入前基线逐字节一致；false=稳定残留已接受
     */
    private boolean acceptExternalDmrPrivacyOffRuntimeRestored(InputStream input,
            OutputStream output, ExternalDmrPrivacyTransactionState transaction,
            StringBuilder report, String evidencePrefix) throws Exception {
        if (transaction == null) {
            throw new IOException("privacy-off恢复事务缺失");
        }
        byte[][] restoredRounds = captureExternalDmrRuntimeRounds(input, output,
                "Privacy-off restored runtime", evidencePrefix, report);
        boolean matched = acceptExternalDmrPrivacyOffRuntimeRestore(
                transaction.privacyOffBaselineRuntime, restoredRounds);
        append(report, "Privacy-off runtime restored byte-for-byte", matched);
        append(report, "Privacy-off restored runtime SHA-256",
                sha256(restoredRounds[0]));
        if (transaction.privacyOffBaselineRuntime != null
                && transaction.privacyOffBaselineRuntime.length > 0) {
            append(report, "Privacy-off baseline runtime SHA-256",
                    sha256(transaction.privacyOffBaselineRuntime));
        }
        if (!matched) {
            append(report, "Privacy-off runtime residual accepted", true);
            append(report, "Privacy-off residual note",
                    "真机证据：SET off 与 sct3258chgpro 0 均不清除 privacy SRAM；"
                            + "频道串 privacy-off CH1 为硬门，残留稳定即可");
        }
        return matched;
    }

    /** @deprecated 名称保留；内部改为可接受残留的验收。 */
    private void verifyExternalDmrPrivacyOffRuntimeRestored(InputStream input,
            OutputStream output, ExternalDmrPrivacyTransactionState transaction,
            StringBuilder report, String evidencePrefix) throws Exception {
        acceptExternalDmrPrivacyOffRuntimeRestored(input, output, transaction,
                report, evidencePrefix);
    }

    /**
     * @param expectedMeasuredRuntime14 null=预检测量模式（只要求三轮稳定并冻结实测）；
     *                                  非null=步骤3/4复核模式（必须等于凭证内实测）。
     * @return 用于后续会话的合同（由实测14字节派生）
     */
    private ExternalDmrStep0Contract prepareExternalDmrPrivacyRuntime(
            InputStream input, OutputStream output,
            ExternalDmrPrivacyTransactionState transaction,
            StringBuilder report, byte[] expectedMeasuredRuntime14)
            throws Exception {
        if (transaction == null) {
            throw new IOException("privacy运行事务状态缺失");
        }
        // 2026-08-10 第二次真机：生产应用恢复后当前频道可能不是冻结 CH1
        // （例：410012500,...），预检/步骤3 必须先钉回 privacy-off CH1 再测基线。
        // 频道变更属已授权门；任何 SET 即标记 mutation，保证 finally 恢复。
        String channelObserved = query(input, output, "AT+DMOGETDIGITALCH");
        append(report, "Privacy channel before normalize",
                printable(channelObserved));
        if (!containsExactAsciiLine(channelObserved,
                "+DMOGETDIGITALCH:" + EXPECTED_DIGITAL_CHANNEL)) {
            transaction.mutationMayHaveStarted = true;
            append(report, "Privacy baseline normalize",
                    "当前频道非冻结 CH1 privacy-off，先 SET 基线");
            String setBase = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "Privacy baseline SET response", printable(setBase));
            if (!containsExactAsciiLine(setBase, "+DMOSETDIGITALCH:0")) {
                throw new IOException("冻结 CH1 privacy-off 基线 SET 未得到精确成功ACK");
            }
        } else {
            append(report, "Privacy baseline normalize", "已是冻结 CH1 privacy-off");
        }
        String channelBefore = query(input, output, "AT+DMOGETDIGITALCH");
        append(report, "Privacy baseline channel", printable(channelBefore));
        if (!containsExactAsciiLine(channelBefore,
                "+DMOGETDIGITALCH:" + EXPECTED_DIGITAL_CHANNEL)) {
            throw new IOException("进入privacy事务前频道不是完整privacy-off基线");
        }
        byte[][] baselineRounds = captureExternalDmrRuntimeRounds(input, output,
                "Privacy-off baseline runtime",
                "h13_ext_dmr_privacy_off_baseline_round", report);
        if (!isStableExternalDmrRuntimeSnapshots(baselineRounds)) {
            throw new IOException("privacy-off运行基线不完整或不稳定");
        }
        transaction.privacyOffBaselineRuntime = baselineRounds[0].clone();
        append(report, "Privacy-off baseline runtime SHA-256",
                sha256(transaction.privacyOffBaselineRuntime));
        transaction.control.baselineVerified();

        byte[][] slices = new byte[EXTERNAL_DMR_FIRMWARE_SLICE_ADDRESSES.length][];
        for (int index = 0; index < slices.length; index++) {
            slices[index] = readMemory(input, output,
                    EXTERNAL_DMR_FIRMWARE_SLICE_ADDRESSES[index],
                    EXTERNAL_DMR_FIRMWARE_SLICE_LENGTHS[index]);
            preserveRawEvidence(report, "Firmware runtime slice " + index,
                    "h13_ext_dmr_fw_slice" + index + "_", slices[index]);
        }
        requireExternalDmrFirmwareSlices(slices);
        append(report, "Pinned full firmware SHA-256",
                EXPECTED_MODULE_FIRMWARE_SHA256);
        append(report, "Runtime firmware slices combined SHA-256",
                EXTERNAL_DMR_FIRMWARE_SLICES_COMBINED_SHA256);

        // 必须先标记再发送SET；即使ACK读取异常，也必须进入privacy-off恢复。
        transaction.control.beforePrivacySet();
        transaction.mutationMayHaveStarted = true;
        String setPrivacy = query(input, output,
                SET_EXTERNAL_DMR_PRIVACY_ON_CHANNEL);
        append(report, "Privacy-on SET response", printable(setPrivacy));
        transaction.control.privacySetAck(containsExactAsciiLine(
                setPrivacy, "+DMOSETDIGITALCH:0"));
        String channelOn = query(input, output, "AT+DMOGETDIGITALCH");
        append(report, "Privacy-on channel readback", printable(channelOn));
        transaction.control.privacyChannelVerified(containsExactAsciiLine(
                channelOn,
                "+DMOGETDIGITALCH:" + EXTERNAL_DMR_PRIVACY_ON_CHANNEL));

        byte[][] rounds = captureExternalDmrRuntimeRounds(input, output,
                "Privacy-on runtime", "h13_ext_dmr_privacy_on_round", report);
        byte[] measured;
        if (expectedMeasuredRuntime14 == null) {
            measured = requireStableExternalDmrRuntimeSnapshots(rounds);
            append(report, "Privacy-on runtime source", "本机实测三轮稳定冻结");
        } else {
            requireExternalDmrRuntimeSnapshotsEqual(rounds,
                    expectedMeasuredRuntime14);
            measured = expectedMeasuredRuntime14.clone();
            append(report, "Privacy-on runtime source", "与预检凭证实测一致");
        }
        transaction.measuredRuntime14 = measured;
        ExternalDmrStep0Contract contract =
                createContractFromMeasuredRuntime(measured);
        if (!contract.matchesPrivacyRuntime(
                Arrays.copyOfRange(measured, 0, 4),
                Arrays.copyOfRange(measured, 4, 5),
                Arrays.copyOfRange(measured, 5, 14))) {
            throw new IOException("由实测快照派生的步骤0合同自洽失败");
        }
        transaction.control.privacyRuntimeVerified(true);
        if (!transaction.control.canEnterBridge()) {
            throw new IOException("privacy事务状态机禁止进入bridge");
        }
        transaction.privacyOnVerified = true;
        append(report, "Privacy-on measured runtime SHA-256", sha256(measured));
        append(report, "Privacy-on runtime contract verified", true);
        return contract;
    }

    private void restoreExternalDmrPrivacyOffChannel(InputStream input,
            OutputStream output, ExternalDmrPrivacyTransactionState transaction,
            StringBuilder report) throws Exception {
        // 完整 privacy-on 事务走控制状态机；仅 CH1 归一化失败时 phase 仍为 NEW，
        // 只要求钉回冻结 privacy-off 频道串。
        boolean useControl = transaction != null
                && transaction.control.requiresRestore();
        if (useControl) {
            transaction.control.beforeRestoreSet();
        }
        String setOff = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
        append(report, "Privacy-off restore SET response", printable(setOff));
        boolean setAccepted = containsExactAsciiLine(setOff,
                "+DMOSETDIGITALCH:0");
        if (useControl) {
            transaction.control.restoreSetAck(setAccepted);
        } else if (!setAccepted) {
            throw new IOException("privacy-off恢复SET未得到精确成功ACK");
        }
        String channelOff = query(input, output, "AT+DMOGETDIGITALCH");
        append(report, "Privacy-off channel readback", printable(channelOff));
        boolean channelAccepted = containsExactAsciiLine(channelOff,
                "+DMOGETDIGITALCH:" + EXPECTED_DIGITAL_CHANNEL);
        if (!channelAccepted) {
            if (useControl) {
                transaction.control.restoreChannelVerified(false);
            }
            throw new IOException("privacy-off恢复完整回读不一致");
        }
        if (transaction == null) {
            return;
        }
        boolean haveBaseline = transaction.privacyOffBaselineRuntime != null
                && transaction.privacyOffBaselineRuntime.length
                == EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH;
        if (haveBaseline) {
            // 频道串已是 privacy-off CH1。运行态：优先匹配基线；不匹配则
            // sct3258chgpro 归一化控制面后再采；仍不匹配则接受稳定残留。
            boolean matched = acceptExternalDmrPrivacyOffRuntimeRestored(input,
                    output, transaction, report,
                    "h13_ext_dmr_privacy_off_restored_round");
            String runtimePath = matched
                    ? "SET频道后运行态匹配进入前基线"
                    : "SET后运行态残留，升级 sct3258chgpro";
            if (!matched) {
                append(report, "Privacy-off runtime escalate",
                        "sct3258chgpro 0 控制面归一化后再采运行态");
                reloadSctBaselineTrafficPlane(input, output, report, 1);
                // chgpro 内已再 SET CH1；复核频道串
                String channelAfterReload = query(input, output,
                        "AT+DMOGETDIGITALCH");
                append(report, "Privacy-off channel after chgpro",
                        printable(channelAfterReload));
                if (!containsExactAsciiLine(channelAfterReload,
                        "+DMOGETDIGITALCH:" + EXPECTED_DIGITAL_CHANNEL)) {
                    throw new IOException(
                            "sct3258chgpro 后频道不是冻结 privacy-off CH1");
                }
                matched = acceptExternalDmrPrivacyOffRuntimeRestored(input,
                        output, transaction, report,
                        "h13_ext_dmr_privacy_off_restored_after_reload_round");
                runtimePath = matched
                        ? "SET后sct3258chgpro归一化匹配基线"
                        : "SET后sct3258chgpro完成；运行态稳定残留已接受";
            }
            append(report, "Privacy-off runtime restore path", runtimePath);
        } else {
            append(report, "Privacy-off runtime restore path",
                    "无进入前基线快照；仅验证频道串 privacy-off CH1");
        }
        if (useControl) {
            transaction.control.restoreChannelVerified(true);
        }
        transaction.privacyOffRestored = true;
    }

    /**
     * 步骤4 离线证明：冻结 44 字节帧哈希、握手后单 data36 交换窗口、
     * credit 格式门正负例、写成功单独不得完成、预算门。无串口。
     */
    static ProbeResult evaluateExternalDmrStep4OfflineOneUnitCredit() {
        StringBuilder report = new StringBuilder();
        append(report, "Mode", "步骤4 离线单 data36 + credit 格式门");
        append(report, "Serial opened", false);
        append(report, "Device mutation", "无");
        append(report, "Signaling snapshot source",
                "离线夹具，非本机运行时冻结值");
        try {
            byte[] plainFrame = requirePlainExternalTxFrameUnit0();
            byte[] frame = requireHostEncryptedExternalTxFrameUnit0();
            append(report, "步骤2冻结AMBE明文unit0线帧字节数", plainFrame.length);
            append(report, "步骤2冻结AMBE明文unit0线帧SHA-256",
                    requireSha256(plainFrame));
            append(report, "步骤2冻结AMBE明文unit0哈希通过", true);
            append(report, "主机privacy密文unit0线帧SHA-256",
                    requireSha256(frame));
            append(report, "主机privacy密文允许设备发送", true);
            append(report, "Bridge path worst-case ms",
                    externalDmrStep4WorstCaseMs());
            append(report, "Bridge budget accepted",
                    externalDmrStep4BudgetFitsBridgeWindow());
            if (!externalDmrStep4BudgetFitsBridgeWindow()) {
                throw new IOException("步骤4最坏路径超过 bridge 窗口");
            }

            // 先走步骤1握手到 COMPLETE，再进入 data36 门。
            ExternalDmrStep0Contract contract =
                    ExternalDmrStep0Contract.forProducer080177b0(
                            13, 99,
                            ExternalDmrStep0Contract.CALL_TYPE_GROUP,
                            0, 0, true,
                            ExternalDmrStep0Contract.OUTPUT_SLOT1,
                            1,
                            0x05, 0xa3,
                            new byte[] {0x11, 0x22, 0x33, 0x44});
            ExternalDmrTxModel handshake = new ExternalDmrTxModel(contract);
            for (int index = 0; index < contract.setupCount(); index++) {
                byte[] request = handshake.expectedRequest();
                ExternalDmrTxModel.ExchangeWindow window =
                        handshake.openPostSendWindow(request,
                                offlineQuietWindowProof());
                if (window == null || !handshake.acceptSetupExchange(window,
                        createControlStatusAckFrame(
                                contract.setupPacketType(index),
                                contract.setupAckField(index)))) {
                    throw new IOException("setup 失败 index=" + index);
                }
            }
            for (int index = 0; index < EXTERNAL_DMR_SESSION_ACK_COUNT; index++) {
                byte[] request = handshake.expectedRequest();
                ExternalDmrTxModel.ExchangeWindow window =
                        handshake.openPostSendWindow(request,
                                offlineQuietWindowProof());
                if (window == null || !handshake.acceptVlcExchange(window,
                        createPaddedHpiFrame(5, new byte[] {0x43}))) {
                    throw new IOException("VLC 失败 index=" + index);
                }
            }
            if (handshake.phase() != ExternalDmrTxModel.Phase.COMPLETE) {
                throw new IOException("握手未完成");
            }
            if (handshake.canSerializeData36()) {
                throw new IOException("步骤1模型不得序列化 data36");
            }

            ExternalDmrStep4OneUnitModel data36 =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            if (data36.expectedFrame() != null) {
                throw new IOException("握手完成前不得取出 data36");
            }
            data36.markHandshakeComplete();
            if (!Arrays.equals(frame, data36.expectedFrame())) {
                throw new IOException("data36 期望帧与冻结 unit0 不一致");
            }

            // 写成功单独不得完成：无 credit 的 accept 必须失败。
            ExternalDmrStep4OneUnitModel writeOnly =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            writeOnly.markHandshakeComplete();
            ExternalDmrStep4OneUnitModel.ExchangeWindow writeOnlyWindow =
                    writeOnly.openPostSendWindow(frame,
                            offlineQuietWindowProof());
            if (writeOnlyWindow == null) {
                throw new IOException("写成功路径窗口应能建立");
            }
            if (writeOnly.acceptWriteCompletedWithoutCredit(writeOnlyWindow)) {
                throw new IOException("写成功单独完成被错误接受");
            }
            if (writeOnly.phase()
                    != ExternalDmrStep4OneUnitModel.Phase.FAILED) {
                throw new IOException("无 credit 后应 FAILED");
            }
            append(report, "Write-only rejected", true);

            // 未排空不得开窗。
            ExternalDmrStep4OneUnitModel undrained =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            undrained.markHandshakeComplete();
            if (undrained.openPostSendWindow(frame, null) != null
                    || undrained.phase()
                    != ExternalDmrStep4OneUnitModel.Phase.FAILED) {
                throw new IOException("未排空开窗应失败");
            }
            append(report, "Undrained window rejected", true);

            // VLC 0x43 不得当作 credit。
            ExternalDmrStep4OneUnitModel vlcAsCredit =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            vlcAsCredit.markHandshakeComplete();
            ExternalDmrStep4OneUnitModel.ExchangeWindow badWindow =
                    vlcAsCredit.openPostSendWindow(frame,
                            offlineQuietWindowProof());
            if (vlcAsCredit.acceptCredit(badWindow,
                    createPaddedHpiFrame(5, new byte[] {0x43}))) {
                throw new IOException("VLC 0x43 被误认为 credit");
            }
            append(report, "VLC-as-credit rejected", true);

            // 前导非 credit 帧后的 credit：宽松门可见，严格门必须拒绝。
            byte[] leadingThenCredit = concatBytes(
                    createControlStatusAckFrame(0, 0x3e),
                    createHpiFrame(0x20, new byte[] {0x01, 0x00}));
            if (!containsExternalEncodedTxCredit(leadingThenCredit)) {
                throw new IOException("宽松门应仍能在后续帧看到 credit");
            }
            if (isStrictPostSendExternalEncodedTxCredit(leadingThenCredit)) {
                throw new IOException("严格门不得接受前导非 credit");
            }
            ExternalDmrStep4OneUnitModel leadingModel =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            leadingModel.markHandshakeComplete();
            ExternalDmrStep4OneUnitModel.ExchangeWindow leadingWindow =
                    leadingModel.openPostSendWindow(frame,
                            offlineQuietWindowProof());
            if (leadingModel.acceptCredit(leadingWindow, leadingThenCredit)) {
                throw new IOException("前导非 credit 响应被错误接受");
            }
            append(report, "Leading-non-credit rejected", true);

            // 空 credit / 超时路径拒绝。
            ExternalDmrStep4OneUnitModel emptyCredit =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            emptyCredit.markHandshakeComplete();
            ExternalDmrStep4OneUnitModel.ExchangeWindow emptyWindow =
                    emptyCredit.openPostSendWindow(frame,
                            offlineQuietWindowProof());
            if (emptyCredit.acceptCredit(emptyWindow, new byte[0])) {
                throw new IOException("空 credit 被错误接受");
            }
            ExternalDmrStep4OneUnitModel timeoutModel =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            timeoutModel.markHandshakeComplete();
            ExternalDmrStep4OneUnitModel.ExchangeWindow timeoutWindow =
                    timeoutModel.openPostSendWindow(frame,
                            offlineQuietWindowProof());
            if (timeoutModel.acceptTimeout(timeoutWindow)
                    || timeoutModel.phase()
                    != ExternalDmrStep4OneUnitModel.Phase.FAILED) {
                throw new IOException("超时路径未失败关闭");
            }
            append(report, "Empty credit rejected", true);
            append(report, "Timeout path rejected", true);

            // 合法 vendor 短 credit（body 0x01）通过严格首帧门。
            ExternalDmrStep4OneUnitModel ok =
                    ExternalDmrStep4OneUnitModel.forVerifiedHostEncryptedUnit0();
            ok.markHandshakeComplete();
            byte[] credit = createHpiFrame(0x20, new byte[] {0x01, 0x00});
            if (!isStrictPostSendExternalEncodedTxCredit(credit)) {
                throw new IOException("合法 credit 未通过严格门");
            }
            ExternalDmrStep4OneUnitModel.ExchangeWindow okWindow =
                    ok.openPostSendWindow(frame,
                            offlineQuietWindowProof());
            if (okWindow == null || !ok.acceptCredit(okWindow, credit)) {
                throw new IOException("合法 credit 格式门失败");
            }
            if (ok.phase() != ExternalDmrStep4OneUnitModel.Phase.ACCEPTED) {
                throw new IOException("credit 后未进入 ACCEPTED");
            }
            if (ok.expectedFrame() != null) {
                throw new IOException("完成后仍能取出 data36");
            }
            // 单单元：完成后再次开窗必须失败。
            if (ok.openPostSendWindow(frame,
                    offlineQuietWindowProof()) != null
                    || ok.phase()
                    != ExternalDmrStep4OneUnitModel.Phase.FAILED) {
                throw new IOException("单单元完成后不得再次发送");
            }
            byte[] extracted = extractFirstExternalEncodedTxCreditFrame(credit);
            if (extracted == null || !Arrays.equals(extracted, credit)) {
                throw new IOException("credit 帧提取失败");
            }
            append(report, "Credit shape accepted", true);
            append(report, "Credit strict first-frame gate", true);
            append(report, "Second data36 rejected", true);
            append(report, "Credit frame SHA-256", requireSha256(credit));
            append(report, "Credit semantics claim",
                    "仅 vendor 短 0/1 首帧格式；非注入/射频成功");
            append(report, "Result",
                    "通过：步骤4 离线单 data36 冻结帧 + 严格 credit 门");
            return new ProbeResult(true, report.toString());
        } catch (Throwable error) {
            append(report, "Error", error.getMessage());
            append(report, "Result", "失败：步骤4 离线 "
                    + error.getMessage());
            return new ProbeResult(false, report.toString());
        }
    }

    /**
     * 返回步骤2冻结 unit0 的 44 字节线帧；哈希不符则硬失败。
     */
    static byte[] requirePlainExternalTxFrameUnit0() throws IOException {
        byte[] frame = createFrozenExternalEncodedTxFrame(0);
        if (frame == null || frame.length != 44) {
            throw new IOException("冻结 unit0 线帧长度必须为 44");
        }
        String hash = requireSha256(frame);
        if (!REAL_RX_EXTERNAL_TX_FRAME_UNIT0_SHA256.equals(hash)) {
            throw new IOException("冻结 unit0 线帧哈希不符: " + hash);
        }
        byte[] unit = extractFrozenData36Unit(REAL_RX_AMBE_108_BYTES, 0);
        if (!REAL_RX_DATA36_UNIT0_SHA256.equals(requireSha256(unit))) {
            throw new IOException("冻结 data36 unit0 载荷哈希不符");
        }
        return frame;
    }

    /**
     * 由步骤2冻结明文和固定0.3.66 privacy参数生成首个主机侧密文单元。
     * raw UART-HPI bridge绕过MCU普通27字节privacy链，设备路径只能发送此固定密文。
     */
    static byte[] requireHostEncryptedExternalTxFrameUnit0() throws IOException {
        byte[] plain = extractFrozenData36Unit(REAL_RX_AMBE_108_BYTES, 0);
        byte[] encrypted = applyDmrPrivacyRc4(plain,
                EXTERNAL_DMR_PRIVACY_KEY5, EXTERNAL_DMR_PRIVACY_MI);
        byte[] fragments = createDmrLateEntryFragments(
                evolveDmrPrivacyMi(EXTERNAL_DMR_PRIVACY_MI));
        for (int frame = 0; frame < 4; frame++) {
            setDmrC3HighNibble(encrypted, frame * 9, fragments[frame] & 0x0f);
        }
        byte[] wire = createExternalEncodedTxFrame(encrypted, 0);
        if (wire == null || wire.length != 44
                || !looksLikeExternalData36Frame(wire)) {
            throw new IOException("主机privacy密文线帧形状错误");
        }
        if (Arrays.equals(wire, requirePlainExternalTxFrameUnit0())) {
            throw new IOException("主机privacy密文不得等于冻结AMBE明文帧");
        }
        String payloadHash = requireSha256(Arrays.copyOfRange(wire, 8, 44));
        String wireHash = requireSha256(wire);
        if (!EXTERNAL_DMR_PRIVACY_DATA36_UNIT0_SHA256.equals(payloadHash)
                || !EXTERNAL_DMR_PRIVACY_FRAME_UNIT0_SHA256.equals(wireHash)) {
            throw new IOException("主机privacy密文固定向量哈希不符 payload="
                    + payloadHash + " wire=" + wireHash);
        }
        return wire;
    }

    /**
     * 使用本次同机14字节运行快照，为实时relay明文生成一个36字节privacy线帧。
     * session[0..4]是5字节密钥材料，session[5..8]是本次MI；禁止离线常量替代。
     */
    static byte[] createRealtimeRelayEncryptedData36Frame(byte[] plain36,
            byte[] measuredRuntime14) throws IOException {
        if (plain36 == null || plain36.length != EXT_ENC_TX_UNIT_BYTES) {
            throw new IOException("实时relay明文必须恰好36字节");
        }
        if (measuredRuntime14 == null || measuredRuntime14.length != 14) {
            throw new IOException("实时relay必须使用本次实测14字节运行快照");
        }
        byte[] key5 = Arrays.copyOfRange(measuredRuntime14, 5, 10);
        byte[] mi = Arrays.copyOfRange(measuredRuntime14, 10, 14);
        byte[] encrypted = applyDmrPrivacyRc4(plain36, key5, mi);
        byte[] fragments = createDmrLateEntryFragments(evolveDmrPrivacyMi(mi));
        for (int frame = 0; frame < 4; frame++) {
            setDmrC3HighNibble(encrypted, frame * 9,
                    fragments[frame] & 0x0f);
        }
        byte[] wire = createExternalEncodedTxFrame(encrypted, 0);
        if (wire == null || wire.length != 44
                || !looksLikeExternalData36Frame(wire)) {
            throw new IOException("实时relay privacy线帧形状错误");
        }
        return wire;
    }

    /** 标准RC4，9字节KSA输入为key5||MI，丢弃256字节并逐帧处理49位。 */
    static byte[] applyDmrPrivacyRc4(byte[] source, byte[] key5, byte[] mi) {
        if (source == null || source.length == 0 || source.length % 9 != 0
                || key5 == null || key5.length != 5
                || mi == null || mi.length != 4) {
            throw new IllegalArgumentException("DMR privacy输入长度错误");
        }
        byte[] key9 = concatBytes(key5, mi);
        int[] box = new int[256];
        for (int index = 0; index < box.length; index++) {
            box[index] = index;
        }
        int j = 0;
        for (int index = 0; index < box.length; index++) {
            j = (j + box[index] + (key9[index % key9.length] & 0xff)) & 0xff;
            int swap = box[index];
            box[index] = box[j];
            box[j] = swap;
        }
        int i = 0;
        j = 0;
        for (int discard = 0; discard < 256; discard++) {
            i = (i + 1) & 0xff;
            j = (j + box[i]) & 0xff;
            int swap = box[i];
            box[i] = box[j];
            box[j] = swap;
            int ignored = box[(box[i] + box[j]) & 0xff];
            if (ignored < 0) {
                throw new AssertionError();
            }
        }
        byte[] result = source.clone();
        for (int frame = 0; frame < result.length / 9; frame++) {
            int offset = frame * 9;
            for (int item = 0; item < 7; item++) {
                i = (i + 1) & 0xff;
                j = (j + box[i]) & 0xff;
                int swap = box[i];
                box[i] = box[j];
                box[j] = swap;
                int stream = box[(box[i] + box[j]) & 0xff];
                if (item < 6) {
                    result[offset + item] ^= (byte) stream;
                } else {
                    result[offset + item] ^= (byte) (stream & 0x80);
                }
            }
        }
        return result;
    }

    /** 固件0x0802020C的32轮MI演进，输入输出均为大端字节序。 */
    static byte[] evolveDmrPrivacyMi(byte[] mi) {
        if (mi == null || mi.length != 4) {
            throw new IllegalArgumentException("MI必须为4字节");
        }
        int value = ((mi[0] & 0xff) << 24) | ((mi[1] & 0xff) << 16)
                | ((mi[2] & 0xff) << 8) | (mi[3] & 0xff);
        for (int round = 0; round < 32; round++) {
            int feedback = ((value >>> 31) ^ (value >>> 3)
                    ^ (value >>> 1)) & 1;
            value = (value << 1) | feedback;
        }
        return new byte[] {(byte) (value >>> 24), (byte) (value >>> 16),
                (byte) (value >>> 8), (byte) value};
    }

    /** 生成三个扩展Golay(24,12)码字并按固定固件索引交织为18个半字节。 */
    static byte[] createDmrLateEntryFragments(byte[] mi) {
        if (mi == null || mi.length != 4) {
            throw new IllegalArgumentException("Late Entry MI必须为4字节");
        }
        boolean[] data36 = new boolean[36];
        for (int bit = 0; bit < 32; bit++) {
            data36[bit] = ((mi[bit / 8] >>> (7 - (bit % 8))) & 1) != 0;
        }
        int crc = dmrCrc4(mi);
        for (int bit = 0; bit < 4; bit++) {
            data36[32 + bit] = ((crc >>> (3 - bit)) & 1) != 0;
        }
        boolean[] code = new boolean[72];
        int[] parityRows = {0xc75, 0x63b, 0xf68, 0x7b4, 0x3da, 0xd99,
                0x6cd, 0x367, 0xdc6, 0xa97, 0x93e, 0x8eb};
        for (int block = 0; block < 3; block++) {
            int parity = 0;
            for (int bit = 0; bit < 12; bit++) {
                boolean value = data36[block * 12 + bit];
                code[block * 24 + bit] = value;
                if (value) {
                    parity ^= parityRows[bit];
                }
            }
            for (int bit = 0; bit < 12; bit++) {
                code[block * 24 + 12 + bit] =
                        ((parity >>> (11 - bit)) & 1) != 0;
            }
        }
        byte[] fragments = new byte[18];
        for (int fragment = 0; fragment < 18; fragment++) {
            int value = 0;
            for (int bit = 0; bit < 4; bit++) {
                int source = 24 * (fragment % 3)
                        + 4 * (fragment / 3) + bit;
                value = (value << 1) | (code[source] ? 1 : 0);
            }
            fragments[fragment] = (byte) value;
        }
        return fragments;
    }

    private static int dmrCrc4(byte[] mi) {
        int[] work = new int[36];
        for (int bit = 0; bit < 32; bit++) {
            work[bit] = (mi[bit / 8] >>> (7 - (bit % 8))) & 1;
        }
        for (int bit = 0; bit < 32; bit++) {
            if (work[bit] != 0) {
                work[bit] ^= 1;
                work[bit + 3] ^= 1;
                work[bit + 4] ^= 1;
            }
        }
        int crc = 0;
        for (int bit = 32; bit < 36; bit++) {
            crc = (crc << 1) | work[bit];
        }
        return crc ^ 0x0f;
    }

    /** 标准air interleave中C3[0..3]分别位于输入bit 21、71、69、67。 */
    static void setDmrC3HighNibble(byte[] frames, int offset, int nibble) {
        if (frames == null || offset < 0 || offset + 9 > frames.length
                || (nibble & ~0x0f) != 0) {
            throw new IllegalArgumentException("C3半字节参数错误");
        }
        int[] bitPositions = {21, 71, 69, 67};
        for (int bit = 0; bit < 4; bit++) {
            int position = bitPositions[bit];
            int byteIndex = offset + position / 8;
            int mask = 1 << (7 - (position % 8));
            if (((nibble >>> (3 - bit)) & 1) != 0) {
                frames[byteIndex] |= (byte) mask;
            } else {
                frames[byteIndex] &= (byte) ~mask;
            }
        }
    }

    private static String requireSha256(byte[] value) throws IOException {
        try {
            return sha256(value);
        } catch (Exception error) {
            throw new IOException("SHA-256 failed: " + error.getMessage(), error);
        }
    }

    /**
     * 44 字节 External encoded TX 数据帧形状检测。步骤3 请求流中不得出现。
     */
    static boolean looksLikeExternalData36Frame(byte[] frame) {
        if (frame == null || frame.length < 44) {
            return false;
        }
        return (frame[0] & 0xff) == 0x84
                && (frame[1] & 0xff) == 0xa9
                && (frame[2] & 0xff) == 0x61
                && (frame[3] & 0xff) == 0x00
                && (frame[4] & 0xff) == 0x26
                && (frame[5] & 0xff) == 0x03
                && (frame[6] & 0xff) == 0x01
                && (frame[7] & 0xff) == 0x24;
    }

    private static byte[] le32(int value) {
        return new byte[] {
                (byte) value,
                (byte) (value >>> 8),
                (byte) (value >>> 16),
                (byte) (value >>> 24)
        };
    }

    /**
     * 步骤3 arm 前门：bridge flag、原 SysTick、临时窗口、counter/marker、
     * 将被替换的 handler 字节与完整哈希必须全部通过后才允许上传/arm。
     */
    static final class UartHpiTimeoutArmGate {
        private UartHpiTimeoutArmGate() {}

        static void validateCleanBaseline(byte[] flag, byte[] vector,
                byte[] code, byte[] counter, byte[] marker, byte[] handler)
                throws IOException {
            if (handler == null
                    || !UART_HPI_TIMEOUT_HANDLER_SHA256.equals(
                    requireSha256(handler))) {
                throw new IOException("Timeout handler hash mismatch");
            }
            if (handler.length != 64 || (handler.length & 3) != 0) {
                throw new IOException("Timeout handler length invalid");
            }
            if (flag == null || flag.length != 1 || (flag[0] & 0xff) != 0) {
                throw new IOException("UART-HPI bridge already active");
            }
            if (vector == null || vector.length != 4
                    || u32le(vector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected SysTick vector baseline");
            }
            if (code == null || code.length != handler.length || !allZero(code)) {
                throw new IOException("Temporary code window is not empty");
            }
            if (counter == null || counter.length != 4 || !allZero(counter)) {
                throw new IOException("Timeout counter window is not empty");
            }
            if (marker == null || marker.length != 4 || !allZero(marker)) {
                throw new IOException("Timeout marker window is not empty");
            }
        }

        static void validateUploadReadback(byte[] expected, byte[] uploaded)
                throws IOException {
            if (expected == null || uploaded == null
                    || !Arrays.equals(expected, uploaded)) {
                throw new IOException("Timeout handler upload mismatch");
            }
            if (!UART_HPI_TIMEOUT_HANDLER_SHA256.equals(
                    requireSha256(uploaded))) {
                throw new IOException("Uploaded handler hash mismatch");
            }
        }

        static void validatePostTimeoutRecovery(byte[] flag, byte[] vector,
                byte[] counter, byte[] marker) throws IOException {
            if (flag == null || flag.length != 1 || (flag[0] & 0xff) != 0) {
                throw new IOException("Bridge flag not cleared by timeout");
            }
            if (vector == null || vector.length != 4
                    || u32le(vector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("SysTick vector not restored by timeout");
            }
            if (counter == null || counter.length != 4
                    || u32le(counter, 0) != 0) {
                throw new IOException("Timeout counter not zero after exit");
            }
            if (marker == null || marker.length != 4
                    || u32le(marker, 0) != UART_HPI_TIMEOUT_MARKER) {
                throw new IOException("Timeout marker missing after exit");
            }
        }
    }

    enum Step3TransportState {
        TEXT_CONFIRMED,
        SRAM_MAY_BE_DIRTY,
        BRIDGE_MAY_BE_ACTIVE,
        BRIDGE_ACTIVE,
        TEXT_AFTER_TIMEOUT_CONFIRMED,
        RECOVERY_UNCERTAIN
    }

    /** 步骤3只用该状态机决定当前允许发送文本还是HPI字节。 */
    static final class Step3TransportTracker {
        private Step3TransportState state = Step3TransportState.TEXT_CONFIRMED;

        Step3TransportState state() {
            return state;
        }

        void beforeTemporarySramWrite() throws IOException {
            // 允许第二 bridge 阶段：setup 退桥恢复后为 TEXT_AFTER_TIMEOUT_CONFIRMED
            if (state != Step3TransportState.TEXT_CONFIRMED
                    && state != Step3TransportState.TEXT_AFTER_TIMEOUT_CONFIRMED) {
                throw new IOException("临时SRAM写入前状态异常: " + state);
            }
            state = Step3TransportState.SRAM_MAY_BE_DIRTY;
        }

        /** setup 阶段退桥并恢复临时窗口后，准备再次 arm bridge 发 VLC。 */
        void readyForSecondBridgePhase() throws IOException {
            if (state != Step3TransportState.TEXT_AFTER_TIMEOUT_CONFIRMED) {
                throw new IOException("第二bridge阶段状态异常: " + state);
            }
            state = Step3TransportState.TEXT_CONFIRMED;
        }

        void beforeBridgeFlagWrite() throws IOException {
            requireState(Step3TransportState.SRAM_MAY_BE_DIRTY,
                    "置bridge flag前状态异常");
            state = Step3TransportState.BRIDGE_MAY_BE_ACTIVE;
        }

        void bridgeFlagWriteReturned() throws IOException {
            requireState(Step3TransportState.BRIDGE_MAY_BE_ACTIVE,
                    "bridge flag返回后状态异常");
            state = Step3TransportState.BRIDGE_ACTIVE;
        }

        void commandModeConfirmedFromFlag(byte[] flag) throws IOException {
            if (flag == null || flag.length != 1 || (flag[0] & 0xff) != 0) {
                state = Step3TransportState.RECOVERY_UNCERTAIN;
                throw new IOException("退桥后bridge flag未确认清零");
            }
            if (!needsTimeoutWait()) {
                throw new IOException("确认退桥时状态异常: " + state);
            }
            state = Step3TransportState.TEXT_AFTER_TIMEOUT_CONFIRMED;
        }

        void temporaryStateRestored() throws IOException {
            if (!canAttemptAsciiRestore()) {
                throw new IOException("临时状态恢复时文本面未确认: " + state);
            }
            state = Step3TransportState.TEXT_AFTER_TIMEOUT_CONFIRMED;
        }

        void recoveryUncertain() {
            state = Step3TransportState.RECOVERY_UNCERTAIN;
        }

        boolean needsTimeoutWait() {
            return state == Step3TransportState.BRIDGE_MAY_BE_ACTIVE
                    || state == Step3TransportState.BRIDGE_ACTIVE;
        }

        boolean maySendHpiCleanup() {
            return state == Step3TransportState.BRIDGE_ACTIVE;
        }

        boolean canAttemptAsciiRestore() {
            return state == Step3TransportState.SRAM_MAY_BE_DIRTY
                    || state == Step3TransportState.TEXT_AFTER_TIMEOUT_CONFIRMED;
        }

        private void requireState(Step3TransportState expected, String message)
                throws IOException {
            if (state != expected) {
                throw new IOException(message + ": " + state);
            }
        }
    }

    interface Step3WordWriter {
        void write(int address, int value) throws Exception;
    }

    interface Step3FlagWriter {
        void write() throws Exception;
    }

    static void uploadStep3TimeoutHandler(Step3TransportTracker transport,
            byte[] handler, Step3WordWriter writer) throws Exception {
        if (transport == null || handler == null || writer == null
                || handler.length != 64 || (handler.length & 3) != 0) {
            throw new IllegalArgumentException("步骤3处理器上传参数无效");
        }
        // 第一个设备写入发生前先推进状态，覆盖“写入已生效但调用抛错”。
        transport.beforeTemporarySramWrite();
        for (int offset = 0; offset < handler.length; offset += 4) {
            writer.write(UART_HPI_TIMEOUT_CODE_ADDRESS + offset,
                    u32le(handler, offset));
        }
    }

    static void activateStep3Bridge(Step3TransportTracker transport,
            Step3FlagWriter writer) throws Exception {
        if (transport == null || writer == null) {
            throw new IllegalArgumentException("步骤3bridge激活参数无效");
        }
        // flag命令发出前先推进状态；只有调用明确返回后才允许HPI清理。
        transport.beforeBridgeFlagWrite();
        writer.write();
        transport.bridgeFlagWriteReturned();
    }

    private static final class Step3EvidenceRecord {
        final String label;
        final String filePrefix;
        final byte[] raw;
        final String sramStage;
        final int sramAddress;

        Step3EvidenceRecord(String label, String filePrefix, byte[] raw) {
            this(label, filePrefix, raw, "", -1);
        }

        Step3EvidenceRecord(String label, String filePrefix, byte[] raw,
                String sramStage, int sramAddress) {
            this.label = label;
            this.filePrefix = filePrefix;
            this.raw = raw.clone();
            this.sramStage = sramStage;
            this.sramAddress = sramAddress;
        }
    }

    /**
     * 步骤3 单次 setup/VLC 交换：静默窗 → 写 → 读 → 模型确认门。
     * {@code setupPhase=true} 只接受 setup ACK；false 只接受 VLC ACK（含真机 type0x20）。
     *
     * @param labelOverride 非空时覆盖默认 setupN/vlcN 标签（v1.91 attempt 分桶）
     * @param allowSetup0StrictEmptyRetry 仅 setup0 且双空时可返回 true 请求一次重试
     * @return true 表示调用方应对同一 setup0 再交换一次；false 表示本交换已成功结束
     */
    private boolean runOneExternalDmrControlExchange(
            ExternalDmrTxModel model, boolean setupPhase,
            InputStream input, OutputStream output,
            Step3TransportTracker transport,
            List<Step3EvidenceRecord> evidenceRecords,
            ByteArrayOutputStream transcript, long transcriptStartedNanos,
             StringBuilder report, String labelOverride,
             boolean allowSetup0StrictEmptyRetry,
             ExternalDmrRealtimeRelayContext realtimeRelay,
             ActiveHpiStreamRouter activeRouter,
             ExternalDmrControlTxProgress txProgress) throws Exception {
        if (transport == null
                || transport.state() != Step3TransportState.BRIDGE_ACTIVE) {
            throw new IOException("控制交换要求 BRIDGE_ACTIVE");
        }
        int index = setupPhase ? model.setupAcks() : model.vlcAcks();
        byte[] request = model.expectedRequest();
        if (request == null) {
            throw new IOException("expectedRequest 为空 phase="
                    + model.phase() + " index=" + index);
        }
        if (looksLikeExternalData36Frame(request)
                || model.canSerializeData36()) {
            throw new IOException("控制会话阶段禁止序列化或发送 data36");
        }
        if (setupPhase && model.phase() != ExternalDmrTxModel.Phase.SETUP) {
            throw new IOException("setup 交换阶段状态错误: " + model.phase());
        }
        if (!setupPhase
                && model.phase() != ExternalDmrTxModel.Phase.VLC_SESSION) {
            throw new IOException("VLC 交换阶段状态错误: " + model.phase());
        }
        String label = (labelOverride != null && labelOverride.length() > 0)
                ? labelOverride
                : ((setupPhase ? "setup" : "vlc") + index);
        long quietBeginMs = SystemClock.elapsedRealtime();
        QuietDrainResult quiet;
        boolean useActiveFrameBoundary = shouldUseActiveFrameBoundary(
                setupPhase, activeRouter != null);
        if (useActiveFrameBoundary) {
            ActiveHpiRead boundary = activeRouter.drainToFrameBoundary(input,
                    EXTERNAL_DMR_PRE_SEND_QUIET_MAX_MS);
            long boundaryAt = SystemClock.elapsedRealtime();
            quiet = new QuietDrainResult(boundary.observed,
                    boundaryAt - quietBeginMs,
                    activeFrameBoundaryProof(boundaryAt));
        } else {
            quiet = drainUntilQuietCapture(input,
                    EXTERNAL_DMR_PRE_SEND_QUIET_MS,
                    EXTERNAL_DMR_PRE_SEND_QUIET_MAX_MS);
        }
        long quietEndMs = SystemClock.elapsedRealtime();
        boolean boundaryVerified = useActiveFrameBoundary
                ? quiet.proof != null
                : quiet.proof != null && quiet.proof.isVerifiedCapture()
                && quiet.proof.quietDurationMs()
                >= EXTERNAL_DMR_PRE_SEND_QUIET_MS;
        if (!boundaryVerified) {
            throw new IOException(useActiveFrameBoundary
                    ? "步骤3未取得完整HPI帧边界"
                    : "步骤3未取得足量连续静默的真实证明");
        }
        recordStep3Evidence(evidenceRecords, transcript,
                transcriptStartedNanos, STEP3_TRANSCRIPT_DRAIN,
                label + " quiet drain", "", quiet.raw, false);
        if (!setupPhase && realtimeRelay != null) {
            realtimeRelay.acceptCompleteCapture(quiet.raw,
                    label + "发送前静默排空");
        }
        append(report, label + (useActiveFrameBoundary
                ? " active-frame-boundary ms" : " quiet window ms"),
                quiet.elapsedMs);
        append(report, label + " quiet begin monoMs", quietBeginMs);
        append(report, label + " quiet end monoMs", quietEndMs);
        Log.i(TAG, String.format(Locale.US,
                "TIMING_QUIET label=%s beginMs=%d endMs=%d elapsedMs=%d rawBytes=%d",
                label, quietBeginMs, quietEndMs, quiet.elapsedMs,
                quiet.raw != null ? quiet.raw.length : 0));
        recordStep3Evidence(evidenceRecords, transcript,
                transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                label + " request TX attempt",
                "h13_ext_dmr_step3_" + label + "_req_",
                request, true);
        // 真正上线写出时刻（quiet 完成之后、write 之前/之后）——勿与交换开始标签混淆
        long wireTxMs = SystemClock.elapsedRealtime();
        Log.i(TAG, String.format(Locale.US,
                "TIMING_SETUP_WIRE_TX label=%s monoMs=%d quietEndedAgoMs=%d",
                label, wireTxMs, wireTxMs - quietEndMs));
        append(report, label + " wire tx monoMs", wireTxMs);
        if (!setupPhase && realtimeRelay != null) {
            realtimeRelay.onVlcWireTx(index, wireTxMs);
        }
        output.write(request);
        output.flush();
        if (txProgress != null) {
            txProgress.recordWriteCompleted(setupPhase, index);
        }
        long wireTxDoneMs = SystemClock.elapsedRealtime();
        Log.i(TAG, String.format(Locale.US,
                "TIMING_SETUP_WIRE_TX_DONE label=%s monoMs=%d writeMs=%d",
                label, wireTxDoneMs, wireTxDoneMs - wireTxMs));
        recordStep3Evidence(evidenceRecords, transcript,
                transcriptStartedNanos, STEP3_TRANSCRIPT_TX_COMPLETE,
                label + " request TX complete", "", new byte[0], false);
        ExternalDmrTxModel.ExchangeWindow window =
                model.openPostSendWindow(request, quiet.proof);
        if (window == null) {
            throw new IOException("接收窗口未建立 phase="
                    + model.phase() + " index=" + index);
        }
        long rxWindowBeginMs = SystemClock.elapsedRealtime();
        byte[] response;
        byte[] responseForModel;
        if (activeRouter != null) {
            final int expectedPacketType = request[5] & 0xff;
            final int expectedField = request[6] & 0xff;
            ActiveHpiRead activeRead = activeRouter.readUntil(input,
                    EXTERNAL_DMR_VLC_SESSION_ACK_TIMEOUT_MS,
                    new HpiFrameMatcher() {
                        @Override
                        public boolean matches(byte[] frame) {
                            return setupPhase
                                    ? isExactSingleControlStatusAck(frame,
                                    expectedPacketType, expectedField)
                                    : containsDmrVlcSessionAck(frame);
                        }
                    });
            response = activeRead.observed;
            responseForModel = activeRead.matchedFrame;
        } else {
            response = !setupPhase && realtimeRelay != null
                    ? readForDurationWithRealtimeRelay(input,
                            EXTERNAL_DMR_VLC_SESSION_ACK_TIMEOUT_MS,
                            realtimeRelay, label + "响应窗口")
                    : readForDuration(input,
                            EXTERNAL_DMR_VLC_SESSION_ACK_TIMEOUT_MS);
            responseForModel = response;
        }
        long rxWindowEndMs = SystemClock.elapsedRealtime();
        Log.i(TAG, String.format(Locale.US,
                "TIMING_ACK_WINDOW label=%s beginMs=%d endMs=%d timeoutMs=%d bytes=%d",
                label, rxWindowBeginMs, rxWindowEndMs,
                EXTERNAL_DMR_VLC_SESSION_ACK_TIMEOUT_MS, response.length));
        append(report, label + " ack window begin monoMs", rxWindowBeginMs);
        append(report, label + " ack window end monoMs", rxWindowEndMs);
        recordStep3Evidence(evidenceRecords, transcript,
                transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                label + " response raw",
                "h13_ext_dmr_step3_" + label + "_rsp_",
                response, true);
        append(report, label + " window", window.sequence());
        append(report, label + " request SHA-256", sha256(request));
        append(report, label + " response bytes", response.length);

        // v1.91：setup0 严格双空时先不 fail 模型，允许一次原样重试。
        // 任何非空字节（含畸形）一律不重试，走严格确认门。
        if (setupPhase && index == 0 && response.length == 0) {
            long lateBeginMs = SystemClock.elapsedRealtime();
            byte[] lateBytes = readForDuration(input,
                    EXTERNAL_DMR_POST_TIMEOUT_LATE_CAPTURE_MS);
            long lateEndMs = SystemClock.elapsedRealtime();
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                    label + " late capture raw",
                    "h13_ext_dmr_step3_" + label + "_late_",
                    lateBytes, true);
            append(report, label + " late capture bytes", lateBytes.length);
            append(report, label + " late capture monoMs",
                    lateBeginMs + ".." + lateEndMs);
            Log.w(TAG, String.format(Locale.US,
                    "LATE_CAPTURE label=%s bytes=%d beginMs=%d endMs=%d hex=%s",
                    label, lateBytes.length, lateBeginMs, lateEndMs,
                    bytesToHex(lateBytes)));
            if (lateBytes.length == 0 && allowSetup0StrictEmptyRetry
                    && model.abandonActiveWindowForSetup0EmptyRetry(window)) {
                append(report, label + " accepted", false);
                append(report, label + " empty_retry_eligible", true);
                Log.i(TAG, "SETUP0_STRICT_EMPTY_RETRY_ELIGIBLE label=" + label);
                return true;
            }
            model.acceptTimeout(window);
            append(report, label + " accepted", false);
            throw new IOException(label
                    + " 确认门失败；setup0 双空且不可重试或已用尽；"
                    + "停止后续请求，等待 SysTick 退桥"
                    + " lateBytes=" + lateBytes.length);
        }

        boolean accepted;
        if (setupPhase) {
            accepted = model.acceptSetupExchange(window, responseForModel);
        } else {
            accepted = model.acceptVlcExchange(window, responseForModel);
        }
        append(report, label + " accepted", accepted);
        if (!accepted) {
            // 只读晚到捕获：不发送任何字节，再观察一轮，区分 ACK 迟到 vs 完全无响应
            long lateBeginMs = SystemClock.elapsedRealtime();
            byte[] lateBytes = readForDuration(input,
                    EXTERNAL_DMR_POST_TIMEOUT_LATE_CAPTURE_MS);
            long lateEndMs = SystemClock.elapsedRealtime();
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                    label + " late capture raw",
                    "h13_ext_dmr_step3_" + label + "_late_",
                    lateBytes, true);
            append(report, label + " late capture bytes", lateBytes.length);
            append(report, label + " late capture monoMs",
                    lateBeginMs + ".." + lateEndMs);
            Log.w(TAG, String.format(Locale.US,
                    "LATE_CAPTURE label=%s bytes=%d beginMs=%d endMs=%d hex=%s",
                    label, lateBytes.length, lateBeginMs, lateEndMs,
                    bytesToHex(lateBytes)));
            // 非空畸形/截断：禁止重试
            throw new IOException(label
                    + " 确认门失败；停止后续请求，等待 SysTick 退桥"
                    + " lateBytes=" + lateBytes.length
                    + " rspBytes=" + response.length);
        }
        return false;
    }

    /**
     * 步骤3/4 真机会话执行体（private）。
     * v1.74：单 bridge；multi-tick fullprep；严格残留准入；setup 最坏预算延迟 +
     * 主机确认 setup4 早于 prep 截止；可选仅隔离（无 VLC）。
     * 仍禁文本 memwrite 会话准备。
     */
    private ProbeResult executeExternalDmrVlcSessionNoRf(
            boolean sendOneHostEncryptedData36, boolean runVlcSession,
            boolean setup0Only, boolean setup04Only,
            boolean sendRealtimeRelayData36) {
        return executeExternalDmrVlcSessionNoRf(sendOneHostEncryptedData36,
                runVlcSession, setup0Only, setup04Only,
                sendRealtimeRelayData36, null);
    }

    private ProbeResult executeExternalDmrVlcSessionNoRf(
            boolean sendOneHostEncryptedData36, boolean runVlcSession,
            boolean setup0Only, boolean setup04Only,
            boolean sendRealtimeRelayData36, byte[] fixedAssetBytes) {
        return executeExternalDmrVlcSessionNoRf(sendOneHostEncryptedData36,
                runVlcSession, setup0Only, setup04Only,
                sendRealtimeRelayData36, fixedAssetBytes, null);
    }

    private ProbeResult executeExternalDmrVlcSessionNoRf(
            boolean sendOneHostEncryptedData36, boolean runVlcSession,
            boolean setup0Only, boolean setup04Only,
            boolean sendRealtimeRelayData36, byte[] fixedAssetBytes,
            byte[] generatedPlain36) {
        return executeExternalDmrVlcSessionNoRf(sendOneHostEncryptedData36,
                runVlcSession, setup0Only, setup04Only,
                sendRealtimeRelayData36, fixedAssetBytes, generatedPlain36,
                null, null);
    }

    private ProbeResult executeExternalDmrVlcSessionNoRf(
            boolean sendOneHostEncryptedData36, boolean runVlcSession,
            boolean setup0Only, boolean setup04Only,
            boolean sendRealtimeRelayData36, byte[] fixedAssetBytes,
            byte[] generatedPlain36, byte[] softwarePcmS16le,
            byte[] softwarePlainAmbe) {
        return executeExternalDmrVlcSessionNoRf(sendOneHostEncryptedData36,
                runVlcSession, setup0Only, setup04Only,
                sendRealtimeRelayData36, fixedAssetBytes, generatedPlain36,
                softwarePcmS16le, softwarePlainAmbe, false, false, false);
    }

    private ProbeResult executeExternalDmrVlcSessionNoRf(
            boolean sendOneHostEncryptedData36, boolean runVlcSession,
            boolean setup0Only, boolean setup04Only,
            boolean sendRealtimeRelayData36, byte[] fixedAssetBytes,
            byte[] generatedPlain36, byte[] softwarePcmS16le,
            byte[] softwarePlainAmbe, boolean lowPowerRf,
            boolean fullMorseLowPowerRf) {
        return executeExternalDmrVlcSessionNoRf(sendOneHostEncryptedData36,
                runVlcSession, setup0Only, setup04Only,
                sendRealtimeRelayData36, fixedAssetBytes, generatedPlain36,
                softwarePcmS16le, softwarePlainAmbe, lowPowerRf,
                fullMorseLowPowerRf, false);
    }

    private ProbeResult executeExternalDmrVlcSessionNoRf(
            boolean sendOneHostEncryptedData36, boolean runVlcSession,
            boolean setup0Only, boolean setup04Only,
            boolean sendRealtimeRelayData36, byte[] fixedAssetBytes,
            byte[] generatedPlain36, byte[] softwarePcmS16le,
            byte[] softwarePlainAmbe, boolean lowPowerRf,
            boolean fullMorseLowPowerRf, boolean productionExternalRf) {
        final boolean sendFixedAssetData36 = fixedAssetBytes != null;
        final boolean sendGeneratedData36 = generatedPlain36 != null;
        final boolean softwareAssetSession = softwarePcmS16le != null
                || softwarePlainAmbe != null;
        final boolean softwareSessionReady = softwareAssetSession
                && !sendOneHostEncryptedData36 && !sendRealtimeRelayData36;
        final boolean softwareOneData36 = softwareAssetSession
                && sendOneHostEncryptedData36;
        final boolean softwareRealtimeData36 = softwareAssetSession
                && sendRealtimeRelayData36;
        final boolean softwareData36 = softwareOneData36
                || softwareRealtimeData36;
        final boolean softwareLegacyLowPowerRf = lowPowerRf
                && softwareOneData36;
        final boolean softwareProductionRf = productionExternalRf
                && softwareOneData36;
        final boolean softwareLowPowerRf = softwareLegacyLowPowerRf
                || softwareProductionRf;
        final boolean softwareFullMorseRf = softwareLowPowerRf
                && fullMorseLowPowerRf;
        if (fullMorseLowPowerRf && !softwareLowPowerRf) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：完整摩尔斯射频模式必须绑定软件AMBE低功率入口");
        }
        if (productionExternalRf && (!softwareFullMorseRf || lowPowerRf)) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：生产同构RF必须是完整摩尔斯且禁止旧DMOPTT入口");
        }
        if (lowPowerRf && !softwareOneData36) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：低功率射频只允许软件AMBE单data36入口");
        }
        if ((softwarePcmS16le == null) != (softwarePlainAmbe == null)) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：软件PCM与AMBE必须成对提供");
        }
        if (softwareAssetSession && (!runVlcSession
                || setup0Only || setup04Only || sendFixedAssetData36
                || sendGeneratedData36)) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：软件AMBE模式只能运行完整VLC并选择硬停止、五VLC后单data36或实时触发单data36");
        }
        if (softwareAssetSession && (softwarePcmS16le.length == 0
                || softwarePcmS16le.length % 320 != 0)) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：软件摩尔斯PCM不是完整160采样帧序列");
        }
        if (softwareAssetSession && (softwarePlainAmbe.length == 0
                || softwarePlainAmbe.length % EXT_ENC_TX_UNIT_BYTES != 0
                || softwarePlainAmbe.length / REAL_RX_AMBE_FRAME_BYTES
                != softwarePcmS16le.length / 320)) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：软件摩尔斯AMBE与PCM帧数或data36边界不一致");
        }
        if (sendGeneratedData36 && generatedPlain36.length != 36) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：内置编码器载荷必须恰好36字节");
        }
        if (sendGeneratedData36 && !sendOneHostEncryptedData36) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：内置编码器载荷必须走单data36严格执行器");
        }
        if (setup0Only && setup04Only) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：setup0-only 与 setup0-4-only 互斥");
        }
        if (sendOneHostEncryptedData36 && !runVlcSession) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：data36 需要 VLC 会话路径");
        }
        if (sendRealtimeRelayData36 && !runVlcSession) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：实时relay data36需要VLC会话路径");
        }
        if (sendFixedAssetData36 && !sendRealtimeRelayData36) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：固定资产载荷必须复用实时三单元触发路径");
        }
        if (sendOneHostEncryptedData36 && sendRealtimeRelayData36) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    new StringBuilder(),
                    "阻断：冻结data36与实时relay模式互斥");
        }
        final boolean silentSetupOnly = setup0Only || setup04Only;
        final boolean activeData36 = sendOneHostEncryptedData36
                || sendRealtimeRelayData36;
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalCode = null;
        byte[] originalCounter = null;
        byte[] originalMarker = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        byte[] originalDatagateOneshot = null;
        byte[] originalDatagateMarker = null;
        byte[] originalDatagateCounter = null;
        byte[] originalAbsCounter = null;
        byte[] originalExitMarker = null;
        byte[] originalDataGate = null;
        byte[] originalSessionState = null;
        byte[] originalPtrA = null;
        byte[] originalPtrB = null;
        byte[] originalFlag1c = null;
        byte[] originalCount = null;
        byte[] originalQueueA = null;
        byte[] originalQueueB = null;
        byte[] originalPrepPhase = null;
        byte[] originalPrepCursor = null;
        byte[] originalMirrorHelper = null;
        byte[] originalRuntimeMirror = null;
        byte[] originalRfPrep = null;
        byte[] originalRfOff = null;
        byte[] originalRfOffMarker = null;
        byte[] originalRfActiveGate = null;
        boolean combinedWindowRestoreRequired = false;
        boolean rfWindowRestoreRequired = false;
        boolean productionRfOffAttempted = false;
        boolean productionRfOffConfirmed = false;
        boolean productionRfPrepareExecuted = false;
        boolean productionRfPreparationWritten = false;
        boolean productionRfWindowStartWritten = false;
        long productionRfMayStartMonotonicMs = -1L;
        long productionRfWindowStartEpoch = -1L;
        Step3TransportTracker transport = new Step3TransportTracker();
        List<Step3EvidenceRecord> evidenceRecords = new ArrayList<>();
        ByteArrayOutputStream transcript = new ByteArrayOutputStream();
        long transcriptStartedNanos = SystemClock.elapsedRealtimeNanos();
        boolean stateRestored = false;
        boolean evidencePersisted = false;
        boolean controlPlaneMutationMayHaveStarted = false;
        boolean controlPlaneReloadAttempted = false;
        boolean controlPlaneRestored = false;
        ExternalDmrPrivacyTransactionState privacyTransaction =
                new ExternalDmrPrivacyTransactionState();
        boolean data36WriteCompleted = false;
        boolean data36CreditAccepted = false;
        boolean softwareHardStopReached = false;
        byte[] softwareEncryptedAmbe = null;
        byte[] softwareWire44Stream = null;
        byte[] softwareFirstRequest = null;
        String softwarePrivacyFinalState = "";
        int rfCommandCount = 0;
        boolean pttOnAttempted = false;
        boolean pttOnAccepted = false;
        boolean txStartObserved = false;
        boolean pttOffAttempted = false;
        boolean pttOffAccepted = false;
        boolean txEndObserved = false;
        boolean audioSwitchBeforePttZero = !softwareLowPowerRf;
        boolean audioSwitchAfterTxStartZero = !softwareLowPowerRf;
        boolean audioSwitchAfterPttOffZero = !softwareLowPowerRf;
        boolean audioSwitchStayedZero = true;
        long pttOnAtMs = -1L;
        long pttOffAtMs = -1L;
        PttHardWatchdog pttWatchdog = null;
        int softwareFullData36WrittenCount = 0;
        int softwareFullCreditCount = 0;
        long softwareFullFirstFlushMs = -1L;
        long softwareFullLastCreditMs = -1L;
        long softwareFullLastFlushMs = -1L;
        long softwareFullMaxPaceLateMs = 0L;
        int softwareFullPaceWindowCount = 0;
        int softwareFullAsyncObservedBytes = 0;
        final ExternalDmrStep4OneUnitExecution data36Execution =
                new ExternalDmrStep4OneUnitExecution();
        boolean outcomeSuccess = false;
        String outcomeStatus = softwareProductionRf
                ? "FAIL: 软件AMBE生产同构External DMR完整摩尔斯低功率空口试验"
                : (softwareFullMorseRf
                ? "FAIL: 软件AMBE完整摩尔斯低功率空口试验"
                : (softwareLowPowerRf
                ? "FAIL: 软件AMBE单data36低功率空口试验"
                : (softwareRealtimeData36
                ? "FAIL: 软件AMBE第三实时单元触发第一条data36"
                : (softwareOneData36
                ? "FAIL: 软件AMBE第一条data36唯一消费"
                : (softwareSessionReady
                ? "FAIL: 软件AMBE真实会话写前硬停止"
                : (sendRealtimeRelayData36
                ? (sendFixedAssetData36
                ? "FAIL: v2.05 固定资产实时触发单data36"
                : "FAIL: v2.03 实时relay单data36")
                : (sendOneHostEncryptedData36
                ? "FAIL: 步骤4 单 data36 credit"
                : (setup0Only
                ? "FAIL: setup0-only 首包重复性"
                : (setup04Only
                ? "FAIL: setup0-4-only 五前序重复性"
                : (runVlcSession
                ? "FAIL: 步骤3 控制会话"
                : "FAIL: setup+fullprep 隔离"))))))))));
        long bridgeArmedAt = 0L;
        long silentWaitMs = EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS
                + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS;
        long worstCaseMs = softwareFullMorseRf
                ? softwareAmbeFullMorseSendDeadlineOffsetMs()
                : (sendRealtimeRelayData36
                ? externalDmrRealtimeRelayWorstCaseMs()
                : (activeData36
                ? externalDmrStep4WorstCaseMs()
                : (setup0Only
                ? externalDmrSetup0OnlyWorstCaseMs()
                : externalDmrStep3WorstCaseMs())));
        boolean budgetOk = softwareFullMorseRf
                ? softwareAmbeFullMorseBudgetFitsBridgeAndWatchdog()
                : (sendRealtimeRelayData36
                ? externalDmrRealtimeRelayBudgetFitsBridgeWindow()
                : (activeData36
                ? externalDmrStep4BudgetFitsBridgeWindow()
                : (setup0Only
                ? externalDmrSetup0OnlyBudgetFitsBridgeWindow()
                : externalDmrStep3BudgetFitsBridgeWindow())));
        boolean setup0FirstOk = false;
        boolean setup0RetryUsed = false;
        boolean setup0RetryOk = false;
        String setup0FailReason = "";
        // finally 原子字段需要读 setup/VLC 计数，故提升到 try 外。
        ExternalDmrTxModel model = null;
        ExternalDmrRealtimeRelayContext realtimeRelay = null;
        ExternalDmrControlTxProgress controlTxProgress =
                new ExternalDmrControlTxProgress();
        final ActiveHpiStreamRouter activeHpiRouter = softwareLowPowerRf
                ? new ActiveHpiStreamRouter() : null;

        append(report, "Mode", softwareProductionRf
                ? "软件AMBE生产同构External DMR完整摩尔斯低功率空口试验（禁止DMOPTT）"
                : (softwareFullMorseRf
                ? "软件AMBE完整26个data36摩尔斯低功率空口试验（H13自动PTT）"
                : (softwareLowPowerRf
                ? "软件AMBE首个data36低功率空口试验（H13自动PTT）"
                : (softwareRealtimeData36
                ? "软件AMBE第三实时单元触发第一条data36（无PTT/无射频命令）"
                : (softwareOneData36
                ? "软件AMBE第一条data36唯一消费（无PTT/无射频命令）"
                : (softwareSessionReady
                ? "软件AMBE真实会话就绪（第一条data36写前硬停止）"
                : (sendRealtimeRelayData36
                ? (sendFixedAssetData36
                ? "External DMR 固定资产unit0实时触发单data36 @57600（v2.05）"
                : "External DMR 实时relay单data36 @57600（v2.03）")
                : (sendOneHostEncryptedData36
                ? "External DMR 单 data36 credit @57600（步骤4）"
                : (setup0Only
                ? "External DMR setup0-only @57600"
                : (setup04Only
                ? "External DMR setup0-4-only @57600（无VLC/无清理）"
                : (runVlcSession
                ? "External DMR 控制会话 @57600（步骤3）"
                : "External DMR setup+fullprep 隔离 @57600（无VLC）")))))))))));
        append(report, "Run VLC session", runVlcSession);
        append(report, "Setup0 only", setup0Only);
        append(report, "Setup0-4 only", setup04Only);
        append(report, "Probe build", probeBuildName());
        append(report, "Device", DEVICE_PATH);
        append(report, "Baud", BAUD_RATE);
        append(report, "Data36", softwareFullMorseRf
                ? "完整发送26个44字节信封；每单元只由新鲜严格credit放行"
                : (softwareRealtimeData36
                ? "完整生成26个信封；第三实时单元只触发第一条软件请求一次并严格观察唯一credit"
                : (softwareOneData36
                ? "完整生成26个信封；只写第一条44字节请求一次并严格观察唯一credit"
                : (softwareSessionReady
                ? "生成完整26个44字节信封；五VLC后只保存第一条请求，串口写调用前硬停止"
                : (sendRealtimeRelayData36
                ? (sendFixedAssetData36
                ? "第三个实时27字节单元只触发时机；发送APK冻结资产unit0；PASS依赖载荷独立性与唯一post-flush credit"
                : "第三个实时27字节单元到达即重组并只写1帧；PASS依赖唯一post-flush credit")
                : (sendOneHostEncryptedData36
                ? (sendGeneratedData36
                ? "仅1帧本次内置编码器生成明文，经实测privacy快照派生密文；PASS依赖credit格式门"
                : "仅1帧步骤2冻结明文派生的固定密文；PASS依赖credit格式门")
                : "禁止"))))));
        append(report, "Write-success-as-PASS", "禁止");
        append(report, "Timeout handler kind",
                "v1.84 combined dual-counter @0x20002F00（迁出 0x20001700 生产重叠区；"
                        + "绝对退桥独立+prep；恢复真实 pre-image）");
        append(report, "RF", softwareProductionRf
                ? "固定low；fullprep后PE6/PF3 low并置active gate；禁止DMOPTT；退桥后0x0801FF34完整关闭；30秒硬断电看门狗"
                : (softwareLowPowerRf
                ? "固定low；旧DMOPTT入口已冻结；30秒硬看门狗"
                : "不发送 AT+DMOPTT；WORK_MODE(2)/五 VLC"
                + (activeData36 ? "/data36" : "")
                + " 仍属潜在发射面，仅在用户当次许可与兼容合同下执行"));
        append(report, "ASCII recovery while bridged", "禁止");
        append(report, "Bridge path worst-case ms", worstCaseMs);
        append(report, "Bridge budget accepted", budgetOk);
        if (softwareFullMorseRf) {
            append(report, "完整摩尔斯预算语义",
                    "80毫秒绝对节拍；异步流只留证不充当credit；总链由16秒绝对发送截止硬截断");
            append(report, "完整摩尔斯发送截止偏移毫秒",
                    softwareAmbeFullMorseSendDeadlineOffsetMs());
            append(report, "完整摩尔斯退桥清理最低余量毫秒",
                    softwareAmbeFullMorseCleanupAllowanceMs());
        }
        append(report, "频道合同", "固定privacy-on、low；无功率覆盖参数");
        append(report, "运行快照来源", "预检凭证内本机实测14字节（禁止合成常量）");
        try {
            requirePinnedExternalDmrLowPowerChannel();
        } catch (IOException contractError) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    report, "阻断：" + contractError.getMessage());
        }
        byte[] expectedMeasuredRuntime14 = null;
        try {
            expectedMeasuredRuntime14 =
                    loadMeasuredRuntimeFromPreflightAttestation();
        } catch (Throwable attestationError) {
            append(report, "预检凭证读取错误",
                    attestationError.getClass().getSimpleName()
                            + ": " + attestationError.getMessage());
        }
        boolean preflightAttested = expectedMeasuredRuntime14 != null
                && expectedMeasuredRuntime14.length
                == EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH + 1
                + EXTERNAL_DMR_SESSION_RECORD_LENGTH;
        append(report, "同版本独立privacy预检凭证", preflightAttested);
        if (preflightAttested) {
            try {
                append(report, "预检实测运行快照SHA-256",
                        requireSha256(expectedMeasuredRuntime14));
            } catch (IOException hashError) {
                return finishExternalDmrLaunchFailure(productionExternalRf,
                        report,
                        "阻断：预检实测运行快照哈希失败: "
                                + hashError.getMessage());
            }
        }
        if (!preflightAttested) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    report,
                    "阻断：缺少同版本独立无HPI privacy预检及完整恢复凭证"
                            + "（须含实测14字节运行快照）");
        }
        if (!budgetOk) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    report, softwareFullMorseRf
                    ? "阻断：完整摩尔斯的16秒发送截止、退桥清理或30秒看门狗预算不自洽"
                    : (activeData36
                    ? "阻断：步骤4最坏路径超过bridge窗口"
                    : "阻断：步骤3最坏路径超过bridge窗口"));
        }
        if (!device.canRead() || !device.canWrite()) {
            return finishExternalDmrLaunchFailure(productionExternalRf,
                    report, "Serial device permission denied");
        }

        try {
            byte[] combinedHandler = wordsToBytes(softwareProductionRf
                    ? EXTERNAL_DMR_RF_COMBINED_WORDS
                    : COMBINED_DUAL_COUNTER_WORDS);
            byte[] mirrorHelper = wordsToBytes(RUNTIME_MIRROR_HELPER_WORDS);
            byte[] rfPrepHandler = wordsToBytes(EXTERNAL_DMR_RF_PREP_WORDS);
            byte[] rfOffHandler = wordsToBytes(EXTERNAL_DMR_RF_OFF_WORDS);
            append(report, "Combined dual-counter SHA-256",
                    sha256(combinedHandler));
            String expectedCombinedHash = softwareProductionRf
                    ? EXTERNAL_DMR_RF_COMBINED_SHA256
                    : COMBINED_DUAL_COUNTER_SHA256;
            if (!expectedCombinedHash.equals(sha256(combinedHandler))) {
                throw new IOException(
                        "Embedded combined dual-counter hash mismatch");
            }
            if ((combinedHandler[0] & 0xff) == 0x72
                    && (combinedHandler[1] & 0xff) == 0x46) {
                throw new IOException(
                        "combined dual-counter forbids mov r2,lr pattern");
            }
            append(report, "Runtime mirror helper SHA-256",
                    sha256(mirrorHelper));
            if (!RUNTIME_MIRROR_HELPER_SHA256.equals(sha256(mirrorHelper))) {
                throw new IOException("Embedded runtime mirror helper hash mismatch");
            }
            if (softwareProductionRf
                    && (!EXTERNAL_DMR_RF_PREP_SHA256.equals(sha256(rfPrepHandler))
                    || !EXTERNAL_DMR_RF_OFF_SHA256.equals(sha256(rfOffHandler)))) {
                throw new IOException("Embedded External DMR RF桩hash不匹配");
            }
            // 兼容旧报告字段名
            append(report, "Datagate oneshot SHA-256",
                    sha256(combinedHandler));

            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);

            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake @57600", printable(connect));
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!containsExactAsciiLine(connect, "+DMOCONNECT:0")
                    || !containsExactAsciiLine(version,
                    "+DMOGETSOFTVERSION:" + EXPECTED_MODULE_VERSION)) {
                throw new IOException("Text baseline failed @57600");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            ExternalDmrStep0Contract contract =
                    prepareExternalDmrPrivacyRuntime(input, output,
                            privacyTransaction, report,
                            expectedMeasuredRuntime14);
            controlPlaneMutationMayHaveStarted = true;
            if (softwareAssetSession) {
                preserveRawEvidenceSummary(report, "软件摩尔斯PCM原件",
                        "software_ambe_session_morse_pcm_", softwarePcmS16le);
                preserveRawEvidence(report, "软件摩尔斯AMBE明文原件",
                        "software_ambe_session_plain_", softwarePlainAmbe);
                byte[] runtime14 = privacyTransaction.measuredRuntime14;
                if (runtime14 == null || runtime14.length != 14) {
                    throw new IOException("未取得同次14字节实测privacy快照");
                }
                preserveRawEvidence(report, "软件会话同次实测privacy快照",
                        "software_ambe_session_runtime14_", runtime14);
                DmrPrivacyStreamContext privacy =
                        DmrPrivacyStreamContext.fromMeasuredRuntime(runtime14);
                ByteArrayOutputStream encryptedStream =
                        new ByteArrayOutputStream();
                ByteArrayOutputStream wireStream = new ByteArrayOutputStream();
                int unitCount = softwarePlainAmbe.length
                        / EXT_ENC_TX_UNIT_BYTES;
                for (int unit = 0; unit < unitCount; unit++) {
                    int offset = unit * EXT_ENC_TX_UNIT_BYTES;
                    byte[] encrypted36 = privacy.encryptData36(
                            Arrays.copyOfRange(softwarePlainAmbe, offset,
                                    offset + EXT_ENC_TX_UNIT_BYTES));
                    encryptedStream.write(encrypted36);
                    byte[] wire = createSoftwareAmbeExternalEncodedTxFrame(
                            encrypted36);
                    if (wire.length != 44
                            || !looksLikeExternalData36Frame(wire)
                            || !Arrays.equals(encrypted36,
                            Arrays.copyOfRange(wire, 8, 44))) {
                        throw new IOException("第" + unit
                                + "个软件AMBE信封合同失败");
                    }
                    wireStream.write(wire);
                }
                softwareEncryptedAmbe = encryptedStream.toByteArray();
                softwareWire44Stream = wireStream.toByteArray();
                softwareFirstRequest = Arrays.copyOfRange(
                        softwareWire44Stream, 0, 44);
                softwarePrivacyFinalState = privacy.stateSummary();
                preserveRawEvidence(report, "软件摩尔斯连续privacy密文",
                        "software_ambe_session_encrypted_",
                        softwareEncryptedAmbe);
                preserveRawEvidence(report, "软件摩尔斯完整44字节信封流",
                        "software_ambe_session_wire44_", softwareWire44Stream);
                append(report, "软件AMBE帧数",
                        softwarePlainAmbe.length / REAL_RX_AMBE_FRAME_BYTES);
                append(report, "软件data36单元数", unitCount);
                append(report, "软件privacy终态", softwarePrivacyFinalState);
            }
            model = new ExternalDmrTxModel(contract);
            append(report, "callslot",
                    String.format(Locale.US, "0x%02x", contract.callSlot()));
            append(report, "LC9", bytesToHex(contract.vlcPayload(0)));
            append(report, "Step3 topology",
                    setup0Only
                            ? "single bridge；仅setup0；禁止其余HPI请求；绝对超时退桥"
                            : (setup04Only
                            ? "single bridge；setup0-4严格确认；禁止VLC/清理帧；绝对超时退桥"
                            : (runVlcSession
                            ? "single bridge；v1.74 multi-tick fullprep"
                            + "（setup最坏预算延迟+主机setup4门）；再VLC"
                            : "single bridge；v1.74 隔离 setup→fullprep→退桥；禁VLC")));
            append(report, "Send-session prep",
                    silentSetupOnly
                            ? "MCU dual-counter仍武装；主机在setup后不发后续HPI；"
                            + "静默等绝对退桥（不发VOCODER_IO_OFF/IDLE）"
                            : ("multi-tick fullprep；prep delay="
                            + MID_BRIDGE_DATAGATE_DELAY_MS
                            + "ms covers setup worst-case；禁文本 memwrite"));

            originalFlag = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            originalDatagateOneshot = readMemory(input, output,
                    COMBINED_DUAL_COUNTER_CODE_ADDRESS, combinedHandler.length);
            originalDatagateMarker = readMemory(input, output,
                    COMBINED_PREP_MARKER_ADDRESS, 4);
            originalDatagateCounter = readMemory(input, output,
                    COMBINED_PREP_COUNTER_ADDRESS, 4);
            originalAbsCounter = readMemory(input, output,
                    COMBINED_ABS_COUNTER_ADDRESS, 4);
            originalExitMarker = readMemory(input, output,
                    COMBINED_EXIT_MARKER_ADDRESS, 4);
            originalPrepPhase = readMemory(input, output,
                    COMBINED_PREP_PHASE_ADDRESS, 4);
            originalPrepCursor = readMemory(input, output,
                    COMBINED_PREP_CURSOR_ADDRESS, 4);
            originalRuntimeMirror = readMemory(input, output,
                    RUNTIME_MIRROR_ADDRESS, RUNTIME_MIRROR_LENGTH);
            originalMirrorHelper = readMemory(input, output,
                    RUNTIME_MIRROR_HELPER_ADDRESS, mirrorHelper.length);
            if (softwareProductionRf) {
                originalRfPrep = readMemory(input, output,
                        EXTERNAL_DMR_RF_PREP_ADDRESS, rfPrepHandler.length);
                byte[] rfPrepRound2 = readMemory(input, output,
                        EXTERNAL_DMR_RF_PREP_ADDRESS, rfPrepHandler.length);
                originalRfOff = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_ADDRESS, rfOffHandler.length);
                byte[] rfOffRound2 = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_ADDRESS, rfOffHandler.length);
                originalRfOffMarker = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                byte[] rfOffMarkerRound2 = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                originalRfActiveGate = readMemory(input, output,
                        EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                byte[] rfActiveGateRound2 = readMemory(input, output,
                        EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                preserveRawEvidence(report, "External DMR RF准备桩测前原件",
                        "external_dmr_rf_prep_pre_", originalRfPrep);
                preserveRawEvidence(report, "External DMR RF关闭桩测前原件",
                        "external_dmr_rf_off_pre_", originalRfOff);
                preserveRawEvidence(report, "External DMR RF关闭标记测前原件",
                        "external_dmr_rf_off_marker_pre_", originalRfOffMarker);
                preserveRawEvidence(report, "External DMR RF active gate测前原件",
                        "external_dmr_rf_active_gate_pre_", originalRfActiveGate);
                if (!Arrays.equals(originalRfPrep, rfPrepRound2)
                        || !Arrays.equals(originalRfOff, rfOffRound2)
                        || !Arrays.equals(originalRfOffMarker,
                        rfOffMarkerRound2)
                        || !Arrays.equals(originalRfActiveGate,
                        rfActiveGateRound2)) {
                    throw new IOException("External DMR RF新窗双读不稳定");
                }
                if (!allZero(originalRfPrep) || !allZero(originalRfOff)
                        || !allZero(originalRfOffMarker)
                        || !allZero(originalRfActiveGate)) {
                    throw new IOException("External DMR RF新窗或active gate存在残留");
                }
            }
            originalDataGate = readMemory(input, output,
                    EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
            originalSessionState = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
            originalPtrA = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
            originalPtrB = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
            originalFlag1c = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
            originalCount = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
            // v1.77：必须真实读出队列；禁止“全零模板冒充备份”。
            originalQueueA = readMemory(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH);
            originalQueueB = readMemory(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH);
            byte[] originalBootReady = readMemory(input, output,
                    SCT_BOOT_READY_ADDRESS, 1);
            byte[] originalBootMode = readMemory(input, output,
                    SCT_BOOT_MODE_ADDRESS, 1);
            // v1.90：测前原始字节先排队，任何后续门失败也必须在finally落盘。
            queueStep3SramSnapshot(evidenceRecords, "pre",
                    originalDatagateOneshot, originalDatagateMarker,
                    originalDatagateCounter, originalAbsCounter,
                    originalExitMarker, originalPrepPhase, originalPrepCursor,
                    originalMirrorHelper, originalRuntimeMirror,
                    originalDataGate, originalSessionState,
                    originalPtrA, originalPtrB, originalFlag1c, originalCount,
                    originalQueueA, originalQueueB, originalVector,
                    originalFlag, originalBootReady, originalBootMode);
            append(report, "Queue backup policy",
                    "full pre-arm queue memread; restore exact bytes");
            append(report, "QueueA SHA-256 before", sha256(originalQueueA));
            append(report, "QueueB SHA-256 before", sha256(originalQueueB));
            append(report, "QueueA all-zero before", allZero(originalQueueA));
            append(report, "QueueB all-zero before", allZero(originalQueueB));
            // 兼容 restoreStep3TemporaryStateAndVerify 形参：本路径不写 0x20001600
            originalCode = new byte[64];
            originalCounter = new byte[4];
            originalMarker = new byte[4];
            append(report, "Bridge flag before", originalFlag[0] & 0xff);
            append(report, "SysTick vector before", String.format(Locale.US,
                    "0x%08x", u32le(originalVector, 0)));
            append(report, "dataGate before", originalDataGate[0] & 0xff);
            append(report, "boot-ready E4 before", originalBootReady[0] & 0xff);
            append(report, "boot-mode E5 before", originalBootMode[0] & 0xff);
            Log.i(TAG, String.format(Locale.US,
                    "SCT_READY_PRE_ARM E4=%d E5=%d bridge=%d",
                    originalBootReady[0] & 0xff, originalBootMode[0] & 0xff,
                    originalFlag[0] & 0xff));
            append(report, "Combined window empty",
                    allZero(originalDatagateOneshot));
            append(report, "Prep marker empty", allZero(originalDatagateMarker));
            append(report, "Prep counter empty",
                    allZero(originalDatagateCounter));
            append(report, "Abs counter empty", allZero(originalAbsCounter));
            append(report, "Exit marker empty", allZero(originalExitMarker));
            append(report, "Runtime mirror empty", allZero(originalRuntimeMirror));
            append(report, "Runtime mirror helper empty",
                    allZero(originalMirrorHelper));
            if ((originalFlag[0] & 0xff) != 0) {
                throw new IOException("UART-HPI bridge already active");
            }
            if (u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected SysTick vector baseline");
            }
            // 严格残留准入：全零，或代码窗口精确匹配已登记制品且元数据全零。
            // v1.77：禁止 force-zero；未知残留必须先只读取证，不得覆盖。
            boolean codeClean = allZero(originalDatagateOneshot);
            boolean codeKnown = Arrays.equals(originalDatagateOneshot,
                    combinedHandler);
            boolean helperClean = allZero(originalMirrorHelper);
            boolean helperKnown = Arrays.equals(originalMirrorHelper,
                    mirrorHelper);
            boolean mirrorClean = allZero(originalRuntimeMirror);
            boolean metaClean = allZero(originalDatagateMarker)
                    && allZero(originalDatagateCounter)
                    && allZero(originalAbsCounter)
                    && allZero(originalExitMarker)
                    && allZero(originalPrepPhase)
                    && allZero(originalPrepCursor);
            if ((codeClean || codeKnown) && (helperClean || helperKnown)
                    && mirrorClean && metaClean) {
                append(report, "Combined window residual",
                        codeClean && helperClean
                                ? "clean-zero"
                                : "zero-or-exact-known-artifacts; overwrite allowed");
                Log.i(TAG, "COMBINED_WINDOW zero or exact known artifacts; overwrite");
            } else {
                // v1.84：未知残留只落盘拒绝 arm，永不清零、永不改写 original*。
                long dumpStamp = SystemClock.elapsedRealtime();
                persistResidualDump(report, "reject_combined_code_" + dumpStamp,
                        originalDatagateOneshot, COMBINED_DUAL_COUNTER_CODE_ADDRESS);
                persistResidualDump(report,
                        "reject_combined_meta_prep_marker_" + dumpStamp,
                        originalDatagateMarker, COMBINED_PREP_MARKER_ADDRESS);
                persistResidualDump(report,
                        "reject_combined_meta_prep_counter_" + dumpStamp,
                        originalDatagateCounter, COMBINED_PREP_COUNTER_ADDRESS);
                persistResidualDump(report,
                        "reject_combined_meta_abs_counter_" + dumpStamp,
                        originalAbsCounter, COMBINED_ABS_COUNTER_ADDRESS);
                persistResidualDump(report,
                        "reject_combined_meta_exit_marker_" + dumpStamp,
                        originalExitMarker, COMBINED_EXIT_MARKER_ADDRESS);
                persistResidualDump(report,
                        "reject_combined_meta_prep_phase_" + dumpStamp,
                        originalPrepPhase, COMBINED_PREP_PHASE_ADDRESS);
                persistResidualDump(report,
                        "reject_combined_meta_prep_cursor_" + dumpStamp,
                        originalPrepCursor, COMBINED_PREP_CURSOR_ADDRESS);
                persistResidualDump(report,
                        "reject_runtime_mirror_" + dumpStamp,
                        originalRuntimeMirror, RUNTIME_MIRROR_ADDRESS);
                persistResidualDump(report,
                        "reject_runtime_mirror_helper_" + dumpStamp,
                        originalMirrorHelper, RUNTIME_MIRROR_HELPER_ADDRESS);
                persistResidualDump(report, "reject_queue_a_" + dumpStamp,
                        originalQueueA, EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS);
                persistResidualDump(report, "reject_queue_b_" + dumpStamp,
                        originalQueueB, EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS);
                int nz = firstNonZeroOffset(originalDatagateOneshot);
                append(report, "Combined window residual",
                        "unknown-nonzero; reject arm; dumps saved; never zero");
                append(report, "Residual code SHA-256",
                        sha256(originalDatagateOneshot));
                append(report, "Residual code first_nonzero_offset",
                        nz < 0 ? "none" : nz);
                if (nz >= 0) {
                    append(report, "Residual code first_nonzero_addr",
                            String.format(Locale.US, "0x%08x",
                                    COMBINED_DUAL_COUNTER_CODE_ADDRESS + nz));
                    append(report, "Residual code first_nonzero_value",
                            String.format(Locale.US, "0x%02x",
                                    originalDatagateOneshot[nz] & 0xff));
                }
                Log.w(TAG, "COMBINED_WINDOW unknown residual sha="
                        + sha256(originalDatagateOneshot)
                        + "; reject arm; never zero; pre-image preserved");
                throw new IOException(
                        "combined 新窗 unknown residual；已落盘 pre-image；"
                                + "禁止清零/arm；换窗或待生产空闲后再测");
            }

            byte[] tickFirstBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickDelta = (u32le(tickSecondBytes, 0)
                    - u32le(tickFirstBytes, 0)) & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            append(report, "Measured tick Hz",
                    String.format(Locale.US, "%.2f", tickRateHz));
            if (tickRateHz < 10.0 || tickRateHz > 100000.0) {
                throw new IOException("Implausible MCU tick rate");
            }
            long timeoutTicksLong = Math.round(tickRateHz
                    * EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS / 1000.0);
            if (timeoutTicksLong < 50 || timeoutTicksLong > 500000) {
                throw new IOException("Calculated abs exit counter out of range");
            }
            int timeoutTicks = (int) timeoutTicksLong;
            long prepTicksLong = Math.round(tickRateHz
                    * MID_BRIDGE_DATAGATE_DELAY_MS / 1000.0);
            if (prepTicksLong < 20 || prepTicksLong > 200000) {
                throw new IOException("Calculated datagate prep counter out of range");
            }
            int prepTicks = (int) prepTicksLong;
            if (prepTicks >= timeoutTicks) {
                throw new IOException("prep ticks must be strictly less than abs exit");
            }
            // 绝对退桥从 arm 起算 18s；prep 延迟覆盖 setup 最坏预算；静默=绝对+裕度
            silentWaitMs = EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS
                    + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS;
            append(report, "Abs exit counter ticks", timeoutTicks);
            append(report, "Timeout counter", timeoutTicks);
            append(report, "Datagate prep counter", prepTicks);
            append(report, "Datagate prep delay ms",
                    MID_BRIDGE_DATAGATE_DELAY_MS);
            append(report, "Setup worst-case budget ms",
                    5L * (EXTERNAL_DMR_PRE_SEND_QUIET_MS
                            + EXTERNAL_DMR_VLC_SESSION_ACK_TIMEOUT_MS));
            append(report, "Silent wait ms", silentWaitMs);
            append(report, "Bridge absolute window ms",
                    EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS);
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_PREP_PLAN delayMs=%d postMarginMs=%d absMs=%d ticksPrep=%d ticksAbs=%d",
                    MID_BRIDGE_DATAGATE_DELAY_MS,
                    MID_BRIDGE_DATAGATE_POST_MARGIN_MS,
                    EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS,
                    prepTicks, timeoutTicks));

            final InputStream step3Input = input;
            final OutputStream step3Output = output;
            if (!privacyTransaction.control.canEnterBridge()
                    || !privacyTransaction.privacyOnVerified) {
                throw new IOException("privacy运行合同未完成，禁止写临时SRAM或进入bridge");
            }
            transport.beforeTemporarySramWrite();
            assertNotForbiddenProductionWindow(
                    COMBINED_DUAL_COUNTER_CODE_ADDRESS, combinedHandler.length);
            assertNotForbiddenProductionWindow(
                    COMBINED_PREP_MARKER_ADDRESS, 0x18);
            assertNotForbiddenProductionWindow(
                    RUNTIME_MIRROR_ADDRESS, RUNTIME_MIRROR_LENGTH);
            assertNotForbiddenProductionWindow(
                    RUNTIME_MIRROR_HELPER_ADDRESS, mirrorHelper.length);
            if (softwareProductionRf) {
                assertNotForbiddenProductionWindow(
                        EXTERNAL_DMR_RF_PREP_ADDRESS, rfPrepHandler.length);
                assertNotForbiddenProductionWindow(
                        EXTERNAL_DMR_RF_OFF_ADDRESS, rfOffHandler.length);
                assertNotForbiddenProductionWindow(
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
            }
            append(report, "Combined code window",
                    String.format(Locale.US, "0x%08x",
                            COMBINED_DUAL_COUNTER_CODE_ADDRESS));
            append(report, "Combined meta window",
                    String.format(Locale.US, "0x%08x",
                            COMBINED_PREP_MARKER_ADDRESS));
            // 上传前 original* 已是测前 pre-image；恢复时必须写回该 pre-image，
            // 禁止在此后用清零结果覆盖 original*。
            // 第一字写入前即建立恢复责任；上传中途失败也必须走 combined 恢复。
            combinedWindowRestoreRequired = true;
            for (int offset = 0; offset < combinedHandler.length; offset += 4) {
                writeMemoryWord(input, output,
                        COMBINED_DUAL_COUNTER_CODE_ADDRESS + offset,
                        u32le(combinedHandler, offset));
            }
            for (int offset = 0; offset < mirrorHelper.length; offset += 4) {
                writeMemoryWord(input, output,
                        RUNTIME_MIRROR_HELPER_ADDRESS + offset,
                        u32le(mirrorHelper, offset));
            }
            if (softwareProductionRf) {
                rfWindowRestoreRequired = true;
                for (int offset = 0; offset < rfPrepHandler.length; offset += 4) {
                    writeMemoryWord(input, output,
                            EXTERNAL_DMR_RF_PREP_ADDRESS + offset,
                            u32le(rfPrepHandler, offset));
                }
                for (int offset = 0; offset < rfOffHandler.length; offset += 4) {
                    writeMemoryWord(input, output,
                            EXTERNAL_DMR_RF_OFF_ADDRESS + offset,
                            u32le(rfOffHandler, offset));
                }
                writeMemoryWord(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 0);
                byte[] uploadedRfPrep = readMemory(input, output,
                        EXTERNAL_DMR_RF_PREP_ADDRESS, rfPrepHandler.length);
                byte[] uploadedRfOff = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_ADDRESS, rfOffHandler.length);
                byte[] uploadedRfMarker = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                preserveRawEvidence(report, "External DMR RF准备桩上传回读",
                        "external_dmr_rf_prep_uploaded_", uploadedRfPrep);
                preserveRawEvidence(report, "External DMR RF关闭桩上传回读",
                        "external_dmr_rf_off_uploaded_", uploadedRfOff);
                preserveRawEvidence(report, "External DMR RF关闭标记上传回读",
                        "external_dmr_rf_off_marker_uploaded_", uploadedRfMarker);
                if (!Arrays.equals(rfPrepHandler, uploadedRfPrep)
                        || !Arrays.equals(rfOffHandler, uploadedRfOff)
                        || !allZero(uploadedRfMarker)
                        || !EXTERNAL_DMR_RF_PREP_SHA256.equals(
                        sha256(uploadedRfPrep))
                        || !EXTERNAL_DMR_RF_OFF_SHA256.equals(
                        sha256(uploadedRfOff))) {
                    throw new IOException("External DMR RF桩上传全量回读失败");
                }
            }
            for (int offset = 0; offset < RUNTIME_MIRROR_LENGTH; offset += 4) {
                writeMemoryWord(input, output,
                        RUNTIME_MIRROR_ADDRESS + offset, 0);
            }
            byte[] uploadedCombined = readMemory(input, output,
                    COMBINED_DUAL_COUNTER_CODE_ADDRESS, combinedHandler.length);
            byte[] uploadedMirrorHelper = readMemory(input, output,
                    RUNTIME_MIRROR_HELPER_ADDRESS, mirrorHelper.length);
            byte[] uploadedRuntimeMirror = readMemory(input, output,
                    RUNTIME_MIRROR_ADDRESS, RUNTIME_MIRROR_LENGTH);
            append(report, "Combined dual-counter upload SHA-256",
                    sha256(uploadedCombined));
            append(report, "Datagate oneshot upload SHA-256",
                    sha256(uploadedCombined));
            if (!Arrays.equals(combinedHandler, uploadedCombined)) {
                throw new IOException(
                        "Combined dual-counter upload readback mismatch");
            }
            if (!expectedCombinedHash.equals(sha256(uploadedCombined))) {
                throw new IOException("Uploaded combined hash mismatch");
            }
            if (!Arrays.equals(mirrorHelper, uploadedMirrorHelper)
                    || !RUNTIME_MIRROR_HELPER_SHA256.equals(
                    sha256(uploadedMirrorHelper))) {
                throw new IOException("Runtime mirror helper upload mismatch");
            }
            if (!allZero(uploadedRuntimeMirror)) {
                throw new IOException("Runtime mirror zero initialization mismatch");
            }

            writeMemoryWord(input, output, COMBINED_PREP_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, COMBINED_EXIT_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, COMBINED_PREP_PHASE_ADDRESS, 0);
            writeMemoryWord(input, output, COMBINED_PREP_CURSOR_ADDRESS, 0);
            // phase=0：prep_counter 为 setup 裕度；到期后 multi-tick 工作
            writeMemoryWord(input, output,
                    COMBINED_PREP_COUNTER_ADDRESS, prepTicks);
            writeMemoryWord(input, output,
                    COMBINED_ABS_COUNTER_ADDRESS, timeoutTicks);
            // v1.90：一次连续24字节回读覆盖全部元数据，避免只验证两个计数器。
            byte[] uploadedMeta = readMemory(input, output,
                    COMBINED_PREP_MARKER_ADDRESS, 0x18);
            byte[] prepMarkerArmed = Arrays.copyOfRange(uploadedMeta, 0, 4);
            byte[] prepCounterArmed = Arrays.copyOfRange(uploadedMeta, 4, 8);
            byte[] absArmed = Arrays.copyOfRange(uploadedMeta, 8, 12);
            byte[] exitMarkerArmed = Arrays.copyOfRange(uploadedMeta, 12, 16);
            byte[] prepPhaseArmed = Arrays.copyOfRange(uploadedMeta, 16, 20);
            byte[] prepCursorArmed = Arrays.copyOfRange(uploadedMeta, 20, 24);
            if (u32le(absArmed, 0) != timeoutTicks) {
                throw new IOException("Abs exit counter write mismatch");
            }
            if (u32le(prepCounterArmed, 0) != prepTicks) {
                throw new IOException("Datagate prep counter write mismatch");
            }
            if (!allZero(prepMarkerArmed) || !allZero(exitMarkerArmed)
                    || !allZero(prepPhaseArmed)
                    || !allZero(prepCursorArmed)) {
                throw new IOException("Combined metadata zero write mismatch");
            }
            // 仍处于文本面、SysTick尚未武装；完整直读上传后快照，不占18秒桥窗口。
            byte[] uploadedDataGate = readMemory(input, output,
                    EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
            byte[] uploadedSessionState = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
            byte[] uploadedPtrA = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
            byte[] uploadedPtrB = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
            byte[] uploadedFlag1c = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
            byte[] uploadedCount = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
            byte[] uploadedQueueA = readMemory(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH);
            byte[] uploadedQueueB = readMemory(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH);
            byte[] uploadedVector = readMemory(input, output,
                    RAM_VECTOR_SYSTICK, 4);
            byte[] uploadedBridgeFlag = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] uploadedBootReady = readMemory(input, output,
                    SCT_BOOT_READY_ADDRESS, 1);
            byte[] uploadedBootMode = readMemory(input, output,
                    SCT_BOOT_MODE_ADDRESS, 1);
            queueStep3SramSnapshot(evidenceRecords, "uploaded",
                    uploadedCombined, prepMarkerArmed, prepCounterArmed,
                    absArmed, exitMarkerArmed, prepPhaseArmed,
                    prepCursorArmed, uploadedMirrorHelper,
                    uploadedRuntimeMirror, uploadedDataGate, uploadedSessionState,
                    uploadedPtrA, uploadedPtrB, uploadedFlag1c, uploadedCount,
                    uploadedQueueA, uploadedQueueB, uploadedVector,
                    uploadedBridgeFlag, uploadedBootReady, uploadedBootMode);
            Log.i(TAG, String.format(Locale.US,
                    "SCT_READY_UPLOADED E4=%d E5=%d bridge=%d",
                    uploadedBootReady[0] & 0xff, uploadedBootMode[0] & 0xff,
                    uploadedBridgeFlag[0] & 0xff));
            if (softwareLegacyLowPowerRf) {
                byte[] audioBeforePttRaw = readDmrAudioSwitchState();
                preserveRawEvidence(report, "PTT前麦克风路径只读回读",
                        "software_ambe_rf_audio_before_ptt_", audioBeforePttRaw);
                String audioBeforePttText = new String(audioBeforePttRaw,
                        StandardCharsets.US_ASCII);
                audioSwitchBeforePttZero = audioBeforePttText.contains(
                        "audio_switch=0");
                audioSwitchStayedZero = audioSwitchBeforePttZero;
                append(report, "audio_switch判据",
                        "只读旁证；真机已证明其不能表示SCT内部DMR麦克风隔离");

                byte[] pttOnRequest = "AT+DMOPTT=1\r\n".getBytes(
                        StandardCharsets.US_ASCII);
                preserveRawEvidence(report, "H13 PTT开启请求原件",
                        "software_ambe_rf_ptt_on_req_", pttOnRequest);
                drainAvailable(input);
                pttOnAttempted = true;
                rfCommandCount++;
                pttOnAtMs = SystemClock.elapsedRealtime();
                pttWatchdog = new PttHardWatchdog(device);
                pttWatchdog.arm(pttOnAtMs);
                output.write(pttOnRequest);
                output.flush();
                byte[] pttOnRaw = readForDuration(input, 1500);
                preserveRawEvidence(report, "H13 PTT开启完整响应原件",
                        "software_ambe_rf_ptt_on_rsp_", pttOnRaw);
                String pttOnText = new String(pttOnRaw,
                        StandardCharsets.US_ASCII);
                pttOnAccepted = containsExactAsciiLine(pttOnText,
                        "+DMOPTT:0");
                txStartObserved = containsExactAsciiLine(pttOnText,
                        "+DMOSENDMOUDULESTA:TxStart");
                appendRaw(report, "H13 PTT开启完整响应", pttOnRaw);
                if (!pttOnAccepted || !txStartObserved) {
                    throw new IOException("H13主动PTT未同时取得DMOPTT确认和TxStart");
                }
                byte[] audioAfterTxStartRaw = readDmrAudioSwitchState();
                preserveRawEvidence(report, "TxStart后麦克风路径只读回读",
                        "software_ambe_rf_audio_after_tx_start_",
                        audioAfterTxStartRaw);
                String audioAfterTxStartText = new String(audioAfterTxStartRaw,
                        StandardCharsets.US_ASCII);
                audioSwitchAfterTxStartZero = audioAfterTxStartText.contains(
                        "audio_switch=0");
                audioSwitchStayedZero = audioSwitchStayedZero
                        && audioSwitchAfterTxStartZero;
            }
            append(report, "Prep phase armed", 0);
            append(report, "Prep policy",
                    "conservative setup-worst-case delay then multi-tick fullprep;"
                            + " host rejects if setup finishes too late");
            // v1.77：MCU prep 计数在 SysTick 向量指向桩后开始有效递减；
            // 主机计时原点取向量写前一刻，并单独记录 flag 写完时刻。
            long systickArmBeginAt = SystemClock.elapsedRealtime();
            if (softwareProductionRf) {
                productionRfMayStartMonotonicMs = systickArmBeginAt
                        + MID_BRIDGE_DATAGATE_DELAY_MS;
                pttOnAtMs = productionRfMayStartMonotonicMs;
                pttWatchdog = new PttHardWatchdog(device);
                pttWatchdog.arm(pttOnAtMs);
                productionRfWindowStartEpoch = epochSecondsForMonotonicTarget(
                        System.currentTimeMillis(),
                        SystemClock.elapsedRealtime(),
                        productionRfMayStartMonotonicMs);
                persistProductionRfPreparationAttestation(
                        productionRfWindowStartEpoch,
                        productionRfMayStartMonotonicMs);
                productionRfPreparationWritten = true;
                append(report, "生产同构RF硬看门狗预计RF起点",
                        pttOnAtMs);
                append(report, "生产同构RF准备凭证已落盘", true);
                append(report, "生产同构RF最早可能起点epoch",
                        productionRfWindowStartEpoch);
                append(report, "生产同构RF启动方式",
                        "fullprep结束后PE6 low、PF3 low、0x20000138=1；禁止DMOPTT");
            }
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_SYSTICK_ARM_BEGIN monoMs=%d", systickArmBeginAt));
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    COMBINED_DUAL_COUNTER_ENTRY);
            byte[] vectorArmed = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            long systickArmEndAt = SystemClock.elapsedRealtime();
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_SYSTICK_ARM_END monoMs=%d armWriteMs=%d",
                    systickArmEndAt, systickArmEndAt - systickArmBeginAt));
            append(report, "SysTick vector armed (combined dual-counter)",
                    String.format(Locale.US, "0x%08x", u32le(vectorArmed, 0)));
            if (u32le(vectorArmed, 0) != COMBINED_DUAL_COUNTER_ENTRY) {
                throw new IOException("Combined dual-counter SysTick arm failed");
            }
            queueStep3SramEvidence(evidenceRecords, "armed",
                    "systick_vector", RAM_VECTOR_SYSTICK, vectorArmed);
            // prep/setup 门一律相对 SysTick 武装原点（非 flag 写后）。
            bridgeArmedAt = systickArmBeginAt;
            if (pttWatchdog != null) {
                pttWatchdog.noteBridgeAutoExitSafeAt(bridgeArmedAt
                        + EXTERNAL_DMR_VLC_SESSION_BRIDGE_TARGET_MS
                        + EXTERNAL_DMR_VLC_SESSION_BRIDGE_MARGIN_MS);
            }

            synchronized (lock) {
                // Raw bridge active: never let closeLocked send print/ASCII.
                logLevelMayBeEnabled = false;
            }
            activateStep3Bridge(transport, () -> writeMemoryByte(step3Input,
                    step3Output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1));
            long bridgeFlagWrittenAt = SystemClock.elapsedRealtime();
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_BRIDGE_FLAG_WRITTEN monoMs=%d sinceSystickArm=%d",
                    bridgeFlagWrittenAt, bridgeFlagWrittenAt - bridgeArmedAt));
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_BRIDGE_ARMED monoMs=%d origin=systick_arm_begin",
                    bridgeArmedAt));
            append(report, "Bridge armed @57600", true);
            append(report, "Prep clock origin", "systick_arm_begin");
            append(report, "Bridge flag written elapsed ms",
                    bridgeFlagWrittenAt - bridgeArmedAt);
            append(report, "Step3 phase",
                    runVlcSession
                            ? "setup → gated fullprep → VLC"
                            : "setup → gated fullprep → exit (isolation)");

            // v1.87 基线 settle=500；v1.92 setup0-only 单变量改为 2000ms
            long settleMs = postBridgeSettleMs(setup0Only);
            long settleBeginMs = SystemClock.elapsedRealtime();
            if (settleMs > 0) {
                SystemClock.sleep(settleMs);
            }
            long settleEndMs = SystemClock.elapsedRealtime();
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_POST_BRIDGE_SETTLE beginMs=%d endMs=%d settleMs=%d sinceBridgeFlag=%d setup0Only=%s",
                    settleBeginMs, settleEndMs, settleMs,
                    settleEndMs - bridgeFlagWrittenAt, setup0Only));
            append(report, "Post-bridge settle ms", settleMs);
            append(report, "Post-bridge settle actual ms",
                    settleEndMs - settleBeginMs);
            append(report, "Post-bridge settle setup0Only", setup0Only);

            while (model.phase() == ExternalDmrTxModel.Phase.SETUP) {
                long setupTxAt = SystemClock.elapsedRealtime();
                // TIMING_SETUP_TX = 交换开始（含 quiet），非上线写出时刻；
                // 上线写出见 runOne 内 TIMING_SETUP_WIRE_TX。
                Log.i(TAG, String.format(Locale.US,
                        "TIMING_SETUP_TX exchange_begin index=%d monoMs=%d sinceBridge=%d sinceBridgeFlag=%d",
                        model.setupAcks(), setupTxAt,
                        setupTxAt - bridgeArmedAt,
                        setupTxAt - bridgeFlagWrittenAt));
                if (setup0Only
                        || (softwareProductionRf && model.setupAcks() == 0)) {
                    // v1.91基线：setup0严格双空时最多原样重发一次。
                    // v3.88只把同一已证明策略接入生产同构RF路径。
                    String setup0Attempt1Label = softwareProductionRf
                            ? null : "setup0_attempt1";
                    String setup0Attempt2Label = softwareProductionRf
                            ? "setup0_retry1" : "setup0_attempt2";
                    boolean needRetry = runOneExternalDmrControlExchange(model,
                            true, input, output, transport, evidenceRecords,
                             transcript, transcriptStartedNanos, report,
                             setup0Attempt1Label, true, null, activeHpiRouter,
                             controlTxProgress);
                    controlPlaneMutationMayHaveStarted = true;
                    if (!needRetry) {
                        setup0FirstOk = true;
                        setup0RetryUsed = false;
                        setup0RetryOk = false;
                        append(report, "setup0_first_ok", true);
                        append(report, "setup0_retry_used", false);
                        append(report, "setup0_retry_ok", false);
                        Log.i(TAG, "SETUP0_FIRST_OK no_retry");
                    } else {
                        setup0RetryUsed = true;
                        append(report, "setup0_first_ok", false);
                        append(report, "setup0_retry_used", true);
                        Log.i(TAG, "SETUP0_EMPTY_RETRY arming attempt2");
                        boolean needThird = runOneExternalDmrControlExchange(
                                 model, true, input, output, transport,
                                evidenceRecords, transcript,
                                 transcriptStartedNanos, report,
                                 setup0Attempt2Label, false, null,
                                 activeHpiRouter, controlTxProgress);
                        if (needThird) {
                            setup0FailReason = "第二次后仍请求第三次（禁止）";
                            throw new IOException(
                                    "setup0 禁止第三次重试");
                        }
                        setup0RetryOk = model.setupAcks() == 1;
                        append(report, "setup0_retry_ok", setup0RetryOk);
                        Log.i(TAG, "SETUP0_RETRY_OK=" + setup0RetryOk);
                    }
                    if (setup0Only) {
                        break;
                    }
                    continue;
                }
                if (sendRealtimeRelayData36 && model.setupAcks() == 0) {
                    // v2.03 单变量：实时主动路径仅在 setup0 的确认窗和迟到窗
                    // 均为空时，允许一次原样重发。任一非空畸形字节不得重试。
                    boolean needRetry = runOneExternalDmrControlExchange(
                            model, true, input, output, transport,
                            evidenceRecords, transcript,
                             transcriptStartedNanos, report,
                             null, true, null, activeHpiRouter,
                             controlTxProgress);
                    controlPlaneMutationMayHaveStarted = true;
                    if (!needRetry) {
                        setup0FirstOk = true;
                        setup0RetryUsed = false;
                        setup0RetryOk = false;
                        append(report, "setup0_first_ok", true);
                        append(report, "setup0_retry_used", false);
                        append(report, "setup0_retry_ok", false);
                        Log.i(TAG, "REALTIME_SETUP0_FIRST_OK no_retry");
                    } else {
                        setup0RetryUsed = true;
                        append(report, "setup0_first_ok", false);
                        append(report, "setup0_retry_used", true);
                        Log.i(TAG,
                                "REALTIME_SETUP0_EMPTY_RETRY arming retry1");
                        boolean needThird = runOneExternalDmrControlExchange(
                                model, true, input, output, transport,
                                evidenceRecords, transcript,
                                 transcriptStartedNanos, report,
                                 "setup0_retry1", false, null,
                                 activeHpiRouter, controlTxProgress);
                        if (needThird) {
                            setup0FailReason = "第二次后仍请求第三次（禁止）";
                            throw new IOException("实时模式 setup0 禁止第三次重试");
                        }
                        setup0RetryOk = model.setupAcks() == 1;
                        append(report, "setup0_retry_ok", setup0RetryOk);
                        Log.i(TAG, "REALTIME_SETUP0_RETRY_OK="
                                + setup0RetryOk);
                    }
                    continue;
                }
                runOneExternalDmrControlExchange(model, true, input, output,
                        transport, evidenceRecords, transcript,
                         transcriptStartedNanos, report,
                         null, false, null, activeHpiRouter,
                         controlTxProgress);
                long setupRxAt = SystemClock.elapsedRealtime();
                Log.i(TAG, String.format(Locale.US,
                        "TIMING_SETUP_RX acks=%d monoMs=%d sinceBridge=%d",
                        model.setupAcks(), setupRxAt,
                        setupRxAt - bridgeArmedAt));
                controlPlaneMutationMayHaveStarted = true;
                if (setup04Only
                        && model.setupAcks() == EXTERNAL_DMR_SETUP_EXCHANGE_COUNT) {
                    break;
                }
            }
            long setupDoneAt = SystemClock.elapsedRealtime();
            long prepWaitDoneAt = setupDoneAt;
            long cleanupHostAt = setupDoneAt;
            if (setup0Only) {
                if (model.setupAcks() != 1
                        || model.phase() != ExternalDmrTxModel.Phase.SETUP) {
                    throw new IOException("setup0-only 状态错误 phase="
                            + model.phase() + " setupAcks=" + model.setupAcks());
                }
                append(report, "setupAcks", model.setupAcks());
                append(report, "Setup0-only ACK accepted", true);
                append(report, "Setup1-4 sent", false);
                append(report, "VLC sent", false);
                append(report, "Data36 write attempted", false);
                append(report, "HPI cleanup sent", false);
                Log.i(TAG, "SETUP0_ONLY_ACK_ACCEPTED no_further_hpi_tx=true");
            } else if (setup04Only) {
                if (model.setupAcks() != EXTERNAL_DMR_SETUP_EXCHANGE_COUNT
                        || model.phase() != ExternalDmrTxModel.Phase.VLC_SESSION) {
                    throw new IOException("setup0-4-only 状态错误 phase="
                            + model.phase() + " setupAcks=" + model.setupAcks());
                }
                append(report, "setupAcks", model.setupAcks());
                append(report, "Setup0-4-only all ACKs accepted", true);
                append(report, "Setup1-4 sent", true);
                append(report, "VLC sent", false);
                append(report, "Data36 write attempted", false);
                append(report, "HPI cleanup sent", false);
                setupDoneAt = SystemClock.elapsedRealtime();
                long setupElapsed = setupDoneAt - bridgeArmedAt;
                append(report, "setup complete elapsed ms", setupElapsed);
                Log.i(TAG, String.format(Locale.US,
                        "TIMING_SETUP_DONE monoMs=%d sinceBridge=%d prepDeadline=%d",
                        setupDoneAt, setupElapsed, MID_BRIDGE_DATAGATE_DELAY_MS));
                // setup4 须在 MCU prep 截止前完成，避免 fullprep 与 setup 竞态
                if (setupElapsed
                        >= MID_BRIDGE_DATAGATE_DELAY_MS
                        - SETUP_BEFORE_PREP_SAFETY_MS) {
                    throw new IOException(
                            "setup0-4-only 完成过晚（elapsed=" + setupElapsed
                                    + "ms >= prepDeadline-"
                                    + SETUP_BEFORE_PREP_SAFETY_MS
                                    + "）；禁止继续");
                }
                append(report, "setup4 before prep deadline", true);
                Log.i(TAG, "SETUP04_ONLY_ACK_ACCEPTED no_further_hpi_tx=true");
            } else {
            if (model.setupAcks() != contract.setupCount()
                    || model.phase() != ExternalDmrTxModel.Phase.VLC_SESSION) {
                throw new IOException("setup 未完整完成 phase="
                        + model.phase() + " setupAcks=" + model.setupAcks());
            }
            append(report, "setupAcks", model.setupAcks());
            append(report, "Step3 setup complete", true);
            setupDoneAt = SystemClock.elapsedRealtime();
            long setupElapsed = setupDoneAt - bridgeArmedAt;
            append(report, "setup complete elapsed ms", setupElapsed);
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_SETUP_DONE monoMs=%d sinceBridge=%d prepDeadline=%d",
                    setupDoneAt, setupElapsed, MID_BRIDGE_DATAGATE_DELAY_MS));
            // 主机门：setup4 必须在 prep 截止前完成，否则禁止 VLC/继续
            if (setupElapsed
                    >= MID_BRIDGE_DATAGATE_DELAY_MS - SETUP_BEFORE_PREP_SAFETY_MS) {
                throw new IOException(
                        "setup 完成过晚（elapsed=" + setupElapsed
                                + "ms >= prepDeadline-"
                                + SETUP_BEFORE_PREP_SAFETY_MS
                                + "）；禁止继续，prep 可能与 setup 竞态");
            }
            append(report, "setup4 before prep deadline", true);

            // 等到 prep 延迟 + multi-tick 工作裕度（相对 SysTick 武装原点）
            long prepReadyAt = bridgeArmedAt + MID_BRIDGE_DATAGATE_DELAY_MS
                    + MID_BRIDGE_DATAGATE_POST_MARGIN_MS;
            long prepRemain = prepReadyAt - SystemClock.elapsedRealtime();
            if (prepRemain > 0) {
                SystemClock.sleep(prepRemain);
            }
            prepWaitDoneAt = SystemClock.elapsedRealtime();
            append(report, "mid-bridge dataGate prep wait done", true);
            append(report, "mid-bridge elapsed ms",
                    prepWaitDoneAt - bridgeArmedAt);
            append(report, "prep wait after setup ms",
                    prepWaitDoneAt - setupDoneAt);
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_PREP_WAIT_DONE monoMs=%d sinceBridge=%d afterSetup=%d",
                    prepWaitDoneAt, prepWaitDoneAt - bridgeArmedAt,
                    prepWaitDoneAt - setupDoneAt));
            // 禁止在 raw bridge 内调用文本 memread（会把 ASCII 打进 HPI 透传）。
            // fullprep 完成证明只能：绝对退桥后文本回读 DGAT/phase，并与
            // prepWaitDone / 首条 VLC 或 cleanup 的主机时刻建立可审计顺序。
            append(report, "prep complete gate policy",
                    "no text-memread while bridged; post-exit DGAT + host timeline");
            Log.i(TAG, "TIMING_PREP_WAIT_DONE_NO_BRIDGED_MEMREAD "
                    + "policy=post_exit_DGAT_plus_host_timeline");
            if (softwareProductionRf) {
                persistProductionRfWindowStartAttestation(
                        productionRfWindowStartEpoch,
                        productionRfMayStartMonotonicMs);
                productionRfWindowStartWritten = true;
                append(report, "生产同构RF起点凭证已落盘", true);
                append(report, "生产同构RF起点单调毫秒",
                        productionRfMayStartMonotonicMs);
            }

            if (runVlcSession) {
                if (sendRealtimeRelayData36) {
                    realtimeRelay = new ExternalDmrRealtimeRelayContext(
                            step3Output, evidenceRecords, transcript,
                            transcriptStartedNanos, report,
                            privacyTransaction.measuredRuntime14,
                            fixedAssetBytes,
                            softwareRealtimeData36
                                    ? Arrays.copyOfRange(softwarePlainAmbe,
                                    0, EXT_ENC_TX_UNIT_BYTES) : null,
                            softwareRealtimeData36
                                    ? softwareFirstRequest : null);
                }
                Log.i(TAG, String.format(Locale.US,
                        "TIMING_VLC_BEGIN monoMs=%d sinceBridge=%d",
                        SystemClock.elapsedRealtime(),
                        SystemClock.elapsedRealtime() - bridgeArmedAt));
                while (model.phase() == ExternalDmrTxModel.Phase.VLC_SESSION) {
                    long vlcTxAt = SystemClock.elapsedRealtime();
                    Log.i(TAG, String.format(Locale.US,
                            "TIMING_VLC_TX index=%d monoMs=%d sinceBridge=%d",
                            model.vlcAcks(), vlcTxAt,
                            vlcTxAt - bridgeArmedAt));
                    runOneExternalDmrControlExchange(model, false, input, output,
                            transport, evidenceRecords, transcript,
                             transcriptStartedNanos, report, null, false,
                             realtimeRelay, activeHpiRouter,
                             controlTxProgress);
                    long vlcRxAt = SystemClock.elapsedRealtime();
                    Log.i(TAG, String.format(Locale.US,
                            "TIMING_VLC_RX acks=%d monoMs=%d sinceBridge=%d",
                            model.vlcAcks(), vlcRxAt,
                            vlcRxAt - bridgeArmedAt));
                    controlPlaneMutationMayHaveStarted = true;
                    if (sendRealtimeRelayData36
                            && model.vlcAcks() == 2) {
                        long waitBeginMs = SystemClock.elapsedRealtime();
                        boolean waitNeeded = realtimeRelay.data27Count() < 3;
                        byte[] waitRaw = waitNeeded
                                ? readForDurationWithRealtimeRelay(step3Input,
                                EXTERNAL_DMR_REALTIME_PRE_VLC2_WAIT_MS,
                                realtimeRelay, "vlc1后vlc2前有界接收窗")
                                : new byte[0];
                        long waitEndMs = SystemClock.elapsedRealtime();
                        realtimeRelay.recordPreVlc2Wait(waitRaw,
                                waitEndMs - waitBeginMs, waitNeeded);
                        if (realtimeRelay.data27Count() < 3) {
                            throw new IOException("vlc1后有界接收窗结束仍不足三个实时单元；"
                                    + "禁止发送vlc2和data36");
                        }
                    }
                }

                if (model.phase() != ExternalDmrTxModel.Phase.COMPLETE
                        || model.setupAcks() != contract.setupCount()
                        || model.vlcAcks() != EXTERNAL_DMR_SESSION_ACK_COUNT) {
                    throw new IOException("VLC 未完整完成 phase="
                            + model.phase() + " vlcAcks=" + model.vlcAcks());
                }
                append(report, "vlcAcks", model.vlcAcks());
                append(report, "Step3 VLC complete", true);
                Log.i(TAG, String.format(Locale.US,
                        "TIMING_VLC_DONE monoMs=%d sinceBridge=%d vlcAcks=%d",
                        SystemClock.elapsedRealtime(),
                        SystemClock.elapsedRealtime() - bridgeArmedAt,
                        model.vlcAcks()));
                if (softwareAssetSession && !sendRealtimeRelayData36) {
                    if (softwareFirstRequest == null
                            || softwareFirstRequest.length != 44
                            || !looksLikeExternalData36Frame(
                            softwareFirstRequest)) {
                        throw new IOException("软件AMBE第一条44字节请求未就绪");
                    }
                    preserveRawEvidence(report, softwareSessionReady
                                    ? "五VLC后已准备但未写出的第一条44字节请求"
                                    : "五VLC后准备唯一写出的第一条44字节请求",
                            "software_ambe_session_first_request_",
                            softwareFirstRequest);
                    append(report, "第一条请求已准备", true);
                    if (softwareSessionReady) {
                        softwareHardStopReached = true;
                        append(report, "软件AMBE data36写前硬停止", true);
                        append(report, "第一条请求写调用已尝试", false);
                        Log.i(TAG, "SOFTWARE_AMBE_HARD_STOP_BEFORE_DATA36 "
                                + "request_ready=true write_attempted=false");
                    } else {
                        append(report, "软件AMBE唯一data36写入已授权", true);
                        if (softwareFullMorseRf) {
                            Log.i(TAG, "SOFTWARE_AMBE_FULL_MORSE_READY "
                                    + "request_ready=true max_writes="
                                    + SOFTWARE_AMBE_MORSE_DATA36_COUNT);
                        } else {
                            Log.i(TAG, "SOFTWARE_AMBE_ONE_DATA36_READY "
                                    + "request_ready=true max_writes=1");
                        }
                    }
                }
                if (sendRealtimeRelayData36) {
                    long observationBegin = SystemClock.elapsedRealtime();
                    byte[] observation = readForDurationWithRealtimeRelay(
                            step3Input, EXTERNAL_DMR_DATA36_CREDIT_TIMEOUT_MS,
                            realtimeRelay, "五VLC后有界观察窗");
                    long observationEnd = SystemClock.elapsedRealtime();
                    realtimeRelay.recordPostObservation(observation,
                            observationEnd - observationBegin);
                    realtimeRelay.finalizeEvidence();
                    data36WriteCompleted = realtimeRelay.writeCompleted();
                    data36CreditAccepted = realtimeRelay.creditAccepted();
                    realtimeRelay.requireStrictPass();
                }
            } else {
                append(report, "VLC session", "skipped isolation");
                append(report, "vlcAcks", 0);
                Log.i(TAG, "ISOLATION_NO_VLC after gated fullprep wait");
            }
            if (!sendOneHostEncryptedData36) {
                append(report, "Data36 write attempted", false);
                append(report, "Data36 write completed", false);
                append(report, "Data36 short-response shape accepted", false);
            }

            if (sendOneHostEncryptedData36 && softwareFullMorseRf) {
                if (activeHpiRouter == null || softwareWire44Stream == null
                        || softwareWire44Stream.length
                        != SOFTWARE_AMBE_MORSE_DATA36_COUNT * 44
                        || softwarePlainAmbe.length / REAL_RX_AMBE_FRAME_BYTES
                        != SOFTWARE_AMBE_MORSE_FRAME_COUNT) {
                    throw new IOException("完整摩尔斯26单元资产或活动HPI路由器不完整");
                }
                append(report, "完整摩尔斯data36计划数",
                        SOFTWARE_AMBE_MORSE_DATA36_COUNT);
                long fullMorseSendDeadlineMs = bridgeArmedAt
                        + softwareAmbeFullMorseSendDeadlineOffsetMs();
                append(report, "完整摩尔斯发送截止单调毫秒",
                        fullMorseSendDeadlineMs);
                for (int unit = 0; unit < SOFTWARE_AMBE_MORSE_DATA36_COUNT;
                        unit++) {
                    long remainingToSendDeadline = fullMorseSendDeadlineMs
                            - SystemClock.elapsedRealtime();
                    if (remainingToSendDeadline <= 0) {
                        throw new IOException("完整摩尔斯第" + unit
                                + "单元发送前已到总截止时间");
                    }
                    long targetMs = softwareFullFirstFlushMs < 0
                            ? -1L : softwareFullFirstFlushMs
                            + unit * SOFTWARE_AMBE_MORSE_UNIT_INTERVAL_MS;
                    ActiveHpiRead boundary;
                    long paceLateMs = 0L;
                    if (unit == 0) {
                        boundary = activeHpiRouter.drainToFrameBoundary(
                                step3Input,
                                Math.min(EXTERNAL_DMR_PRE_SEND_QUIET_MAX_MS,
                                        remainingToSendDeadline));
                    } else {
                        long paceRemainMs = targetMs
                                - SystemClock.elapsedRealtime();
                        boundary = paceRemainMs > 0
                                ? activeHpiRouter.readUntil(step3Input,
                                Math.min(paceRemainMs,
                                        remainingToSendDeadline),
                                new HpiFrameMatcher() {
                                    @Override
                                    public boolean matches(byte[] frame) {
                                        return false;
                                    }
                                })
                                : new ActiveHpiRead(new byte[0], null);
                        long beforeWriteLateMs = Math.max(0L,
                                SystemClock.elapsedRealtime() - targetMs);
                        if (beforeWriteLateMs > SOFTWARE_AMBE_MORSE_MAX_LATE_MS) {
                            throw new IOException("完整摩尔斯第" + unit
                                    + "单元写前节拍迟到" + beforeWriteLateMs
                                    + "毫秒；禁止追赶式突发");
                        }
                    }
                    softwareFullAsyncObservedBytes += boundary.observed.length;
                    recordStep3Evidence(evidenceRecords, transcript,
                            transcriptStartedNanos, STEP3_TRANSCRIPT_DRAIN,
                            "morse data36[" + unit + "]发送前节拍窗异步帧",
                            "h13_software_morse_data36_" + unit
                                    + "_pace_window_",
                            boundary.observed, true);
                    byte[] request = Arrays.copyOfRange(softwareWire44Stream,
                            unit * 44, unit * 44 + 44);
                    if (!looksLikeExternalData36Frame(request)) {
                        throw new IOException("完整摩尔斯第" + unit
                                + "单元信封形状错误");
                    }
                    recordStep3Evidence(evidenceRecords, transcript,
                            transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                            "morse data36[" + unit + "]请求",
                            "h13_software_morse_data36_" + unit + "_req_",
                            request, true);
                    step3Output.write(request);
                    step3Output.flush();
                    long flushAt = SystemClock.elapsedRealtime();
                    if (softwareFullFirstFlushMs < 0) {
                        softwareFullFirstFlushMs = flushAt;
                        targetMs = flushAt;
                    }
                    if (flushAt < targetMs) {
                        throw new IOException("完整摩尔斯第" + unit
                                + "单元早于绝对节拍目标写出");
                    }
                    paceLateMs = flushAt - targetMs;
                    if (paceLateMs > SOFTWARE_AMBE_MORSE_MAX_LATE_MS) {
                        throw new IOException("完整摩尔斯第" + unit
                                + "单元实际flush迟到" + paceLateMs
                                + "毫秒；禁止追赶式突发");
                    }
                    // unit0也执行了发送前完整帧边界窗；26个单元必须有26个窗。
                    softwareFullPaceWindowCount++;
                    softwareFullMaxPaceLateMs = Math.max(
                            softwareFullMaxPaceLateMs, paceLateMs);
                    softwareFullLastFlushMs = flushAt;
                    softwareFullData36WrittenCount++;
                    recordStep3Evidence(evidenceRecords, transcript,
                            transcriptStartedNanos,
                            STEP3_TRANSCRIPT_TX_COMPLETE,
                            "morse data36[" + unit + "]写出完成", "",
                            new byte[0], false);
                    String unitMeta = "unit_index=" + unit + "\n"
                            + "request_sha256=" + sha256(request) + "\n"
                            + "pacing_mode=fixed_80ms\n"
                            + "target_ms=" + targetMs + "\n"
                            + "flush_ms=" + flushAt + "\n"
                            + "pace_late_ms=" + paceLateMs + "\n"
                            + "async_observed_bytes="
                            + boundary.observed.length + "\n";
                    evidenceRecords.add(new Step3EvidenceRecord(
                            "morse data36[" + unit + "]元数据",
                            "h13_software_morse_data36_" + unit + "_meta_",
                            unitMeta.getBytes(StandardCharsets.UTF_8)));
                    append(report, "morse data36[" + unit + "] request SHA-256",
                            sha256(request));
                    append(report, "morse data36[" + unit + "]节拍迟到毫秒",
                            paceLateMs);
                }
                long tailTargetMs = softwareFullFirstFlushMs
                        + SOFTWARE_AMBE_MORSE_DATA36_COUNT
                        * SOFTWARE_AMBE_MORSE_UNIT_INTERVAL_MS;
                long tailRemainMs = Math.min(
                        tailTargetMs - SystemClock.elapsedRealtime(),
                        fullMorseSendDeadlineMs - SystemClock.elapsedRealtime());
                if (tailRemainMs <= 0) {
                    throw new IOException("完整摩尔斯末单元后80毫秒消费窗已错过");
                }
                ActiveHpiRead tailWindow = activeHpiRouter.readUntil(
                        step3Input, tailRemainMs, new HpiFrameMatcher() {
                            @Override
                            public boolean matches(byte[] frame) {
                                return false;
                            }
                        });
                long tailEndMs = SystemClock.elapsedRealtime();
                if (tailEndMs < tailTargetMs) {
                    throw new IOException("完整摩尔斯末单元后80毫秒消费窗提前结束");
                }
                softwareFullPaceWindowCount++;
                softwareFullAsyncObservedBytes += tailWindow.observed.length;
                recordStep3Evidence(evidenceRecords, transcript,
                        transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                        "morse末单元后80毫秒异步帧",
                        "h13_software_morse_tail_pace_window_",
                        tailWindow.observed, true);
                String tailMeta = "pacing_mode=fixed_80ms\n"
                        + "start_ms=" + softwareFullLastFlushMs + "\n"
                        + "target_ms=" + tailTargetMs + "\n"
                        + "end_ms=" + tailEndMs + "\n"
                        + "pace_late_ms=" + (tailEndMs - tailTargetMs) + "\n"
                        + "async_observed_bytes="
                        + tailWindow.observed.length + "\n";
                evidenceRecords.add(new Step3EvidenceRecord(
                        "morse末单元后80毫秒元数据",
                        "h13_software_morse_tail_pace_meta_",
                        tailMeta.getBytes(StandardCharsets.UTF_8)));
                data36WriteCompleted = softwareFullData36WrittenCount
                        == SOFTWARE_AMBE_MORSE_DATA36_COUNT;
                data36CreditAccepted = false;
                append(report, "完整摩尔斯data36实际写出数",
                        softwareFullData36WrittenCount);
                append(report, "完整摩尔斯节拍窗数",
                        softwareFullPaceWindowCount);
                append(report, "完整摩尔斯最大节拍迟到毫秒",
                        softwareFullMaxPaceLateMs);
                append(report, "完整摩尔斯异步流留证字节数",
                        softwareFullAsyncObservedBytes);
            } else if (sendOneHostEncryptedData36) {
                // 步骤4唯一增量由单帧执行器承担，失败后不存在第二次写入路径。
                byte[] data36Frame = softwareOneData36
                        ? softwareFirstRequest
                        : (sendGeneratedData36
                        ? createRealtimeRelayEncryptedData36Frame(
                        generatedPlain36,
                        privacyTransaction.measuredRuntime14)
                        : requireHostEncryptedExternalTxFrameUnit0());
                append(report, "Data36 unit index", 0);
                append(report, "Data36 input kind", softwareOneData36
                        ? "H13软件编码摩尔斯第0单元；按本次实测privacy连续状态生成"
                        : (sendGeneratedData36
                                ? "本次帧级适配器从内置编码器输出窗提取；"
                                + "按本次实测privacy快照加密"
                                : "步骤2冻结明文经固定参数主机加密；"
                                + "raw bridge不依赖MCU普通privacy链"));
                if (sendGeneratedData36) {
                    preserveRawEvidence(report, "本次内置编码器data36明文",
                            "h13_ext_dmr_generated_plain36_",
                            generatedPlain36);
                }
                append(report, "Data36 wire SHA-256", sha256(data36Frame));
                controlPlaneMutationMayHaveStarted = true;
                try {
                    executeExternalDmrStep4OneUnit(
                            transport.state() == Step3TransportState.BRIDGE_ACTIVE,
                            model.phase() == ExternalDmrTxModel.Phase.COMPLETE,
                            privacyTransaction.privacyOnVerified
                                    && privacyTransaction.control.canEnterBridge(),
                            data36Frame,
                            new ExternalDmrStep4OneUnitIo() {
                                @Override
                                public QuietDrainResult establishQuietWindow()
                                        throws Exception {
                                    return drainUntilQuietCapture(step3Input,
                                            EXTERNAL_DMR_PRE_SEND_QUIET_MS,
                                            EXTERNAL_DMR_PRE_SEND_QUIET_MAX_MS);
                                }

                                @Override
                                public void write(byte[] frame) throws Exception {
                                    step3Output.write(frame);
                                }

                                @Override
                                public void flush() throws Exception {
                                    step3Output.flush();
                                }

                                @Override
                                public byte[] readCredit() throws Exception {
                                    return readForDuration(step3Input,
                                            EXTERNAL_DMR_DATA36_CREDIT_TIMEOUT_MS);
                                }

                                @Override
                                public long nowMs() {
                                    return SystemClock.elapsedRealtime();
                                }
                            },
                            new ExternalDmrStep4OneUnitEvidence() {
                                @Override
                                public void onDrain(byte[] raw, long elapsedMs)
                                        throws Exception {
                                    recordStep3Evidence(evidenceRecords, transcript,
                                            transcriptStartedNanos,
                                            STEP3_TRANSCRIPT_DRAIN,
                                            "data36 quiet drain", "", raw, false);
                                    append(report, "Data36 quiet window ms",
                                            elapsedMs);
                                }

                                @Override
                                public void onWriteAttempt(byte[] frame)
                                        throws Exception {
                                    recordStep3Evidence(evidenceRecords, transcript,
                                            transcriptStartedNanos,
                                            STEP3_TRANSCRIPT_TX,
                                            "data36 request TX attempt",
                                            "h13_ext_dmr_step4_data36_req_",
                                            frame, true);
                                }

                                @Override
                                public void onWriteComplete() throws Exception {
                                    recordStep3Evidence(evidenceRecords, transcript,
                                            transcriptStartedNanos,
                                            STEP3_TRANSCRIPT_TX_COMPLETE,
                                            "data36 request TX complete", "",
                                            new byte[0], false);
                                }

                                @Override
                                public void onResponse(byte[] raw)
                                        throws Exception {
                                    recordStep3Evidence(evidenceRecords, transcript,
                                            transcriptStartedNanos,
                                            STEP3_TRANSCRIPT_RX,
                                            "data36 credit response raw",
                                            "h13_ext_dmr_step4_data36_credit_rsp_",
                                            raw, true);
                                    append(report,
                                            "Data36 short-response bytes", raw.length);
                                    append(report,
                                            "Data36 short-response SHA-256", sha256(raw));
                                    byte[] frame =
                                            extractFirstExternalEncodedTxCreditFrame(raw);
                                    if (frame != null) {
                                        append(report,
                                                "Data36 short-response frame SHA-256",
                                                sha256(frame));
                                    }
                                }
                            }, data36Execution, !softwareOneData36);
                } finally {
                    data36WriteCompleted = data36Execution.writeCompleted();
                    data36CreditAccepted =
                            data36Execution.creditShapeAccepted();
                }
                append(report, "Data36 short-response semantics",
                        "仅严格vendor短帧格式；不证明射频、可听音频或注入成功");
            }

            // HPI-only cleanup while still bridged — never ASCII.
            // 记录 cleanup 主机时刻，供退桥后与 DGAT 结果对照（非 bridge 内 memread）。
            cleanupHostAt = SystemClock.elapsedRealtime();
            append(report, "cleanup host monoMs", cleanupHostAt);
            append(report, "cleanup since systick arm ms",
                    cleanupHostAt - bridgeArmedAt);
            append(report, "cleanup after prepWaitDone ms",
                    cleanupHostAt - prepWaitDoneAt);
            if (cleanupHostAt < prepWaitDoneAt) {
                throw new IOException("时间线错乱：cleanup 早于 prepWaitDone");
            }
            Log.i(TAG, String.format(Locale.US,
                    "TIMING_CLEANUP_TX monoMs=%d sinceBridge=%d afterPrepWait=%d",
                    cleanupHostAt, cleanupHostAt - bridgeArmedAt,
                    cleanupHostAt - prepWaitDoneAt));
            controlPlaneMutationMayHaveStarted = true;
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                    "cleanup VOCODER_IO_OFF request",
                    "h13_ext_dmr_step3_cleanup_vocoder_off_req_",
                    HPI_VOCODER_IO_OFF, true);
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                    "cleanup WORK_MODE_IDLE request",
                    "h13_ext_dmr_step3_cleanup_idle_req_",
                    HPI_WORK_MODE_IDLE, true);
            hpiExitTrafficPlaneWhileBridged(output, report);
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_TX_COMPLETE,
                    "cleanup writes complete", "", new byte[0], false);
            byte[] cleanupResponse = readForDuration(input,
                    DATA_PLANE_CLEANUP_CAPTURE_MS);
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                    "cleanup response raw",
                    "h13_ext_dmr_step3_cleanup_rsp_",
                    cleanupResponse, true);
            boolean cleanupVocoderOffAck = containsControlStatusAck(
                    cleanupResponse, 0, 0x3e);
            boolean cleanupIdleAck = containsControlStatusAck(
                    cleanupResponse, 0, 0x18);
            append(report, "Cleanup VOCODER_IO_OFF ACK", cleanupVocoderOffAck);
            append(report, "Cleanup WORK_MODE_IDLE ACK", cleanupIdleAck);
            if (!cleanupVocoderOffAck || !cleanupIdleAck) {
                throw new IOException("HPI清理确认不完整，继续等待退桥并恢复");
            }
            }

            long safeReadAt = bridgeArmedAt + silentWaitMs;
            long remaining = safeReadAt - SystemClock.elapsedRealtime();
            if (remaining > 0) {
                SystemClock.sleep(remaining);
            }

            byte[] flagAfter = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            // flag=0一经严格读回，立即切回文本面；后续读取失败不得再发HPI。
            transport.commandModeConfirmedFromFlag(flagAfter);
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            if (softwareLegacyLowPowerRf && pttOnAttempted) {
                byte[] pttOffRequest = "AT+DMOPTT=0\r\n".getBytes(
                        StandardCharsets.US_ASCII);
                preserveRawEvidence(report, "H13 PTT释放请求原件",
                        "software_ambe_rf_ptt_off_req_", pttOffRequest);
                drainAvailable(input);
                pttOffAttempted = true;
                rfCommandCount++;
                output.write(pttOffRequest);
                output.flush();
                byte[] pttOffRaw = readForDuration(input, 1500);
                pttOffAtMs = SystemClock.elapsedRealtime();
                preserveRawEvidence(report, "H13 PTT释放完整响应原件",
                        "software_ambe_rf_ptt_off_rsp_", pttOffRaw);
                String pttOffText = new String(pttOffRaw,
                        StandardCharsets.US_ASCII);
                pttOffAccepted = containsExactAsciiLine(pttOffText,
                        "+DMOPTT:0");
                txEndObserved = containsExactAsciiLine(pttOffText,
                        "+DMOSENDMOUDULESTA:TxEnd");
                if (pttOffAccepted && txEndObserved && pttWatchdog != null) {
                    pttWatchdog.cancelAfterConfirmedRelease();
                }
                appendRaw(report, "H13 PTT释放完整响应", pttOffRaw);

                byte[] audioAfterPttOffRaw = readDmrAudioSwitchState();
                preserveRawEvidence(report, "PTT释放后麦克风路径只读回读",
                        "software_ambe_rf_audio_after_ptt_off_",
                        audioAfterPttOffRaw);
                String audioAfterPttOffText = new String(audioAfterPttOffRaw,
                        StandardCharsets.US_ASCII);
                audioSwitchAfterPttOffZero = audioAfterPttOffText.contains(
                        "audio_switch=0");
                audioSwitchStayedZero = audioSwitchStayedZero
                        && audioSwitchAfterPttOffZero;
            }
            if (softwareProductionRf) {
                byte[] rfPrepMarkerBeforeOff = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                byte[] activeGateBeforeOff = readMemory(input, output,
                        EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                preserveRawEvidence(report,
                        "生产同构RF准备执行标记原件",
                        "external_dmr_rf_prep_marker_before_off_",
                        rfPrepMarkerBeforeOff);
                preserveRawEvidence(report,
                        "生产同构RF关闭前active gate原件",
                        "external_dmr_rf_active_gate_before_off_",
                        activeGateBeforeOff);
                productionRfPrepareExecuted = u32le(rfPrepMarkerBeforeOff, 0)
                        == EXTERNAL_DMR_RF_PREP_MARKER;
                if (!productionRfPrepareExecuted) {
                    throw new IOException("生产同构RF准备桩缺少独立执行标记");
                }
                if (u32le(activeGateBeforeOff, 0) != 1) {
                    throw new IOException("生产同构fullprep未留下RF active gate=1");
                }
                productionRfOffAttempted = true;
                writeMemoryWord(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 0);
                writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                        EXTERNAL_DMR_RF_OFF_ENTRY);
                SystemClock.sleep(100);
                byte[] rfOffMarkerAfter = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                byte[] activeGateAfterOff = readMemory(input, output,
                        EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                byte[] vectorAfterOff = readMemory(input, output,
                        RAM_VECTOR_SYSTICK, 4);
                pttOffAtMs = SystemClock.elapsedRealtime();
                preserveRawEvidence(report, "生产同构RF关闭标记原件",
                        "external_dmr_rf_off_marker_after_", rfOffMarkerAfter);
                preserveRawEvidence(report, "生产同构RF关闭后active gate原件",
                        "external_dmr_rf_active_gate_after_off_",
                        activeGateAfterOff);
                preserveRawEvidence(report, "生产同构RF关闭后SysTick原件",
                        "external_dmr_rf_vector_after_off_", vectorAfterOff);
                productionRfOffConfirmed =
                        u32le(rfOffMarkerAfter, 0)
                                == EXTERNAL_DMR_RF_OFF_MARKER
                        && u32le(activeGateAfterOff, 0) == 0
                        && u32le(vectorAfterOff, 0)
                                == ORIGINAL_SYSTICK_HANDLER;
                append(report, "生产同构完整RF关闭确认",
                        productionRfOffConfirmed);
                if (!productionRfOffConfirmed) {
                    throw new IOException("生产同构完整RF关闭桩未闭环");
                }
                persistProductionRfReleaseAttestation(rfOffMarkerAfter,
                        activeGateAfterOff, vectorAfterOff);
                if (pttWatchdog != null) {
                    pttWatchdog.cancelAfterConfirmedRelease();
                }
            }
            byte[] vectorAfter = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            byte[] absAfter = readMemory(input, output,
                    COMBINED_ABS_COUNTER_ADDRESS, 4);
            byte[] exitAfter = readMemory(input, output,
                    COMBINED_EXIT_MARKER_ADDRESS, 4);
            byte[] prepMarkerAfter = readMemory(input, output,
                    COMBINED_PREP_MARKER_ADDRESS, 4);
            byte[] combinedAfter = readMemory(input, output,
                    COMBINED_DUAL_COUNTER_CODE_ADDRESS,
                    combinedHandler.length);
            byte[] prepCounterAfter = readMemory(input, output,
                    COMBINED_PREP_COUNTER_ADDRESS, 4);
            byte[] prepPhaseAfter = readMemory(input, output,
                    COMBINED_PREP_PHASE_ADDRESS, 4);
            byte[] prepCursorAfter = readMemory(input, output,
                    COMBINED_PREP_CURSOR_ADDRESS, 4);
            byte[] runtimeMirrorAfter = readMemory(input, output,
                    RUNTIME_MIRROR_ADDRESS, RUNTIME_MIRROR_LENGTH);
            byte[] mirrorHelperAfter = readMemory(input, output,
                    RUNTIME_MIRROR_HELPER_ADDRESS,
                    wordsToBytes(RUNTIME_MIRROR_HELPER_WORDS).length);
            byte[] dataGateAfter = readMemory(input, output,
                    EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
            byte[] sessionStateAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
            byte[] ptrAAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
            byte[] ptrBAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
            byte[] flag1cAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
            byte[] countAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
            byte[] queueAAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH);
            byte[] queueBAfter = readMemory(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH);
            byte[] bootReadyAfter = readMemory(input, output,
                    SCT_BOOT_READY_ADDRESS, 1);
            byte[] bootModeAfter = readMemory(input, output,
                    SCT_BOOT_MODE_ADDRESS, 1);
            queueStep3SramSnapshot(evidenceRecords, "postexit",
                    combinedAfter, prepMarkerAfter, prepCounterAfter,
                    absAfter, exitAfter, prepPhaseAfter, prepCursorAfter,
                    mirrorHelperAfter, runtimeMirrorAfter,
                    dataGateAfter, sessionStateAfter, ptrAAfter, ptrBAfter,
                    flag1cAfter, countAfter, queueAAfter, queueBAfter,
                    vectorAfter, flagAfter, bootReadyAfter, bootModeAfter);
            append(report, "Bridge flag after", flagAfter[0] & 0xff);
            append(report, "boot-ready E4 after", bootReadyAfter[0] & 0xff);
            append(report, "boot-mode E5 after", bootModeAfter[0] & 0xff);
            Log.i(TAG, String.format(Locale.US,
                    "SCT_READY_POSTEXIT E4=%d E5=%d bridge=%d DGAT=0x%08x",
                    bootReadyAfter[0] & 0xff, bootModeAfter[0] & 0xff,
                    flagAfter[0] & 0xff, u32le(prepMarkerAfter, 0)));
            append(report, "SysTick after bridge", String.format(Locale.US,
                    "0x%08x", u32le(vectorAfter, 0)));
            append(report, "Abs exit counter after", u32le(absAfter, 0));
            append(report, "Exit marker after", String.format(Locale.US,
                    "0x%08x", u32le(exitAfter, 0)));
            append(report, "Datagate oneshot marker after",
                    String.format(Locale.US, "0x%08x",
                            u32le(prepMarkerAfter, 0)));
            append(report, "dataGate after bridge exit",
                    dataGateAfter[0] & 0xff);
            // 短行：避免 logcat 截断长报告导致无 DGAT 证据
            Log.i(TAG, String.format(Locale.US,
                    "COMBINED_MARKERS DGAT=0x%08x EXIT=0x%08x dataGate=%d "
                            + "flag=%d vector=0x%08x abs=%d",
                    u32le(prepMarkerAfter, 0), u32le(exitAfter, 0),
                    dataGateAfter[0] & 0xff, flagAfter[0] & 0xff,
                    u32le(vectorAfter, 0), u32le(absAfter, 0)));
            if ((flagAfter[0] & 0xff) != 0) {
                throw new IOException("Bridge flag not cleared by abs exit");
            }
            if (u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("SysTick vector not restored by abs exit");
            }
            if (u32le(absAfter, 0) != 0) {
                throw new IOException("Abs exit counter not zero after exit");
            }
            if (u32le(exitAfter, 0) != COMBINED_EXIT_MARKER) {
                throw new IOException("EXIT marker missing after abs exit");
            }
            if (u32le(prepMarkerAfter, 0) != COMBINED_PREP_MARKER) {
                throw new IOException(
                        "退桥后 DGAT marker 缺失；无法证明 multi-tick fullprep 完成");
            }
            if (u32le(runtimeMirrorAfter, 8) != RUNTIME_MIRROR_MARKER) {
                throw new IOException("退桥后 MIRR marker 缺失；实时字段未冻结");
            }
            if ((runtimeMirrorAfter[6] & 0xff) != 1
                    || (runtimeMirrorAfter[7] & 0xff) != 1) {
                throw new IOException("fullprep 实时镜像 dataGate/session_state 非1");
            }
            append(report, "Fullprep runtime mirror",
                    bytesToHex(runtimeMirrorAfter));
            append(report, "Fullprep runtime mirror fields match preflight",
                    runtimeMirrorVlcFieldsMatchPreflight(
                            expectedMeasuredRuntime14, runtimeMirrorAfter));
            if (!runtimeMirrorVlcFieldsMatchPreflight(
                    expectedMeasuredRuntime14, runtimeMirrorAfter)) {
                throw new IOException("fullprep 后实时字段与同版本预检凭证不一致");
            }
            // 可审计顺序（主机时刻）：setupDone ≤ prepWaitDone ≤ cleanup/首条VLC；
            // DGAT 仅在退桥后文本回读确认存在。不能据此单独反推 MCU 写 DGAT 的
            // 精确 tick；若需更强证明，应由桩写入完成 tick 供退桥后读取。
            append(report, "post-exit DGAT observed", true);
            append(report, "post-exit dataGate", dataGateAfter[0] & 0xff);
            if (setup0Only) {
                append(report, "Setup0-only post-exit DGAT observed", true);
                Log.i(TAG, String.format(Locale.US,
                        "SETUP0_ONLY_POST_EXIT DGAT=0x%08x dataGate=%d no_further_hpi_tx=true",
                        u32le(prepMarkerAfter, 0), dataGateAfter[0] & 0xff));
            } else if (setup04Only) {
                append(report, "Setup0-4-only post-exit DGAT observed", true);
                Log.i(TAG, String.format(Locale.US,
                        "SETUP04_ONLY_POST_EXIT DGAT=0x%08x dataGate=%d "
                                + "setupAcks=5 no_further_hpi_tx=true",
                        u32le(prepMarkerAfter, 0), dataGateAfter[0] & 0xff));
            } else {
                append(report, "host timeline ok prepWait before cleanup",
                        cleanupHostAt >= prepWaitDoneAt);
                Log.i(TAG, String.format(Locale.US,
                        "TIMING_PREP_COMPLETE_POST_EXIT DGAT=0x%08x dataGate=%d "
                                + "prepWaitMs=%d cleanupMs=%d",
                        u32le(prepMarkerAfter, 0), dataGateAfter[0] & 0xff,
                        prepWaitDoneAt - bridgeArmedAt,
                        cleanupHostAt - bridgeArmedAt));
            }

            stateRestored = restoreCombinedFullPrepState(input, output,
                    originalDatagateOneshot, originalDatagateMarker,
                    originalDatagateCounter, originalAbsCounter,
                    originalExitMarker, originalPrepPhase, originalPrepCursor,
                    originalMirrorHelper, originalRuntimeMirror,
                    originalDataGate, originalSessionState,
                    originalPtrA, originalPtrB, originalFlag1c, originalCount,
                    originalQueueA, originalQueueB, originalVector,
                    originalFlag, evidenceRecords, report, true);
            if (softwareProductionRf && rfWindowRestoreRequired) {
                restoreWords(input, output, EXTERNAL_DMR_RF_PREP_ADDRESS,
                        originalRfPrep);
                restoreWords(input, output, EXTERNAL_DMR_RF_OFF_ADDRESS,
                        originalRfOff);
                restoreWords(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                        originalRfOffMarker);
                restoreWords(input, output,
                        EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                        originalRfActiveGate);
                byte[] restoredRfPrep = readMemory(input, output,
                        EXTERNAL_DMR_RF_PREP_ADDRESS, originalRfPrep.length);
                byte[] restoredRfOff = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_ADDRESS, originalRfOff.length);
                byte[] restoredRfMarker = readMemory(input, output,
                        EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                byte[] restoredRfGate = readMemory(input, output,
                        EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                preserveRawEvidence(report, "External DMR RF准备桩恢复回读",
                        "external_dmr_rf_prep_restored_", restoredRfPrep);
                preserveRawEvidence(report, "External DMR RF关闭桩恢复回读",
                        "external_dmr_rf_off_restored_", restoredRfOff);
                preserveRawEvidence(report, "External DMR RF关闭标记恢复回读",
                        "external_dmr_rf_off_marker_restored_", restoredRfMarker);
                preserveRawEvidence(report, "External DMR RF active gate恢复回读",
                        "external_dmr_rf_active_gate_restored_", restoredRfGate);
                if (!Arrays.equals(originalRfPrep, restoredRfPrep)
                        || !Arrays.equals(originalRfOff, restoredRfOff)
                        || !Arrays.equals(originalRfOffMarker,
                        restoredRfMarker)
                        || !Arrays.equals(originalRfActiveGate,
                        restoredRfGate)) {
                    throw new IOException("External DMR RF新窗恢复不一致");
                }
                rfWindowRestoreRequired = false;
            }
            transport.temporaryStateRestored();

            // 所有桥内证据只在退桥并恢复SRAM后落盘，文件延迟不占18秒窗口。
            persistStep3Evidence(evidenceRecords, transcript, report);
            evidencePersisted = true;

            // WORK_MODE(2)/VLC之后必须执行一次且仅一次生产控制面归一化。
            controlPlaneReloadAttempted = true;
            reloadSctBaselineTrafficPlane(input, output, report, 1);
            verifyExternalDmrPrivacyOffRuntimeRestored(input, output,
                    privacyTransaction, report,
                    "h13_ext_dmr_post_reload_runtime_round");
            privacyTransaction.control.restoredByValidatedReload();
            privacyTransaction.privacyOffRestored = true;
            controlPlaneRestored = true;

            disableLogLevel(input, output, report);
            if (softwareSessionReady) {
                if (!softwareHardStopReached
                        || data36Execution.writeAttempted()
                        || data36WriteCompleted
                        || softwareFirstRequest == null
                        || softwareFirstRequest.length != 44) {
                    throw new IOException("软件AMBE写前硬停止合同未满足");
                }
                outcomeSuccess = true;
                outcomeStatus = "PASS: 软件AMBE已绑定同次privacy、五前序、"
                        + "WORK_MODE(2)及五VLC；第一条data36写调用前硬停止；"
                        + "SRAM与控制面恢复通过";
            } else if (softwareProductionRf) {
                boolean setup0PathOk = (setup0FirstOk
                        && !setup0RetryUsed && !setup0RetryOk)
                        || (!setup0FirstOk && setup0RetryUsed
                        && setup0RetryOk);
                if (!data36WriteCompleted
                        || softwareFullData36WrittenCount
                        != SOFTWARE_AMBE_MORSE_DATA36_COUNT
                        || softwareFullPaceWindowCount
                         != SOFTWARE_AMBE_MORSE_DATA36_COUNT
                        || softwareFullMaxPaceLateMs
                        > SOFTWARE_AMBE_MORSE_MAX_LATE_MS
                        || !productionRfPreparationWritten
                        || !productionRfWindowStartWritten
                        || !productionRfPrepareExecuted
                        || !productionRfOffAttempted
                        || !productionRfOffConfirmed
                        || rfCommandCount != 0 || pttOnAttempted
                        || pttOffAttempted || !setup0PathOk
                        || setup0FailReason.length() != 0) {
                    throw new IOException("生产同构摩尔斯26单元、80毫秒节拍或完整RF关闭闭环不完整");
                }
                outcomeSuccess = true;
                outcomeStatus = "PASS: 生产同构External DMR不经DMOPTT，按80毫秒绝对节拍写出完整26个"
                        + "data36（104个AMBE帧），0x0801FF34完整RF关闭及active gate清零通过；"
                        + "流程完成不证明模块消费，最终仍以TYT可辨认摩尔斯为准";
            } else if (softwareFullMorseRf) {
                if (!data36WriteCompleted
                        || softwareFullData36WrittenCount
                        != SOFTWARE_AMBE_MORSE_DATA36_COUNT
                        || softwareFullPaceWindowCount
                        != SOFTWARE_AMBE_MORSE_DATA36_COUNT
                        || !pttOnAccepted || !txStartObserved
                        || !pttOffAccepted || !txEndObserved
                        || rfCommandCount != 2) {
                    throw new IOException("完整摩尔斯26单元、80毫秒节拍或PTT闭环不完整");
                }
                outcomeSuccess = true;
                outcomeStatus = "PASS: H13自动低功率PTT并按80毫秒绝对节拍写出完整26个"
                        + "data36（104个AMBE帧）；TxStart/TxEnd闭环通过；"
                        + "最终听感仍以TYT可辨认摩尔斯为准";
            } else if (softwareLegacyLowPowerRf) {
                if (!data36WriteCompleted || !data36CreditAccepted
                        || !pttOnAccepted || !txStartObserved
                        || !pttOffAccepted || !txEndObserved
                        || rfCommandCount != 2) {
                    throw new IOException("低功率空口试验的data36或PTT闭环不完整");
                }
                outcomeSuccess = true;
                outcomeStatus = "PASS: H13自动低功率PTT、软件AMBE首个data36、"
                        + "严格credit及TxStart/TxEnd闭环均通过；"
                        + "仍须以TYT实际收到的可辨认摩尔斯音频完成最终空口验收";
            } else if (softwareOneData36) {
                if (!data36WriteCompleted || !data36CreditAccepted
                        || data36Execution.writeAttempted() == false
                        || softwareFirstRequest == null) {
                    throw new IOException("软件AMBE第一条data36未完成唯一写入和credit门");
                }
                outcomeSuccess = true;
                outcomeStatus = "PASS: 软件AMBE第一条data36唯一写入、flush、"
                        + "严格credit、五前序、WORK_MODE(2)、五VLC、SRAM与控制面恢复均通过；"
                        + "不构成步骤8射频证明";
            } else if (softwareRealtimeData36) {
                if (realtimeRelay == null) {
                    throw new IOException("软件AMBE实时触发上下文未建立");
                }
                realtimeRelay.requireStrictPass();
                if (!"software_ambe".equals(realtimeRelay.payloadSource())) {
                    throw new IOException("软件AMBE实时触发载荷来源标记错误");
                }
                outcomeSuccess = true;
                outcomeStatus = "PASS: 软件AMBE第一条data36由第三实时DMR单元触发；"
                        + "载荷与实时流独立、唯一post-flush短credit、五VLC、"
                        + "SRAM与控制面恢复均通过；不构成步骤8射频证明";
            } else if (sendRealtimeRelayData36) {
                if (realtimeRelay == null) {
                    throw new IOException("实时relay上下文未建立");
                }
                realtimeRelay.requireStrictPass();
                outcomeSuccess = true;
                outcomeStatus = sendFixedAssetData36
                        ? "PASS: v2.05 第三个实时DMR单元触发唯一固定资产unit0；"
                        + "载荷与实时流独立、唯一post-flush短credit、五VLC、SRAM与控制面恢复均通过；"
                        + "本结论仍不替代接收端可听音频验收"
                        : "PASS: v2.03 第三个实时DMR单元触发唯一data36；"
                        + "唯一post-flush短credit、五VLC、SRAM与控制面恢复均通过；"
                        + "本结论仍不替代接收端可听音频验收";
            } else if (sendOneHostEncryptedData36) {
                if (!data36WriteCompleted || !data36CreditAccepted) {
                    throw new IOException(
                            "步骤4 要求 data36 写出且 credit 格式门通过");
                }
                outcomeSuccess = true;
                outcomeStatus = (sendGeneratedData36
                        ? "PASS: 本次内置编码器生成data36的credit格式门通过；"
                        : "PASS: 步骤4 冻结 unit0 data36 credit 格式门通过；")
                        + "write 成功不单独计 PASS；恢复闭环通过；"
                        + "非射频注入成功证明";
            } else if (setup0Only) {
                outcomeSuccess = true;
                if (setup0RetryUsed && setup0RetryOk) {
                    outcomeStatus = "PASS: setup0-only 第二次原样重发后严格确认；"
                            + "首次双空；未发送setup1-4、WORK_MODE、VLC、data36或PTT；"
                            + "SRAM与控制面恢复通过";
                } else {
                    outcomeStatus = "PASS: setup0-only 首次严格8字节确认；未重试；"
                            + "未发送setup1-4、WORK_MODE、VLC、data36或PTT；"
                            + "SRAM与控制面恢复通过";
                }
            } else if (setup04Only) {
                outcomeSuccess = true;
                outcomeStatus = "PASS: setup0-4-only 五前序严格确认；未发送VLC、"
                        + "data36、PTT或HPI清理；setup4早于prep截止；"
                        + "SRAM与控制面恢复通过";
            } else if (runVlcSession) {
                outcomeSuccess = true;
                outcomeStatus = "PASS: 步骤3 五前序+五 VLC 控制会话 @57600；data36 未发送；"
                        + "SysTick退桥、SRAM与控制面恢复通过";
            } else {
                outcomeSuccess = true;
                outcomeStatus = "PASS: setup+fullprep 隔离 @57600；VLC未发送；"
                        + "setup4早于prep截止；DGAT+EXIT；SRAM与控制面恢复通过";
            }
        } catch (Throwable error) {
            Log.e(TAG, "External DMR VLC session @57600 failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            append(report, "Transport state at failure", transport.state());
            append(report, "Data36 write completed at failure",
                    data36WriteCompleted);
            append(report, "Data36 short-response shape accepted at failure",
                    data36CreditAccepted);
            outcomeSuccess = false;
            if (softwareProductionRf) {
                if (setup0FailReason == null
                        || setup0FailReason.length() == 0) {
                    setup0FailReason = error.getMessage() == null
                            ? "生产同构RF失败原因缺失"
                            : error.getMessage();
                }
                outcomeStatus = "FAIL: 软件AMBE生产同构External DMR完整摩尔斯低功率空口试验";
            } else if (softwareFullMorseRf) {
                outcomeStatus = "FAIL: 软件AMBE完整摩尔斯低功率空口试验";
            } else if (softwareLowPowerRf) {
                outcomeStatus = "FAIL: 软件AMBE单data36低功率空口试验";
            } else if (softwareRealtimeData36) {
                outcomeStatus = "FAIL: 软件AMBE第三实时单元触发第一条data36";
            } else if (softwareOneData36) {
                outcomeStatus = "FAIL: 软件AMBE第一条data36唯一消费";
            } else if (softwareSessionReady) {
                outcomeStatus = "FAIL: 软件AMBE真实会话写前硬停止";
            } else if (sendRealtimeRelayData36) {
                if (setup0FailReason == null || setup0FailReason.length() == 0) {
                    setup0FailReason = error.getMessage() == null
                            ? "实时relay失败原因缺失"
                            : error.getMessage();
                }
                outcomeStatus = (sendFixedAssetData36
                        ? "FAIL: v2.05 固定资产实时触发单data36；"
                        : "FAIL: v2.04 实时relay单data36；")
                        + setup0FailReason;
            } else if (sendOneHostEncryptedData36) {
                outcomeStatus = "FAIL: 步骤4 单 data36 credit";
            } else if (setup0Only) {
                if (setup0FailReason == null || setup0FailReason.length() == 0) {
                    setup0FailReason = error.getMessage() == null
                            ? "setup0 确认失败"
                            : error.getMessage();
                }
                outcomeStatus = "FAIL: setup0-only " + setup0FailReason
                        + " first_ok=" + setup0FirstOk
                        + " retry_used=" + setup0RetryUsed
                        + " retry_ok=" + setup0RetryOk;
            } else if (setup04Only) {
                outcomeStatus = "FAIL: setup0-4-only 五前序重复性";
            } else if (!runVlcSession) {
                outcomeStatus = "FAIL: setup+fullprep 隔离";
            } else {
                outcomeStatus = "FAIL: 步骤3 控制会话";
            }
        } finally {
            if (realtimeRelay != null) {
                try {
                    realtimeRelay.finalizeEvidence();
                    data36WriteCompleted = realtimeRelay.writeCompleted();
                    data36CreditAccepted = realtimeRelay.creditAccepted();
                } catch (Throwable relayEvidenceError) {
                    append(report, "finally.realtimeRelayEvidence",
                            "fail: " + relayEvidenceError.getMessage());
                }
            }
            // 只有flag写入明确返回后才允许HPI清理；不确定时保持静默等看门狗。
            if (silentSetupOnly && transport.maySendHpiCleanup()) {
                append(report, "finally.hpiExitWhileBridged",
                        setup0Only
                                ? "skipped: setup0-only禁止任何后续HPI请求，静默等待绝对退桥"
                                : "skipped: setup0-4-only禁止VLC/清理帧，静默等待绝对退桥");
            } else if (transport.maySendHpiCleanup() && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())) {
                try {
                    append(report, "finally.hpiExitWhileBridged", "attempt");
                    controlPlaneMutationMayHaveStarted = true;
                    recordStep3Evidence(evidenceRecords, transcript,
                            transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                            "finally cleanup VOCODER_IO_OFF request",
                            "h13_ext_dmr_step3_finally_vocoder_off_req_",
                            HPI_VOCODER_IO_OFF, true);
                    recordStep3Evidence(evidenceRecords, transcript,
                            transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                            "finally cleanup WORK_MODE_IDLE request",
                            "h13_ext_dmr_step3_finally_idle_req_",
                            HPI_WORK_MODE_IDLE, true);
                    hpiExitTrafficPlaneWhileBridged(output, report);
                    recordStep3Evidence(evidenceRecords, transcript,
                            transcriptStartedNanos,
                            STEP3_TRANSCRIPT_TX_COMPLETE,
                            "finally cleanup writes complete", "",
                            new byte[0], false);
                    append(report, "finally.hpiExitWhileBridged", "ok");
                } catch (Throwable exitError) {
                    append(report, "finally.hpiExitWhileBridged",
                            "fail: " + exitError.getMessage());
                }
            } else if (transport.state()
                    == Step3TransportState.BRIDGE_MAY_BE_ACTIVE) {
                append(report, "finally.hpiExitWhileBridged",
                        "skipped: flag写入结果不确定，HPI/ASCII均禁止");
            }
            if (transport.needsTimeoutWait() && input != null && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())) {
                try {
                    append(report, "finally.waitSysTickTimeout", "attempt");
                    long safeReadAt = bridgeArmedAt > 0
                            ? bridgeArmedAt + silentWaitMs
                            : SystemClock.elapsedRealtime() + silentWaitMs;
                    long remaining = safeReadAt
                            - SystemClock.elapsedRealtime();
                    if (remaining > 0) {
                        SystemClock.sleep(remaining);
                    }
                    byte[] flagAfter = readMemory(input, output,
                            UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
                    transport.commandModeConfirmedFromFlag(flagAfter);
                    if (softwareProductionRf && !productionRfOffConfirmed) {
                        byte[] markerBeforeEmergencyOff = readMemory(input,
                                output, EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                        byte[] gateBeforeEmergencyOff = readMemory(input, output,
                                EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                        preserveRawEvidence(report,
                                "异常路径RF关闭前准备/关闭标记原件",
                                "external_dmr_rf_marker_emergency_before_",
                                markerBeforeEmergencyOff);
                        preserveRawEvidence(report,
                                "异常路径RF关闭前active gate原件",
                                "external_dmr_rf_active_gate_emergency_before_",
                                gateBeforeEmergencyOff);
                        int markerBeforeOffValue = u32le(
                                markerBeforeEmergencyOff, 0);
                        int gateBeforeOffValue = u32le(
                                gateBeforeEmergencyOff, 0);
                        productionRfPrepareExecuted = markerBeforeOffValue
                                == EXTERNAL_DMR_RF_PREP_MARKER;
                        boolean mustExecuteRfOff = productionRfPrepareExecuted
                                || gateBeforeOffValue == 1;
                        if (mustExecuteRfOff) {
                            productionRfOffAttempted = true;
                            writeMemoryWord(input, output,
                                    EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 0);
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    EXTERNAL_DMR_RF_OFF_ENTRY);
                            SystemClock.sleep(100);
                            byte[] emergencyRfOffMarker = readMemory(input,
                                    output, EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                            byte[] emergencyRfGate = readMemory(input, output,
                                    EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                            byte[] emergencyRfVector = readMemory(input, output,
                                    RAM_VECTOR_SYSTICK, 4);
                            pttOffAtMs = SystemClock.elapsedRealtime();
                            preserveRawEvidence(report,
                                    "异常路径RF关闭标记原件",
                                    "external_dmr_rf_off_emergency_marker_",
                                    emergencyRfOffMarker);
                            preserveRawEvidence(report,
                                    "异常路径RF关闭后active gate原件",
                                    "external_dmr_rf_off_emergency_gate_",
                                    emergencyRfGate);
                            productionRfOffConfirmed =
                                    u32le(emergencyRfOffMarker, 0)
                                            == EXTERNAL_DMR_RF_OFF_MARKER
                                    && u32le(emergencyRfGate, 0) == 0
                                    && u32le(emergencyRfVector, 0)
                                            == ORIGINAL_SYSTICK_HANDLER;
                            if (productionRfOffConfirmed) {
                                persistProductionRfReleaseAttestation(
                                        emergencyRfOffMarker, emergencyRfGate,
                                        emergencyRfVector);
                            }
                            if (!productionRfPrepareExecuted) {
                                append(report, "异常路径RF准备标记",
                                        "缺失但active gate=1；已优先强制关闭，证据不完整");
                            }
                        } else if (markerBeforeOffValue
                                == EXTERNAL_DMR_RF_OFF_MARKER
                                && gateBeforeOffValue == 0) {
                            productionRfPrepareExecuted = true;
                            productionRfOffConfirmed = true;
                            append(report, "异常路径RF关闭",
                                    "关闭标记已存在且active gate=0");
                        } else if (markerBeforeOffValue == 0
                                && gateBeforeOffValue == 0) {
                            productionRfOffConfirmed = true;
                            append(report, "异常路径RF关闭",
                                    "无需执行：准备标记和active gate均为0");
                        } else {
                            throw new IOException("异常路径RF标记/active gate组合非法 marker="
                                    + String.format(Locale.US, "0x%08x",
                                    markerBeforeOffValue) + " gate="
                                    + gateBeforeOffValue);
                        }
                        if (!productionRfOffConfirmed) {
                            throw new IOException("异常路径完整RF关闭未确认");
                        }
                        if (pttWatchdog != null) {
                            pttWatchdog.cancelAfterConfirmedRelease();
                        }
                    }
                    // PTT释放优先于任何post-exit SRAM取证/恢复；v3.81在这里
                    // 先做取证导致异常发射多保持约97秒。
                    if (softwareLegacyLowPowerRf && pttOnAttempted
                            && !(pttOffAccepted && txEndObserved)) {
                        byte[] emergencyOffRequest =
                                "AT+DMOPTT=0\r\n".getBytes(
                                        StandardCharsets.US_ASCII);
                        preserveRawEvidence(report,
                                "文本面首次恢复后的优先PTT释放请求",
                                "software_ambe_rf_ptt_off_priority_req_",
                                emergencyOffRequest);
                        drainAvailable(input);
                        pttOffAttempted = true;
                        rfCommandCount++;
                        output.write(emergencyOffRequest);
                        output.flush();
                        byte[] emergencyOffRaw = readForDuration(input, 1500);
                        pttOffAtMs = SystemClock.elapsedRealtime();
                        preserveRawEvidence(report,
                                "文本面首次恢复后的优先PTT释放响应",
                                "software_ambe_rf_ptt_off_priority_rsp_",
                                emergencyOffRaw);
                        String emergencyOffText = new String(emergencyOffRaw,
                                StandardCharsets.US_ASCII);
                        pttOffAccepted = containsExactAsciiLine(
                                emergencyOffText, "+DMOPTT:0");
                        txEndObserved = txEndObserved
                                || containsExactAsciiLine(emergencyOffText,
                                "+DMOSENDMOUDULESTA:TxEnd");
                        appendRaw(report, "优先PTT释放响应", emergencyOffRaw);
                        if (pttOffAccepted && txEndObserved
                                && pttWatchdog != null) {
                            pttWatchdog.cancelAfterConfirmedRelease();
                        }
                    }
                    synchronized (lock) {
                        logLevelMayBeEnabled = true;
                    }
                    // v1.90：失败样本也必须在恢复前保存完整postexit快照。
                    // 证据读取失败只降低验收，不得阻断已经确认文本面的恢复动作。
                    try {
                        byte[] finallyCode = readMemory(input, output,
                                COMBINED_DUAL_COUNTER_CODE_ADDRESS,
                                wordsToBytes(COMBINED_DUAL_COUNTER_WORDS).length);
                        byte[] finallyPrepMarker = readMemory(input, output,
                                COMBINED_PREP_MARKER_ADDRESS, 4);
                        byte[] finallyPrepCounter = readMemory(input, output,
                                COMBINED_PREP_COUNTER_ADDRESS, 4);
                        byte[] finallyAbsCounter = readMemory(input, output,
                                COMBINED_ABS_COUNTER_ADDRESS, 4);
                        byte[] finallyExitMarker = readMemory(input, output,
                                COMBINED_EXIT_MARKER_ADDRESS, 4);
                        byte[] finallyPrepPhase = readMemory(input, output,
                                COMBINED_PREP_PHASE_ADDRESS, 4);
                        byte[] finallyPrepCursor = readMemory(input, output,
                                COMBINED_PREP_CURSOR_ADDRESS, 4);
                        byte[] finallyRuntimeMirror = readMemory(input, output,
                                RUNTIME_MIRROR_ADDRESS, RUNTIME_MIRROR_LENGTH);
                        byte[] finallyMirrorHelper = readMemory(input, output,
                                RUNTIME_MIRROR_HELPER_ADDRESS,
                                wordsToBytes(RUNTIME_MIRROR_HELPER_WORDS).length);
                        byte[] finallyDataGate = readMemory(input, output,
                                EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
                        byte[] finallySessionState = readMemory(input, output,
                                EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
                        byte[] finallyPtrA = readMemory(input, output,
                                EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
                        byte[] finallyPtrB = readMemory(input, output,
                                EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
                        byte[] finallyFlag1c = readMemory(input, output,
                                EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
                        byte[] finallyCount = readMemory(input, output,
                                EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
                        byte[] finallyQueueA = readMemory(input, output,
                                EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                                EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH);
                        byte[] finallyQueueB = readMemory(input, output,
                                EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                                EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH);
                        byte[] finallyVector = readMemory(input, output,
                                RAM_VECTOR_SYSTICK, 4);
                        byte[] finallyBootReady = readMemory(input, output,
                                SCT_BOOT_READY_ADDRESS, 1);
                        byte[] finallyBootMode = readMemory(input, output,
                                SCT_BOOT_MODE_ADDRESS, 1);
                        queueStep3SramSnapshot(evidenceRecords, "postexit",
                                finallyCode, finallyPrepMarker,
                                finallyPrepCounter, finallyAbsCounter,
                                finallyExitMarker, finallyPrepPhase,
                                finallyPrepCursor, finallyMirrorHelper,
                                finallyRuntimeMirror, finallyDataGate,
                                finallySessionState, finallyPtrA, finallyPtrB,
                                finallyFlag1c, finallyCount, finallyQueueA,
                                finallyQueueB, finallyVector, flagAfter,
                                finallyBootReady, finallyBootMode);
                        Log.i(TAG, String.format(Locale.US,
                                "SCT_READY_FINALLY_POSTEXIT E4=%d E5=%d bridge=%d",
                                finallyBootReady[0] & 0xff,
                                finallyBootMode[0] & 0xff,
                                flagAfter[0] & 0xff));
                        append(report, "finally.postexitEvidence",
                                "完整原始快照已排队");
                    } catch (Throwable snapshotError) {
                        append(report, "finally.postexitEvidence",
                                "不完整: " + snapshotError.getMessage());
                    }
                    append(report, "finally.waitSysTickTimeout",
                            "command mode restored");
                } catch (Throwable waitError) {
                    transport.recoveryUncertain();
                    append(report, "finally.waitSysTickTimeout",
                            "fail: " + waitError.getMessage()
                                    + "；禁止继续协议恢复，要求重启");
                }
            }
            // v3.88：异常恢复可能阻塞，先把已取得的setup和postexit原件落盘。
            // 原始证据持久化不得依赖后续SRAM恢复成功。
            if (!evidencePersisted && (!evidenceRecords.isEmpty()
                    || transcript.size() > 0)) {
                try {
                    persistStep3Evidence(evidenceRecords, transcript, report);
                    evidencePersisted = true;
                } catch (Throwable evidenceError) {
                    append(report, "finally.persistEvidenceBeforeRestore",
                            "fail: " + evidenceError.getMessage());
                }
            }
            if (transport.canAttemptAsciiRestore() && !stateRestored
                    && input != null && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())
                    && combinedWindowRestoreRequired
                    && originalDatagateOneshot != null
                    && originalDataGate != null) {
                try {
                    synchronized (lock) {
                        logLevelMayBeEnabled = true;
                    }
                    // 失败路径必须恢复 combined 窗口 + dataGate（v1.69 缺陷修复）
                    try {
                        byte[] prepM = readMemory(input, output,
                                COMBINED_PREP_MARKER_ADDRESS, 4);
                        byte[] exitM = readMemory(input, output,
                                COMBINED_EXIT_MARKER_ADDRESS, 4);
                        byte[] dg = readMemory(input, output,
                                EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
                        Log.i(TAG, String.format(Locale.US,
                                "FINALLY_MARKERS DGAT=0x%08x EXIT=0x%08x "
                                        + "dataGate=%d",
                                u32le(prepM, 0), u32le(exitM, 0),
                                dg[0] & 0xff));
                        append(report, "finally.DGAT",
                                String.format(Locale.US, "0x%08x",
                                        u32le(prepM, 0)));
                        append(report, "finally.EXIT",
                                String.format(Locale.US, "0x%08x",
                                        u32le(exitM, 0)));
                        append(report, "finally.dataGate", dg[0] & 0xff);
                    } catch (Throwable markErr) {
                        append(report, "finally.markerRead",
                                "fail: " + markErr.getMessage());
                    }
                    stateRestored = restoreCombinedFullPrepState(
                            input, output, originalDatagateOneshot,
                            originalDatagateMarker, originalDatagateCounter,
                            originalAbsCounter, originalExitMarker,
                            originalPrepPhase, originalPrepCursor,
                            originalMirrorHelper, originalRuntimeMirror,
                            originalDataGate, originalSessionState,
                            originalPtrA, originalPtrB, originalFlag1c,
                            originalCount, originalQueueA, originalQueueB,
                            originalVector, originalFlag, evidenceRecords,
                            report, false);
                    if (softwareProductionRf && rfWindowRestoreRequired
                            && originalRfPrep != null && originalRfOff != null
                            && originalRfOffMarker != null
                            && originalRfActiveGate != null) {
                        restoreWords(input, output,
                                EXTERNAL_DMR_RF_PREP_ADDRESS, originalRfPrep);
                        restoreWords(input, output,
                                EXTERNAL_DMR_RF_OFF_ADDRESS, originalRfOff);
                        restoreWords(input, output,
                                EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS,
                                originalRfOffMarker);
                        restoreWords(input, output,
                                EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS,
                                originalRfActiveGate);
                        byte[] finalRfPrep = readMemory(input, output,
                                EXTERNAL_DMR_RF_PREP_ADDRESS,
                                originalRfPrep.length);
                        byte[] finalRfOff = readMemory(input, output,
                                EXTERNAL_DMR_RF_OFF_ADDRESS,
                                originalRfOff.length);
                        byte[] finalRfMarker = readMemory(input, output,
                                EXTERNAL_DMR_RF_OFF_MARKER_ADDRESS, 4);
                        byte[] finalRfGate = readMemory(input, output,
                                EXTERNAL_DMR_RF_ACTIVE_GATE_ADDRESS, 4);
                        preserveRawEvidence(report,
                                "异常路径RF准备桩恢复回读",
                                "external_dmr_rf_prep_emergency_restored_",
                                finalRfPrep);
                        preserveRawEvidence(report,
                                "异常路径RF关闭桩恢复回读",
                                "external_dmr_rf_off_emergency_restored_",
                                finalRfOff);
                        if (!Arrays.equals(originalRfPrep, finalRfPrep)
                                || !Arrays.equals(originalRfOff, finalRfOff)
                                || !Arrays.equals(originalRfOffMarker,
                                finalRfMarker)
                                || !Arrays.equals(originalRfActiveGate,
                                finalRfGate)) {
                            throw new IOException("异常路径RF新窗恢复不一致");
                        }
                        rfWindowRestoreRequired = false;
                    }
                    transport.temporaryStateRestored();
                    append(report, "finally.emergencySramRestore",
                            "ok: combined+dataGate 逐字节回读一致");
                } catch (Throwable restoreError) {
                    transport.recoveryUncertain();
                    append(report, "finally.emergencySramRestore",
                            "fail: " + restoreError.getMessage());
                }
            } else if (transport.canAttemptAsciiRestore() && !stateRestored
                    && input != null && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())
                    && originalCode != null && originalCode.length == 64
                    && !allZero(originalCode)) {
                // 旧路径：仅 0x20001600 超时区（非 v1.70 step3 主路径）
                try {
                    synchronized (lock) {
                        logLevelMayBeEnabled = true;
                    }
                    stateRestored = restoreStep3TemporaryStateAndVerify(
                            input, output, originalCode, originalCounter,
                            originalMarker, originalVector, originalFlag, report);
                    transport.temporaryStateRestored();
                    append(report, "finally.emergencySramRestore",
                            "ok: 超时区逐字节回读一致");
                } catch (Throwable restoreError) {
                    transport.recoveryUncertain();
                    append(report, "finally.emergencySramRestore",
                            "fail: " + restoreError.getMessage());
                }
            } else if (!stateRestored && transport.state()
                    == Step3TransportState.RECOVERY_UNCERTAIN) {
                append(report, "finally.emergencySramRestore",
                        "skipped: 数据面不确定，ASCII禁止，要求重启");
            } else if (!stateRestored && combinedWindowRestoreRequired) {
                append(report, "finally.emergencySramRestore",
                        "skipped: 无文本面或备份不全，要求重启");
                transport.recoveryUncertain();
            }
            // 无法在恢复前落盘时，再做最后一次持久化尝试。
            if (!evidencePersisted && (!evidenceRecords.isEmpty()
                    || transcript.size() > 0)) {
                try {
                    persistStep3Evidence(evidenceRecords, transcript, report);
                    evidencePersisted = true;
                } catch (Throwable evidenceError) {
                    append(report, "finally.persistEvidence",
                            "fail: " + evidenceError.getMessage());
                }
            }
            if (softwareLegacyLowPowerRf && pttOnAttempted
                    && !(pttOffAccepted && txEndObserved)
                    && transport.canAttemptAsciiRestore()
                    && input != null && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())) {
                try {
                    byte[] emergencyOffRequest = "AT+DMOPTT=0\r\n".getBytes(
                            StandardCharsets.US_ASCII);
                    preserveRawEvidence(report, "异常路径PTT释放请求原件",
                            "software_ambe_rf_ptt_off_emergency_req_",
                            emergencyOffRequest);
                    drainAvailable(input);
                    pttOffAttempted = true;
                    rfCommandCount++;
                    output.write(emergencyOffRequest);
                    output.flush();
                    byte[] emergencyOffRaw = readForDuration(input, 1500);
                    pttOffAtMs = SystemClock.elapsedRealtime();
                    preserveRawEvidence(report, "异常路径PTT释放响应原件",
                            "software_ambe_rf_ptt_off_emergency_rsp_",
                            emergencyOffRaw);
                    String emergencyOffText = new String(emergencyOffRaw,
                            StandardCharsets.US_ASCII);
                    pttOffAccepted = containsExactAsciiLine(emergencyOffText,
                            "+DMOPTT:0");
                    txEndObserved = txEndObserved
                            || containsExactAsciiLine(emergencyOffText,
                            "+DMOSENDMOUDULESTA:TxEnd");
                    appendRaw(report, "异常路径PTT释放响应", emergencyOffRaw);
                    if (pttOffAccepted && txEndObserved
                            && pttWatchdog != null) {
                        pttWatchdog.cancelAfterConfirmedRelease();
                    }
                } catch (Throwable pttOffError) {
                    append(report, "finally.pttOff",
                            "fail: " + pttOffError.getMessage());
                }
            }
            if (softwareLowPowerRf && pttWatchdog != null) {
                boolean normalRfReleaseConfirmed = softwareProductionRf
                        ? productionRfOffConfirmed
                        : (pttOffAccepted && txEndObserved);
                if (!normalRfReleaseConfirmed) {
                    long waitMs = Math.max(0L, pttWatchdog.deadlineMs
                            - SystemClock.elapsedRealtime()) + 3000L;
                    pttWatchdog.awaitCompletion(waitMs);
                } else {
                    pttWatchdog.awaitCompletion(500L);
                }
                if (pttWatchdog.releaseAttempted) {
                    pttOffAttempted = true;
                    rfCommandCount++;
                    pttOffAtMs = Math.max(pttOffAtMs,
                            pttWatchdog.releaseAtMs);
                    try {
                        preserveRawEvidence(report,
                                "30秒看门狗PTT释放响应原件",
                                "software_ambe_rf_watchdog_ptt_off_rsp_",
                                pttWatchdog.responseRaw);
                    } catch (Throwable evidenceError) {
                        append(report, "30秒看门狗响应落盘失败",
                                evidenceError.getMessage());
                    }
                    pttOffAccepted = pttOffAccepted
                            || pttWatchdog.releaseAccepted;
                    txEndObserved = txEndObserved
                            || pttWatchdog.txEndObserved;
                }
                if (pttWatchdog.modulePowerOffAttempted) {
                    pttOffAtMs = Math.max(pttOffAtMs,
                            pttWatchdog.releaseAtMs);
                    try {
                        preserveRawEvidence(report,
                                "看门狗武装时dmr_switch基线原件",
                                "software_ambe_rf_watchdog_dmr_switch_before_",
                                pttWatchdog.modulePowerBeforeRaw);
                        preserveRawEvidence(report,
                                "30秒看门狗模块断电后dmr_switch原件",
                                "software_ambe_rf_watchdog_dmr_switch_after_",
                                pttWatchdog.modulePowerAfterRaw);
                    } catch (Throwable evidenceError) {
                        append(report, "30秒看门狗模块断电证据落盘失败",
                                evidenceError.getMessage());
                    }
                }
                append(report, "PTT看门狗已武装", pttWatchdog.armed);
                append(report, "PTT看门狗超时毫秒",
                        SOFTWARE_AMBE_PTT_WATCHDOG_TIMEOUT_MS);
                append(report, "PTT看门狗提前接管毫秒",
                        SOFTWARE_AMBE_PTT_WATCHDOG_TAKEOVER_LEAD_MS);
                append(report, "PTT看门狗已到期", pttWatchdog.expired);
                append(report, "PTT看门狗释放已尝试",
                        pttWatchdog.releaseAttempted);
                append(report, "PTT看门狗线程已完成",
                        pttWatchdog.completed || pttWatchdog.cancelled);
                append(report, "PTT看门狗已接管串口",
                        pttWatchdog.takeoverStarted);
                append(report, "PTT看门狗已撤销主线程串口所有权",
                        pttWatchdog.serialRevoked);
                append(report, "PTT看门狗模块断电已尝试",
                        pttWatchdog.modulePowerOffAttempted);
                append(report, "PTT看门狗模块断电已确认",
                        pttWatchdog.modulePowerOffConfirmed);
                append(report, "PTT看门狗绝对期限内确认",
                        pttWatchdog.absoluteDeadlineMet);
                append(report, "PTT看门狗接管时已越过文本面安全时刻",
                        pttWatchdog.bridgeSafetyDeadlineSatisfied);
                append(report, "PTT看门狗预计文本面安全时刻",
                        pttWatchdog.bridgeAutoExitSafeAtMs);
                append(report, "PTT看门狗错误", pttWatchdog.error);
            }
            if (softwareLegacyLowPowerRf) {
                try {
                    byte[] audioFinalRaw = readDmrAudioSwitchState();
                    preserveRawEvidence(report, "finally麦克风路径只读回读",
                            "software_ambe_rf_audio_final_", audioFinalRaw);
                    String audioFinalText = new String(audioFinalRaw,
                            StandardCharsets.US_ASCII);
                    audioSwitchStayedZero = audioSwitchStayedZero
                            && audioFinalText.contains("audio_switch=0");
                } catch (Throwable audioReadError) {
                    audioSwitchStayedZero = false;
                    append(report, "finally.audioSwitchRead",
                            "fail: " + audioReadError.getMessage());
                }
                if (pttOnAttempted
                        && !(pttOffAccepted && txEndObserved)) {
                    outcomeSuccess = false;
                    outcomeStatus = "FAIL: H13发射释放闭环未确认";
                }
            }
            if (softwareProductionRf && !productionRfOffConfirmed) {
                outcomeSuccess = false;
                outcomeStatus = "FAIL: 生产同构External DMR完整RF关闭未确认";
            }
            if (privacyTransaction.mutationMayHaveStarted
                    && transport.state() == Step3TransportState.TEXT_CONFIRMED
                    && !controlPlaneReloadAttempted
                    && input != null && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())) {
                controlPlaneReloadAttempted = true;
                try {
                    restoreExternalDmrPrivacyOffChannel(input, output,
                            privacyTransaction, report);
                    controlPlaneRestored = true;
                } catch (Throwable restorePrivacyError) {
                    append(report, "finally.privacyOffRestore",
                            "fail: " + restorePrivacyError.getMessage());
                    controlPlaneRestored = false;
                    outcomeSuccess = false;
                    outcomeStatus = "FAIL: privacy-off恢复失败";
                }
            }
            if ((controlPlaneMutationMayHaveStarted
                    || privacyTransaction.mutationMayHaveStarted) && stateRestored
                    && transport.state()
                    == Step3TransportState.TEXT_AFTER_TIMEOUT_CONFIRMED
                    && !controlPlaneReloadAttempted
                    && input != null && output != null
                    && (pttWatchdog == null || !pttWatchdog.ownsSerial())) {
                controlPlaneReloadAttempted = true;
                controlPlaneRestored = bestEffortStep3ControlPlaneReload(
                        input, output, report);
                if (controlPlaneRestored) {
                    try {
                        verifyExternalDmrPrivacyOffRuntimeRestored(input, output,
                                privacyTransaction, report,
                                "h13_ext_dmr_final_reload_runtime_round");
                        privacyTransaction.control.restoredByValidatedReload();
                        privacyTransaction.privacyOffRestored = true;
                    } catch (Throwable runtimeRestoreError) {
                        append(report, "finally.privacyRuntimeRestore",
                                "fail: " + runtimeRestoreError.getMessage());
                        controlPlaneRestored = false;
                    }
                }
                if (!controlPlaneRestored) {
                    outcomeSuccess = false;
                    outcomeStatus = "FAIL: 步骤3控制面恢复失败";
                }
            } else if ((controlPlaneMutationMayHaveStarted
                    || privacyTransaction.mutationMayHaveStarted)
                    && !controlPlaneRestored && !controlPlaneReloadAttempted) {
                append(report, "finally.controlPlaneReload",
                        "skipped: 文本面或SRAM恢复未确认，要求重启");
            }
            boolean rebootRecoveryRequired = transport.state()
                    == Step3TransportState.RECOVERY_UNCERTAIN
                    || ((controlPlaneMutationMayHaveStarted
                    || privacyTransaction.mutationMayHaveStarted)
                    && !controlPlaneRestored);
            if (rebootRecoveryRequired) {
                synchronized (lock) {
                    // 状态不确定后close不得再发送print等文本命令。
                    logLevelMayBeEnabled = false;
                }
                outcomeSuccess = false;
                outcomeStatus = "FAIL: 步骤3恢复不确定，要求获批后重启恢复";
                append(report, "Recovery action", "要求获批后重启，禁止继续协议命令");
                Log.e(TAG, "STEP3_REBOOT_REQUIRED transport="
                        + transport.state() + " controlPlaneRestored="
                        + controlPlaneRestored);
            }
            append(report, "Final transport state", transport.state());
            append(report, "Control-plane reload attempted",
                    controlPlaneReloadAttempted);
            append(report, "Control-plane restored", controlPlaneRestored);
            append(report, "Privacy-on runtime verified",
                    privacyTransaction.privacyOnVerified);
            append(report, "Privacy-off channel restored",
                    privacyTransaction.privacyOffRestored || controlPlaneRestored);
            append(report, "Evidence persisted", evidencePersisted);
            if (sendOneHostEncryptedData36) {
                append(report, "Data36 write attempted",
                        softwareFullMorseRf
                                ? softwareFullData36WrittenCount > 0
                                : data36Execution.writeAttempted());
                append(report, "Data36 write completed",
                        softwareFullMorseRf
                                ? data36WriteCompleted
                                : data36Execution.writeCompleted());
                append(report, "Data36 flush completed monotonic ms",
                        data36Execution.flushCompletedAtMs());
                append(report, "Data36 response captured monotonic ms",
                        data36Execution.responseCapturedAtMs());
                append(report, "Data36 response after flush ms",
                        data36Execution.responseAfterFlushMs());
                append(report, "Data36 short-response shape accepted",
                        data36Execution.creditShapeAccepted());
                ExternalEncodedTxCreditShape creditShape =
                        data36Execution.creditShape();
                if (creditShape != null) {
                    append(report, "Data36 short-response packet type",
                            creditShape.packetType);
                    append(report, "Data36 short-response payload length",
                            creditShape.payloadLength);
                    append(report, "Data36 short-response value",
                            creditShape.responseValue);
                    append(report, "Data36 short-response second payload byte",
                            creditShape.secondPayloadByte);
                    append(report, "Data36 short-response declared frame bytes",
                            creditShape.declaredFrameLength);
                    append(report, "Data36 short-response wire bytes",
                            creditShape.wireLength);
                    append(report, "Data36 short-response padding present",
                            creditShape.paddingPresent);
                }
                append(report, "Data36 recovery completed",
                        stateRestored && controlPlaneRestored
                                && !rebootRecoveryRequired);
                append(report, "Data36 write-as-PASS", false);
            } else if (sendRealtimeRelayData36 && realtimeRelay != null) {
                append(report, "Realtime relay data36 write completed",
                        realtimeRelay.writeCompleted());
                append(report, "Realtime relay credit accepted",
                        realtimeRelay.creditAccepted());
                append(report, "Realtime relay data36 write-as-PASS", false);
            }
            // 原子结果：在 close 前落盘，宿主优先读文件而非 logcat
            // v1.97：统一附加 setup/VLC/data36 计数与禁止写出字段，供宿主模式硬门。
            int setupAcksFinal = 0;
            int vlcAcksFinal = 0;
            try {
                if (model != null) {
                    setupAcksFinal = model.setupAcks();
                    vlcAcksFinal = model.vlcAcks();
                }
            } catch (Throwable ignored) {
                // model 可能在早期失败前未初始化
            }
            int data36Count = softwareFullMorseRf
                    ? softwareFullData36WrittenCount
                    : (data36WriteCompleted ? 1 : 0);
            if (data36Execution != null && data36Execution.writeCompleted()) {
                data36Count = 1;
            }
            if (sendRealtimeRelayData36 && realtimeRelay != null) {
                data36Count = realtimeRelay.writeCount();
            }
            long creditLatencyMs = -1L;
            if (data36Execution != null
                    && data36Execution.creditShapeAccepted()
                    && data36Execution.responseAfterFlushMs() >= 0) {
                creditLatencyMs = data36Execution.responseAfterFlushMs();
            }
            boolean creditShapeOk = data36Execution != null
                    && data36Execution.creditShapeAccepted();
            long data36FlushMs = data36Execution == null ? -1L
                    : data36Execution.flushCompletedAtMs();
            long data36ResponseMs = data36Execution != null
                    && data36Execution.creditShapeAccepted()
                    ? data36Execution.responseCapturedAtMs() : -1L;
            if (softwareFullMorseRf) {
                creditLatencyMs = -1L;
                creditShapeOk = false;
                data36FlushMs = softwareFullFirstFlushMs;
                data36ResponseMs = softwareFullLastFlushMs;
            }
            if (sendRealtimeRelayData36 && realtimeRelay != null) {
                creditLatencyMs = realtimeRelay.creditLatencyMs();
                creditShapeOk = realtimeRelay.creditAccepted();
                data36FlushMs = realtimeRelay.flushCompletedAtMs();
                data36ResponseMs = realtimeRelay.creditObservedAtMs();
            }
            // 本路径禁止的写出：非 setup0-only 时 setup1-4/VLC/data36 由模式门控制；
            // forbidden_tx_count 统计“本模式不应出现却已完成”的 data36（VLC-only 应为0）。
            int forbiddenTxCount = 0;
            if (runVlcSession && !activeData36
                    && data36Count > 0) {
                forbiddenTxCount = data36Count;
            }
            if (setup0Only && (setupAcksFinal > 1 || vlcAcksFinal > 0
                    || data36Count > 0)) {
                forbiddenTxCount = Math.max(forbiddenTxCount,
                        (setupAcksFinal > 1 ? setupAcksFinal - 1 : 0)
                                + vlcAcksFinal + data36Count);
            }
            StringBuilder atomicExtraBuilder = new StringBuilder();
            atomicExtraBuilder.append("setup_acks=").append(setupAcksFinal)
                    .append('\n');
            atomicExtraBuilder.append("vlc_acks=").append(vlcAcksFinal)
                    .append('\n');
            atomicExtraBuilder.append("data36_written=")
                    .append(data36Count > 0)
                    .append('\n');
            atomicExtraBuilder.append("data36_count=").append(data36Count)
                    .append('\n');
            atomicExtraBuilder.append("credit_shape_accepted=")
                    .append(creditShapeOk).append('\n');
            atomicExtraBuilder.append("credit_latency_ms=")
                    .append(creditLatencyMs).append('\n');
            atomicExtraBuilder.append("data36_flush_completed_ms=")
                    .append(data36FlushMs)
                    .append('\n');
            atomicExtraBuilder.append("data36_response_captured_ms=")
                    .append(data36ResponseMs)
                    .append('\n');
            atomicExtraBuilder.append("forbidden_tx_count=")
                    .append(forbiddenTxCount).append('\n');
            atomicExtraBuilder.append("rf_command_count=")
                    .append(rfCommandCount).append('\n');
            if (softwareLowPowerRf) {
                atomicExtraBuilder.append("production_external_rf=")
                        .append(softwareProductionRf).append('\n');
                if (softwareProductionRf) {
                    atomicExtraBuilder.append("startup_rejected=false\n");
                    atomicExtraBuilder.append("production_rf_preparation_written=")
                            .append(productionRfPreparationWritten).append('\n');
                    atomicExtraBuilder.append("rf_prepare_executed=")
                            .append(productionRfPrepareExecuted).append('\n');
                }
                atomicExtraBuilder.append("production_rf_window_start_written=")
                        .append(productionRfWindowStartWritten).append('\n');
                atomicExtraBuilder.append("production_rf_window_start_epoch=")
                        .append(productionRfWindowStartEpoch).append('\n');
                atomicExtraBuilder.append("dmoptt_forbidden=")
                        .append(softwareProductionRf).append('\n');
                atomicExtraBuilder.append("production_rf_off_attempted=")
                        .append(productionRfOffAttempted).append('\n');
                atomicExtraBuilder.append("production_rf_off_confirmed=")
                        .append(productionRfOffConfirmed).append('\n');
                atomicExtraBuilder.append("rf_window_restored=")
                        .append(!rfWindowRestoreRequired).append('\n');
                atomicExtraBuilder.append("ptt_on_attempted=")
                        .append(pttOnAttempted).append('\n');
                atomicExtraBuilder.append("ptt_on_accepted=")
                        .append(pttOnAccepted).append('\n');
                atomicExtraBuilder.append("tx_start_observed=")
                        .append(txStartObserved).append('\n');
                atomicExtraBuilder.append("ptt_off_attempted=")
                        .append(pttOffAttempted).append('\n');
                atomicExtraBuilder.append("ptt_off_accepted=")
                        .append(pttOffAccepted).append('\n');
                atomicExtraBuilder.append("tx_end_observed=")
                        .append(txEndObserved).append('\n');
                atomicExtraBuilder.append("manual_pa_write_attempted=false\n");
                atomicExtraBuilder.append("audio_switch_before_ptt_zero=")
                        .append(audioSwitchBeforePttZero).append('\n');
                atomicExtraBuilder.append("audio_switch_after_tx_start_zero=")
                        .append(audioSwitchAfterTxStartZero).append('\n');
                atomicExtraBuilder.append("audio_switch_after_ptt_off_zero=")
                        .append(audioSwitchAfterPttOffZero).append('\n');
                atomicExtraBuilder.append("audio_switch_during_rf=")
                        .append(audioSwitchStayedZero ? "0" : "unknown_or_nonzero")
                        .append('\n');
                atomicExtraBuilder.append("tx_duration_ms=")
                        .append(pttOnAtMs >= 0 && pttOffAtMs >= pttOnAtMs
                                ? pttOffAtMs - pttOnAtMs : -1L)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_armed=")
                        .append(pttWatchdog != null && pttWatchdog.armed)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_timeout_ms=")
                        .append(SOFTWARE_AMBE_PTT_WATCHDOG_TIMEOUT_MS)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_takeover_lead_ms=")
                        .append(SOFTWARE_AMBE_PTT_WATCHDOG_TAKEOVER_LEAD_MS)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_expired=")
                        .append(pttWatchdog != null && pttWatchdog.expired)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_ptt_off_attempted=")
                        .append(pttWatchdog != null
                                && pttWatchdog.releaseAttempted)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_takeover_started=")
                        .append(pttWatchdog != null
                                && pttWatchdog.takeoverStarted)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_serial_revoked=")
                        .append(pttWatchdog != null
                                && pttWatchdog.serialRevoked)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_module_power_off_attempted=")
                        .append(pttWatchdog != null
                                && pttWatchdog.modulePowerOffAttempted)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_module_power_off_confirmed=")
                        .append(pttWatchdog != null
                                && pttWatchdog.modulePowerOffConfirmed)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_absolute_deadline_met=")
                        .append(pttWatchdog != null
                                && pttWatchdog.absoluteDeadlineMet)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_bridge_safety_satisfied=")
                        .append(pttWatchdog != null
                                && pttWatchdog.bridgeSafetyDeadlineSatisfied)
                        .append('\n');
                atomicExtraBuilder.append("watchdog_bridge_safe_at_ms=")
                        .append(pttWatchdog == null ? -1L
                                : pttWatchdog.bridgeAutoExitSafeAtMs)
                        .append('\n');
            }
            if (softwareAssetSession) {
                atomicExtraBuilder.append("software_session_ready=")
                        .append(softwareSessionReady
                                ? outcomeSuccess && softwareHardStopReached
                                : softwareFirstRequest != null)
                        .append('\n');
                atomicExtraBuilder.append("software_hard_stop_before_data36=")
                        .append(softwareHardStopReached).append('\n');
                atomicExtraBuilder.append("software_one_data36=")
                        .append(softwareData36 && !softwareFullMorseRf)
                        .append('\n');
                atomicExtraBuilder.append("software_full_morse=")
                        .append(softwareFullMorseRf).append('\n');
                atomicExtraBuilder.append("software_ambe_frame_count=")
                        .append(softwarePlainAmbe.length
                                / REAL_RX_AMBE_FRAME_BYTES).append('\n');
                atomicExtraBuilder.append("software_credit_count=")
                        .append(softwareFullMorseRf
                                ? softwareFullCreditCount
                                : (data36CreditAccepted ? 1 : 0))
                        .append('\n');
                atomicExtraBuilder.append("software_data36_written_count=")
                        .append(softwareFullMorseRf
                                ? softwareFullData36WrittenCount
                                : (data36WriteCompleted ? 1 : 0))
                        .append('\n');
                atomicExtraBuilder.append("software_pacing_mode=")
                        .append(softwareFullMorseRf
                                ? "fixed_80ms" : "not_applicable")
                        .append('\n');
                atomicExtraBuilder.append("software_pace_interval_ms=")
                        .append(softwareFullMorseRf
                                ? SOFTWARE_AMBE_MORSE_UNIT_INTERVAL_MS : -1L)
                        .append('\n');
                atomicExtraBuilder.append("software_pace_window_count=")
                        .append(softwareFullMorseRf
                                ? softwareFullPaceWindowCount : 0)
                        .append('\n');
                atomicExtraBuilder.append("software_max_pace_late_ms=")
                        .append(softwareFullMorseRf
                                ? softwareFullMaxPaceLateMs : -1L)
                        .append('\n');
                atomicExtraBuilder.append("software_async_observed_bytes=")
                        .append(softwareFullMorseRf
                                ? softwareFullAsyncObservedBytes : 0)
                        .append('\n');
                atomicExtraBuilder.append("software_bridge_exit_guard_ms=")
                        .append(SOFTWARE_AMBE_MORSE_BRIDGE_EXIT_GUARD_MS)
                        .append('\n');
                atomicExtraBuilder.append("data36_write_attempted=")
                        .append(softwareFullMorseRf
                                ? softwareFullData36WrittenCount > 0
                                : softwareRealtimeData36
                                ? realtimeRelay != null
                                && realtimeRelay.writeAttempted()
                                : data36Execution.writeAttempted()).append('\n');
                atomicExtraBuilder.append("work_mode_tx_sent=")
                        .append(controlTxProgress.workModeTxSent()).append('\n');
                atomicExtraBuilder.append("vlc_sent=")
                        .append(controlTxProgress.vlcSent()).append('\n');
                atomicExtraBuilder.append("vlc_sent_count=")
                        .append(controlTxProgress.vlcSentCount()).append('\n');
                atomicExtraBuilder.append("software_plain_ambe_sha256=")
                        .append(sha256(softwarePlainAmbe)).append('\n');
                atomicExtraBuilder.append("software_encrypted_ambe_sha256=")
                        .append(softwareEncryptedAmbe == null ? ""
                                : sha256(softwareEncryptedAmbe)).append('\n');
                atomicExtraBuilder.append("software_wire44_sha256=")
                        .append(softwareWire44Stream == null ? ""
                                : sha256(softwareWire44Stream)).append('\n');
                atomicExtraBuilder.append("software_first_request_sha256=")
                        .append(softwareFirstRequest == null ? ""
                                : sha256(softwareFirstRequest)).append('\n');
                atomicExtraBuilder.append("software_privacy_final_state=")
                        .append(softwarePrivacyFinalState).append('\n');
            }
            if (sendRealtimeRelayData36) {
                atomicExtraBuilder.append("realtime_unit_count=")
                        .append(realtimeRelay == null ? 0
                                : realtimeRelay.data27Count())
                        .append('\n');
                atomicExtraBuilder.append("relay_ready=")
                        .append(realtimeRelay != null
                                && realtimeRelay.data27Count() >= 3)
                        .append('\n');
                atomicExtraBuilder.append("relay_third_observed_ms=")
                        .append(realtimeRelay == null ? -1L
                                : realtimeRelay.thirdUnitObservedAtMs())
                        .append('\n');
                atomicExtraBuilder.append("vlc2_wire_tx_ms=")
                        .append(realtimeRelay == null ? -1L
                                : realtimeRelay.vlc2WireTxAtMs())
                        .append('\n');
                atomicExtraBuilder.append("relay_pre_vlc2_wait_ms=")
                        .append(realtimeRelay == null ? -1L
                                : realtimeRelay.preVlc2WaitMs())
                        .append('\n');
                atomicExtraBuilder.append("credit_observation_window_ms=")
                        .append(realtimeRelay == null ? -1L
                                : realtimeRelay.postObservationWindowMs())
                        .append('\n');
                atomicExtraBuilder.append("data36_payload_source=")
                        .append(realtimeRelay == null
                                ? "" : realtimeRelay.payloadSource())
                        .append('\n');
                atomicExtraBuilder.append("fixed_asset_unit_index=")
                        .append(realtimeRelay != null
                                && realtimeRelay.fixedAssetPayload() ? 0 : -1)
                        .append('\n');
                atomicExtraBuilder.append("fixed_asset_offset=")
                        .append(realtimeRelay != null
                                && realtimeRelay.fixedAssetPayload() ? 0 : -1)
                        .append('\n');
            }
            if (sendGeneratedData36) {
                atomicExtraBuilder.append("data36_payload_source=")
                        .append("frame_adapter_unique_candidate36")
                        .append('\n');
                atomicExtraBuilder.append("generated_plain36_sha256=")
                        .append(sha256(generatedPlain36)).append('\n');
            }
            if (setup0Only || sendRealtimeRelayData36
                    || softwareProductionRf) {
                atomicExtraBuilder.append("setup0_first_ok=")
                        .append(setup0FirstOk).append('\n');
                atomicExtraBuilder.append("setup0_retry_used=")
                        .append(setup0RetryUsed).append('\n');
                atomicExtraBuilder.append("setup0_retry_ok=")
                        .append(setup0RetryOk).append('\n');
                atomicExtraBuilder.append("setup0_fail_reason=")
                        .append(setup0FailReason == null ? "" : setup0FailReason)
                        .append('\n');
                append(report, "setup0_first_ok_final", setup0FirstOk);
                append(report, "setup0_retry_used_final", setup0RetryUsed);
                append(report, "setup0_retry_ok_final", setup0RetryOk);
            }
            writeAtomicProbeSessionResult(outcomeSuccess, rebootRecoveryRequired,
                    outcomeStatus, String.valueOf(transport.state()),
                    stateRestored, controlPlaneRestored,
                    atomicExtraBuilder.toString());
            close();
        }
        return finish(outcomeSuccess, report, outcomeStatus);
    }

    /**
     * 步骤1纯离线握手证明：使用步骤0合同与合成确认字节跑完五前序+五 VLC，
     * 不打开串口、不写设备。确认字节仅为合同形状夹具，不是真机捕获。
     * 实现为无 Android Log 依赖的静态评估，便于 JVM 单测。
     */
    ProbeResult runExternalDmrStep1OfflineHandshakeProof() {
        ProbeResult offline = evaluateExternalDmrStep1OfflineHandshake();
        return finish(offline.success, new StringBuilder(offline.report),
                offline.success
                        ? "通过：步骤1离线五前序+五 VLC 握手状态机完整走通（无串口）"
                        : "失败：步骤1离线握手");
    }

    static ProbeResult evaluateExternalDmrStep1OfflineHandshake() {
        StringBuilder report = new StringBuilder();
        append(report, "Mode", "步骤1离线 5-前序+5-VLC 握手状态机");
        append(report, "Serial opened", false);
        append(report, "Device mutation", "无");
        append(report, "Data36", "禁止（本模式不序列化 data36）");
        try {
            ExternalDmrStep0Contract contract =
                    ExternalDmrStep0Contract.forProducer080177b0(
                            13, 99,
                            ExternalDmrStep0Contract.CALL_TYPE_GROUP,
                            0, 0, true,
                            ExternalDmrStep0Contract.OUTPUT_SLOT1,
                            1,
                            0x05, 0xa3,
                            new byte[] {0x11, 0x22, 0x33, 0x44});
            ExternalDmrTxModel model = new ExternalDmrTxModel(contract);
            append(report, "callslot",
                    String.format(Locale.US, "0x%02x", contract.callSlot()));
            append(report, "LC9", bytesToHex(contract.vlcPayload(0)));
            append(report, "payload10", bytesToHex(contract.vlcPayload(2)));
            append(report, "payload2", bytesToHex(contract.vlcPayload(3)));

            for (int index = 0; index < contract.setupCount(); index++) {
                byte[] request = model.expectedRequest();
                if (request == null) {
                    throw new IOException("setup 阶段 expectedRequest 为空 index="
                            + index);
                }
                if (!Arrays.equals(request, contract.setupFrame(index))) {
                    throw new IOException("setup 请求与合同不一致 index=" + index);
                }
                byte[] ack = createControlStatusAckFrame(
                        contract.setupPacketType(index),
                        contract.setupAckField(index));
                ExternalDmrTxModel.ExchangeWindow window =
                        model.openPostSendWindow(request,
                                offlineQuietWindowProof());
                if (window == null) {
                    throw new IOException("setup 接收窗口未建立 index=" + index);
                }
                append(report, "setup" + index + " request", bytesToHex(request));
                append(report, "setup" + index + " window", window.sequence());
                append(report, "setup" + index + " ack fixture", bytesToHex(ack));
                if (!model.acceptSetupExchange(window, ack)) {
                    throw new IOException("setup 确认门失败 index=" + index);
                }
            }
            if (model.phase() != ExternalDmrTxModel.Phase.VLC_SESSION) {
                throw new IOException("未进入 VLC 阶段 phase=" + model.phase());
            }
            for (int index = 0; index < EXTERNAL_DMR_SESSION_ACK_COUNT; index++) {
                byte[] request = model.expectedRequest();
                if (request == null) {
                    throw new IOException("VLC 阶段 expectedRequest 为空 index="
                            + index);
                }
                byte[] ack = createPaddedHpiFrame(5, new byte[] {0x43});
                ExternalDmrTxModel.ExchangeWindow window =
                        model.openPostSendWindow(request,
                                offlineQuietWindowProof());
                if (window == null) {
                    throw new IOException("VLC 接收窗口未建立 index=" + index);
                }
                append(report, "vlc" + index + " request", bytesToHex(request));
                append(report, "vlc" + index + " window", window.sequence());
                append(report, "vlc" + index + " mode",
                        String.format(Locale.US, "0x%02x",
                                contract.vlcMode(index)));
                append(report, "vlc" + index + " payload",
                        bytesToHex(contract.vlcPayload(index)));
                if (!model.acceptVlcExchange(window, ack)) {
                    throw new IOException("VLC 确认门失败 index=" + index);
                }
            }
            if (model.phase() != ExternalDmrTxModel.Phase.COMPLETE) {
                throw new IOException("握手未完成 phase=" + model.phase());
            }
            if (model.expectedRequest() != null) {
                throw new IOException("完成后仍能取出下一请求");
            }
            if (model.canSerializeData36()) {
                throw new IOException("步骤1模型不得允许 data36");
            }
            append(report, "setupAcks", model.setupAcks());
            append(report, "vlcAcks", model.vlcAcks());
            append(report, "Result",
                    "通过：步骤1离线五前序+五 VLC 握手状态机完整走通（无串口）");
            return new ProbeResult(true, report.toString());
        } catch (Throwable error) {
            append(report, "Error", error.getMessage());
            append(report, "Result", "失败：步骤1离线握手 " + error.getMessage());
            return new ProbeResult(false, report.toString());
        }
    }

