    /**
     * 硬门：bridge flag 为 0 时禁止把 HPI 二进制帧写到 UART 文本面。
     * ChatGPT 01:18：v2.61–v2.65 根因。
     */
    static void requireHpiPlaneForBinaryWrite(int bridgeFlagByte,
            byte[] frame) {
        if (frame == null || frame.length < 3) {
            throw new IllegalArgumentException("HPI 帧为空或过短");
        }
        boolean looksHpi = (frame[0] & 0xff) == 0x84
                && (frame[1] & 0xff) == 0xa9
                && (frame[2] & 0xff) == 0x61;
        if (looksHpi && (bridgeFlagByte & 0xff) == 0) {
            throw new IllegalStateException(
                    "禁止在 bridge=0 文本面写 HPI 二进制帧（传输平面错误）");
        }
    }

    /** v2.08 七批SRAM原始状态；动态会话区只读，绝不写回。 */
    static final class HardwareEncoderSramState {
        final byte[] baudCode;
        final byte[] baudMarker;
        final byte[] timeoutCode;
        final byte[] timeoutCounter;
        final byte[] timeoutMarker;
        final byte[] systick;
        final byte[] bridgeFlag;
        final byte[] uartRing;
        final byte[] signalingFlags;
        final byte[] dataGate;
        final byte[] sessionState;
        final byte[] sessionPtrA;
        final byte[] sessionPtrB;
        final byte[] sessionFlag1c;
        final byte[] sessionCount;
        final byte[] queueA;
        final byte[] queueB;
        final byte[] sessionRecord;
        final byte[] bootReady;
        final byte[] bootMode;

        HardwareEncoderSramState(byte[] baudCode, byte[] baudMarker,
                byte[] timeoutCode, byte[] timeoutCounter, byte[] timeoutMarker,
                byte[] systick, byte[] bridgeFlag, byte[] uartRing,
                byte[] signalingFlags, byte[] dataGate, byte[] sessionState,
                byte[] sessionPtrA, byte[] sessionPtrB, byte[] sessionFlag1c,
                byte[] sessionCount, byte[] queueA, byte[] queueB,
                byte[] sessionRecord, byte[] bootReady, byte[] bootMode) {
            this.baudCode = copyRequired(baudCode, 56, "baudCode");
            this.baudMarker = copyRequired(baudMarker, 4, "baudMarker");
            this.timeoutCode = copyRequired(timeoutCode, 64, "timeoutCode");
            this.timeoutCounter = copyRequired(timeoutCounter, 4,
                    "timeoutCounter");
            this.timeoutMarker = copyRequired(timeoutMarker, 4,
                    "timeoutMarker");
            this.systick = copyRequired(systick, 4, "systick");
            this.bridgeFlag = copyRequired(bridgeFlag, 1, "bridgeFlag");
            this.uartRing = copyRequired(uartRing, UART_RING_STATE_LENGTH,
                    "uartRing");
            this.signalingFlags = copyRequired(signalingFlags,
                    EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH, "signalingFlags");
            this.dataGate = copyRequired(dataGate, 1, "dataGate");
            this.sessionState = copyRequired(sessionState, 1, "sessionState");
            this.sessionPtrA = copyRequired(sessionPtrA, 4, "sessionPtrA");
            this.sessionPtrB = copyRequired(sessionPtrB, 4, "sessionPtrB");
            this.sessionFlag1c = copyRequired(sessionFlag1c, 1,
                    "sessionFlag1c");
            this.sessionCount = copyRequired(sessionCount, 4, "sessionCount");
            this.queueA = copyRequired(queueA,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH, "queueA");
            this.queueB = copyRequired(queueB,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH, "queueB");
            this.sessionRecord = copyRequired(sessionRecord,
                    EXTERNAL_DMR_SESSION_RECORD_LENGTH, "sessionRecord");
            this.bootReady = copyRequired(bootReady, 1, "bootReady");
            this.bootMode = copyRequired(bootMode, 1, "bootMode");
        }

        private static byte[] copyRequired(byte[] value, int length,
                String field) {
            if (value == null || value.length != length) {
                throw new IllegalArgumentException(field + " 长度不符");
            }
            return value.clone();
        }
    }

    private static final class HardwareEncoderCaptureRecord {
        final String label;
        final String windowToken;
        final byte[] raw;

        HardwareEncoderCaptureRecord(String label, String windowToken,
                byte[] raw) {
            this.label = label;
            this.windowToken = windowToken;
            this.raw = raw != null ? raw.clone() : new byte[0];
        }
    }

    private static final class UartDiagnosticRecord {
        final String token;
        final UartDiagnostics.Snapshot snapshot;

        UartDiagnosticRecord(String token, UartDiagnostics.Snapshot snapshot) {
            this.token = token;
            this.snapshot = snapshot;
        }
    }

    static final class HardwareEncoderReadChunk {
        final int availableBeforeRead;
        final long readStartedNanos;
        final long readCompletedNanos;
        final byte[] raw;

        HardwareEncoderReadChunk(int availableBeforeRead,
                long readStartedNanos, long readCompletedNanos, byte[] raw) {
            this.availableBeforeRead = availableBeforeRead;
            this.readStartedNanos = readStartedNanos;
            this.readCompletedNanos = readCompletedNanos;
            this.raw = raw != null ? raw.clone() : new byte[0];
        }
    }

    private static final class HardwareEncoderWriteChunk {
        final int index;
        final int offset;
        final long writeStartedNanos;
        final long writeReturnedNanos;
        final long gapStartedNanos;
        final long gapCompletedNanos;
        final byte[] raw;
        final UartDiagnostics.DrainSnapshot drain;

        HardwareEncoderWriteChunk(int index, int offset,
                long writeStartedNanos, long writeReturnedNanos,
                long gapStartedNanos, long gapCompletedNanos,
                byte[] raw, UartDiagnostics.DrainSnapshot drain) {
            this.index = index;
            this.offset = offset;
            this.writeStartedNanos = writeStartedNanos;
            this.writeReturnedNanos = writeReturnedNanos;
            this.gapStartedNanos = gapStartedNanos;
            this.gapCompletedNanos = gapCompletedNanos;
            this.raw = raw.clone();
            this.drain = drain;
        }
    }

    private void captureUartDiagnostic(List<UartDiagnosticRecord> records,
            String token, int expectedBaud, StringBuilder report)
            throws Exception {
        UartDiagnostics.Snapshot snapshot = UartDiagnostics.snapshot(serialPort);
        if (!snapshot.termiosAvailable()) {
            throw new IOException("UART termios快照失败：errno="
                    + snapshot.termiosErrno());
        }
        if (snapshot.inputBaud() != expectedBaud
                || snapshot.outputBaud() != expectedBaud) {
            throw new IOException("UART termios波特率不符：期望=" + expectedBaud
                    + " 实际输入/输出=" + snapshot.inputBaud() + "/"
                    + snapshot.outputBaud());
        }
        records.add(new UartDiagnosticRecord(token, snapshot));
        append(report, "UART诊断 " + token,
                "波特率=" + snapshot.outputBaud()
                        + " TIOCGICOUNT="
                        + (snapshot.icountAvailable() ? "可用" : "不可用")
                        + " errno=" + snapshot.icountErrno());
    }

    private void persistUartDiagnostics(List<UartDiagnosticRecord> records,
            List<HardwareEncoderReadChunk> chunks,
            List<HardwareEncoderWriteChunk> writeChunks, StringBuilder report)
            throws Exception {
        boolean pcmDiagnosticStarted = false;
        for (int index = 0; index < records.size(); index++) {
            UartDiagnosticRecord record = records.get(index);
            pcmDiagnosticStarted |= record.token.contains("pcm");
            String prefix = String.format(Locale.US,
                    "h13_hw_encoder_uart_%02d_%s_", index, record.token);
            preserveRawEvidence(report, "UART诊断原始快照 " + record.token,
                    prefix + "raw_", record.snapshot.toRawBytes());
            preserveRawEvidence(report, "UART诊断中文解码 " + record.token,
                    prefix + "decoded_", record.snapshot.toChineseText());
        }
        ByteArrayOutputStream rebuilt = new ByteArrayOutputStream();
        for (int index = 0; index < chunks.size(); index++) {
            HardwareEncoderReadChunk chunk = chunks.get(index);
            String prefix = String.format(Locale.US,
                    "h13_hw_encoder_pcm_read_chunk_%03d_", index);
            preserveRawEvidence(report, "PCM响应读取块 " + index,
                    prefix + "raw_", chunk.raw);
            String metadata = "块序号=" + index + "\n"
                    + "读取前available=" + chunk.availableBeforeRead + "\n"
                    + "读取开始单调纳秒=" + chunk.readStartedNanos + "\n"
                    + "读取完成单调纳秒=" + chunk.readCompletedNanos + "\n"
                    + "实际读取字节数=" + chunk.raw.length + "\n";
            preserveRawEvidence(report, "PCM响应读取块元数据 " + index,
                    prefix + "meta_",
                    metadata.getBytes(StandardCharsets.UTF_8));
            rebuilt.write(chunk.raw);
        }
        if (pcmDiagnosticStarted) {
            preserveRawEvidence(report, "PCM读取块重组原件",
                    "h13_hw_encoder_pcm_read_chunks_rebuilt_",
                    rebuilt.toByteArray());
        }
        ByteArrayOutputStream rebuiltWrite = new ByteArrayOutputStream();
        for (int index = 0; index < writeChunks.size(); index++) {
            HardwareEncoderWriteChunk chunk = writeChunks.get(index);
            String prefix = String.format(Locale.US,
                    "h13_hw_encoder_pcm_write_chunk_%03d_", index);
            preserveRawEvidence(report, "PCM发送分组 " + index,
                    prefix + "raw_", chunk.raw);
            preserveRawEvidence(report, "PCM发送排空原始快照 " + index,
                    prefix + "drain_raw_", chunk.drain.toRawBytes());
            preserveRawEvidence(report, "PCM发送排空中文解码 " + index,
                    prefix + "drain_decoded_", chunk.drain.toChineseText());
            String metadata = "组序号=" + chunk.index + "\n"
                    + "起始偏移=" + chunk.offset + "\n"
                    + "实际字节数=" + chunk.raw.length + "\n"
                    + "写入开始单调纳秒=" + chunk.writeStartedNanos + "\n"
                    + "write返回单调纳秒=" + chunk.writeReturnedNanos + "\n"
                    + "排空开始单调纳秒=" + chunk.drain.startedNanos() + "\n"
                    + "排空完成单调纳秒=" + chunk.drain.completedNanos() + "\n"
                    + "排空成功=" + chunk.drain.successful() + "\n"
                    + "排空错误码=" + chunk.drain.errorNumber() + "\n"
                    + "首次发送队列字节=" + chunk.drain.queuedBefore() + "\n"
                    + "末次发送队列字节=" + chunk.drain.queuedAfter() + "\n"
                    + "发送队列轮询次数=" + chunk.drain.pollCount() + "\n"
                    + "线时长保护纳秒=" + chunk.drain.guardNanos() + "\n"
                    + "组间静默开始单调纳秒=" + chunk.gapStartedNanos + "\n"
                    + "组间静默完成单调纳秒=" + chunk.gapCompletedNanos + "\n";
            preserveRawEvidence(report, "PCM发送分组元数据 " + index,
                    prefix + "meta_",
                    metadata.getBytes(StandardCharsets.UTF_8));
            rebuiltWrite.write(chunk.raw);
        }
        if (!writeChunks.isEmpty()) {
            preserveRawEvidence(report, "PCM发送分组重组原件",
                    "h13_hw_encoder_pcm_write_chunks_rebuilt_",
                    rebuiltWrite.toByteArray());
        }
        append(report, "UART诊断快照数", records.size());
        append(report, "PCM实际read块数", chunks.size());
        append(report, "PCM实际发送分组数", writeChunks.size());
    }

    static List<byte[]> hardwareEncoderPcmWriteChunks(byte[] wire) {
        if (wire == null || wire.length == 0) {
            throw new IllegalArgumentException("PCM线帧为空");
        }
        List<byte[]> chunks = new ArrayList<>();
        for (int offset = 0; offset < wire.length;
                offset += HARDWARE_ENCODER_PCM_WRITE_CHUNK_BYTES) {
            int count = Math.min(HARDWARE_ENCODER_PCM_WRITE_CHUNK_BYTES,
                    wire.length - offset);
            chunks.add(Arrays.copyOfRange(wire, offset, offset + count));
        }
        return chunks;
    }

    private void writeHardwareEncoderPcmChunked(OutputStream output,
            byte[] wire, List<HardwareEncoderWriteChunk> records)
            throws Exception {
        List<byte[]> chunks = hardwareEncoderPcmWriteChunks(wire);
        int offset = 0;
        for (int index = 0; index < chunks.size(); index++) {
            byte[] chunk = chunks.get(index);
            long writeStarted = SystemClock.elapsedRealtimeNanos();
            output.write(chunk);
            output.flush();
            long writeReturned = SystemClock.elapsedRealtimeNanos();
            UartDiagnostics.DrainSnapshot drain =
                    UartDiagnostics.drainTransmitter(serialPort,
                    BAUD_RATE_230400, chunk.length,
                    HARDWARE_ENCODER_PCM_DRAIN_TIMEOUT_MS);
            long gapStarted = -1;
            long gapCompleted = -1;
            if (drain.successful() && index + 1 < chunks.size()) {
                gapStarted = SystemClock.elapsedRealtimeNanos();
                SystemClock.sleep(HARDWARE_ENCODER_PCM_WRITE_GAP_MS);
                gapCompleted = SystemClock.elapsedRealtimeNanos();
            }
            records.add(new HardwareEncoderWriteChunk(index, offset,
                    writeStarted, writeReturned, gapStarted, gapCompleted,
                    chunk, drain));
            if (!drain.successful()) {
                throw new IOException("PCM发送分组" + index
                        + "排空失败：errno=" + drain.errorNumber());
            }
            if (gapStarted >= 0
                    && (gapCompleted - gapStarted)
                    > HARDWARE_ENCODER_PCM_WRITE_GAP_MAX_MS * 1000000L) {
                throw new IOException("PCM发送分组" + index
                        + "组间静默超过20毫秒，禁止继续");
            }
            offset += chunk.length;
        }
        if (offset != wire.length) {
            throw new IOException("PCM发送分组累计字节数不符");
        }
    }

    private void writeHardwareEncoderPcmSingle(OutputStream output,
            byte[] wire, List<HardwareEncoderWriteChunk> records)
            throws Exception {
        long writeStarted = SystemClock.elapsedRealtimeNanos();
        output.write(wire);
        output.flush();
        long writeReturned = SystemClock.elapsedRealtimeNanos();
        UartDiagnostics.DrainSnapshot drain =
                UartDiagnostics.drainTransmitter(serialPort,
                BAUD_RATE_230400, wire.length,
                HARDWARE_ENCODER_PCM_DRAIN_TIMEOUT_MS);
        records.add(new HardwareEncoderWriteChunk(0, 0,
                writeStarted, writeReturned, -1, -1, wire, drain));
        if (!drain.successful()) {
            throw new IOException("PCM单帧排空失败：errno="
                    + drain.errorNumber());
        }
    }

    private HardwareEncoderSramState captureHardwareEncoderSramState(
            InputStream input, OutputStream output, String stage,
            StringBuilder report) throws Exception {
        HardwareEncoderSramState state = new HardwareEncoderSramState(
                readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS, 56),
                readMemory(input, output, BAUD_ONESHOT_MARKER_ADDRESS, 4),
                readMemory(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS, 64),
                readMemory(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4),
                readMemory(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 4),
                readMemory(input, output, RAM_VECTOR_SYSTICK, 4),
                readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1),
                readMemory(input, output, UART_RING_STATE_ADDRESS,
                        UART_RING_STATE_LENGTH),
                readMemory(input, output, EXTERNAL_DMR_SIGNALING_FLAGS_ADDRESS,
                        EXTERNAL_DMR_SIGNALING_FLAGS_LENGTH),
                readMemory(input, output,
                        EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS,
                        EXTERNAL_DMR_TX_WORK_QUEUE_A_LENGTH),
                readMemory(input, output,
                        EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS,
                        EXTERNAL_DMR_TX_WORK_QUEUE_B_LENGTH),
                readMemory(input, output, EXTERNAL_DMR_SESSION_RECORD_ADDRESS,
                        EXTERNAL_DMR_SESSION_RECORD_LENGTH),
                readMemory(input, output, SCT_BOOT_READY_ADDRESS, 1),
                readMemory(input, output, SCT_BOOT_MODE_ADDRESS, 1));
        persistHardwareEncoderSramState(stage, state, report);
        return state;
    }

