        append(report, "模式", twoStageVocoderOut
                ? "v2.17硬件编码器0x80输入后切0x10输出@230400"
                : sendTonePcm
                ? "v2.16硬件编码器800赫兹单帧内容因果@230400"
                : sendOnePcm
                ? "v2.14硬件编码器纯输入路由PCM长帧64字节分块@230400"
                : "v2.08硬件编码器无输入基线@230400");
