    /**
     * Read-only SRAM safety gate after an interrupted raw-bridge session.
     * This sends text queries and print 1/0 only: no SRAM write, baud switch,
     * SCT reload, HPI command, or RF operation is performed.
     */
    ProbeResult runSramPreflight57600() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        append(report, "Mode", "read-only SRAM preflight @57600");
        append(report, "Probe build", "v1.02-sram-preflight-57600");
        append(report, "Mutation boundary",
                "print 1/0 only; no SRAM write, baud switch, SCT reload, HPI, or RF");
        append(report, "PASS criterion",
                "flag=0 vector=0x08021ddd code64/counter/marker all zero");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);

            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake @57600", printable(connect));
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!connect.contains("+DMOCONNECT:0")
                    || !version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Text baseline failed before SRAM preflight");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            drainAvailable(input);
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            MemoryReadEvidence flagEvidence = readMemoryEvidence(input, output,
                    "bridge_flag", UART_HPI_BRIDGE_FLAG_ADDRESS, 1, report);
            MemoryReadEvidence vectorEvidence = readMemoryEvidence(input, output,
                    "systick_vector", RAM_VECTOR_SYSTICK, 4, report);
            MemoryReadEvidence codeEvidence = readMemoryEvidence(input, output,
                    "timeout_code_64", UART_HPI_TIMEOUT_CODE_ADDRESS,
                    wordsToBytes(UART_HPI_TIMEOUT_WORDS).length, report);
            MemoryReadEvidence counterEvidence = readMemoryEvidence(input, output,
                    "timeout_counter", UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4, report);
            MemoryReadEvidence markerEvidence = readMemoryEvidence(input, output,
                    "timeout_marker", UART_HPI_TIMEOUT_MARKER_ADDRESS, 4, report);

            byte[] flag = flagEvidence.parsed;
            byte[] vector = vectorEvidence.parsed;
            byte[] code = codeEvidence.parsed;
            byte[] counter = counterEvidence.parsed;
            byte[] marker = markerEvidence.parsed;
            boolean clean = isCleanSramPreflight(flag, vector, code, counter, marker);
            append(report, "Bridge flag", flag[0] & 0xff);
            append(report, "SysTick vector", String.format(Locale.US,
                    "0x%08x", u32le(vector, 0)));
            append(report, "Timeout code all zero", allZero(code));
            append(report, "Timeout code SHA-256", sha256(code));
            append(report, "Timeout counter", u32le(counter, 0));
            append(report, "Timeout marker", String.format(Locale.US,
                    "0x%08x", u32le(marker, 0)));

            byte[] snapshot = concatBytes(concatBytes(concatBytes(
                    concatBytes(flag, vector), code), counter), marker);
            File snapshotFile = new File(outputDirectory, String.format(Locale.US,
                    "sram_preflight_snapshot_%d.bin", System.currentTimeMillis()));
            writeFile(snapshotFile, snapshot);
            append(report, "Parsed snapshot file", snapshotFile.getAbsolutePath());
            append(report, "Parsed snapshot SHA-256", sha256(snapshot));

            disableLogLevel(input, output, report);
            return finish(clean, report, clean
                    ? "PASS: temporary SRAM baseline clean; v1.01 gate open"
                    : "FAIL: temporary SRAM baseline not clean; v1.01 remains blocked");
        } catch (Throwable error) {
            Log.e(TAG, "SRAM preflight failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            return finish(false, report, "FAIL: SRAM preflight incomplete");
        } finally {
            close();
        }
    }

    static boolean isCleanSramPreflight(byte[] flag, byte[] vector, byte[] code,
            byte[] counter, byte[] marker) {
        return flag != null && flag.length == 1 && (flag[0] & 0xff) == 0
                && vector != null && vector.length == 4
                && u32le(vector, 0) == ORIGINAL_SYSTICK_HANDLER
                && code != null
                && code.length == wordsToBytes(UART_HPI_TIMEOUT_WORDS).length
                && allZero(code)
                && counter != null && counter.length == 4 && allZero(counter)
                && marker != null && marker.length == 4 && allZero(marker);
    }

    /**
     * Read-only power gate. Text memread is the only data-plane operation;
     * this never enters HPI, keys PTT, or writes MCU/SCT state.
     */
    ProbeResult runPowerCalibrationSnapshot57600() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        append(report, "Mode", "read-only RF calibration snapshot @57600");
        append(report, "Probe build", "v1.06-power-calibration-snapshot-57600");
        append(report, "Mutation boundary",
                "print 1/0 only; no SRAM write, baud switch, HPI, PTT, or RF");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);

            String connect = query(input, output, "AT+DMOCONNECT");
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Handshake @57600", printable(connect));
            append(report, "Version @57600", printable(version));
            if (!connect.contains("+DMOCONNECT:0")
                    || !version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Text baseline failed before power snapshot");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            drainAvailable(input);
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            byte[] calibration = readMemoryEvidence(input, output,
                    "rf_calibration_412", RF_CALIBRATION_RECORD_ADDRESS,
                    RF_CALIBRATION_RECORD_BYTES, report).parsed;
            byte[] runtimeBytes = readMemoryEvidence(input, output,
                    "runtime_power_code", RUNTIME_POWER_CODE_ADDRESS, 2, report).parsed;
            PowerCalibrationAnchor[] low = parsePowerCalibrationTable(calibration, false);
            PowerCalibrationAnchor[] high = parsePowerCalibrationTable(calibration, true);
            int runtimeCode = u16le(runtimeBytes, 0);
            int expectedLow = selectNearestPowerCode(low,
                    APPROVED_CHANNEL_FREQUENCY_HZ);
            int expectedHigh = selectNearestPowerCode(high,
                    APPROVED_CHANNEL_FREQUENCY_HZ);

            File snapshotFile = new File(outputDirectory, String.format(Locale.US,
                    "rf_calibration_snapshot_%d.bin", System.currentTimeMillis()));
            writeFile(snapshotFile, calibration);
            append(report, "Calibration snapshot file", snapshotFile.getAbsolutePath());
            append(report, "Calibration snapshot SHA-256", sha256(calibration));
            append(report, "Approved channel frequency Hz", APPROVED_CHANNEL_FREQUENCY_HZ);
            append(report, "Runtime DAC code", runtimeCode);
            append(report, "Expected low-table code", expectedLow);
            append(report, "Expected high-table code", expectedHigh);
            append(report, "Runtime matches low table", runtimeCode == expectedLow);
            append(report, "Runtime matches high table", runtimeCode == expectedHigh);
            for (int index = 0; index < low.length; index++) {
                append(report, "PowerLow[" + index + "]",
                        low[index].frequencyHz + " Hz -> code " + low[index].dacCode);
            }
            for (int index = 0; index < high.length; index++) {
                append(report, "PowerHigh[" + index + "]",
                        high[index].frequencyHz + " Hz -> code " + high[index].dacCode);
            }

            disableLogLevel(input, output, report);
            boolean pass = runtimeCode == expectedLow;
            return finish(pass, report, pass
                    ? "PASS: runtime code matches 433.550 MHz PowerLow table"
                    : "FAIL: runtime code does not match approved low-power channel");
        } catch (Throwable error) {
            Log.e(TAG, "Power calibration snapshot failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            return finish(false, report, "FAIL: power snapshot incomplete");
        } finally {
            close();
        }
    }

    /**
     * Control A (job.md ChatGPT review): 57600 only. Device-side DMR tape
     * {@code CHAN_D} gate via {@link #awaitDmrRxMilestoneTrigger} must pass
     * before raw bridge. Then Voice OUT route only; capture briefly while TX
     * may still be held. PASS = tape trigger + at least one framed HPI event.
     * Does not change baud.
     */
    ProbeResult runVoiceOutPcm57600ControlA() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalTimeoutCode = null;
        byte[] originalTimeoutCounter = null;
        byte[] originalTimeoutMarker = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        boolean bridgeMayBeActive = false;
        boolean controlPlaneReloadDone = false;
        boolean outcomeSuccess = false;
        String outcomeStatus = "FAIL";

        append(report, "Mode",
                "Control A: Voice OUT @57600 after v0.61 CHAN_D tape gate (no 230400)");
        append(report, "Probe build", "v0.87-p0-probe-infra");
        append(report, "Device", DEVICE_PATH);
        append(report, "Prerequisite",
                "job.md ChatGPT review: must not direct-to-bridge without tape gate");
        append(report, "Baud", BAUD_RATE);
        append(report, "RF", "receive only; operator TYT on approved CH1 until tape gate");
        append(report, "PASS criterion",
                "tape CHAN_D trigger + >=1 framed HPI event after Voice OUT");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            if (!"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(sha256(handler))) {
                throw new IOException("Timeout handler hash mismatch");
            }
            append(report, "Timeout handler SHA-256", sha256(handler));

            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connect = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed at 57600");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected version at 57600");
            }

            // v0.84: do NOT force sct3258chgpro before tape when coming from a
            // healthy Interphone session (job.md: production RX already OK).
            // Pre-run chgpro was flaky and burned the TX window (v0.82/v0.83).
            // Heal path remains: HPI exit WORK_MODE_IDLE + post-HPI chgpro.
            drainAvailable(input);
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));
            // Ensure approved CH1 without full SCT reload.
            String setCh = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "Pre-tape CH1 ensure", printable(setCh));

            // Device-side gate: app decides when RX is live (not chat cue alone).
            Log.i(TAG, ">>> TRANSMIT NOW for TAPE GATE: TYT CH1 TG99 CC8 TS1 low; "
                    + "hold until device logs TAPE TRIGGER PASSED (up to 90s) <<<");
            append(report, "Operator cue",
                    "TRANSMIT for CHAN_D tape gate (device decides pass)");
            phase("TRANSMIT_NOW", "现在发射！一直按住",
                    "Control A @57600 — 过门后再按几秒");
            long tapeWaitStarted = SystemClock.elapsedRealtime();
            DmrRxMilestoneTrigger dmrTrigger =
                    awaitDmrRxMilestoneTrigger(input, output, report);
            long tapeGateMs = SystemClock.elapsedRealtime() - tapeWaitStarted;
            append(report, "Tape gate wait ms", tapeGateMs);
            append(report, "Tape gate units", dmrTrigger.units);
            append(report, "Tape gate file",
                    dmrTrigger.captureFile.getAbsolutePath());
            Log.i(TAG, ">>> TAPE TRIGGER PASSED units=" + dmrTrigger.units
                    + " — entering 57600 bridge; keep PTT if still held <<<");
            phase("TAPE_OK", "过门了！继续按住",
                    "units=" + dmrTrigger.units + " Control A bridge@57600");

            originalFlag = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            originalTimeoutCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            originalTimeoutCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            originalTimeoutMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            if ((originalFlag[0] & 0xff) != 0
                    || u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected bridge/SysTick baseline after tape gate");
            }

            byte[] tickFirstBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickDelta = (u32le(tickSecondBytes, 0) - u32le(tickFirstBytes, 0))
                    & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            append(report, "Measured tick Hz", String.format(Locale.US, "%.2f",
                    tickRateHz));
            if (tickRateHz < 10.0 || tickRateHz > 100000.0) {
                throw new IOException("Implausible MCU tick rate");
            }
            // Short bridge after live gate (Control A needs any framed HPI event).
            int timeoutTicks = (int) Math.round(tickRateHz * 8000.0 / 1000.0);
            append(report, "Bridge timeout ticks", timeoutTicks);

            for (int offset = 0; offset < handler.length; offset += 4) {
                writeMemoryWord(input, output,
                        UART_HPI_TIMEOUT_CODE_ADDRESS + offset,
                        u32le(handler, offset));
            }
            stateChanged = true;
            if (!Arrays.equals(handler, readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length))) {
                throw new IOException("Timeout handler upload mismatch");
            }

            writeMemoryWord(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    timeoutTicks);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    UART_HPI_TIMEOUT_ENTRY);
            if (u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    != UART_HPI_TIMEOUT_ENTRY) {
                throw new IOException("Unable to arm bridge timeout vector");
            }
            synchronized (lock) {
                logLevelMayBeEnabled = false;
            }
            long bridgeArmedAt = SystemClock.elapsedRealtime();
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            bridgeMayBeActive = true;

            output.write(HPI_VOCODER_IO_OFF);
            output.flush();
            SystemClock.sleep(20);
            output.write(HPI_VOCODER_IO_VOICE_OUT_HPI);
            output.flush();
            SystemClock.sleep(30);
            byte[] raw = readForDuration(input, 5000);
            // v0.82: exit HPI traffic plane BEFORE bridge drops (not only VOCODER off).
            hpiExitTrafficPlaneWhileBridged(output, report);
            raw = concatBytes(raw,
                    readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));

            long safeReadAt = bridgeArmedAt + 8000 + 2000;
            long remaining = safeReadAt - SystemClock.elapsedRealtime();
            if (remaining > 0) {
                SystemClock.sleep(remaining);
            }

            byte[] flagAfter = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] vectorAfter = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            byte[] counterAfter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            byte[] markerAfter = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            append(report, "Bridge flag after", flagAfter[0] & 0xff);
            append(report, "SysTick after bridge", String.format(Locale.US,
                    "0x%08x", u32le(vectorAfter, 0)));
            append(report, "Timeout counter after", u32le(counterAfter, 0));
            append(report, "Timeout marker after", String.format(Locale.US,
                    "0x%08x", u32le(markerAfter, 0)));
            if ((flagAfter[0] & 0xff) != 0
                    || u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER
                    || u32le(counterAfter, 0) != 0
                    || u32le(markerAfter, 0) != UART_HPI_TIMEOUT_MARKER) {
                throw new IOException("Bridge recovery mismatch @57600 after Control A");
            }
            bridgeMayBeActive = false;
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }

            long stamp = System.currentTimeMillis();
            File captureFile = new File(outputDirectory, String.format(Locale.US,
                    "hpi_voice_out_pcm_57600_control_a_%d.bin", stamp));
            writeFile(captureFile, raw);
            HpiCaptureSummary summary = summarizeHpiCapture(raw);
            append(report, "Capture raw bytes", raw.length);
            append(report, "Capture SHA-256", sha256(raw));
            append(report, "Capture file", captureFile.getAbsolutePath());
            append(report, "HPI summary", summary.toString());
            append(report, "HPI frames", summary.frames);
            append(report, "pcm160", summary.pcm160);
            append(report, "chanD27", summary.chanD27);

            restoreWords(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS,
                    originalTimeoutCode);
            restoreWords(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    originalTimeoutCounter);
            restoreWords(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS,
                    originalTimeoutMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    u32le(originalVector, 0));
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                    originalFlag[0] & 0xff);
            stateRestored = Arrays.equals(originalTimeoutCode, readMemory(input,
                    output, UART_HPI_TIMEOUT_CODE_ADDRESS, originalTimeoutCode.length))
                    && u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    == ORIGINAL_SYSTICK_HANDLER
                    && (readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1)[0]
                    & 0xff) == (originalFlag[0] & 0xff);
            append(report, "transportRestored", stateRestored);
            append(report, "Temporary state restored", stateRestored);
            if (!stateRestored) {
                throw new IOException("Temporary state restore mismatch");
            }
            // Transport restore ≠ control-plane restore: exactly one reload here.
            reloadSctBaselineTrafficPlane(input, output, report);
            controlPlaneReloadDone = true;
            append(report, "controlPlaneReloadCount", 1);
            // Tape gate already observed new CHAN_D units this session.
            if (dmrTrigger.units >= DMR_RX_TRIGGER_MIN_UNITS) {
                append(report, "rxTrafficPlaneHealthy", true);
            }
            disableLogLevel(input, output, report);

            boolean tapeOk = dmrTrigger.units >= DMR_RX_TRIGGER_MIN_UNITS;
            boolean hpiOk = summary.frames > 0 || raw.length > 0;
            if (!tapeOk) {
                outcomeSuccess = false;
                outcomeStatus = "INVALID: tape CHAN_D gate did not meet min units";
            } else if (!hpiOk) {
                outcomeSuccess = false;
                outcomeStatus = "FAIL: tape gate OK but raw bridge empty @57600 — "
                        + "investigate route/bridge before 230400";
            } else {
                outcomeSuccess = true;
                outcomeStatus = String.format(Locale.US,
                        "PASS Control A: tape units=%d HPI frames=%d raw=%d @57600",
                        dmrTrigger.units, summary.frames, raw.length);
            }
        } catch (Throwable error) {
            Log.e(TAG, "Control A 57600 failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            append(report, "Bridge may be active at failure", bridgeMayBeActive);
            String msg = error.getMessage() != null ? error.getMessage() : "";
            outcomeSuccess = false;
            if (msg.contains("No new DMR RX trigger")) {
                outcomeStatus = "INVALID: no tape RX — traffic-plane may be stale "
                        + "(not an HPI/baud test); cold-start Interphone "
                        + "or run production restore";
            } else {
                outcomeStatus = "FAIL";
            }
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    if (bridgeMayBeActive) {
                        try {
                            if (output != null) {
                                append(report, "restore.step.hpiExit", "attempt");
                                hpiExitTrafficPlaneWhileBridged(output, report);
                                append(report, "restore.step.hpiExit", "ok");
                            }
                        } catch (Throwable exitError) {
                            append(report, "restore.step.hpiExit",
                                    "fail: " + exitError.getMessage());
                        }
                        SystemClock.sleep(2500);
                    }
                    if (input != null && output != null) {
                        try {
                            if (originalTimeoutCode != null) {
                                restoreWords(input, output,
                                        UART_HPI_TIMEOUT_CODE_ADDRESS,
                                        originalTimeoutCode);
                            }
                            if (originalTimeoutCounter != null) {
                                restoreWords(input, output,
                                        UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                                        originalTimeoutCounter);
                            }
                            if (originalTimeoutMarker != null) {
                                restoreWords(input, output,
                                        UART_HPI_TIMEOUT_MARKER_ADDRESS,
                                        originalTimeoutMarker);
                            }
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                            writeMemoryByte(input, output,
                                    UART_HPI_BRIDGE_FLAG_ADDRESS, 0);
                            append(report, "restore.step.emergencyTransport", "ok");
                        } catch (Throwable transportError) {
                            append(report, "restore.step.emergencyTransport",
                                    "fail: " + transportError.getMessage());
                        }
                    }
                } catch (Throwable restoreError) {
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                }
            }
            // P0: success path already reloaded once — never double sct3258chgpro.
            if (input != null && output != null) {
                if (shouldAttemptFinallyControlReload(controlPlaneReloadDone)) {
                    if (bestEffortControlPlaneReload(input, output, report)) {
                        controlPlaneReloadDone = true;
                        append(report, "controlPlaneReloadCount", 1);
                    }
                    append(report, "finallyReloadSkipped", false);
                    append(report, "finallyReloadBestEffort", true);
                } else {
                    append(report, "finallyReloadSkipped", true);
                    append(report, "controlPlaneReloadCount", 1);
                }
                try {
                    disableLogLevel(input, output, report);
                    append(report, "restore.step.print0", "ok");
                } catch (Throwable printError) {
                    append(report, "restore.step.print0",
                            "fail: " + printError.getMessage());
                }
            }
            close();
            append(report, "serialClosed", true);
        }
        return finish(outcomeSuccess, report, outcomeStatus);
    }

    /**
     * Control B (after Control A PASS): same v0.61 tape gate @57600, then the
     * only intentional change is stack-safe pre-bridge switch to 230400, then
     * Voice OUT capture. PASS = tape gate + framed HPI @230400 (compare to A).
     */
    ProbeResult runVoiceOutPcm230400ControlB() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalTimeoutCode = null;
        byte[] originalTimeoutCounter = null;
        byte[] originalTimeoutMarker = null;
        byte[] originalBaudCode = null;
        byte[] originalBaudMarker = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        boolean bridgeMayBeActive = false;
        boolean controlPlaneReloadDone = false;
        boolean outcomeSuccess = false;
        String outcomeStatus = "FAIL";
        int mcuBaud = BAUD_RATE;
        int androidBaud = BAUD_RATE;

        append(report, "Mode",
                "Control B v0.87: pregate-230400 + single control-plane reload");
        append(report, "Probe build", "v0.87-p0-probe-infra");
        append(report, "Device", DEVICE_PATH);
        append(report, "Prerequisite",
                "Control A path; HPI poison healed by one sct3258chgpro 0 after bridge");
        append(report, "Timeline note",
                "90s is MAX wait for tape CHAN_D only — NOT a 90s PCM window. "
                        + "PCM capture is bridgeCaptureMs after gate.");
        append(report, "Single variable vs Control A",
                "text+bridge at 230400 (baud set before tape wait)");
        append(report, "PASS criterion",
                "tape CHAN_D trigger + >=1 framed HPI event @230400");
        phase("SETUP", "准备中…", "生产态恢复 / 握手 / 切 230400");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] setCode = wordsToBytes(BAUD_SET_230400_WORDS);
            byte[] restoreCode = wordsToBytes(BAUD_RESTORE_57600_WORDS);
            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            if (!BAUD_SET_230400_SHA256.equals(sha256(setCode))
                    || !BAUD_RESTORE_57600_SHA256.equals(sha256(restoreCode))
                    || !"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(sha256(handler))) {
                throw new IOException("Stub/handler hash mismatch");
            }
            assertStackSafeBaudStub(setCode, "set-230400");
            assertStackSafeBaudStub(restoreCode, "restore-57600");
            append(report, "Set-230400 stub SHA-256", sha256(setCode));
            append(report, "Timeout handler SHA-256", sha256(handler));

            // ---- Phase 0: 57600 baseline (recover if MCU left at 230400) ----
            phase("SETUP", "准备中…", "串口握手 / 必要时从 230400 恢复");
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            mcuBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(400);
            drainAvailable(input);
            String connect = "";
            for (int attempt = 0; attempt < 3; attempt++) {
                output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
                output.flush();
                connect = readResponse(input, RESPONSE_TIMEOUT_MS);
                if (connect.contains("+DMOCONNECT:0")) {
                    break;
                }
                SystemClock.sleep(200);
                drainAvailable(input);
            }
            append(report, "Handshake @57600", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                // MCU may still be at 230400 after a previous run / force-stop.
                append(report, "57600 connect empty — try recover @230400", true);
                closeSerialLocked(report);
                openSerialLocked(device, BAUD_RATE_230400, report);
                androidBaud = BAUD_RATE_230400;
                mcuBaud = BAUD_RATE_230400;
                input = serialPort.getInputStream();
                output = outputStream;
                SystemClock.sleep(400);
                drainAvailable(input);
                String connectHigh = "";
                for (int attempt = 0; attempt < 3; attempt++) {
                    output.write("AT+DMOCONNECT\r\n"
                            .getBytes(StandardCharsets.US_ASCII));
                    output.flush();
                    connectHigh = readResponse(input, RESPONSE_TIMEOUT_MS);
                    if (connectHigh.contains("+DMOCONNECT:0")) {
                        break;
                    }
                    SystemClock.sleep(200);
                    drainAvailable(input);
                }
                append(report, "Handshake @230400 recovery",
                        printable(connectHigh));
                if (!connectHigh.contains("+DMOCONNECT:0")) {
                    throw new IOException(
                            "Connect failed at 57600 and 230400 — power-cycle MCU?");
                }
                // memwrite needs print 1 even on recovery path.
                synchronized (lock) {
                    logLevelMayBeEnabled = true;
                }
                writeCommand(output, LOG_ENABLE_COMMAND);
                appendRaw(report, "Recover log enable",
                        readBytes(input, SHORT_READ_TIMEOUT_MS));
                // Restore text plane to 57600 so baseline matches Control A.
                armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                        "recover-restore-57600", report);
                mcuBaud = BAUD_RATE;
                closeSerialLocked(report);
                openSerialLocked(device, BAUD_RATE, report);
                androidBaud = BAUD_RATE;
                input = serialPort.getInputStream();
                output = outputStream;
                SystemClock.sleep(400);
                drainAvailable(input);
                verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                        "recover-restore-57600", report);
                connect = "";
                for (int attempt = 0; attempt < 3; attempt++) {
                    output.write("AT+DMOCONNECT\r\n"
                            .getBytes(StandardCharsets.US_ASCII));
                    output.flush();
                    connect = readResponse(input, RESPONSE_TIMEOUT_MS);
                    if (connect.contains("+DMOCONNECT:0")) {
                        break;
                    }
                    SystemClock.sleep(200);
                    drainAvailable(input);
                }
                append(report, "Handshake @57600 after recover",
                        printable(connect));
                if (!connect.contains("+DMOCONNECT:0")) {
                    throw new IOException(
                            "Connect failed at 57600 after 230400 recover");
                }
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected version at 57600");
            }

            // v0.84: skip pre-tape forced chgpro (same rationale as Control A).
            drainAvailable(input);
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));
            String setChB = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "Pre-tape CH1 ensure", printable(setChB));

            originalFlag = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            originalTimeoutCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            originalTimeoutCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            originalTimeoutMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            originalBaudCode = readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                    BAUD_SET_230400_WORDS.length * 4);
            originalBaudMarker = readMemory(input, output,
                    BAUD_ONESHOT_MARKER_ADDRESS, 4);
            if ((originalFlag[0] & 0xff) != 0
                    || u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected baseline before prepare");
            }

            byte[] tickFirstBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickDelta = (u32le(tickSecondBytes, 0) - u32le(tickFirstBytes, 0))
                    & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            append(report, "Measured tick Hz", String.format(Locale.US, "%.2f",
                    tickRateHz));
            final long bridgeCaptureMs = 15000;
            final long bridgeTimeoutMs = 22000;
            int timeoutTicks = (int) Math.round(tickRateHz * bridgeTimeoutMs / 1000.0);
            append(report, "Bridge capture ms", bridgeCaptureMs);
            append(report, "Bridge timeout ms", bridgeTimeoutMs);
            append(report, "Bridge timeout ticks", timeoutTicks);

            // ---- Phase 1 PRE-GATE: upload handler + switch 230400 (flag=0) ----
            // v0.77 bug: doing this AFTER tape gate cost ~13s while operator TX ended.
            for (int offset = 0; offset < handler.length; offset += 4) {
                writeMemoryWord(input, output,
                        UART_HPI_TIMEOUT_CODE_ADDRESS + offset,
                        u32le(handler, offset));
            }
            stateChanged = true;
            if (!Arrays.equals(handler, readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length))) {
                throw new IOException("Timeout handler upload mismatch");
            }

            long baudSwitchStarted = SystemClock.elapsedRealtime();
            armBaudOneShot(input, output, BAUD_SET_230400_WORDS, "set-230400",
                    report);
            mcuBaud = BAUD_RATE_230400;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE_230400, report);
            androidBaud = BAUD_RATE_230400;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(100);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_230400,
                    "set-230400", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectHigh = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @230400 before tape gate",
                    printable(connectHigh));
            if (!connectHigh.contains("+DMOCONNECT:0")) {
                throw new IOException("CONNECT failed @230400 before tape gate");
            }
            append(report, "Pre-gate baud switch ms",
                    SystemClock.elapsedRealtime() - baudSwitchStarted);

            // ---- Phase 2: tape gate ALREADY at 230400 text (memread proven) ----
            Log.i(TAG, ">>> TRANSMIT NOW for TAPE GATE @230400 (Control B v0.79): "
                    + "TYT CH1 TG99 CC8 TS1 low; HOLD through TAPE PASSED + 15s PCM <<<");
            append(report, "Operator cue",
                    "HOLD PTT until TAPE PASSED then keep holding 15s for PCM@230400");
            phase("TRANSMIT_NOW", "现在发射！一直按住",
                    "TYT CH1 TG99 CC8 TS1 low — 过门后再按 15 秒");
            long tapeWaitStarted = SystemClock.elapsedRealtime();
            DmrRxMilestoneTrigger dmrTrigger =
                    awaitDmrRxMilestoneTrigger(input, output, report);
            append(report, "Tape gate wait ms",
                    SystemClock.elapsedRealtime() - tapeWaitStarted);
            append(report, "Tape gate units", dmrTrigger.units);
            append(report, "Tape gate file",
                    dmrTrigger.captureFile.getAbsolutePath());

            // ---- Phase 3: IMMEDIATE bridge — no baud/serial reopen after gate ----
            long gateToBridgeStarted = SystemClock.elapsedRealtime();
            Log.i(TAG, ">>> TAPE TRIGGER PASSED units=" + dmrTrigger.units
                    + " — IMMEDIATE bridge@230400 (no baud switch); KEEP PTT <<<");
            phase("TAPE_OK", "过门了！再按住 15 秒",
                    "units=" + dmrTrigger.units + " 正在开桥收 PCM");

            writeMemoryWord(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    timeoutTicks);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    UART_HPI_TIMEOUT_ENTRY);
            synchronized (lock) {
                logLevelMayBeEnabled = false;
            }
            long bridgeArmedAt = SystemClock.elapsedRealtime();
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            bridgeMayBeActive = true;
            append(report, "Gate-to-bridge arm ms",
                    bridgeArmedAt - gateToBridgeStarted);

            output.write(HPI_VOCODER_IO_OFF);
            output.flush();
            SystemClock.sleep(10);
            output.write(HPI_VOCODER_IO_VOICE_OUT_HPI);
            output.flush();
            SystemClock.sleep(20);
            phase("CAPTURING", "正在收语音…继续按住",
                    "15s PCM @230400");
            byte[] raw = readForDuration(input, bridgeCaptureMs);
            // v0.82: VOCODER off + WORK_MODE idle while bridge still up.
            hpiExitTrafficPlaneWhileBridged(output, report);
            raw = concatBytes(raw,
                    readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));
            append(report, "Capture actual ms",
                    SystemClock.elapsedRealtime() - bridgeArmedAt);
            phase("RESTORE", "可以松手 · 恢复中…",
                    "raw=" + raw.length + " B · 将 sct3258chgpro 0");

            long safeReadAt = bridgeArmedAt + bridgeTimeoutMs + 2500;
            long remaining = safeReadAt - SystemClock.elapsedRealtime();
            if (remaining > 0) {
                SystemClock.sleep(remaining);
            }

            byte[] flagAfter = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] vectorAfter = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            byte[] counterAfter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            byte[] markerAfter = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            append(report, "Bridge flag after", flagAfter[0] & 0xff);
            append(report, "SysTick after bridge", String.format(Locale.US,
                    "0x%08x", u32le(vectorAfter, 0)));
            append(report, "Timeout marker after", String.format(Locale.US,
                    "0x%08x", u32le(markerAfter, 0)));
            if ((flagAfter[0] & 0xff) != 0
                    || u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER
                    || u32le(counterAfter, 0) != 0
                    || u32le(markerAfter, 0) != UART_HPI_TIMEOUT_MARKER) {
                throw new IOException("Bridge recovery mismatch @230400 Control B");
            }
            bridgeMayBeActive = false;
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }

            long stamp = System.currentTimeMillis();
            File captureFile = new File(outputDirectory, String.format(Locale.US,
                    "hpi_voice_out_pcm_230400_control_b_%d.bin", stamp));
            writeFile(captureFile, raw);
            HpiCaptureSummary summary = summarizeHpiCapture(raw);
            append(report, "Capture raw bytes", raw.length);
            append(report, "Capture SHA-256", sha256(raw));
            append(report, "Capture file", captureFile.getAbsolutePath());
            append(report, "HPI summary", summary.toString());
            append(report, "HPI frames", summary.frames);
            append(report, "pcm160", summary.pcm160);
            append(report, "chanD27", summary.chanD27);
            append(report, "Control A reference",
                    "raw=428 frames=9 pcm160=1 chanD27=1 @57600");

            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                    "restore-57600", report);
            mcuBaud = BAUD_RATE;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                    "restore-57600", report);
            // Exactly one control-plane reload on success (P0).
            reloadSctBaselineTrafficPlane(input, output, report);
            controlPlaneReloadDone = true;
            append(report, "controlPlaneReloadCount", 1);

            restoreWords(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS,
                    originalTimeoutCode);
            restoreWords(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    originalTimeoutCounter);
            restoreWords(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS,
                    originalTimeoutMarker);
            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalBaudCode);
            restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS,
                    originalBaudMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    u32le(originalVector, 0));
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                    originalFlag[0] & 0xff);
            stateRestored = Arrays.equals(originalTimeoutCode, readMemory(input,
                    output, UART_HPI_TIMEOUT_CODE_ADDRESS, originalTimeoutCode.length))
                    && u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    == ORIGINAL_SYSTICK_HANDLER;
            append(report, "transportRestored", stateRestored);
            append(report, "Temporary state restored", stateRestored);
            if (!stateRestored) {
                throw new IOException("Temporary state restore mismatch");
            }
            if (dmrTrigger.units >= DMR_RX_TRIGGER_MIN_UNITS) {
                append(report, "rxTrafficPlaneHealthy", true);
            }
            disableLogLevel(input, output, report);

            boolean tapeOk = dmrTrigger.units >= DMR_RX_TRIGGER_MIN_UNITS;
            boolean hpiOk = summary.frames > 0 || raw.length > 0;
            if (!tapeOk) {
                outcomeSuccess = false;
                outcomeStatus = "INVALID: tape gate failed";
            } else if (!hpiOk) {
                outcomeSuccess = false;
                outcomeStatus = "FAIL Control B: tape OK but bridge empty @230400 "
                        + "(compare Control A raw @57600)";
            } else {
                outcomeSuccess = true;
                outcomeStatus = String.format(Locale.US,
                        "PASS Control B: tape units=%d HPI frames=%d raw=%d @230400",
                        dmrTrigger.units, summary.frames, raw.length);
            }
        } catch (Throwable error) {
            Log.e(TAG, "Control B 230400 failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            append(report, "MCU baud at failure", mcuBaud);
            append(report, "Android baud at failure", androidBaud);
            String msg = error.getMessage() != null ? error.getMessage() : "";
            outcomeSuccess = false;
            if (msg.contains("No new DMR RX trigger")) {
                outcomeStatus = "INVALID: no tape RX — traffic-plane may be stale; "
                        + "cold-start Interphone or production restore";
            } else {
                outcomeStatus = "FAIL";
            }
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    if (bridgeMayBeActive && mcuBaud == androidBaud) {
                        try {
                            if (output != null) {
                                append(report, "restore.step.hpiExit", "attempt");
                                hpiExitTrafficPlaneWhileBridged(output, report);
                                append(report, "restore.step.hpiExit", "ok");
                            }
                        } catch (Throwable exitError) {
                            append(report, "restore.step.hpiExit",
                                    "fail: " + exitError.getMessage());
                        }
                        SystemClock.sleep(2500);
                    }
                    if (androidBaud != mcuBaud && mcuBaud == BAUD_RATE_230400) {
                        try {
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE_230400, report);
                            androidBaud = BAUD_RATE_230400;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            append(report, "restore.step.reopen230400", "ok");
                        } catch (Throwable reopenError) {
                            append(report, "restore.step.reopen230400",
                                    "fail: " + reopenError.getMessage());
                        }
                    }
                    if (input != null && output != null
                            && mcuBaud == BAUD_RATE_230400) {
                        try {
                            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                                    "emergency-restore-57600", report);
                            mcuBaud = BAUD_RATE;
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE, report);
                            androidBaud = BAUD_RATE;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            append(report, "restore.step.emergencyBaud57600", "ok");
                        } catch (Throwable baudError) {
                            append(report, "restore.step.emergencyBaud57600",
                                    "fail: " + baudError.getMessage());
                        }
                    }
                    if (input != null && output != null && mcuBaud == BAUD_RATE) {
                        try {
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                            writeMemoryByte(input, output,
                                    UART_HPI_BRIDGE_FLAG_ADDRESS, 0);
                            append(report, "restore.step.emergencyTransport", "ok");
                        } catch (Throwable transportError) {
                            append(report, "restore.step.emergencyTransport",
                                    "fail: " + transportError.getMessage());
                        }
                    }
                } catch (Throwable restoreError) {
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                }
            }
            if (input != null && output != null && mcuBaud == BAUD_RATE) {
                if (shouldAttemptFinallyControlReload(controlPlaneReloadDone)) {
                    if (bestEffortControlPlaneReload(input, output, report)) {
                        controlPlaneReloadDone = true;
                        append(report, "controlPlaneReloadCount", 1);
                    }
                    append(report, "finallyReloadSkipped", false);
                    append(report, "finallyReloadBestEffort", true);
                } else {
                    append(report, "finallyReloadSkipped", true);
                    append(report, "controlPlaneReloadCount", 1);
                }
                try {
                    disableLogLevel(input, output, report);
                    append(report, "restore.step.print0", "ok");
                } catch (Throwable printError) {
                    append(report, "restore.step.print0",
                            "fail: " + printError.getMessage());
                }
            }
            close();
            append(report, "serialClosed", true);
        }
        return finish(outcomeSuccess, report, outcomeStatus);
    }

    /**
     * Legacy direct 230400 RX without tape gate — blocked for RF experiments.
     * Use {@link #runVoiceOutPcm230400ControlB()} after Control A.
     */
    ProbeResult runVoiceOutPcm230400RxCapture() {
        return runVoiceOutPcm230400ControlB();
    }

    /**
     * P0 no-RF instrument smoke: handshake + exactly one control-plane reload +
     * close. Proves finallyReloadSkipped and handoff without TYT transmit.
     */
    ProbeResult runP0SessionSmoke() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        boolean controlPlaneReloadDone = false;
        boolean outcomeSuccess = false;
        String outcomeStatus = "FAIL";

        append(report, "Mode", "P0 session smoke (no RF)");
        append(report, "Probe build", "v0.87-p0-probe-infra");
        append(report, "Device", DEVICE_PATH);
        append(report, "RF", "none — no Voice OUT, no tape gate, no TYT");
        append(report, "PASS criterion",
                "CONNECT+version+one control reload; finallyReloadSkipped=true");
        phase("SETUP", "P0 无 RF 冒烟", "握手 + 单次 sct3258chgpro 0");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            synchronized (lock) {
                closeLocked(report);
                serialPort = new SerialPort(device, BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
            }
            SystemClock.sleep(250);
            append(report, "Startup", printable(readResponse(input, STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake response", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect response not recognized");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected MCU version");
            }
            String channelBefore = query(input, output, "AT+DMOGETDIGITALCH");
            append(report, "Digital CH before reload", printable(channelBefore));

            reloadSctBaselineTrafficPlane(input, output, report);
            controlPlaneReloadDone = true;
            append(report, "controlPlaneReloadCount", 1);
            append(report, "transportRestored", "n/a-no-adapter");

            disableLogLevel(input, output, report);
            outcomeSuccess = true;
            outcomeStatus = "PASS P0 session smoke: single control reload @57600";
        } catch (Throwable error) {
            Log.e(TAG, "P0 session smoke failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            outcomeSuccess = false;
            outcomeStatus = "FAIL";
        } finally {
            if (input != null && output != null) {
                if (shouldAttemptFinallyControlReload(controlPlaneReloadDone)) {
                    if (bestEffortControlPlaneReload(input, output, report)) {
                        controlPlaneReloadDone = true;
                        append(report, "controlPlaneReloadCount", 1);
                    }
                    append(report, "finallyReloadSkipped", false);
                    append(report, "finallyReloadBestEffort", true);
                } else {
                    append(report, "finallyReloadSkipped", true);
                    append(report, "controlPlaneReloadCount", 1);
                }
                try {
                    disableLogLevel(input, output, report);
                    append(report, "restore.step.print0", "ok");
                } catch (Throwable printError) {
                    append(report, "restore.step.print0",
                            "fail: " + printError.getMessage());
                }
            }
            close();
            append(report, "serialClosed", true);
        }
        return finish(outcomeSuccess, report, outcomeStatus);
    }

    /**
     * P2-B research: hunt true SCT/HPI linear PCM (NOT host AMBE).
     * Single variable = HPI route after tape-proven RF.
     * PASS = tape gate + HPI capture files + P0 restore.
     * Does <b>not</b> claim decoded voice; offline score_speech_likeness.py + operator.
     *
     * @param route one of: voice_out, voice_out_both, modem_out, vocoder_out,
     *        process_mode2_voice_out, debug_speech
     */
    ProbeResult runHpiPcmRouteHunt(String route) {
        if (route == null || route.isEmpty()) {
            route = "voice_out";
        }
        final String routeKey = route;
        final byte[][] armCommands;
        final String routeLabel;
        if ("debug_speech".equals(routeKey)) {
            // Historical no-RF silent; only re-run if new static evidence appears.
            routeLabel = "DEBUG_SPEECH_HPI WORK_MODE debug=7 (historical silent)";
            armCommands = new byte[][] {HPI_VOCODER_IO_OFF, HPI_DEBUG_SPEECH};
        } else if ("voice_out_both".equals(routeKey)) {
            routeLabel = "VOCODER_IO=0x02 Voice OUT both (codec+file)";
            armCommands = new byte[][] {HPI_VOCODER_IO_OFF, HPI_VOCODER_IO_VOICE_OUT_BOTH};
        } else if ("modem_out".equals(routeKey)) {
            routeLabel = "VOCODER_IO=0x04 Modem OUT HPI (encoded CHAN_D plane)";
            armCommands = new byte[][] {HPI_VOCODER_IO_OFF, HPI_VOCODER_IO_MODEM_OUT_HPI};
        } else if ("vocoder_out".equals(routeKey)) {
            routeLabel = "VOCODER_IO=0x20 Vocoder OUT HPI (encoded plane)";
            armCommands = new byte[][] {HPI_VOCODER_IO_OFF, HPI_VOCODER_IO_VOCODER_OUT_BOTH};
        } else if ("process_mode2_voice_out".equals(routeKey)) {
            // Primary next single-variable hypothesis after ChatGPT 10:17 review:
            // vendor DMR_Receive uses PROCESS_MODE(2); Voice OUT alone may leave
            // the streaming type30/count=160 source on a non-decoder buffer.
            routeLabel = "PROCESS_MODE(2)+VOCODER_IO=0x01 (single-var hypothesis)";
            armCommands = new byte[][] {
                    HPI_VOCODER_IO_OFF,
                    HPI_PROCESS_MODE_2,
                    HPI_VOCODER_IO_VOICE_OUT_HPI
            };
        } else {
            routeLabel = "VOCODER_IO=0x01 Voice OUT HPI (baseline; content FAIL)";
            armCommands = new byte[][] {HPI_VOCODER_IO_OFF, HPI_VOCODER_IO_VOICE_OUT_HPI};
        }

        // Reuse Control B timeline: tape gate then bridge@230400, inject route.
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalTimeoutCode = null;
        byte[] originalTimeoutCounter = null;
        byte[] originalTimeoutMarker = null;
        byte[] originalBaudCode = null;
        byte[] originalBaudMarker = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        boolean bridgeMayBeActive = false;
        boolean controlPlaneReloadDone = false;
        boolean outcomeSuccess = false;
        String outcomeStatus = "FAIL";
        int mcuBaud = BAUD_RATE;
        int androidBaud = BAUD_RATE;
        final long captureMs = 12000L;

        append(report, "Mode", "HPI true-PCM hunt (P2-B research)");
        append(report, "Probe build", "0.91-hpi-pcm-hunt");
        append(report, "Route key", routeKey);
        append(report, "Route label", routeLabel);
        append(report, "Claim policy",
                "NEVER claim SCT linear PCM from frame headers alone; "
                        + "require offline speech_like + operator hearing");
        append(report, "Not this mode", "CHAN_D host AMBE is a separate encoded path");
        phase("SETUP", "PCM寻猎准备…", routeKey);
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] setCode = wordsToBytes(BAUD_SET_230400_WORDS);
            byte[] restoreCode = wordsToBytes(BAUD_RESTORE_57600_WORDS);
            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            if (!BAUD_SET_230400_SHA256.equals(sha256(setCode))
                    || !BAUD_RESTORE_57600_SHA256.equals(sha256(restoreCode))
                    || !"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(sha256(handler))) {
                throw new IOException("Stub/handler hash mismatch");
            }
            assertStackSafeBaudStub(setCode, "set-230400");
            assertStackSafeBaudStub(restoreCode, "restore-57600");

            synchronized (lock) {
                closeLocked(report);
                serialPort = new SerialPort(device, BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
            }
            SystemClock.sleep(250);
            append(report, "Startup", printable(readResponse(input, STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version", printable(version));
            if (!version.contains("0.3.66")) {
                throw new IOException("Unexpected version");
            }
            String setCh = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "CH1 ensure", printable(setCh));

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable", readBytes(input, SHORT_READ_TIMEOUT_MS));

            originalFlag = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            if ((originalFlag[0] & 0xff) != 0
                    || u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Bad baseline flag/vector");
            }
            originalBaudCode = readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                    BAUD_SET_230400_WORDS.length * 4);
            originalBaudMarker = readMemory(input, output, BAUD_ONESHOT_MARKER_ADDRESS, 4);
            originalTimeoutCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            originalTimeoutCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            originalTimeoutMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);

            byte[] tickFirstBytes = readMemory(input, output, MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(input, output, MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickDelta = (u32le(tickSecondBytes, 0) - u32le(tickFirstBytes, 0))
                    & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 1000.0;
            int timeoutTicks = (int) Math.round(tickRateHz * (captureMs + 8000) / 1000.0);
            if (timeoutTicks < 100) {
                timeoutTicks = 120000;
            }
            append(report, "Measured tick Hz",
                    String.format(Locale.US, "%.2f", tickRateHz));

            for (int i = 0; i < handler.length; i += 4) {
                writeMemoryWord(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS + i,
                        u32le(handler, i));
            }
            stateChanged = true;

            // Pre-gate 230400 (flag=0).
            armBaudOneShot(input, output, BAUD_SET_230400_WORDS, "set-230400", report);
            mcuBaud = BAUD_RATE_230400;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE_230400, report);
            androidBaud = BAUD_RATE_230400;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_230400,
                    "set-230400", report);

            phase("TRANSMIT_NOW", "现在发射！一直按住",
                    "过门后继续说 · 路由=" + routeKey);
            DmrRxMilestoneTrigger dmrTrigger =
                    awaitDmrRxMilestoneTrigger(input, output, report);
            append(report, "Tape gate units (RF oracle)", dmrTrigger.units);
            append(report, "Tape gate file", dmrTrigger.captureFile.getAbsolutePath());
            phase("TAPE_OK", "过门了！继续按住",
                    "units=" + dmrTrigger.units + " 开桥 " + routeKey);

            writeMemoryWord(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS, timeoutTicks);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK, UART_HPI_TIMEOUT_ENTRY);
            synchronized (lock) {
                logLevelMayBeEnabled = false;
            }
            long bridgeArmedAt = SystemClock.elapsedRealtime();
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            bridgeMayBeActive = true;

            for (byte[] cmd : armCommands) {
                output.write(cmd);
                output.flush();
                SystemClock.sleep(30);
            }
            phase("CAPTURING", "HPI采集中…继续说",
                    captureMs + "ms · " + routeKey);
            byte[] raw = readForDuration(input, captureMs);
            hpiExitTrafficPlaneWhileBridged(output, report);
            raw = concatBytes(raw, readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));

            long waitMore = bridgeArmedAt + captureMs + 3000
                    - SystemClock.elapsedRealtime();
            if (waitMore > 0) {
                SystemClock.sleep(waitMore);
            }
            bridgeMayBeActive = false;

            long stamp = System.currentTimeMillis();
            File rawFile = new File(outputDirectory, String.format(Locale.US,
                    "hpi_pcm_hunt_%s_%d.bin", routeKey, stamp));
            writeFile(rawFile, raw);
            ProductPcmRecovery product = recoverProductPcm(raw);
            int speech1280 = countSpeechSamples1280Frames(raw);
            File productFile = new File(outputDirectory, String.format(Locale.US,
                    "hpi_pcm_hunt_%s_%d_product.raw", routeKey, stamp));
            File wavFile = new File(outputDirectory, String.format(Locale.US,
                    "hpi_pcm_hunt_%s_%d_product.wav", routeKey, stamp));
            writeFile(productFile, product.productPcm);
            writeWav8kMonoS16le(wavFile, product.productPcm);

            append(report, "Capture raw bytes", raw.length);
            append(report, "Capture SHA-256", sha256(raw));
            append(report, "Capture file", rawFile.getAbsolutePath());
            append(report, "speechFrames_LENGTH323_count160", product.speechFrames);
            append(report, "speechFrames_LENGTH1283_count640 (vendor SPEECH_SAMPLES)",
                    speech1280);
            append(report, "wire328Frames", product.wire328Frames);
            append(report, "productBytes", product.productPcm.length);
            append(report, "productDurationMs", product.productPcm.length / 16.0);
            append(report, "product wav", wavFile.getAbsolutePath());
            append(report, "container_only",
                    "WAV is time-aligned container from LENGTH=323 frames; "
                            + "NOT proof of decoder PCM");
            append(report, "OFFLINE_REQUIRED",
                    "score_speech_likeness.py on product wav; "
                            + "operator hearing; concurrent CHAN_D is RF oracle only; "
                            + "PASS voice requires speech_like=true AND operator OK");

            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                    "restore-57600", report);
            mcuBaud = BAUD_RATE;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                    "restore-57600", report);
            restoreWords(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS,
                    originalTimeoutCode);
            restoreWords(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    originalTimeoutCounter);
            restoreWords(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS,
                    originalTimeoutMarker);
            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalBaudCode);
            restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS,
                    originalBaudMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    u32le(originalVector, 0));
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                    originalFlag[0] & 0xff);
            stateRestored = true;
            append(report, "transportRestored", true);

            reloadSctBaselineTrafficPlane(input, output, report);
            controlPlaneReloadDone = true;
            append(report, "controlPlaneReloadCount", 1);
            append(report, "rxTrafficPlaneHealthy",
                    dmrTrigger.units >= DMR_RX_TRIGGER_MIN_UNITS);
            disableLogLevel(input, output, report);

            outcomeSuccess = dmrTrigger.units >= DMR_RX_TRIGGER_MIN_UNITS
                    && stateRestored && controlPlaneReloadDone;
            outcomeStatus = String.format(Locale.US,
                    "PASS hunt lifecycle route=%s tape=%d raw=%d speechFrames=%d "
                            + "(NOT a PCM-voice claim)",
                    routeKey, dmrTrigger.units, raw.length, product.speechFrames);
        } catch (Throwable error) {
            Log.e(TAG, "HPI PCM hunt failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            outcomeSuccess = false;
            outcomeStatus = "FAIL";
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    if (bridgeMayBeActive && output != null) {
                        try {
                            hpiExitTrafficPlaneWhileBridged(output, report);
                        } catch (Throwable ignored) {
                            // continue
                        }
                        SystemClock.sleep(2500);
                    }
                    if (mcuBaud == BAUD_RATE_230400 && input != null && output != null) {
                        try {
                            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                                    "emergency-restore-57600", report);
                            mcuBaud = BAUD_RATE;
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE, report);
                            androidBaud = BAUD_RATE;
                            input = serialPort.getInputStream();
                            output = outputStream;
                        } catch (Throwable ignored) {
                            // continue
                        }
                    }
                    if (input != null && output != null && mcuBaud == BAUD_RATE) {
                        try {
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                            writeMemoryByte(input, output,
                                    UART_HPI_BRIDGE_FLAG_ADDRESS, 0);
                        } catch (Throwable ignored) {
                            // continue
                        }
                    }
                } catch (Throwable restoreError) {
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                }
            }
            if (input != null && output != null && mcuBaud == BAUD_RATE) {
                if (shouldAttemptFinallyControlReload(controlPlaneReloadDone)) {
                    bestEffortControlPlaneReload(input, output, report);
                    append(report, "finallyReloadSkipped", false);
                } else {
                    append(report, "finallyReloadSkipped", true);
                }
                try {
                    disableLogLevel(input, output, report);
                } catch (Throwable ignored) {
                    // ignore
                }
            }
            close();
            append(report, "serialClosed", true);
        }
        return finish(outcomeSuccess, report, outcomeStatus);
    }

    /**
     * Legacy P2 file-stream helper. Does not prove SCT linear PCM voice.
     */
    ProbeResult runRxPcmProductStream() {
        return runRxPcmProductStream(15000L);
    }

    ProbeResult runRxPcmProductStream(long captureMs) {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalTimeoutCode = null;
        byte[] originalTimeoutCounter = null;
        byte[] originalTimeoutMarker = null;
        byte[] originalBaudCode = null;
        byte[] originalBaudMarker = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        boolean bridgeMayBeActive = false;
        boolean controlPlaneReloadDone = false;
        boolean outcomeSuccess = false;
        String outcomeStatus = "FAIL";
        int mcuBaud = BAUD_RATE;
        int androidBaud = BAUD_RATE;
        if (captureMs < 1000L) {
            captureMs = 1000L;
        }
        if (captureMs > 60000L) {
            captureMs = 60000L;
        }

        append(report, "Mode", "P2 RX PCM product stream @230400");
        append(report, "Probe build", "0.89-p2-rx-pcm-stream");
        append(report, "Device", DEVICE_PATH);
        append(report, "Capture ms", captureMs);
        append(report, "Pad policy", "zero_pad_to_160_when_wire328");
        append(report, "PASS criterion",
                "lifecycle OK + product files written; speech frames if RF present");
        phase("SETUP", "P2 PCM 流", "握手 / 230400 / Voice OUT");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] setCode = wordsToBytes(BAUD_SET_230400_WORDS);
            byte[] restoreCode = wordsToBytes(BAUD_RESTORE_57600_WORDS);
            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            if (!BAUD_SET_230400_SHA256.equals(sha256(setCode))
                    || !BAUD_RESTORE_57600_SHA256.equals(sha256(restoreCode))
                    || !"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(sha256(handler))) {
                throw new IOException("Stub/handler hash mismatch");
            }
            assertStackSafeBaudStub(setCode, "set-230400");
            assertStackSafeBaudStub(restoreCode, "restore-57600");

            synchronized (lock) {
                closeLocked(report);
                serialPort = new SerialPort(device, BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
                androidBaud = BAUD_RATE;
            }
            SystemClock.sleep(250);
            append(report, "Startup", printable(readResponse(input, STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version", printable(version));
            if (!version.contains("0.3.66")) {
                throw new IOException("Unexpected version");
            }
            String setCh = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "CH1 ensure", printable(setCh));
            if (!setCh.contains("+DMOSETDIGITALCH:0")) {
                throw new IOException("CH1 ensure failed");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable", readBytes(input, SHORT_READ_TIMEOUT_MS));

            originalFlag = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            if ((originalFlag[0] & 0xff) != 0) {
                throw new IOException("Bridge already active");
            }
            if (u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected SysTick");
            }
            originalBaudCode = readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                    BAUD_SET_230400_WORDS.length * 4);
            originalBaudMarker = readMemory(input, output, BAUD_ONESHOT_MARKER_ADDRESS, 4);
            originalTimeoutCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            originalTimeoutCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            originalTimeoutMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);

            byte[] tickFirstBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickDelta = (u32le(tickSecondBytes, 0) - u32le(tickFirstBytes, 0))
                    & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 1000.0;
            long bridgeTimeoutMs = captureMs + 7000;
            int timeoutTicks = (int) Math.round(tickRateHz * bridgeTimeoutMs / 1000.0);
            if (timeoutTicks < 100) {
                timeoutTicks = 100000;
            }
            append(report, "Measured tick Hz",
                    String.format(Locale.US, "%.2f", tickRateHz));
            append(report, "Bridge timeout ticks", timeoutTicks);

            // Upload timeout handler while still @57600, flag=0.
            for (int i = 0; i < handler.length; i += 4) {
                writeMemoryWord(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS + i,
                        u32le(handler, i));
            }
            stateChanged = true;
            if (!Arrays.equals(handler, readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length))) {
                throw new IOException("Timeout handler upload mismatch");
            }

            // Baud to 230400 before bridge (flag still 0).
            armBaudOneShot(input, output, BAUD_SET_230400_WORDS, "set-230400", report);
            mcuBaud = BAUD_RATE_230400;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE_230400, report);
            androidBaud = BAUD_RATE_230400;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_230400,
                    "set-230400", report);

            writeMemoryWord(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    timeoutTicks);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK, UART_HPI_TIMEOUT_ENTRY);
            synchronized (lock) {
                logLevelMayBeEnabled = false;
            }
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            bridgeMayBeActive = true;

            output.write(HPI_VOCODER_IO_OFF);
            output.flush();
            SystemClock.sleep(20);
            output.write(HPI_VOCODER_IO_VOICE_OUT_HPI);
            output.flush();
            SystemClock.sleep(30);

            phase("CAPTURING", "采集 PCM…", captureMs + " ms @230400");
            long bridgeArmedAt = SystemClock.elapsedRealtime();
            byte[] raw = readForDuration(input, captureMs);
            hpiExitTrafficPlaneWhileBridged(output, report);
            raw = concatBytes(raw, readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));

            long safeReadAt = bridgeArmedAt + captureMs + 3000;
            long remaining = safeReadAt - SystemClock.elapsedRealtime();
            if (remaining > 0) {
                SystemClock.sleep(remaining);
            }

            byte[] flagAfter = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] vectorAfter = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            if ((flagAfter[0] & 0xff) != 0
                    || u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER) {
                // Best-effort continue restore; note mismatch.
                append(report, "Bridge recovery note",
                        "flag/vector not fully restored before baud restore");
            }
            bridgeMayBeActive = false;

            long stamp = System.currentTimeMillis();
            File rawFile = new File(outputDirectory, String.format(Locale.US,
                    "hpi_rx_pcm_product_raw_%d.bin", stamp));
            writeFile(rawFile, raw);
            ProductPcmRecovery product = recoverProductPcm(raw);
            File productRaw = new File(outputDirectory, String.format(Locale.US,
                    "pcm_product_160_s16le_%d.raw", stamp));
            File availableRaw = new File(outputDirectory, String.format(Locale.US,
                    "pcm_available_s16le_%d.raw", stamp));
            File gapsFile = new File(outputDirectory, String.format(Locale.US,
                    "pcm_gaps_%d.csv", stamp));
            File wavFile = new File(outputDirectory, String.format(Locale.US,
                    "pcm_product_160_8k_%d.wav", stamp));
            writeFile(productRaw, product.productPcm);
            writeFile(availableRaw, product.availablePcm);
            writeFile(gapsFile, product.gapsCsv.getBytes(StandardCharsets.US_ASCII));
            writeWav8kMonoS16le(wavFile, product.productPcm);

            append(report, "Capture raw bytes", raw.length);
            append(report, "Capture SHA-256", sha256(raw));
            append(report, "Capture file", rawFile.getAbsolutePath());
            append(report, "speechFrames", product.speechFrames);
            append(report, "wire328Frames", product.wire328Frames);
            append(report, "complete160Frames", product.complete160Frames);
            append(report, "gapFrames", product.gapFrames);
            append(report, "missingSamplesTotal", product.missingSamplesTotal);
            append(report, "productBytes", product.productPcm.length);
            append(report, "productDurationMs", product.productPcm.length / 16.0);
            append(report, "product SHA-256", sha256(product.productPcm));
            append(report, "product wav", wavFile.getAbsolutePath());
            append(report, "gaps file", gapsFile.getAbsolutePath());

            // Restore 57600 + transport + one control reload.
            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                    "restore-57600", report);
            mcuBaud = BAUD_RATE;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                    "restore-57600", report);

            restoreWords(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS,
                    originalTimeoutCode);
            restoreWords(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    originalTimeoutCounter);
            restoreWords(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS,
                    originalTimeoutMarker);
            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalBaudCode);
            restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS,
                    originalBaudMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    u32le(originalVector, 0));
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                    originalFlag[0] & 0xff);
            stateRestored = u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    == ORIGINAL_SYSTICK_HANDLER;
            append(report, "transportRestored", stateRestored);

            reloadSctBaselineTrafficPlane(input, output, report);
            controlPlaneReloadDone = true;
            append(report, "controlPlaneReloadCount", 1);
            if (product.speechFrames > 0) {
                append(report, "rxTrafficPlaneHealthy", true);
            }
            disableLogLevel(input, output, report);

            outcomeSuccess = stateRestored && controlPlaneReloadDone;
            if (product.speechFrames > 0) {
                outcomeStatus = String.format(Locale.US,
                        "PASS P2 stream: speech=%d productMs=%.0f raw=%d",
                        product.speechFrames, product.productPcm.length / 16.0,
                        raw.length);
            } else {
                outcomeStatus = String.format(Locale.US,
                        "PASS P2 lifecycle (no SPEECH — need RF TX): raw=%d",
                        raw.length);
            }
        } catch (Throwable error) {
            Log.e(TAG, "P2 RX PCM stream failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            outcomeSuccess = false;
            outcomeStatus = "FAIL";
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    if (bridgeMayBeActive && output != null
                            && mcuBaud == androidBaud) {
                        try {
                            hpiExitTrafficPlaneWhileBridged(output, report);
                        } catch (Throwable ignored) {
                            // continue
                        }
                        SystemClock.sleep(2500);
                    }
                    if (mcuBaud == BAUD_RATE_230400 && input != null
                            && output != null) {
                        try {
                            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                                    "emergency-restore-57600", report);
                            mcuBaud = BAUD_RATE;
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE, report);
                            androidBaud = BAUD_RATE;
                            input = serialPort.getInputStream();
                            output = outputStream;
                        } catch (Throwable ignored) {
                            // continue
                        }
                    }
                    if (input != null && output != null && mcuBaud == BAUD_RATE) {
                        try {
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                            writeMemoryByte(input, output,
                                    UART_HPI_BRIDGE_FLAG_ADDRESS, 0);
                        } catch (Throwable ignored) {
                            // continue
                        }
                    }
                } catch (Throwable restoreError) {
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                }
            }
            if (input != null && output != null && mcuBaud == BAUD_RATE) {
                if (shouldAttemptFinallyControlReload(controlPlaneReloadDone)) {
                    if (bestEffortControlPlaneReload(input, output, report)) {
                        controlPlaneReloadDone = true;
                        append(report, "controlPlaneReloadCount", 1);
                    }
                    append(report, "finallyReloadSkipped", false);
                    append(report, "finallyReloadBestEffort", true);
                } else {
                    append(report, "finallyReloadSkipped", true);
                    append(report, "controlPlaneReloadCount", 1);
                }
                try {
                    disableLogLevel(input, output, report);
                } catch (Throwable ignored) {
                    // ignore
                }
            }
            close();
            append(report, "serialClosed", true);
        }
        return finish(outcomeSuccess, report, outcomeStatus);
    }

    private static void writeWav8kMonoS16le(File file, byte[] pcm) throws Exception {
        int dataLen = pcm != null ? pcm.length : 0;
        int riffLen = 36 + dataLen;
        ByteArrayOutputStream out = new ByteArrayOutputStream(44 + dataLen);
        out.write(new byte[] {'R', 'I', 'F', 'F'});
        out.write(intLe(riffLen));
        out.write(new byte[] {'W', 'A', 'V', 'E', 'f', 'm', 't', ' '});
        out.write(intLe(16)); // fmt chunk size
        out.write(shortLe(1)); // PCM
        out.write(shortLe(1)); // mono
        out.write(intLe(8000));
        out.write(intLe(8000 * 2)); // byte rate
        out.write(shortLe(2)); // block align
        out.write(shortLe(16)); // bits
        out.write(new byte[] {'d', 'a', 't', 'a'});
        out.write(intLe(dataLen));
        if (dataLen > 0) {
            out.write(pcm);
        }
        writeFile(file, out.toByteArray());
    }

    private static byte[] intLe(int value) {
        return new byte[] {
                (byte) value, (byte) (value >>> 8),
                (byte) (value >>> 16), (byte) (value >>> 24)
        };
    }

    private static byte[] shortLe(int value) {
        return new byte[] {(byte) value, (byte) (value >>> 8)};
    }

    /**
     * No-RF scaffold (H13.md §18.27 next): after proven stack-safe 230400 text
     * face, switch MCU to 230400 while flag=0, arm v0.61 timeout handler, enter
     * raw bridge, send Voice OUT route {@code VOCODER_IO_SET=0x01}, capture
     * briefly, auto-exit bridge, restore 57600.
     * <p>
     * Does not request RF. Without air activity, PCM blocks may be zero; PASS
     * requires bridge recovery @230400 + text face restore @57600. Baud setter
     * is never called with bridge flag=1 (would force 115200).
     */
    ProbeResult runUartHpiBridge230400Smoke() {
        return runUartHpiBridge230400Smoke(true, null, false, null);
    }

    /**
     * v0.92 recovery-only gate. It changes no HPI route and requests no RF;
     * the only behavior under test is reversible line-rate/bridge recovery.
     */
    ProbeResult runRestoreRoundTrip() {
        return runUartHpiBridge230400Smoke(false, null, false, null);
    }

    /**
     * v0.93 no-RF positive control: inject immutable native 27-byte CHAN_D
     * units into the vendor-supported local decoder route and capture output.
     */
    ProbeResult runLocalChanDDecodeProof(byte[] chanD) {
        return runUartHpiBridge230400Smoke(false, chanD, false, null);
    }

