    ProbeResult runChannelConfigHpiEntry230400NoRfProof() {
        return runUartHpiBridge230400Smoke(false, null, false, null,
                0, 0, null, false, 3);
    }

    /**
     * Physical RF Carrier Enablement Test (low power, strictly timed duration <= 1.0s).
     * 1. AT+DMOSETANALOGCH=433.5500,433.5500,0,0,4,4,0,0,0,0
     * 2. Validate/Apply low power code (e.g. 2030 or custom 1000)
     * 3. Send AT+DMOPTT=1 at 57600 baud to trigger MCU analog TX entry (sct3258anaentertx/sct3258anacallstart)
     *    which locks RF synthesizer (LMX2571/BK4819) to 433.550 MHz & drives PA DAC bias voltage.
     * 4. Hold carrier for specified duration (e.g. 600 ms, max 1000 ms).
     * 5. Send AT+DMOPTT=0 to de-key.
     * 6. Trigger ANALOG_RF_OFF_WORDS (0x0801ff35) via SysTick stub to ensure hardware DAC/GPIO quiesce.
     * 7. Restore digital channel AT+DMOSETDIGITALCH.
     */
    ProbeResult runAnalogRfCarrierPulseTest(int powerCode, long durationMs) {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalRuntimePowerCode = null;
        boolean powerOverrideChanged = false;
        boolean pttArmed = false;
        boolean pttReleased = false;
        boolean analogRfOffConfirmed = false;

        long safeDurationMs = Math.min(Math.max(durationMs, 200L), 1000L);

        append(report, "Mode", "Physical Analog RF Carrier Pulse Test (57600 baud)");
        append(report, "Device", DEVICE_PATH);
        append(report, "Carrier Frequency", "433.550 MHz");
        append(report, "Target Transmit Duration ms", safeDurationMs);
        append(report, "Safety Limit", "Strictly <= 1.0s, Low Power");

        try {
            validateCustomAnalogPowerCode(powerCode, FACTORY_LOW_POWER_CODE);
        } catch (IllegalArgumentException error) {
            append(report, "Requested power code", powerCode);
            append(report, "Error", error.getMessage());
            return finish(false, report, "INVALID: explicit low power_code required");
        }

        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            openSerialLocked(device, BAUD_RATE, report);
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);

            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connect = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed at 57600");
            }

            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected version at 57600");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response", readBytes(input, SHORT_READ_TIMEOUT_MS));

            // Set 433.550 MHz Analog channel
            String analogSet = query(input, output, SET_EXPECTED_ANALOG_CHANNEL);
            append(report, "Analogue channel set", printable(analogSet));
            if (!analogSet.contains("+DMOSETANALOGCH:0")) {
                throw new IOException("Analogue channel set rejected");
            }

            // Verify / Apply low power code
            try {
                originalRuntimePowerCode = readMemory(input, output, RUNTIME_POWER_CODE_ADDRESS, 2);
                int liveCode = u16le(originalRuntimePowerCode, 0);
                append(report, "Runtime low-table code before", liveCode);
                if (powerCode != liveCode) {
                    powerOverrideChanged = true;
                    writeAndVerifyRuntimePowerCode(input, output, powerCodeBytesLe(powerCode));
                    append(report, "Temporary power code applied", powerCode);
                }
            } catch (Throwable powerCodeError) {
                append(report, "Power code memread warning", powerCodeError.getMessage());
            }

            // Execute DMOPTT=1 to trigger MCU analog TX entry & RF PLL lock
            append(report, "Phase", "AT+DMOPTT=1 Carrier Pulse Start");
            output.write("AT+DMOPTT=1\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String ptt1Resp = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "DMOPTT=1 response", printable(ptt1Resp));
            pttArmed = ptt1Resp.contains("+DMOPTT:0");

            if (!pttArmed) {
                throw new IOException("DMOPTT=1 rejected by MCU");
            }

            // Hold RF Carrier for timed duration
            SystemClock.sleep(safeDurationMs);

            // Execute DMOPTT=0 to de-key
            append(report, "Phase", "AT+DMOPTT=0 Carrier Pulse Stop");
            output.write("AT+DMOPTT=0\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String ptt0Resp = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "DMOPTT=0 response", printable(ptt0Resp));
            pttReleased = ptt0Resp.contains("+DMOPTT:0");

            // Hardware quiesce via ANALOG_RF_OFF_WORDS
            byte[] rfOffCode = wordsToBytes(ANALOG_RF_OFF_WORDS);
            assertStackSafeBaudStub(rfOffCode, "analogue-rf-off");
            armBaudOneShot(input, output, ANALOG_RF_OFF_WORDS, "analogue-rf-off", report);
            verifyBaudOneShot(input, output, ANALOG_RF_OFF_MARKER, "analogue-rf-off", report);
            analogRfOffConfirmed = true;

            // Restore power code if changed
            if (powerOverrideChanged) {
                writeAndVerifyRuntimePowerCode(input, output, originalRuntimePowerCode);
                powerOverrideChanged = false;
                append(report, "Original power code restored", u16le(originalRuntimePowerCode, 0));
            }

            // Restore production digital channel
            String digitalRestore = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "Digital channel restore", printable(digitalRestore));

            boolean success = pttArmed && pttReleased && analogRfOffConfirmed;
            return finish(success, report, success
                    ? "PASS: Physical Analog RF Carrier pulse transmitted for " + safeDurationMs + " ms"
                    : "FAIL: Carrier pulse sequence incomplete");
        } catch (Throwable error) {
            Log.e(TAG, "RF carrier pulse test failed", error);
            append(report, "Error", error.getClass().getSimpleName() + ": " + error.getMessage());
            return finish(false, report, "FAIL");
        } finally {
            if (pttArmed && !pttReleased && input != null && output != null) {
                try {
                    output.write("AT+DMOPTT=0\r\n".getBytes(StandardCharsets.US_ASCII));
                    output.flush();
                } catch (Throwable ignored) {}
            }
            if (powerOverrideChanged && input != null && output != null && originalRuntimePowerCode != null) {
                try {
                    writeAndVerifyRuntimePowerCode(input, output, originalRuntimePowerCode);
                } catch (Throwable ignored) {}
            }
            close();
        }
    }

    private ProbeResult runUartHpiBridge230400Smoke(boolean sendVoiceOutRoute,
            byte[] localChanD, boolean analogOneBlock,
            Integer analogPowerOverride) {
        return runUartHpiBridge230400Smoke(sendVoiceOutRoute, localChanD,
                analogOneBlock, analogPowerOverride, analogOneBlock ? 1 : 0, 0, null);
    }

    private ProbeResult runUartHpiBridge230400Smoke(boolean sendVoiceOutRoute,
            byte[] localChanD, boolean analogOneBlock,
            Integer analogPowerOverride, int analogBlockCount,
            long analogBlockGapMs) {
        return runUartHpiBridge230400Smoke(sendVoiceOutRoute, localChanD,
                analogOneBlock, analogPowerOverride, analogBlockCount,
                analogBlockGapMs, null);
    }

    private ProbeResult runUartHpiBridge230400Smoke(boolean sendVoiceOutRoute,
            byte[] localChanD, boolean analogOneBlock,
            Integer analogPowerOverride, int analogBlockCount,
            long analogBlockGapMs, byte[] customPcm) {
        return runUartHpiBridge230400Smoke(sendVoiceOutRoute, localChanD,
                analogOneBlock, analogPowerOverride, analogBlockCount,
                analogBlockGapMs, customPcm, false);
    }

    private ProbeResult runUartHpiBridge230400Smoke(boolean sendVoiceOutRoute,
            byte[] localChanD, boolean analogOneBlock,
            Integer analogPowerOverride, int analogBlockCount,
            long analogBlockGapMs, byte[] customPcm, boolean dmrVoiceInMode) {
        return runUartHpiBridge230400Smoke(sendVoiceOutRoute, localChanD,
                analogOneBlock, analogPowerOverride, analogBlockCount,
                analogBlockGapMs, customPcm, dmrVoiceInMode, 0);
    }

    private ProbeResult runUartHpiBridge230400Smoke(boolean sendVoiceOutRoute,
            byte[] localChanD, boolean analogOneBlock,
            Integer analogPowerOverride, int analogBlockCount,
            long analogBlockGapMs, byte[] customPcm, boolean dmrVoiceInMode,
            int noRfEncoderKind) {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalBaudCode = null;
        byte[] originalBaudMarker = null;
        byte[] originalTimeoutCode = null;
        byte[] originalTimeoutCounter = null;
        byte[] originalTimeoutMarker = null;
        byte[] originalVector = null;
        byte[] originalFlag = null;
        byte[] originalRuntimePowerCode = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        boolean powerOverrideChanged = false;
        boolean bridgeMayBeActive = false;
        boolean analogRfPrepared = false;
        boolean analogCreditObserved = false;
        boolean analogStopSent = false;
        boolean analogRfOffConfirmed = false;
        boolean encoderControlAccepted = false;
        boolean channelConfigApplied = false;
        boolean channelConfigReadbackVerified = false;
        boolean hpiEntryControlAccepted = false;
        int analogCodecGain = -1;
        int mcuBaud = BAUD_RATE;
        int androidBaud = BAUD_RATE;
        boolean needsRebootHint = false;
        long analogBridgeTargetMs = analogBlockCount > 5
                ? Math.max(12000L, analogBlockCount * 120L + 5000L)
                : analogBlockCount > 1
                ? ANALOG_FIVE_BLOCK_BRIDGE_TARGET_MS
                : ANALOG_ONE_BLOCK_BRIDGE_TARGET_MS;

        boolean localDecode = localChanD != null;
        boolean noRfEncoder = noRfEncoderKind == 1 || noRfEncoderKind == 2;
        boolean channelConfigHpiEntry = noRfEncoderKind == 3;
        append(report, "Mode", noRfEncoder
                ? (noRfEncoderKind == 1
                ? "no-RF zero PCM to CHAN_D causality baseline @230400"
                : "no-RF tone PCM to CHAN_D causality comparison @230400")
                : channelConfigHpiEntry
                ? "no-RF CH1 configuration then one HPI control gate @230400"
                : analogOneBlock
                ? (analogBlockCount == 1
                ? "FM VoiceIn one 80 ms block @230400"
                : "FM VoiceIn five 80 ms blocks, 300 ms gaps @230400")
                : localDecode
                ? "local CHAN_D decoder positive control (no RF)"
                : sendVoiceOutRoute
                ? "UART-HPI bridge @230400 smoke + Voice OUT route (no RF)"
                : "restore-only 57600 -> 230400 -> bridge -> 57600 (no RF/HPI route)");
        append(report, "Device", DEVICE_PATH);
        append(report, "Prerequisite",
                "§18.26 Step A PASS; §18.27 Step B+C PASS (stack-safe 230400)");
        append(report, "RF transmit", noRfEncoder || channelConfigHpiEntry
                ? "not requested; no PTT/call-start/RF helper/GPIO write"
                : analogOneBlock
                ? "authorized low setting; bounded VoiceIn payload"
                : "not requested");
        if (analogPowerOverride != null) {
            append(report, "Requested temporary power code",
                    analogPowerOverride);
            append(report, "Power-code policy",
                    "explicit 0..factory-low; restore original after RF-off");
        }
        append(report, "Baud policy",
                "0x08010A00(230400) only while flag=0; never after bridge arm");
        append(report, "Timeout handler",
                "v0.61 command-tail 0x20001600 SHA 5c531f29...");
        if (localDecode) {
            append(report, "Local route/state",
                    "VOCODER_IO=0x09 -> PROCESS_MODE(3) -> WORK_MODE(3,3,0)");
            append(report, "CHAN_D source SHA-256", sha256ForLog(localChanD));
            append(report, "CHAN_D source bytes", localChanD.length);
            if (localChanD.length % LOCAL_CHAN_D_UNIT_BYTES != 0
                    || localChanD.length < LOCAL_CHAN_D_PROOF_UNITS
                    * LOCAL_CHAN_D_UNIT_BYTES) {
                return finish(false, report,
                        "Invalid frozen CHAN_D asset length");
            }
        }
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] setCode = wordsToBytes(BAUD_SET_230400_WORDS);
            byte[] restoreCode = wordsToBytes(BAUD_RESTORE_57600_WORDS);
            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            append(report, "Set-230400 stub SHA-256", sha256(setCode));
            append(report, "Restore-57600 stub SHA-256", sha256(restoreCode));
            append(report, "Timeout handler SHA-256", sha256(handler));
            if (!BAUD_SET_230400_SHA256.equals(sha256(setCode))
                    || !BAUD_RESTORE_57600_SHA256.equals(sha256(restoreCode))) {
                throw new IOException("Baud stub hash mismatch");
            }
            if (!"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(sha256(handler))) {
                throw new IOException("Timeout handler hash mismatch");
            }
            assertStackSafeBaudStub(setCode, "set-230400");
            assertStackSafeBaudStub(restoreCode, "restore-57600");
            if (analogOneBlock) {
                byte[] rfPrepCode = wordsToBytes(ANALOG_RF_PREP_WORDS);
                byte[] rfOffCode = wordsToBytes(ANALOG_RF_OFF_WORDS);
                append(report, "RF prepare stub SHA-256", sha256(rfPrepCode));
                append(report, "RF off stub SHA-256", sha256(rfOffCode));
                if (!ANALOG_RF_PREP_SHA256.equals(sha256(rfPrepCode))
                        || !ANALOG_RF_OFF_SHA256.equals(sha256(rfOffCode))) {
                    throw new IOException("Analogue RF helper stub hash mismatch");
                }
                assertStackSafeBaudStub(rfPrepCode, "analogue-rf-prepare");
                assertStackSafeBaudStub(rfOffCode, "analogue-rf-off");
            }

            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            mcuBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connect = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed at 57600");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected version at 57600");
            }

            if (channelConfigHpiEntry) {
                String setChannel = query(input, output,
                        SET_EXPECTED_DIGITAL_CHANNEL);
                append(report, "Pre-bridge CH1 configuration", printable(setChannel));
                channelConfigApplied = setChannel.contains(
                        "+DMOSETDIGITALCH:0");
                if (!channelConfigApplied) {
                    throw new IOException("CH1 configuration rejected before bridge");
                }
                String channelReadback = query(input, output,
                        "AT+DMOGETDIGITALCH");
                append(report, "Pre-bridge CH1 readback",
                        printable(channelReadback));
                channelConfigReadbackVerified = channelReadback.contains(
                        "+DMOGETDIGITALCH:") && channelReadback.contains(
                        EXPECTED_DIGITAL_CHANNEL);
                if (!channelConfigReadbackVerified) {
                    throw new IOException("CH1 readback mismatch before bridge");
                }
            }

            if (noRfEncoder) {
                drainAvailable(input);
                writeCommand(output, SCT_RELOAD_BASELINE_COMMAND);
                byte[] normalizedInitial = readUntilContains(
                        input, "+DMOSTARTUP:0", UART_WAKE_INITIAL_WAIT_MS);
                boolean normalizationWakeKick = shouldWakeKickMode0(
                        normalizedInitial);
                if (normalizationWakeKick) {
                    output.write('\n');
                    output.flush();
                }
                byte[] normalizedRemaining = containsAscii(normalizedInitial,
                        "+DMOSTARTUP:0") ? new byte[0] : readUntilContains(
                        input, "+DMOSTARTUP:0", 25000);
                byte[] normalizedStartup = concatBytes(normalizedInitial,
                        normalizedRemaining);
                append(report, "Pre-230400 mode0 wake kick",
                        normalizationWakeKick);
                appendRaw(report, "Pre-230400 mode0 normalization",
                        normalizedStartup);
                SystemClock.sleep(100);
                drainAvailable(input);

                String normalizedConnect = "";
                for (int attempt = 1; attempt <= 6; attempt++) {
                    output.write("AT+DMOCONNECT\r\n"
                            .getBytes(StandardCharsets.US_ASCII));
                    output.flush();
                    normalizedConnect = readResponse(input,
                            RESPONSE_TIMEOUT_MS);
                    append(report, "Pre-230400 CONNECT attempt " + attempt,
                            printable(normalizedConnect));
                    if (normalizedConnect.contains("+DMOCONNECT:0")) {
                        break;
                    }
                    SystemClock.sleep(400);
                    drainAvailable(input);
                }
                String normalizedVersion = query(input, output,
                        "AT+DMOGETSOFTVERSION");
                append(report, "Pre-230400 normalized version",
                        printable(normalizedVersion));
                if (!noRfEncoderPreBridgeReady(normalizedStartup,
                        normalizedConnect, normalizedVersion)) {
                    throw new IOException(
                            "Pre-230400 mode0 normalization failed");
                }
            }

            drainAvailable(input);
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            originalFlag = readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            originalBaudCode = readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                    BAUD_SET_230400_WORDS.length * 4);
            originalBaudMarker = readMemory(input, output,
                    BAUD_ONESHOT_MARKER_ADDRESS, 4);
            originalTimeoutCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            originalTimeoutCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            originalTimeoutMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            append(report, "Bridge flag before", originalFlag[0] & 0xff);
            append(report, "SysTick before", String.format(Locale.US, "0x%08x",
                    u32le(originalVector, 0)));
            if ((originalFlag[0] & 0xff) != 0) {
                throw new IOException("Raw bridge already active");
            }
            if (u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected SysTick vector");
            }

            // Measure tick @57600 before baud change (text memread proven).
            byte[] tickFirstBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(input, output,
                    MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickDelta = (u32le(tickSecondBytes, 0) - u32le(tickFirstBytes, 0))
                    & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            append(report, "Measured tick Hz", String.format(Locale.US, "%.2f",
                    tickRateHz));
            if (tickRateHz < 10.0 || tickRateHz > 100000.0) {
                throw new IOException("Implausible MCU tick rate");
            }
            long bridgeTargetMs = analogOneBlock
                    ? analogBridgeTargetMs
                    : localDecode
                    ? LOCAL_CHAN_D_BRIDGE_TARGET_MS : UART_HPI_TIMEOUT_TARGET_MS;
            int timeoutTicks = (int) Math.round(
                    tickRateHz * bridgeTargetMs / 1000.0);
            append(report, "Bridge target ms", bridgeTargetMs);
            append(report, "Bridge timeout ticks", timeoutTicks);

            // Upload timeout handler while still @57600 (more reliable print/mem).
            for (int offset = 0; offset < handler.length; offset += 4) {
                writeMemoryWord(input, output,
                        UART_HPI_TIMEOUT_CODE_ADDRESS + offset,
                        u32le(handler, offset));
            }
            stateChanged = true;
            if (!Arrays.equals(handler, readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length))) {
                throw new IOException("Timeout handler upload mismatch");
            }

            if (analogOneBlock) {
                String chanCmd = dmrVoiceInMode ? SET_EXPECTED_DIGITAL_CHANNEL : SET_EXPECTED_ANALOG_CHANNEL;
                String chanTag = dmrVoiceInMode ? "+DMOSETDIGITALCH:0" : "+DMOSETANALOGCH:0";
                String analogSet = query(input, output, chanCmd);
                append(report, dmrVoiceInMode ? "DMR digital channel set" : "Analogue channel set", printable(analogSet));
                if (!analogSet.contains(chanTag)) {
                    throw new IOException(dmrVoiceInMode ? "DMR channel rejected" : "Analogue low channel rejected");
                }
                originalRuntimePowerCode = readMemory(input, output,
                        RUNTIME_POWER_CODE_ADDRESS, 2);
                int liveCode = u16le(originalRuntimePowerCode, 0);
                append(report, "Runtime low-table code", liveCode);
                if (liveCode != FACTORY_LOW_POWER_CODE) {
                    throw new IOException("Runtime power code changed from approved 2030");
                }
                if (analogPowerOverride != null) {
                    validateCustomAnalogPowerCode(analogPowerOverride, liveCode);
                    powerOverrideChanged = true;
                    writeAndVerifyRuntimePowerCode(input, output,
                            powerCodeBytesLe(analogPowerOverride));
                    append(report, "Temporary power code applied",
                            analogPowerOverride);
                }
                int activeProfile = readMemory(input, output,
                        ACTIVE_PROFILE_INDEX_ADDRESS, 1)[0] & 0xff;
                if (activeProfile > MAX_PROFILE_INDEX) {
                    throw new IOException("Active profile index outside validated range");
                }
                int profileAddress = PROFILE_TABLE_ADDRESS
                        + activeProfile * PROFILE_RECORD_BYTES;
                int micPreset = readMemory(input, output, profileAddress
                        + PROFILE_ANALOG_MIC_PRESET_OFFSET, 1)[0] & 0xff;
                byte[] gainTable = readMemory(input, output,
                        ANALOG_CODEC_GAIN_TABLE_ADDRESS,
                        ANALOG_CODEC_GAIN_PRESETS);
                analogCodecGain = selectAnalogCodecGain(activeProfile,
                        micPreset, gainTable);
                append(report, "Active analogue profile", activeProfile);
                append(report, "Analogue mic preset", micPreset);
                append(report, "Runtime TX codec gain", analogCodecGain);

                append(report, "Phase", "AT+DMOPTT=1 Carrier Keying Before Bridge");
                try {
                    Runtime.getRuntime().exec(new String[]{"su", "-c", "echo 1 > /sys/boptt/audio_switch; echo 1 > /sys/boptt/pa_enable"});
                    append(report, "Sysfs audio_switch & pa_enable", "enabled (=1)");
                } catch (Throwable sysfsErr) {
                    append(report, "Sysfs audio_switch warning", sysfsErr.getMessage());
                }
                output.write("AT+DMOPTT=1\r\n".getBytes(StandardCharsets.US_ASCII));
                output.flush();
                String ptt1Resp = readResponse(input, RESPONSE_TIMEOUT_MS);
                append(report, "DMOPTT=1 response", printable(ptt1Resp));
                if (!ptt1Resp.contains("+DMOPTT:0")) {
                    throw new IOException("DMOPTT=1 rejected by MCU before bridge");
                }
            }

            // flag=0: switch MCU to 230400, then Android reopen (Step B proven).
            append(report, "Phase", "stack-safe set-230400 before bridge");
            armBaudOneShot(input, output, BAUD_SET_230400_WORDS, "set-230400",
                    report);
            mcuBaud = BAUD_RATE_230400;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE_230400, report);
            androidBaud = BAUD_RATE_230400;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_230400,
                    "set-230400", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectHigh = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @230400 before bridge",
                    printable(connectHigh));
            if (!connectHigh.contains("+DMOCONNECT:0")) {
                throw new IOException("CONNECT failed at 230400 before bridge");
            }

            if (analogOneBlock) {
                append(report, "Independent PA-off watchdog",
                        "omitted by explicit operator direction");
                armBaudOneShot(input, output, ANALOG_RF_PREP_WORDS,
                        "analogue-rf-prepare-no-call-start", report);
                verifyBaudOneShot(input, output, ANALOG_RF_PREP_MARKER,
                        "analogue-rf-prepare-no-call-start", report);
                analogRfPrepared = true;
            }

            // Arm timeout + enter bridge. Do NOT call 0x08010A00 after this.
            writeMemoryWord(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 0);
            writeMemoryWord(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    timeoutTicks);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    UART_HPI_TIMEOUT_ENTRY);
            if (u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    != UART_HPI_TIMEOUT_ENTRY) {
                throw new IOException("Unable to arm bridge timeout vector");
            }
            synchronized (lock) {
                logLevelMayBeEnabled = false;
            }
            long bridgeArmedAt = SystemClock.elapsedRealtime();
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            bridgeMayBeActive = true;
            append(report, "Bridge armed @230400", true);
            long noRfEncoderSettleMs = noRfEncoderBridgeSettleMs(
                    noRfEncoderKind);
            if (noRfEncoderSettleMs > 0) {
                SystemClock.sleep(noRfEncoderSettleMs);
                append(report, "No-RF encoder bridge settle before first control ms",
                        noRfEncoderSettleMs);
            } else if (analogOneBlock && analogBlockCount > 1) {
                SystemClock.sleep(ANALOG_MULTI_BLOCK_BRIDGE_SETTLE_MS);
                append(report, "Bridge settle before first codec ms",
                        ANALOG_MULTI_BLOCK_BRIDGE_SETTLE_MS);
            }

            byte[] raw;
            LocalChanDInjection localInjection = null;
            if (noRfEncoder) {
                ByteArrayOutputStream controlRaw = new ByteArrayOutputStream();
                byte[][] controls = new byte[][] {
                        HPI_VOCODER_IO_OFF,
                        HPI_VOCODER_IO_PCM_TO_AMBE_HPI,
                        HPI_PROCESS_MODE_3,
                        HPI_WORK_MODE_VOCODER_LOOPBACK_FULL_DUPLEX
                };
                String[] names = new String[] {
                        "VOCODER_IO_OFF", "VOCODER_IO=0x90",
                        "PROCESS_MODE(3)", "WORK_MODE(3,3,0)"
                };
                encoderControlAccepted = true;
                for (int controlIndex = 0;
                        controlIndex < controls.length; controlIndex++) {
                    byte[] request = controls[controlIndex];
                    drainAvailable(input);
                    output.write(request);
                    output.flush();
                    byte[] response = readForDuration(input,
                            ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    preserveRawEvidence(report,
                            names[controlIndex] + " response @230400",
                            "h13_pcm_to_chan_d_230400_control_"
                                    + controlIndex + "_", response);
                    boolean ack = containsAnalogControlAck(response, request);
                    boolean fieldError = containsExactHpiFrameAtBoundaries(
                            response, HPI_ERROR_PROCESSING_FIELD);
                    append(report, names[controlIndex] + " ACK", ack);
                    append(report, names[controlIndex]
                            + " field error (17 06)", fieldError);
                    controlRaw.write(response);
                    if (!ack || fieldError) {
                        encoderControlAccepted = false;
                        throw new IOException(names[controlIndex]
                                + " failed exact ACK gate");
                    }
                }

                final int blockCount = 10;
                byte[] pcmBlock = noRfEncoderKind == 1
                        ? new byte[ANALOG_VOICE_IN_BLOCK_BYTES]
                        : createTonePcm8kS16le(800, 4000, 640);
                byte[] wireFrame = createAnalogVoiceInPcmFrame(pcmBlock, 0);
                preserveRawEvidence(report,
                        noRfEncoderKind == 1
                                ? "Zero PCM outbound frame @230400"
                                : "Tone PCM outbound frame @230400",
                        noRfEncoderKind == 1
                                ? "h13_pcm_to_chan_d_230400_zero_outbound_"
                                : "h13_pcm_to_chan_d_230400_tone_outbound_",
                        wireFrame);
                drainAvailable(input);
                ByteArrayOutputStream dataRaw = new ByteArrayOutputStream();
                long firstWriteUs = -1;
                for (int blockIndex = 0; blockIndex < blockCount; blockIndex++) {
                    long blockStartedAt = SystemClock.elapsedRealtime();
                    long writeStartedAt = SystemClock.elapsedRealtimeNanos();
                    output.write(wireFrame);
                    output.flush();
                    long writeUs = (SystemClock.elapsedRealtimeNanos()
                            - writeStartedAt) / 1000L;
                    if (blockIndex == 0) {
                        firstWriteUs = writeUs;
                    }
                    long remainingMs = blockStartedAt
                            + ANALOG_VOICE_IN_BLOCK_DURATION_MS
                            - SystemClock.elapsedRealtime();
                    dataRaw.write(readForDuration(input,
                            Math.max(1L, remainingMs)));
                }
                dataRaw.write(readForDuration(input, 300));
                byte[] encodedRaw = dataRaw.toByteArray();
                HpiCaptureSummary encoderSummary = summarizeHpiCapture(encodedRaw);
                append(report, "Encoder input kind",
                        noRfEncoderKind == 1 ? "zero" : "800 Hz amplitude 4000");
                append(report, "Encoder PCM blocks sent", blockCount);
                append(report, "Encoder PCM wire bytes",
                        blockCount * wireFrame.length);
                append(report, "First PCM frame write duration us", firstWriteUs);
                append(report, "Post-input CHAN_D27 units",
                        encoderSummary.chanD27);
                append(report, "Post-input HPI summary",
                        encoderSummary.toString());
                preserveRawEvidence(report, "Post-input encoder raw @230400",
                        noRfEncoderKind == 1
                                ? "h13_pcm_to_chan_d_230400_zero_response_"
                                : "h13_pcm_to_chan_d_230400_tone_response_",
                        encodedRaw);
                raw = concatBytes(controlRaw.toByteArray(), encodedRaw);
                output.write(HPI_VOCODER_IO_OFF);
                output.write(HPI_WORK_MODE_IDLE);
                output.flush();
                raw = concatBytes(raw,
                        readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));
            } else if (channelConfigHpiEntry) {
                drainAvailable(input);
                output.write(HPI_VOCODER_IO_OFF);
                output.flush();
                byte[] response = readForDuration(input,
                        ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                preserveRawEvidence(report,
                        "CH1-configured VOCODER_IO_OFF response @230400",
                        "h13_ch1_config_hpi_entry_230400_control_", response);
                hpiEntryControlAccepted = containsAnalogControlAck(response,
                        HPI_VOCODER_IO_OFF)
                        && !containsExactHpiFrameAtBoundaries(response,
                        HPI_ERROR_PROCESSING_FIELD);
                append(report, "CH1-configured VOCODER_IO_OFF ACK",
                        hpiEntryControlAccepted);
                if (!hpiEntryControlAccepted) {
                    throw new IOException(
                            "CH1-configured VOCODER_IO_OFF failed exact ACK gate");
                }
                raw = response;
            } else if (analogOneBlock) {
                AnalogVoiceInTxModel voiceIn = null;
                ByteArrayOutputStream controlRaw = new ByteArrayOutputStream();
                if (dmrVoiceInMode) {
                    // 1. WORK_MODE IDLE (clear MCU stock call state)
                    byte[] idleFrame = createAnalogWorkModeIdleFrame();
                    output.write(idleFrame);
                    output.flush();
                    byte[] idleAck = readForDuration(input, ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    append(report, "DMR WORK_MODE_IDLE ACK", containsAnalogControlAck(idleAck, idleFrame));
                    SystemClock.sleep(20);

                    // 2. VOCODER_IO_SET=0x80 (Voice IN = HPI)
                    byte[] routeFrame = createAnalogVoiceInRouteFrame();
                    output.write(routeFrame);
                    output.flush();
                    byte[] routeAck = readForDuration(input, ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    boolean routeAcked = containsAnalogControlAck(routeAck, routeFrame);
                    append(report, "DMR VOCODER_IO=0x80 ACK", routeAcked);
                    if (!routeAcked) {
                        throw new IOException("SCT3258 rejected VOCODER_IO=0x80 for DMR VoiceIn");
                    }
                    SystemClock.sleep(20);

                    // 3. PROCESS_MODE(2) (DMR Mode)
                    byte[] processFrame = createHpiFrame(0, new byte[] {0x1a, 0x02});
                    output.write(processFrame);
                    output.flush();
                    byte[] processAck = readForDuration(input, ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    append(report, "DMR PROCESS_MODE(2) ACK", containsAnalogControlAck(processAck, processFrame));
                    SystemClock.sleep(20);

                    // 4. WORK_MODE(2) (TX Mode)
                    byte[] workFrame = createAnalogVoiceInWorkModeFrame();
                    output.write(workFrame);
                    output.flush();
                    byte[] workAck = readForDuration(input, ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    boolean workAcked = containsAnalogControlAck(workAck, workFrame);
                    append(report, "DMR WORK_MODE(2) ACK", workAcked);
                    if (!workAcked) {
                        throw new IOException("SCT3258 rejected WORK_MODE(2) for DMR VoiceIn");
                    }
                    SystemClock.sleep(20);

                    // 5. CALL_START (0x78) with VOCODER_IO=0x80 active!
                    byte[] startFrame = createAnalogCallStartFrame();
                    output.write(startFrame);
                    output.flush();
                    byte[] startAck = readForDuration(input, ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    boolean startAcked = containsAnalogControlAck(startAck, startFrame);
                    append(report, "DMR CALL_START(0x78) ACK", startAcked);
                    if (!startAcked) {
                        throw new IOException("SCT3258 rejected CALL_START for DMR VoiceIn");
                    }
                    SystemClock.sleep(20);
                } else {
                    voiceIn = new AnalogVoiceInTxModel(
                            0, 0, 0, 0, analogCodecGain);
                    while (voiceIn.phase()
                            != AnalogVoiceInTxModel.Phase.FIRST_BLOCK_READY) {
                        controlRaw.write(sendAndRequireAnalogControlAck(input, output,
                                voiceIn, analogBlockCount > 1, report));
                    }
                }

                byte[] tone = customPcm != null
                        ? customPcm
                        : createTonePcm8kS16le(ANALOG_TEST_TONE_HZ,
                                ANALOG_TEST_TONE_AMPLITUDE, 640 * analogBlockCount);
                ByteArrayOutputStream dataRaw = new ByteArrayOutputStream();
                int creditedBlocks = 0;
                int totalWireBytes = 0;
                for (int blockIndex = 0; blockIndex < analogBlockCount;
                        blockIndex++) {
                    long blockStartedAt = SystemClock.elapsedRealtime();
                    byte[] voiceInFrame = dmrVoiceInMode
                            ? createAnalogVoiceInPcmFrame(tone, blockIndex)
                            : voiceIn.serializeNextBlock(tone, blockIndex);
                    output.write(voiceInFrame);
                    output.flush();
                    totalWireBytes += voiceInFrame.length;
                    append(report, "VoiceIn block " + (blockIndex + 1)
                            + " wire bytes", voiceInFrame.length);
                    byte[] blockRaw = readForDuration(input,
                            ANALOG_POST_BLOCK_CREDIT_WINDOW_MS);
                    dataRaw.write(blockRaw);
                    boolean blockCredited = dmrVoiceInMode
                            ? containsAnalogVoiceInCredit(blockRaw)
                            : voiceIn.acceptDataCredit(blockRaw);
                    append(report, "VoiceIn block " + (blockIndex + 1)
                            + " credit", blockCredited);
                    if (!blockCredited) {
                        break;
                    }
                    creditedBlocks++;
                    if (blockIndex + 1 < analogBlockCount) {
                        long nextBlockAt = blockStartedAt
                                + ANALOG_VOICE_IN_BLOCK_DURATION_MS
                                + analogBlockGapMs;
                        long scheduleWaitMs = nextBlockAt
                                - SystemClock.elapsedRealtime();
                        if (scheduleWaitMs > 0) {
                            SystemClock.sleep(scheduleWaitMs);
                        }
                    }
                }
                analogCreditObserved = creditedBlocks == analogBlockCount;
                append(report, "VoiceIn wire bytes", totalWireBytes);
                append(report, "VoiceIn PCM bytes",
                        creditedBlocks * ANALOG_VOICE_IN_BLOCK_BYTES);
                append(report, "VoiceIn serialized blocks",
                        dmrVoiceInMode ? creditedBlocks : voiceIn.serializedBlocks());
                append(report, "VoiceIn credited blocks", creditedBlocks);
                append(report, "VoiceIn inter-block silence target ms",
                        analogBlockGapMs);
                append(report, "VoiceIn block-start interval target ms",
                        ANALOG_VOICE_IN_BLOCK_DURATION_MS + analogBlockGapMs);

                if (!dmrVoiceInMode && voiceIn != null) {
                    if (!voiceIn.requestStop()) {
                        throw new IOException("VoiceIn state refused stop");
                    }
                    controlRaw.write(sendAndRequireAnalogControlAck(input, output,
                            voiceIn, analogBlockCount > 1, report));
                    analogStopSent = true;
                    controlRaw.write(sendAndRequireAnalogControlAck(input, output,
                            voiceIn, analogBlockCount > 1, report));
                }
                raw = concatBytes(controlRaw.toByteArray(),
                        dataRaw.toByteArray());
            } else if (localDecode) {
                output.write(HPI_VOCODER_IO_OFF);
                output.flush();
                SystemClock.sleep(20);
                output.write(HPI_VOCODER_IO_LOCAL_CHAN_D_TO_VOICE_OUT);
                output.flush();
                SystemClock.sleep(20);
                output.write(HPI_PROCESS_MODE_3);
                output.flush();
                SystemClock.sleep(20);
                output.write(HPI_WORK_MODE_VOCODER_LOOPBACK_FULL_DUPLEX);
                output.flush();
                byte[] controlRaw = readForDuration(input,
                        PCM_CONTROL_ACK_CAPTURE_MS);
                boolean routeAck = containsBytes(controlRaw,
                        createHpiFrame(0, new byte[] {0x3e, 0x00}));
                boolean processAck = containsBytes(controlRaw,
                        HPI_PROCESS_MODE_ACK);
                boolean workAck = containsBytes(controlRaw, HPI_WORK_MODE_ACK);
                boolean fieldError = containsBytes(controlRaw,
                        HPI_ERROR_PROCESSING_FIELD);
                append(report, "VOCODER_IO=0x09 ACK", routeAck);
                append(report, "PROCESS_MODE(3) ACK", processAck);
                append(report, "WORK_MODE(3,3,0) ACK", workAck);
                append(report, "Control field error", fieldError);
                if (!routeAck || !processAck || !workAck || fieldError) {
                    throw new IOException("Local decoder control chain rejected");
                }
                localInjection = injectLocalChanD(input, output, localChanD,
                        LOCAL_CHAN_D_PROOF_UNITS);
                raw = concatBytes(controlRaw, localInjection.raw);
                output.write(HPI_VOCODER_IO_OFF);
                output.write(HPI_WORK_MODE_IDLE);
                output.flush();
                raw = concatBytes(raw,
                        readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));
            } else if (sendVoiceOutRoute) {
                output.write(HPI_VOCODER_IO_OFF);
                output.flush();
                SystemClock.sleep(20);
                output.write(HPI_VOCODER_IO_VOICE_OUT_HPI);
                output.flush();
                raw = readForDuration(input, DATA_PLANE_CAPTURE_MS);
                output.write(HPI_VOCODER_IO_OFF);
                output.flush();
                raw = concatBytes(raw,
                        readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));
            } else {
                raw = readForDuration(input, DATA_PLANE_CAPTURE_MS);
                raw = concatBytes(raw,
                        readForDuration(input, DATA_PLANE_CLEANUP_CAPTURE_MS));
            }

            long safeReadAt = bridgeArmedAt + bridgeTargetMs
                    + UART_HPI_TIMEOUT_MARGIN_MS;
            long remaining = safeReadAt - SystemClock.elapsedRealtime();
            if (remaining > 0) {
                SystemClock.sleep(remaining);
            }

            // Recovery memread still at 230400 (MCU baud unchanged by bridge exit).
            byte[] flagAfter = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] vectorAfter = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            byte[] counterAfter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            byte[] markerAfter = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            append(report, "Bridge flag after", flagAfter[0] & 0xff);
            append(report, "SysTick after bridge", String.format(Locale.US,
                    "0x%08x", u32le(vectorAfter, 0)));
            append(report, "Timeout counter after", u32le(counterAfter, 0));
            append(report, "Timeout marker after", String.format(Locale.US,
                    "0x%08x", u32le(markerAfter, 0)));
            if ((flagAfter[0] & 0xff) != 0
                    || u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER
                    || u32le(counterAfter, 0) != 0
                    || u32le(markerAfter, 0) != UART_HPI_TIMEOUT_MARKER) {
                throw new IOException(
                        "Bridge recovery mismatch at 230400 after Voice OUT smoke");
            }
            bridgeMayBeActive = false;
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }

            if (analogOneBlock) {
                armBaudOneShot(input, output, ANALOG_RF_OFF_WORDS,
                        "analogue-rf-off", report);
                verifyBaudOneShot(input, output, ANALOG_RF_OFF_MARKER,
                        "analogue-rf-off", report);
                analogRfPrepared = false;
                analogRfOffConfirmed = true;
                if (powerOverrideChanged) {
                    writeAndVerifyRuntimePowerCode(input, output,
                            originalRuntimePowerCode);
                    powerOverrideChanged = false;
                    append(report, "Original power code restored",
                            u16le(originalRuntimePowerCode, 0));
                }
            }

            File captureFile = new File(outputDirectory, String.format(Locale.US,
                    noRfEncoder
                            ? (noRfEncoderKind == 1
                            ? "hpi_pcm_to_chan_d_230400_zero_%d.bin"
                            : "hpi_pcm_to_chan_d_230400_tone_%d.bin")
                    : channelConfigHpiEntry
                            ? "hpi_ch1_config_hpi_entry_230400_%d.bin"
                    : analogOneBlock ? (analogBlockCount == 1
                            ? "hpi_fm_voice_in_one_block_%d.bin"
                            : "hpi_fm_voice_in_five_blocks_%d.bin")
                            : localDecode ? "hpi_local_chan_d_decode_%d.bin"
                            : "hpi_voice_out_bridge_230400_%d.bin",
                    System.currentTimeMillis()));
            writeFile(captureFile, raw);
            HpiCaptureSummary summary = summarizeHpiCapture(raw);
            append(report, "Capture raw bytes", raw.length);
            append(report, "Capture SHA-256", sha256(raw));
            append(report, "Capture file", captureFile.getAbsolutePath());
            append(report, "HPI summary", summary.toString());
            append(report, "pcm160 blocks", summary.pcm160);
            append(report, "chanD27 blocks", summary.chanD27);
            append(report, "dmrSlotFound", summary.dmrSlotFound);
            if (noRfEncoder) {
                append(report, "Encoder control chain accepted",
                        encoderControlAccepted);
                append(report, "Encoder CHAN_D27 units", summary.chanD27);
                append(report, "Causality claim",
                        "requires zero/tone comparison; structural result only");
            } else if (channelConfigHpiEntry) {
                append(report, "CH1 configuration acknowledged",
                        channelConfigApplied);
                append(report, "CH1 readback verified",
                        channelConfigReadbackVerified);
                append(report, "Single HPI control acknowledged",
                        hpiEntryControlAccepted);
            } else if (analogOneBlock) {
                append(report, "Tone", ANALOG_TEST_TONE_HZ + " Hz, amplitude "
                        + ANALOG_TEST_TONE_AMPLITUDE + ", "
                        + (640 * analogBlockCount) + " samples");
                append(report, "VoiceIn blocks sent", analogBlockCount);
                append(report, "STOP_CALL sent", analogStopSent);
                append(report, "Stock RF-off helper confirmed",
                        analogRfOffConfirmed);
            } else if (localDecode) {
                append(report, "CHAN_D units requested", LOCAL_CHAN_D_PROOF_UNITS);
                append(report, "CHAN_D units ACKed", localInjection.ackedUnits);
                append(report, "CHAN_D input wire bytes", localInjection.sentBytes);
                append(report, "CHAN_D ACK latency max ms",
                        localInjection.maxAckLatencyMs);
                byte[] injectedPrefix = Arrays.copyOf(localChanD,
                        LOCAL_CHAN_D_PROOF_UNITS * LOCAL_CHAN_D_UNIT_BYTES);
                File inputFile = new File(outputDirectory, String.format(Locale.US,
                        "local_chan_d_input_20units_%d.bin",
                        System.currentTimeMillis()));
                writeFile(inputFile, injectedPrefix);
                append(report, "Injected CHAN_D SHA-256", sha256(injectedPrefix));
                append(report, "Injected CHAN_D file", inputFile.getAbsolutePath());
                ProductPcmRecovery product = recoverProductPcm(raw);
                File productRaw = new File(outputDirectory, String.format(Locale.US,
                        "local_chan_d_candidate_pcm_%d.raw",
                        System.currentTimeMillis()));
                File productWav = new File(outputDirectory, String.format(Locale.US,
                        "local_chan_d_candidate_pcm_%d.wav",
                        System.currentTimeMillis()));
                writeFile(productRaw, product.productPcm);
                writeWav8kMonoS16le(productWav, product.productPcm);
                append(report, "Candidate PCM frames", product.speechFrames);
                append(report, "Candidate PCM wire328 frames", product.wire328Frames);
                append(report, "Candidate PCM bytes", product.productPcm.length);
                append(report, "Candidate PCM raw", productRaw.getAbsolutePath());
                append(report, "Candidate PCM wav", productWav.getAbsolutePath());
                append(report, "PCM claim", "offline correlation/listening required");
            } else if (sendVoiceOutRoute) {
                boolean voiceOutAck = containsBytes(raw, HPI_VOCODER_IO_VOICE_OUT_HPI)
                        || containsBytes(raw,
                        createHpiFrame(0, new byte[] {0x3e, 0x00}));
                append(report, "Voice OUT route traffic observed", voiceOutAck
                        || summary.frames > 0);
            } else {
                append(report, "HPI route commands sent", 0);
            }

            // Restore 57600 while flag=0 (stack-safe Step C).
            append(report, "Phase", "stack-safe restore-57600 after bridge");
            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                    "restore-57600", report);
            mcuBaud = BAUD_RATE;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                    "restore-57600", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectBack = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600 after restore",
                    printable(connectBack));
            if (!connectBack.contains("+DMOCONNECT:0")) {
                throw new IOException("CONNECT failed after restore to 57600");
            }
            String versionBack = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600 after restore", printable(versionBack));
            if (!versionBack.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("VERSION failed after restore to 57600");
            }
            if (analogOneBlock) {
                append(report, "Phase", "AT+DMOPTT=0 Carrier De-key After Bridge");
                output.write("AT+DMOPTT=0\r\n".getBytes(StandardCharsets.US_ASCII));
                output.flush();
                String ptt0Resp = readResponse(input, RESPONSE_TIMEOUT_MS);
                append(report, "DMOPTT=0 response", printable(ptt0Resp));

                String digitalRestore = query(input, output,
                        SET_EXPECTED_DIGITAL_CHANNEL);
                append(report, "Digital channel restore", printable(digitalRestore));
                if (!digitalRestore.contains("+DMOSETDIGITALCH:0")) {
                    throw new IOException("Production digital channel restore failed");
                }
            }

            // Restore temporary SRAM (baud window + timeout window + vector/flag).
            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalBaudCode);
            restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS,
                    originalBaudMarker);
            restoreWords(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS,
                    originalTimeoutCode);
            restoreWords(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                    originalTimeoutCounter);
            restoreWords(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS,
                    originalTimeoutMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    u32le(originalVector, 0));
            writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                    originalFlag[0] & 0xff);
            stateRestored = Arrays.equals(originalBaudCode, readMemory(input, output,
                    BAUD_ONESHOT_CODE_ADDRESS, originalBaudCode.length))
                    && Arrays.equals(originalTimeoutCode, readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, originalTimeoutCode.length))
                    && u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    == ORIGINAL_SYSTICK_HANDLER
                    && (readMemory(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1)[0]
                    & 0xff) == (originalFlag[0] & 0xff);
            append(report, "Temporary state restored", stateRestored);
            if (!stateRestored) {
                throw new IOException("Temporary state restore mismatch");
            }
            disableLogLevel(input, output, report);

            // No-RF smoke: bridge@230400 recovery + 57600 restore is the gate.
            // PCM may be empty without air activity — not a FAIL for this mode.
            boolean success = raw != null && stateRestored
                    && (!noRfEncoder || (encoderControlAccepted
                    && summary.chanD27 > 0))
                    && (!channelConfigHpiEntry || (channelConfigApplied
                    && channelConfigReadbackVerified
                    && hpiEntryControlAccepted))
                    && (!analogOneBlock || (analogCreditObserved
                    && analogStopSent && analogRfOffConfirmed
                    && !powerOverrideChanged))
                    && (!localDecode || (localInjection != null
                    && localInjection.ackedUnits == LOCAL_CHAN_D_PROOF_UNITS));
            append(report, "No-RF note",
                    "PCM empty is OK without TYT; bridge@230400 recovery is the gate");
            return finish(success, report, success
                    ? (noRfEncoder
                    ? (noRfEncoderKind == 1
                    ? "PASS STRUCTURE: zero PCM produced CHAN_D27 at 230400; tone comparison required"
                    : "PASS STRUCTURE: tone PCM produced CHAN_D27 at 230400; offline comparison required")
                    : channelConfigHpiEntry
                    ? "PASS: CH1 configuration restored one HPI control ACK at 230400; no PCM or RF sent"
                    : analogOneBlock
                    ? (analogBlockCount == 1
                    ? "PASS: FM VoiceIn first block credited; STOP/RF-off/restore passed"
                    : "PASS: FM VoiceIn five blocks credited; STOP/RF-off/restore passed")
                    : localDecode
                    ? "PASS STRUCTURE: local CHAN_D accepted; offline PCM gate required"
                    : sendVoiceOutRoute
                    ? "PASS: bridge@230400 + Voice OUT route smoke; 57600 restored"
                    : "PASS: restore-only bridge roundtrip; 57600 restored")
                    : "FAIL");
        } catch (Throwable error) {
            Log.e(TAG, "Bridge 230400 smoke failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            append(report, "MCU baud at failure", mcuBaud);
            append(report, "Android baud at failure", androidBaud);
            append(report, "Bridge may be active at failure", bridgeMayBeActive);
            return finish(false, report, "FAIL");
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    // Wait for auto bridge exit if still in window.
                    if (bridgeMayBeActive && mcuBaud == androidBaud) {
                        SystemClock.sleep((analogOneBlock
                                ? analogBridgeTargetMs : 0)
                                + UART_HPI_TIMEOUT_MARGIN_MS);
                        if (analogOneBlock) {
                            bridgeMayBeActive = false;
                        }
                    }
                    if (androidBaud != mcuBaud) {
                        try {
                            closeSerialLocked(report);
                            openSerialLocked(device, mcuBaud, report);
                            androidBaud = mcuBaud;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            SystemClock.sleep(150);
                            drainAvailable(input);
                        } catch (Throwable openError) {
                            append(report, "Emergency reopen failed",
                                    openError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (analogRfPrepared && !bridgeMayBeActive
                            && input != null && output != null
                            && androidBaud == mcuBaud) {
                        try {
                            armBaudOneShot(input, output, ANALOG_RF_OFF_WORDS,
                                    "emergency-analogue-rf-off", report);
                            verifyBaudOneShot(input, output,
                                    ANALOG_RF_OFF_MARKER,
                                    "emergency-analogue-rf-off", report);
                            analogRfPrepared = false;
                            analogRfOffConfirmed = true;
                        } catch (Throwable rfOffError) {
                            append(report, "Emergency analogue RF-off failed",
                                    rfOffError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (input != null && output != null
                            && mcuBaud == BAUD_RATE_230400
                            && androidBaud == BAUD_RATE_230400) {
                        try {
                            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                                    "emergency-restore-57600", report);
                            mcuBaud = BAUD_RATE;
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE, report);
                            androidBaud = BAUD_RATE;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            SystemClock.sleep(150);
                            drainAvailable(input);
                        } catch (Throwable restoreArmError) {
                            append(report, "Emergency restore arm failed",
                                    restoreArmError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (input != null && output != null && androidBaud == mcuBaud
                            && mcuBaud == BAUD_RATE) {
                        try {
                            if (originalTimeoutCode != null) {
                                restoreWords(input, output,
                                        UART_HPI_TIMEOUT_CODE_ADDRESS,
                                        originalTimeoutCode);
                            }
                            if (originalTimeoutCounter != null) {
                                restoreWords(input, output,
                                        UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                                        originalTimeoutCounter);
                            }
                            if (originalTimeoutMarker != null) {
                                restoreWords(input, output,
                                        UART_HPI_TIMEOUT_MARKER_ADDRESS,
                                        originalTimeoutMarker);
                            }
                            if (originalBaudCode != null) {
                                restoreWords(input, output,
                                        BAUD_ONESHOT_CODE_ADDRESS, originalBaudCode);
                            }
                            if (originalBaudMarker != null) {
                                restoreWords(input, output,
                                        BAUD_ONESHOT_MARKER_ADDRESS,
                                        originalBaudMarker);
                            }
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                            writeMemoryByte(input, output,
                                    UART_HPI_BRIDGE_FLAG_ADDRESS, 0);
                            if (powerOverrideChanged
                                    && originalRuntimePowerCode != null) {
                                try {
                                    writeAndVerifyRuntimePowerCode(input, output,
                                            originalRuntimePowerCode);
                                    powerOverrideChanged = false;
                                    append(report,
                                            "Emergency original power code restored",
                                            u16le(originalRuntimePowerCode, 0));
                                } catch (Throwable powerRestoreError) {
                                    append(report,
                                            "Emergency power-code restore failed",
                                            powerRestoreError.getMessage());
                                    needsRebootHint = true;
                                }
                            }
                            if (analogOneBlock) {
                                String channelRestore = query(input, output,
                                        SET_EXPECTED_DIGITAL_CHANNEL);
                                append(report, "Final channel restore",
                                        printable(channelRestore));
                            }
                        } catch (Throwable restoreError) {
                            append(report, "Emergency SRAM restore failed",
                                    restoreError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                } catch (Throwable restoreError) {
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                    needsRebootHint = true;
                }
            }
            if (input != null && output != null && mcuBaud == BAUD_RATE
                    && androidBaud == BAUD_RATE) {
                try {
                    disableLogLevel(input, output, report);
                } catch (Throwable ignored) {
                    // ignore
                }
            }
            if (needsRebootHint || (stateChanged && !stateRestored
                    && mcuBaud != BAUD_RATE)) {
                append(report, "Rollback recommendation",
                        "ADB reboot if module unresponsive at 57600");
            }
            close();
        }
    }

    /**
     * Step A only (H13.md §18.25): call {@code 0x08010A00(57600)} from SysTick
     * with stack-safe EXC_RETURN, stay at 57600, verify marker + CONNECT.
     * Does not change line rate and does not open 230400. One variable only.
     */
    ProbeResult runUartBaudKeep57600IsrProof() {
        return runUartBaudStackSafeProof(false);
    }

    /**
     * Step B only (H13.md §18.26): after Step A PASS, call
     * {@code 0x08010A00(230400)} from SysTick with stack-safe EXC_RETURN,
     * reopen Android @230400, CONNECT/VERSION, restore 57600.
     * Does not re-run keep-57600; one line-rate variable only.
     */
    ProbeResult runUartBaud230400RoundTrip() {
        return runUartBaud230400StepBOnly();
    }

    private ProbeResult runUartBaud230400StepBOnly() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalCode = null;
        byte[] originalMarker = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        int mcuBaud = BAUD_RATE;
        int androidBaud = BAUD_RATE;
        boolean needsRebootHint = false;

        append(report, "Mode", "USART1 Step B 230400 only (no RF; Step A already PASS)");
        append(report, "Device", DEVICE_PATH);
        append(report, "Prerequisite", "H13.md §18.26 Step A PASS 2026-08-07");
        append(report, "RF transmit", "not requested");
        append(report, "Baud stub generation",
                "v0.68/v0.70 stack EXC_RETURN 56-byte (not v0.66 r2-save)");
        append(report, "Forbidden stubs", "v0.63-v0.67");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] setCode = wordsToBytes(BAUD_SET_230400_WORDS);
            byte[] restoreCode = wordsToBytes(BAUD_RESTORE_57600_WORDS);
            append(report, "Set-230400 stub SHA-256", sha256(setCode));
            append(report, "Restore-57600 stub SHA-256", sha256(restoreCode));
            if (!BAUD_SET_230400_SHA256.equals(sha256(setCode))
                    || !BAUD_RESTORE_57600_SHA256.equals(sha256(restoreCode))) {
                throw new IOException("Embedded baud stub hash mismatch");
            }
            assertStackSafeBaudStub(setCode, "set-230400");
            assertStackSafeBaudStub(restoreCode, "restore-57600");

            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            mcuBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(250);
            drainAvailable(input);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connect = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect not recognized at 57600");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected version before Step B");
            }

            drainAvailable(input);
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            byte[] bridgeFlag = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] sysTick = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            originalCode = readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                    BAUD_SET_230400_WORDS.length * 4);
            originalMarker = readMemory(input, output,
                    BAUD_ONESHOT_MARKER_ADDRESS, 4);
            append(report, "Bridge flag before", bridgeFlag[0] & 0xff);
            append(report, "SysTick before", String.format(Locale.US, "0x%08x",
                    u32le(sysTick, 0)));
            if ((bridgeFlag[0] & 0xff) != 0) {
                throw new IOException("Raw bridge already active");
            }
            if (u32le(sysTick, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected SysTick vector");
            }

            append(report, "Step B", "set-230400 then Android reopen @230400");
            armBaudOneShot(input, output, BAUD_SET_230400_WORDS, "set-230400",
                    report);
            stateChanged = true;
            mcuBaud = BAUD_RATE_230400;
            append(report, "MCU baud assumed after set arm", mcuBaud);

            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE_230400, report);
            androidBaud = BAUD_RATE_230400;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_230400,
                    "set-230400", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectHigh = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @230400", printable(connectHigh));
            if (!connectHigh.contains("+DMOCONNECT:0")) {
                throw new IOException(
                        "Step B FAIL: CONNECT failed at 230400 after stack-safe set");
            }
            String versionHigh = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @230400", printable(versionHigh));
            if (!versionHigh.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Step B FAIL: VERSION failed at 230400");
            }
            append(report, "Step B result", "PASS: text face OK @230400");

            append(report, "Step C", "restore-57600 then Android reopen");
            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                    "restore-57600", report);
            mcuBaud = BAUD_RATE;
            append(report, "MCU baud assumed after restore arm", mcuBaud);
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                    "restore-57600", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectBack = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600 after restore", printable(connectBack));
            if (!connectBack.contains("+DMOCONNECT:0")) {
                throw new IOException("CONNECT failed after restore to 57600");
            }
            String versionBack = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600 after restore", printable(versionBack));
            if (!versionBack.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("VERSION failed after restore to 57600");
            }
            append(report, "Step C result", "PASS: restored @57600");

            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalCode);
            restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS, originalMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    ORIGINAL_SYSTICK_HANDLER);
            stateRestored = Arrays.equals(originalCode, readMemory(input, output,
                    BAUD_ONESHOT_CODE_ADDRESS, originalCode.length))
                    && Arrays.equals(originalMarker, readMemory(input, output,
                    BAUD_ONESHOT_MARKER_ADDRESS, 4))
                    && u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    == ORIGINAL_SYSTICK_HANDLER;
            append(report, "Temporary state restored", stateRestored);
            if (!stateRestored) {
                throw new IOException("Temporary baud-stub state restore mismatch");
            }
            disableLogLevel(input, output, report);
            return finish(true, report,
                    "PASS Step B+C: 57600->230400->57600 text face OK (stack-safe)");
        } catch (Throwable error) {
            Log.e(TAG, "Baud Step B failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            append(report, "MCU baud at failure", mcuBaud);
            append(report, "Android baud at failure", androidBaud);
            return finish(false, report, "FAIL");
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    if (androidBaud != mcuBaud) {
                        try {
                            closeSerialLocked(report);
                            openSerialLocked(device, mcuBaud, report);
                            androidBaud = mcuBaud;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            SystemClock.sleep(150);
                            drainAvailable(input);
                        } catch (Throwable openError) {
                            append(report, "Emergency reopen failed",
                                    openError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (input != null && output != null
                            && mcuBaud == BAUD_RATE_230400
                            && androidBaud == BAUD_RATE_230400) {
                        try {
                            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                                    "emergency-restore-57600", report);
                            mcuBaud = BAUD_RATE;
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE, report);
                            androidBaud = BAUD_RATE;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            SystemClock.sleep(150);
                            drainAvailable(input);
                        } catch (Throwable restoreArmError) {
                            append(report, "Emergency restore arm failed",
                                    restoreArmError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (input != null && output != null && originalCode != null
                            && androidBaud == mcuBaud) {
                        try {
                            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                                    originalCode);
                            if (originalMarker != null) {
                                restoreWords(input, output,
                                        BAUD_ONESHOT_MARKER_ADDRESS, originalMarker);
                            }
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                        } catch (Throwable restoreError) {
                            append(report, "Emergency SRAM restore failed",
                                    restoreError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                } catch (Throwable restoreError) {
                    Log.e(TAG, "Emergency baud state restore failed", restoreError);
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                    needsRebootHint = true;
                }
            }
            if (input != null && output != null && mcuBaud == BAUD_RATE
                    && androidBaud == BAUD_RATE) {
                try {
                    disableLogLevel(input, output, report);
                } catch (Throwable ignored) {
                    // ignore
                }
            }
            if (needsRebootHint || (stateChanged && !stateRestored
                    && mcuBaud != BAUD_RATE)) {
                append(report, "Rollback recommendation",
                        "ADB reboot if module text face unresponsive at 57600");
            }
            close();
        }
    }

    /**
     * @param include230400 when false, only Step A (keep-57600 ISR). When true,
     *                      A then B then C — reserved for after A is documented.
     */
    private ProbeResult runUartBaudStackSafeProof(boolean include230400) {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        byte[] originalCode = null;
        byte[] originalMarker = null;
        boolean stateChanged = false;
        boolean stateRestored = false;
        int mcuBaud = BAUD_RATE;
        int androidBaud = BAUD_RATE;
        boolean needsRebootHint = false;

        append(report, "Mode", include230400
                ? "USART1 stack-safe A+B+C (no RF)"
                : "USART1 Step A keep-57600 ISR only (no RF, no 230400)");
        append(report, "Device", DEVICE_PATH);
        append(report, "RF transmit", "not requested");
        append(report, "PTT/Flash/HPI data plane", "none");
        append(report, "Include 230400", include230400);
        append(report, "Baud stub generation",
                "v0.68/v0.69 stack EXC_RETURN push{r4,lr}/pop{r2,r3} 56-byte");
        append(report, "Forbidden stubs",
                "v0.63-v0.65 no-LR; v0.66-v0.67 r2-save (r2 clobbered by 0x08006194)");
        append(report, "Root cause note",
                "0x08010A00 bl 0x08006194; 0x08006194 starts movs r2,#0");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            byte[] keepCode = wordsToBytes(BAUD_KEEP_57600_WORDS);
            append(report, "Keep-57600 stub SHA-256", sha256(keepCode));
            if (!BAUD_KEEP_57600_SHA256.equals(sha256(keepCode))) {
                throw new IOException("Embedded keep-57600 stub hash mismatch");
            }
            assertStackSafeBaudStub(keepCode, "keep-57600");
            if (include230400) {
                byte[] setCode = wordsToBytes(BAUD_SET_230400_WORDS);
                byte[] restoreCode = wordsToBytes(BAUD_RESTORE_57600_WORDS);
                append(report, "Set-230400 stub SHA-256", sha256(setCode));
                append(report, "Restore-57600 stub SHA-256", sha256(restoreCode));
                if (!BAUD_SET_230400_SHA256.equals(sha256(setCode))
                        || !BAUD_RESTORE_57600_SHA256.equals(sha256(restoreCode))) {
                    throw new IOException("Embedded baud stub hash mismatch");
                }
                assertStackSafeBaudStub(setCode, "set-230400");
                assertStackSafeBaudStub(restoreCode, "restore-57600");
            }

            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            mcuBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;

            SystemClock.sleep(250);
            drainAvailable(input);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connect = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect response not recognized at 57600");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Unexpected version before baud test");
            }

            drainAvailable(input);
            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            appendRaw(report, "Log enable response",
                    readBytes(input, SHORT_READ_TIMEOUT_MS));

            byte[] bridgeFlag = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            byte[] sysTick = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            originalCode = readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                    BAUD_KEEP_57600_WORDS.length * 4);
            originalMarker = readMemory(input, output,
                    BAUD_ONESHOT_MARKER_ADDRESS, 4);
            append(report, "Bridge flag before", bridgeFlag[0] & 0xff);
            append(report, "SysTick before", String.format(Locale.US, "0x%08x",
                    u32le(sysTick, 0)));
            if ((bridgeFlag[0] & 0xff) != 0) {
                throw new IOException("Raw bridge already active; refusing baud test");
            }
            if (u32le(sysTick, 0) != ORIGINAL_SYSTICK_HANDLER) {
                throw new IOException("Unexpected SysTick vector; refusing baud test");
            }

            // Step A only variable: ISR calls setter(57600), line rate unchanged.
            append(report, "Step A", "keep-57600 ISR call/return (no line-rate change)");
            armBaudOneShot(input, output, BAUD_KEEP_57600_WORDS, "keep-57600",
                    report);
            stateChanged = true;
            SystemClock.sleep(50);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_KEEP,
                    "keep-57600", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectKeep = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600 after keep-ISR", printable(connectKeep));
            if (!connectKeep.contains("+DMOCONNECT:0")) {
                throw new IOException(
                        "Step A FAIL: text face dead after keep-57600 ISR call");
            }
            String versionKeep = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @57600 after keep-ISR", printable(versionKeep));
            if (!versionKeep.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException(
                        "Step A FAIL: version query after keep-57600 ISR call");
            }
            append(report, "Step A result",
                    "PASS: stack EXC_RETURN + 0x08010A00 from SysTick @57600");

            if (!include230400) {
                restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalCode);
                restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS,
                        originalMarker);
                writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                        ORIGINAL_SYSTICK_HANDLER);
                stateRestored = Arrays.equals(originalCode, readMemory(input, output,
                        BAUD_ONESHOT_CODE_ADDRESS, originalCode.length))
                        && Arrays.equals(originalMarker, readMemory(input, output,
                        BAUD_ONESHOT_MARKER_ADDRESS, 4))
                        && u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                        == ORIGINAL_SYSTICK_HANDLER;
                append(report, "Temporary state restored", stateRestored);
                if (!stateRestored) {
                    throw new IOException("Temporary baud-stub state restore mismatch");
                }
                disableLogLevel(input, output, report);
                return finish(true, report,
                        "PASS Step A only: keep-57600 ISR call/return; 230400 not run");
            }

            // Steps B/C only when explicitly enabled after Step A is documented.
            append(report, "Step B", "set-230400 then Android reopen");
            armBaudOneShot(input, output, BAUD_SET_230400_WORDS, "set-230400",
                    report);
            mcuBaud = BAUD_RATE_230400;
            append(report, "MCU baud assumed after set arm", mcuBaud);
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE_230400, report);
            androidBaud = BAUD_RATE_230400;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_230400,
                    "set-230400", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectHigh = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @230400", printable(connectHigh));
            if (!connectHigh.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed at 230400");
            }
            String versionHigh = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version @230400", printable(versionHigh));
            if (!versionHigh.contains("+DMOGETSOFTVERSION:0.3.66")) {
                throw new IOException("Version query failed at 230400");
            }

            append(report, "Step C", "restore-57600 then Android reopen");
            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                    "restore-57600", report);
            mcuBaud = BAUD_RATE;
            closeSerialLocked(report);
            openSerialLocked(device, BAUD_RATE, report);
            androidBaud = BAUD_RATE;
            input = serialPort.getInputStream();
            output = outputStream;
            SystemClock.sleep(200);
            drainAvailable(input);
            verifyBaudOneShot(input, output, BAUD_ONESHOT_MARKER_57600,
                    "restore-57600", report);
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            String connectBack = readResponse(input, RESPONSE_TIMEOUT_MS);
            append(report, "Handshake @57600 after restore", printable(connectBack));
            if (!connectBack.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect failed after restore to 57600");
            }

            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS, originalCode);
            restoreWords(input, output, BAUD_ONESHOT_MARKER_ADDRESS, originalMarker);
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    ORIGINAL_SYSTICK_HANDLER);
            stateRestored = Arrays.equals(originalCode, readMemory(input, output,
                    BAUD_ONESHOT_CODE_ADDRESS, originalCode.length))
                    && Arrays.equals(originalMarker, readMemory(input, output,
                    BAUD_ONESHOT_MARKER_ADDRESS, 4))
                    && u32le(readMemory(input, output, RAM_VECTOR_SYSTICK, 4), 0)
                    == ORIGINAL_SYSTICK_HANDLER;
            append(report, "Temporary state restored", stateRestored);
            if (!stateRestored) {
                throw new IOException("Temporary baud-stub state restore mismatch");
            }
            disableLogLevel(input, output, report);
            return finish(true, report, "PASS: Step A+B+C stack-safe baud round-trip");
        } catch (Throwable error) {
            Log.e(TAG, "Baud stack-safe proof failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            append(report, "MCU baud at failure", mcuBaud);
            append(report, "Android baud at failure", androidBaud);
            return finish(false, report, "FAIL");
        } finally {
            if (stateChanged && !stateRestored) {
                try {
                    if (androidBaud != mcuBaud) {
                        try {
                            closeSerialLocked(report);
                            openSerialLocked(device, mcuBaud, report);
                            androidBaud = mcuBaud;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            SystemClock.sleep(150);
                            drainAvailable(input);
                        } catch (Throwable openError) {
                            append(report, "Emergency reopen failed",
                                    openError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (input != null && output != null
                            && mcuBaud == BAUD_RATE_230400
                            && androidBaud == BAUD_RATE_230400) {
                        try {
                            armBaudOneShot(input, output, BAUD_RESTORE_57600_WORDS,
                                    "emergency-restore-57600", report);
                            mcuBaud = BAUD_RATE;
                            closeSerialLocked(report);
                            openSerialLocked(device, BAUD_RATE, report);
                            androidBaud = BAUD_RATE;
                            input = serialPort.getInputStream();
                            output = outputStream;
                            SystemClock.sleep(150);
                            drainAvailable(input);
                        } catch (Throwable restoreArmError) {
                            append(report, "Emergency restore arm failed",
                                    restoreArmError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                    if (input != null && output != null && originalCode != null
                            && androidBaud == mcuBaud) {
                        try {
                            restoreWords(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                                    originalCode);
                            if (originalMarker != null) {
                                restoreWords(input, output,
                                        BAUD_ONESHOT_MARKER_ADDRESS, originalMarker);
                            }
                            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                                    ORIGINAL_SYSTICK_HANDLER);
                        } catch (Throwable restoreError) {
                            append(report, "Emergency SRAM restore failed",
                                    restoreError.getMessage());
                            needsRebootHint = true;
                        }
                    }
                } catch (Throwable restoreError) {
                    Log.e(TAG, "Emergency baud state restore failed", restoreError);
                    append(report, "Emergency restore error",
                            restoreError.getMessage());
                    needsRebootHint = true;
                }
            }
            if (input != null && output != null && mcuBaud == BAUD_RATE
                    && androidBaud == BAUD_RATE) {
                try {
                    disableLogLevel(input, output, report);
                } catch (Throwable ignored) {
                    // ignore print-0 failures on teardown
                }
            }
            if (needsRebootHint || (stateChanged && !stateRestored
                    && mcuBaud != BAUD_RATE)) {
                append(report, "Rollback recommendation",
                        "ADB reboot if module text face unresponsive at 57600");
            }
            close();
        }
    }

    private static boolean skipFrameAdapterPcmForVersion() {
        return BuildConfig.VERSION_CODE >= 330
                && BuildConfig.VERSION_CODE < 337;
    }

    private static boolean useFrameAdapterDebugSpeechHpi() {
        return BuildConfig.VERSION_CODE < 329
                || BuildConfig.VERSION_CODE >= 337;
    }

    private static String frameAdapterControlRouteName() {
        if (BuildConfig.VERSION_CODE >= 329
                && BuildConfig.VERSION_CODE < 337) {
            return "OFF+0x90+PROCESS(3)+VOCODER_LOOPBACK";
        }
        if (BuildConfig.VERSION_CODE >= 328) {
            return "OFF+0x90+PROCESS(3)+DEBUG_SPEECH_HPI";
        }
        return "OFF+0x80+PROCESS(3)+DEBUG_SPEECH_HPI";
    }

    private void maybeRunStockHpiReadOnlyLoopAfterCredit(InputStream input,
            OutputStream output, StringBuilder report, boolean accepted)
            throws Exception {
        if (BuildConfig.VERSION_CODE >= 337
                && BuildConfig.VERSION_CODE < 340 && accepted) {
            runStockHpiReadOnlyLoopAfterCredit(input, output, report);
        }
    }

    private void maybeSnapshotTxChanDQueue(InputStream input,
            OutputStream output, StringBuilder report, String stage)
            throws Exception {
        if (BuildConfig.VERSION_CODE < 344) {
            return;
        }
        String prefix = "tx_chand_" + stage + "_";
        byte[] count1 = readMemoryEvidence(input, output,
                prefix + "count_r1", CHAN_D_QUEUE_COUNT_ADDRESS, 4,
                report).parsed;
        byte[] queue1 = readMemoryEvidence(input, output,
                prefix + "queue_r1", CHAN_D_QUEUE_BASE, CHAN_D_QUEUE_SIZE,
                report).parsed;
        SystemClock.sleep(EXTERNAL_DMR_RUNTIME_SNAPSHOT_GAP_MS);
        byte[] count2 = readMemoryEvidence(input, output,
                prefix + "count_r2", CHAN_D_QUEUE_COUNT_ADDRESS, 4,
                report).parsed;
        byte[] queue2 = readMemoryEvidence(input, output,
                prefix + "queue_r2", CHAN_D_QUEUE_BASE, CHAN_D_QUEUE_SIZE,
                report).parsed;
        boolean stable = Arrays.equals(count1, count2)
                && Arrays.equals(queue1, queue2);
        int nonzero = 0;
        int nonemptySlots = 0;
        if (queue2 != null) {
            for (int i = 0; i < queue2.length; i++) {
                if (queue2[i] != 0) {
                    nonzero++;
                }
            }
            if (queue2.length == CHAN_D_QUEUE_SIZE) {
                for (int slot = 0; slot < 4; slot++) {
                    boolean used = false;
                    int base = slot * 28;
                    for (int j = 0; j < 28; j++) {
                        if (queue2[base + j] != 0) {
                            used = true;
                            break;
                        }
                    }
                    if (used) {
                        nonemptySlots++;
                    }
                }
            }
        }
        append(report, stage + "发送队列计数r1", u32le(count1, 0));
        append(report, stage + "发送队列计数r2", u32le(count2, 0));
        append(report, stage + "发送队列双读一致", stable);
        append(report, stage + "发送队列非零字节", nonzero);
        append(report, stage + "发送队列非空槽", nonemptySlots);
        if (!stable) {
            append(report, stage + "发送队列", "动态现场，两轮原件均已落盘");
        }
    }

