    private void runStockHpiReadOnlyLoopAfterCredit(InputStream input,
            OutputStream output, StringBuilder report) throws Exception {
        byte[] stub = wordsToBytes(STOCK_HPI_REREAD_WORDS);
        assertStackSafeBaudStub(stub, "stock-hpi-reread");
        if (!STOCK_HPI_REREAD_SHA256.equals(sha256(stub))) {
            throw new IOException("stock HPI只读连读桩哈希不符");
        }
        byte[] codePre = readMemory(input, output,
                STOCK_HPI_REREAD_CODE_ADDRESS, stub.length);
        byte[] markerPre = readMemory(input, output,
                STOCK_HPI_REREAD_MARKER_ADDRESS, 4);
        preserveRawEvidence(report, "只读连读桩测前原像",
                "h13_stock_hpi_reread_code_pre_", codePre);
        preserveRawEvidence(report, "只读连读标记测前原像",
                "h13_stock_hpi_reread_marker_pre_", markerPre);
        for (int index = 0; index < STOCK_HPI_REREAD_WORDS.length; index++) {
            writeMemoryWord(input, output,
                    STOCK_HPI_REREAD_CODE_ADDRESS + index * 4,
                    STOCK_HPI_REREAD_WORDS[index]);
        }
        byte[] uploaded = readMemory(input, output,
                STOCK_HPI_REREAD_CODE_ADDRESS, stub.length);
        if (!Arrays.equals(stub, uploaded)) {
            restoreWords(input, output, STOCK_HPI_REREAD_CODE_ADDRESS, codePre);
            restoreWords(input, output, STOCK_HPI_REREAD_MARKER_ADDRESS,
                    markerPre);
            throw new IOException("stock HPI只读连读桩回读不符");
        }
        int produced27 = 0;
        int produced36 = 0;
        int calls = 0;
        try {
            for (int i = 1; i <= STOCK_HPI_REREAD_MAX; i++) {
                writeMemoryWord(input, output,
                        FRAME_ADAPTER_RESPONSE_STATE_ADDRESS + 8,
                        FRAME_ADAPTER_RESPONSE_PENDING);
                writeMemoryWord(input, output,
                        STOCK_HPI_REREAD_MARKER_ADDRESS, 0);
                writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                        STOCK_HPI_REREAD_ENTRY);
                SystemClock.sleep(20);
                long deadline = SystemClock.elapsedRealtime() + 1800;
                boolean marked = false;
                while (SystemClock.elapsedRealtime() < deadline) {
                    byte[] marker = readMemory(input, output,
                            STOCK_HPI_REREAD_MARKER_ADDRESS, 4);
                    if (u32le(marker, 0) == STOCK_HPI_REREAD_MARKER) {
                        marked = true;
                        break;
                    }
                    SystemClock.sleep(20);
                }
                writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                        ORIGINAL_SYSTICK_HANDLER);
                byte[] state = readMemoryEvidence(input, output,
                        "stock_hpi_reread_" + i + "_state",
                        FRAME_ADAPTER_RESPONSE_STATE_ADDRESS,
                        FRAME_ADAPTER_RESPONSE_STATE_LENGTH, report).parsed;
                byte[] rx = readMemoryEvidence(input, output,
                        "stock_hpi_reread_" + i + "_rx",
                        STOCK_HPI_RX_BUFFER_ADDRESS,
                        STOCK_HPI_RX_BUFFER_LENGTH, report).parsed;
                byte[] payload = readMemoryEvidence(input, output,
                        "stock_hpi_reread_" + i + "_payload",
                        STOCK_HPI_PAYLOAD_BUFFER_ADDRESS,
                        STOCK_HPI_PAYLOAD_BUFFER_LENGTH, report).parsed;
                byte[] wire = reconstructStockHpiReadResponse(state, rx,
                        payload);
                preserveRawEvidence(report, "stock HPI只读连读第" + i + "次线帧",
                        "h13_stock_hpi_reread_" + i + "_wire_", wire);
                calls = i;
                append(report, "reread_" + i + "_marked", marked);
                append(report, "reread_" + i + "_return", u32le(state, 0x08));
                append(report, "reread_" + i + "_len", u16le(state, 0x00));
                append(report, "reread_" + i + "_field",
                        String.format(Locale.US, "0x%02x", state[0x02] & 0xff));
                append(report, "reread_" + i + "_wire_bytes", wire.length);
                HpiEvidenceParse parsed = parseHpiEvidence(wire);
                produced27 += parsed.candidate27;
                produced36 += parsed.candidate36;
                if (parsed.candidate27 > 0 || parsed.candidate36 > 0) {
                    break;
                }
            }
        } finally {
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    ORIGINAL_SYSTICK_HANDLER);
            restoreWords(input, output, STOCK_HPI_REREAD_CODE_ADDRESS, codePre);
            restoreWords(input, output, STOCK_HPI_REREAD_MARKER_ADDRESS,
                    markerPre);
        }
        append(report, "stock_hpi_reread_calls", calls);
        append(report, "stock_hpi_reread_candidate27", produced27);
        append(report, "stock_hpi_reread_candidate36", produced36);
    }

    private static void assertStackSafeBaudStub(byte[] code, String label)
            throws IOException {
        if (code.length != 56) {
            throw new IOException(label + " stub length " + code.length
                    + " != 56 (v0.68 stack-safe)");
        }
        int half = (code[0] & 0xff) | ((code[1] & 0xff) << 8);
        // push {r4, lr} encoding on Thumb is 0xb510
        if (half != 0xb510) {
            throw new IOException(label + " first halfword 0x"
                    + Integer.toHexString(half)
                    + " is not push {r4,lr}=0xb510; refuse arming");
        }
        // Explicit ban of v0.66 mov r2,lr
        if ((code[0] & 0xff) == 0x72 && (code[1] & 0xff) == 0x46) {
            throw new IOException(label
                    + " is forbidden v0.66 r2-save stub (r2 clobbered by 0x08006194)");
        }
    }

    private void openSerialLocked(File device, int baud, StringBuilder report)
            throws Exception {
        synchronized (lock) {
            closeLocked(report);
            serialPort = new SerialPort(device, baud, 0);
            serialPort.enableClock();
            outputStream = serialPort.getOutputStream();
        }
        append(report, "Serial open", "success at " + baud + " baud");
    }

    private void closeSerialLocked(StringBuilder report) {
        synchronized (lock) {
            closeLocked(report);
        }
        append(report, "Serial close", "ok");
    }

    /**
     * While UART-HPI bridge is still active: drop Voice OUT routing and force
     * WORK_MODE idle. Must run before bridge auto-exit — text AT cannot reach
     * these SCT fields. Fixes incomplete recovery after HPI Voice OUT that left
     * RF decode → CHAN_D tape producer dead (job.md 16:38→16:44 sequence).
     */
    private void hpiExitTrafficPlaneWhileBridged(OutputStream output,
            StringBuilder report) throws Exception {
        output.write(HPI_VOCODER_IO_OFF);
        output.flush();
        SystemClock.sleep(20);
        output.write(HPI_WORK_MODE_IDLE);
        output.flush();
        SystemClock.sleep(50);
        append(report, "HPI exit while bridged",
                "VOCODER_IO_OFF + WORK_MODE_IDLE");
        Log.i(TAG, "HPI exit while bridged: VOCODER_IO_OFF + WORK_MODE_IDLE");
    }

    /**
     * P0: finally may attempt control-plane reload only when the success path
     * has not already completed one. Dual reload was proven harmful (v0.86).
     */
    static boolean shouldAttemptFinallyControlReload(boolean controlPlaneReloadDone) {
        return !controlPlaneReloadDone;
    }

    /**
     * MCU text/control-plane mode0 reload ({@code sct3258chgpro 0}).
     * Proven by baseline_reload_proof. SRAM/baud restore alone is NOT enough
     * after HPI Voice OUT. Success here is <b>controlPlaneRestored</b> only —
     * CONNECT/version/CH1 do <b>not</b> prove live RF tape production
     * ({@code rxTrafficPlaneHealthy} stays unverified unless a separate gate).
     */
    private void reloadSctBaselineTrafficPlane(InputStream input,
            OutputStream output, StringBuilder report) throws Exception {
        reloadSctBaselineTrafficPlane(input, output, report, 2,
                EXPECTED_DIGITAL_CHANNEL, false);
    }

    private void reloadSctBaselineTrafficPlane(InputStream input,
            OutputStream output, StringBuilder report, int reloadCommandAttempts)
            throws Exception {
        reloadSctBaselineTrafficPlane(input, output, report,
                reloadCommandAttempts, EXPECTED_DIGITAL_CHANNEL, false);
    }

    private void reloadSctBaselineTrafficPlanePreservingDigitalChannel(
            InputStream input, OutputStream output, StringBuilder report,
            int reloadCommandAttempts, String originalDigitalChannel)
            throws Exception {
        if (extractDigitalChannelPayload("+DMOGETDIGITALCH:"
                + originalDigitalChannel) == null) {
            throw new IOException("缺少合法实测原频道，禁止控制面reload");
        }
        reloadSctBaselineTrafficPlane(input, output, report,
                reloadCommandAttempts, originalDigitalChannel, true);
    }

    private void reloadSctBaselineTrafficPlane(InputStream input,
            OutputStream output, StringBuilder report, int reloadCommandAttempts,
            String restoreDigitalChannel, boolean preserveChannelEvidence)
            throws Exception {
        if (reloadCommandAttempts < 1 || reloadCommandAttempts > 2) {
            throw new IllegalArgumentException("控制面reload次数只能为1或2");
        }
        if (extractDigitalChannelPayload("+DMOGETDIGITALCH:"
                + restoreDigitalChannel) == null) {
            throw new IOException("控制面待恢复频道格式非法");
        }
        phase("RESTORE", "恢复 SCT 控制面…", "sct3258chgpro 0");
        append(report, "restore.step.controlReload", "attempt");
        // Match baseline_reload_proof: print 1 before chgpro.
        synchronized (lock) {
            logLevelMayBeEnabled = true;
        }
        drainAvailable(input);
        writeCommand(output, LOG_ENABLE_COMMAND);
        appendRaw(report, "Pre-reload log enable",
                readBytes(input, SHORT_READ_TIMEOUT_MS));

        byte[] reloadResponse = new byte[0];
        String reloadText = "";
        boolean startupSeen = false;
        boolean protocolCmpSeen = false;
        for (int attempt = 1; attempt <= reloadCommandAttempts; attempt++) {
            drainAvailable(input);
            writeCommand(output, SCT_RELOAD_BASELINE_COMMAND);
            append(report, "SCT baseline reload attempt", attempt);
            // Accept either +DMOSTARTUP:0 or vendor "change protocol cmp" then
            // prove with CONNECT (v0.83 saw 46B = echo+cmp without STARTUP).
            reloadResponse = readUntilContains(input, "+DMOSTARTUP:0", 25000);
            if (reloadResponse.length == 0
                    || !new String(reloadResponse, StandardCharsets.US_ASCII)
                    .contains("+DMOSTARTUP:0")) {
                // Also wait for protocol-complete string if STARTUP absent.
                byte[] more = readUntilContains(input,
                        "sct3258 change protocol cmp", 15000);
                reloadResponse = concatBytes(reloadResponse, more);
            }
            appendRaw(report, "SCT baseline reload response attempt " + attempt,
                    reloadResponse);
            reloadText = new String(reloadResponse, StandardCharsets.US_ASCII);
            startupSeen = reloadText.contains("+DMOSTARTUP:0");
            protocolCmpSeen = reloadText.contains("sct3258 change protocol cmp")
                    || reloadText.contains("change protocol cmp");
            if (startupSeen || protocolCmpSeen || reloadResponse.length > 0) {
                break;
            }
            Log.w(TAG, "SCT baseline reload attempt " + attempt
                    + " silent, bytes=" + reloadResponse.length);
            SystemClock.sleep(500);
        }
        append(report, "SCT reload STARTUP seen", startupSeen);
        append(report, "SCT reload protocol-cmp seen", protocolCmpSeen);
        drainAvailable(input);
        SystemClock.sleep(500);
        String connect = "";
        for (int attempt = 0; attempt < 6; attempt++) {
            output.write("AT+DMOCONNECT\r\n".getBytes(StandardCharsets.US_ASCII));
            output.flush();
            connect = readResponse(input, RESPONSE_TIMEOUT_MS);
            if (containsExactAsciiLine(connect, "+DMOCONNECT:0")) {
                break;
            }
            SystemClock.sleep(400);
            drainAvailable(input);
        }
        append(report, "Handshake after SCT baseline reload", printable(connect));
        if (!containsExactAsciiLine(connect, "+DMOCONNECT:0")) {
            append(report, "restore.step.controlReload", "fail: CONNECT");
            append(report, "controlPlaneRestored", false);
            throw new IOException(
                    "CONNECT failed after SCT baseline reload (STARTUP="
                            + startupSeen + " protocolCmp=" + protocolCmpSeen
                            + ")");
        }
        // CONNECT is the hard gate; STARTUP is preferred but not sole proof.
        if (!startupSeen && !protocolCmpSeen) {
            append(report, "SCT reload note",
                    "no STARTUP/cmp text; CONNECT OK — proceed cautiously");
        }
        // v1.84：严格版本门恢复。CONNECT 不能代替 0.3.66 版本证明。
        // 允许有限次重试并落盘每次原文；禁止 relaxed CONNECT-only PASS。
        String version = "";
        boolean versionOk = false;
        SystemClock.sleep(800);
        drainAvailable(input);
        for (int vAttempt = 1; vAttempt <= 4; vAttempt++) {
            SystemClock.sleep(400);
            drainAvailable(input);
            String connectRetry = query(input, output, "AT+DMOCONNECT");
            append(report, "CONNECT before version attempt " + vAttempt,
                    printable(connectRetry));
            version = query(input, output, "AT+DMOGETSOFTVERSION");
            if (version == null) {
                version = "";
            }
            append(report, "Version after SCT baseline reload attempt "
                            + vAttempt,
                    printable(version));
            append(report, "Version HEX attempt " + vAttempt,
                    bytesToHex(version.getBytes(StandardCharsets.ISO_8859_1)));
            if (containsExactAsciiLine(version,
                    "+DMOGETSOFTVERSION:" + EXPECTED_MODULE_VERSION)) {
                versionOk = true;
                break;
            }
        }
        if (!versionOk) {
            append(report, "restore.step.controlReload", "fail: version");
            append(report, "controlPlaneRestored", false);
            throw new IOException(
                    "Version unexpected after SCT baseline reload; last="
                            + printable(version));
        }
        String setChannel = query(input, output,
                "AT+DMOSETDIGITALCH=" + restoreDigitalChannel);
        append(report, "数字频道恢复命令响应",
                printable(setChannel));
        if (preserveChannelEvidence) {
            preserveRawEvidence(report, "数字频道恢复命令响应原文",
                    "h13_hw_encoder_channel_restore_ack_",
                    setChannel.getBytes(StandardCharsets.ISO_8859_1));
        }
        if (!containsExactAsciiLine(setChannel, "+DMOSETDIGITALCH:0")) {
            append(report, "restore.step.controlReload", "fail: 频道恢复命令");
            append(report, "controlPlaneRestored", false);
            throw new IOException("SCT reload后原频道恢复命令失败");
        }
        String channel = query(input, output, "AT+DMOGETDIGITALCH");
        append(report, "SCT reload后数字频道", printable(channel));
        if (preserveChannelEvidence) {
            preserveRawEvidence(report, "SCT reload后数字频道原文",
                    "h13_hw_encoder_channel_restored_",
                    channel.getBytes(StandardCharsets.ISO_8859_1));
        }
        if (!containsExactAsciiLine(channel,
                "+DMOGETDIGITALCH:" + restoreDigitalChannel)) {
            append(report, "restore.step.controlReload",
                    "fail: 原频道完整回读不一致");
            append(report, "controlPlaneRestored", false);
            throw new IOException("原频道完整回读不一致，不能声称控制面恢复");
        }
        // P0: CONNECT/version/CH1 prove control plane only — not live RF decode.
        // v1.86：reload 后显式再开 print 1，并用桥标志安全地址验证 memread 调试面
        // （与 AT 控制面拆分；不改变 VLC/setup 载荷）。
        drainAvailable(input);
        writeCommand(output, LOG_ENABLE_COMMAND);
        byte[] postReloadPrint = readBytes(input, SHORT_READ_TIMEOUT_MS);
        appendRaw(report, "Post-reload log enable", postReloadPrint);
        Log.i(TAG, "POST_RELOAD_PRINT1 hex=" + bytesToHex(postReloadPrint));
        try {
            byte[] bridgeFlagProbe = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            append(report, "Post-reload memread bridgeFlag address",
                    String.format(Locale.US, "0x%08x",
                            UART_HPI_BRIDGE_FLAG_ADDRESS));
            append(report, "Post-reload memread bridgeFlag HEX",
                    bytesToHex(bridgeFlagProbe));
            append(report, "Post-reload memread bridgeFlag bytes",
                    bridgeFlagProbe.length);
            Log.i(TAG, "POST_RELOAD_MEMREAD_BRIDGE_FLAG bytes="
                    + bridgeFlagProbe.length + " hex="
                    + bytesToHex(bridgeFlagProbe));
            if (bridgeFlagProbe.length != 1) {
                throw new IOException(
                        "reload 后 memread 调试面未就绪（bridge flag 读长="
                                + bridgeFlagProbe.length + "）");
            }
        } catch (Throwable memreadProbeError) {
            append(report, "Post-reload memread probe",
                    "fail: " + memreadProbeError.getMessage());
            append(report, "controlPlaneRestored", false);
            append(report, "restore.step.controlReload",
                    "fail: post-reload memread");
            throw new IOException(
                    "AT控制面OK但 memread 调试面失败: "
                            + memreadProbeError.getMessage(),
                    memreadProbeError);
        }
        append(report, "controlPlaneRestored", true);
        append(report, "rxTrafficPlaneHealthy", "unverified");
        append(report, "restore.step.controlReload", "ok");
        Log.i(TAG, "controlPlaneRestored via sct3258chgpro 0"
                + " STARTUP=" + startupSeen + " cmp=" + protocolCmpSeen
                + " (rxTrafficPlaneHealthy=unverified)");
    }

    /**
     * Best-effort control reload for finally paths. Never swallows without
     * writing the real step result into the report.
     */
    private boolean bestEffortControlPlaneReload(InputStream input,
            OutputStream output, StringBuilder report) {
        if (input == null || output == null) {
            append(report, "restore.step.finallyControlReload",
                    "fail: null streams");
            return false;
        }
        try {
            reloadSctBaselineTrafficPlane(input, output, report);
            return true;
        } catch (Throwable error) {
            String msg = error.getMessage() != null ? error.getMessage() : "";
            append(report, "restore.step.finallyControlReload",
                    "fail: " + error.getClass().getSimpleName() + ": " + msg);
            append(report, "controlPlaneRestored", false);
            Log.w(TAG, "best-effort control reload failed", error);
            return false;
        }
    }

    private void armBaudOneShot(InputStream input, OutputStream output,
            int[] words, String label, StringBuilder report) throws Exception {
        byte[] expected = wordsToBytes(words);
        append(report, label + " expected SHA-256", sha256(expected));
        byte[] uploaded = requireExactBytesWithRetry(expected,
                BAUD_STUB_UPLOAD_MAX_ATTEMPTS,
                attempt -> {
                    for (int index = 0; index < words.length; index++) {
                        writeMemoryWord(input, output,
                                BAUD_ONESHOT_CODE_ADDRESS + index * 4,
                                words[index]);
                    }
                    return readMemory(input, output, BAUD_ONESHOT_CODE_ADDRESS,
                            expected.length);
                },
                (attempt, actual, error, mismatchOffset) -> {
                    String outcome;
                    if (error != null) {
                        outcome = "read_error " + error.getClass().getSimpleName()
                                + ": " + error.getMessage();
                    } else if (actual == null) {
                        outcome = "null_readback";
                    } else if (actual.length < expected.length) {
                        outcome = "short_read expected=" + expected.length
                                + " actual=" + actual.length;
                    } else if (actual.length != expected.length) {
                        outcome = "length_mismatch expected=" + expected.length
                                + " actual=" + actual.length;
                    } else if (mismatchOffset >= 0) {
                        outcome = String.format(Locale.US,
                                "full_length_mismatch first_offset=0x%02x expected=0x%02x actual=0x%02x",
                                mismatchOffset, expected[mismatchOffset] & 0xff,
                                actual[mismatchOffset] & 0xff);
                    } else {
                        outcome = "exact_match";
                    }
                    append(report, label + " upload attempt " + attempt, outcome);
                    append(report, label + " upload attempt " + attempt
                            + " actual SHA-256",
                            actual == null ? "<none>" : sha256ForLog(actual));
                    Log.i(TAG, label + " upload attempt=" + attempt
                            + " outcome=" + outcome);
                });
        append(report, label + " upload SHA-256", sha256(uploaded));
        // The vector is armed only after requireExactBytesWithRetry returns.
        writeMemoryWord(input, output, BAUD_ONESHOT_MARKER_ADDRESS, 0);
        writeMemoryWord(input, output, RAM_VECTOR_SYSTICK, BAUD_ONESHOT_ENTRY);
        // Wait for one SysTick (~10 ms at 100 Hz) plus margin. After this the
        // MCU USART baud has changed; caller must reopen Android serial before
        // any further memread/verify.
        SystemClock.sleep(100);
        append(report, label + " armed and waited", "100 ms");
    }

    interface ExactByteAttempt {
        byte[] run(int attempt) throws Exception;
    }

    interface ExactByteAttemptObserver {
        void onAttempt(int attempt, byte[] actual, Exception error,
                int mismatchOffset);
    }

    static byte[] requireExactBytesWithRetry(byte[] expected, int maxAttempts,
            ExactByteAttempt operation, ExactByteAttemptObserver observer)
            throws Exception {
        if (expected == null || operation == null || observer == null) {
            throw new IllegalArgumentException("verification arguments must be non-null");
        }
        if (maxAttempts < 1) {
            throw new IllegalArgumentException("maxAttempts must be positive");
        }
        Exception lastError = null;
        String lastOutcome = "not attempted";
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            byte[] actual;
            try {
                actual = operation.run(attempt);
            } catch (Exception error) {
                lastError = error;
                lastOutcome = "read error: " + error.getMessage();
                observer.onAttempt(attempt, null, error, -1);
                continue;
            }
            int mismatchOffset = firstMismatchOffset(expected, actual);
            observer.onAttempt(attempt, actual, null, mismatchOffset);
            if (mismatchOffset < 0 && actual != null
                    && actual.length == expected.length) {
                return actual;
            }
            if (actual == null) {
                lastOutcome = "null readback";
            } else if (actual.length != expected.length) {
                lastOutcome = "length " + actual.length + " expected "
                        + expected.length;
            } else {
                lastOutcome = String.format(Locale.US,
                        "full-length mismatch at 0x%02x", mismatchOffset);
            }
        }
        IOException failure = new IOException("exact upload verification failed after "
                + maxAttempts + " attempts: " + lastOutcome);
        if (lastError != null) {
            failure.initCause(lastError);
        }
        throw failure;
    }

    static int firstMismatchOffset(byte[] expected, byte[] actual) {
        if (expected == null || actual == null) {
            return 0;
        }
        int shared = Math.min(expected.length, actual.length);
        for (int index = 0; index < shared; index++) {
            if (expected[index] != actual[index]) {
                return index;
            }
        }
        return expected.length == actual.length ? -1 : shared;
    }

    private void verifyBaudOneShot(InputStream input, OutputStream output,
            int expectedMarker, String label, StringBuilder report)
            throws Exception {
        byte[] vectorAfter = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
        byte[] markerAfter = readMemory(input, output,
                BAUD_ONESHOT_MARKER_ADDRESS, 4);
        append(report, label + " SysTick after", String.format(Locale.US,
                "0x%08x", u32le(vectorAfter, 0)));
        append(report, label + " marker after", String.format(Locale.US,
                "0x%08x", u32le(markerAfter, 0)));
        if (u32le(vectorAfter, 0) != ORIGINAL_SYSTICK_HANDLER) {
            writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                    ORIGINAL_SYSTICK_HANDLER);
            throw new IOException(label + " did not restore SysTick vector");
        }
        if (u32le(markerAfter, 0) != expectedMarker) {
            throw new IOException(label + " marker mismatch");
        }
    }

    private DmrRxMilestoneTrigger awaitDmrRxMilestoneTrigger(InputStream input,
            OutputStream output, StringBuilder report) throws Exception {
        String channel = query(input, output, "AT+DMOGETDIGITALCH");
        append(report, "Digital channel before RX milestone", printable(channel));
        if (!channel.contains("+DMOGETDIGITALCH:" + EXPECTED_DIGITAL_CHANNEL)) {
            String setChannel = query(input, output, SET_EXPECTED_DIGITAL_CHANNEL);
            append(report, "Approved CH1 restore", printable(setChannel));
            if (!setChannel.contains("+DMOSETDIGITALCH:0")) {
                throw new IOException("Unable to restore approved CH1 configuration");
            }
            channel = query(input, output, "AT+DMOGETDIGITALCH");
            if (!channel.contains("+DMOGETDIGITALCH:" + EXPECTED_DIGITAL_CHANNEL)) {
                throw new IOException("Approved CH1 readback mismatch");
            }
        }

        int unitLength = u16le(readMemory(input, output,
                TAPE_UNIT_LENGTH_ADDRESS, 2), 0);
        if (unitLength != 27) {
            throw new IOException("DMR RX milestone requires 27-byte CHAN_D; found "
                    + unitLength);
        }
        byte[] initialHeader = readMemory(input, output, TAPE_BASE, TAPE_HEADER_SIZE);
        int initialCount = initialHeader[0x28] & 0xff;
        append(report, "Tape count before record enable", initialCount);

        // If tape already looks full/stale, toggle record to re-arm cursor then
        // re-baseline so a live RX can still create a detectable transition.
        if (initialCount >= DMR_RX_TRIGGER_MIN_UNITS) {
            String preDisable = String.format(Locale.US,
                    "AT+DMOSETRECORDSW=0,%d,%d,%d,%d",
                    u32le(initialHeader, 0x00), u16le(initialHeader, 0x12),
                    u16le(initialHeader, 0x04), u16le(initialHeader, 0x06));
            String preDisableResp = query(input, output, preDisable);
            append(report, "Tape pre-clear disable", printable(preDisableResp));
            SystemClock.sleep(200);
            initialHeader = readMemory(input, output, TAPE_BASE, TAPE_HEADER_SIZE);
            initialCount = initialHeader[0x28] & 0xff;
            append(report, "Tape count after pre-clear disable", initialCount);
        }

        String recordEnable = String.format(Locale.US,
                "AT+DMOSETRECORDSW=1,%d,%d,%d,%d",
                u32le(initialHeader, 0x00), u16le(initialHeader, 0x12),
                u16le(initialHeader, 0x04), u16le(initialHeader, 0x06));
        String enableResponse = query(input, output, recordEnable);
        append(report, "RX trigger record enable", recordEnable);
        append(report, "RX trigger record response", printable(enableResponse));
        if (!enableResponse.contains("+DMOSETRECORDSW:0")) {
            throw new IOException("Record enable response not recognized");
        }
        SystemClock.sleep(150);
        initialHeader = readMemory(input, output, TAPE_BASE, TAPE_HEADER_SIZE);
        initialCount = initialHeader[0x28] & 0xff;
        append(report, "Tape baseline count after record enable", initialCount);

        // Baseline payload fingerprint: full-buffer RX may keep count==29 while
        // overwriting CHAN_D bytes — count-only gate misses that (v0.80-r2 FAIL).
        String baselinePayloadSha = "";
        if (initialCount > 0) {
            int baselineLen = Math.min(initialCount, DMR_RX_TRIGGER_MIN_UNITS)
                    * unitLength;
            if (baselineLen > 0 && baselineLen <= TAPE_DATA_CAPACITY) {
                byte[] marker0 = readMemory(input, output,
                        TAPE_BASE + TAPE_HEADER_SIZE, TAPE_BLOCK_MARKER_SIZE);
                if (u32le(marker0, 0) == TAPE_BLOCK_MARKER) {
                    baselinePayloadSha = sha256(readMemory(input, output,
                            TAPE_DATA_BASE, baselineLen));
                }
            }
        }
        append(report, "Tape baseline payload SHA (first units)",
                baselinePayloadSha.isEmpty() ? "<none>" : baselinePayloadSha);

        boolean observedTransition = false;
        boolean payloadChanged = false;
        int maximumCount = initialCount;
        int lastCount = initialCount;
        long deadline = SystemClock.elapsedRealtime() + DMR_RX_TRIGGER_TIMEOUT_MS;
        long lastUiMs = 0;
        phase("WAITING_TAPE", "等待过门…请发射",
                String.format(Locale.US, "count=%d 基线=%d 需≥%d且有新RX",
                        initialCount, initialCount, DMR_RX_TRIGGER_MIN_UNITS));

        while (SystemClock.elapsedRealtime() < deadline) {
            byte[] before = readMemory(input, output, TAPE_BASE, TAPE_HEADER_SIZE);
            int count = before[0x28] & 0xff;
            lastCount = count;
            maximumCount = Math.max(maximumCount, count);
            boolean headerTransition = !sameTapeMetadata(initialHeader, before)
                    || count != initialCount;
            // Rollover: count dropped then climbed again.
            if (count < initialCount) {
                headerTransition = true;
            }
            if (headerTransition) {
                observedTransition = true;
            }

            // Detect in-place overwrite when count is already saturated.
            if (count >= DMR_RX_TRIGGER_MIN_UNITS) {
                int probeLen = Math.min(count, DMR_RX_TRIGGER_MIN_UNITS) * unitLength;
                try {
                    byte[] marker = readMemory(input, output,
                            TAPE_BASE + TAPE_HEADER_SIZE, TAPE_BLOCK_MARKER_SIZE);
                    if (u32le(marker, 0) == TAPE_BLOCK_MARKER
                            && probeLen > 0 && probeLen <= TAPE_DATA_CAPACITY) {
                        String nowSha = sha256(readMemory(input, output,
                                TAPE_DATA_BASE, probeLen));
                        if (!baselinePayloadSha.isEmpty()
                                && !baselinePayloadSha.equals(nowSha)) {
                            payloadChanged = true;
                            observedTransition = true;
                        }
                        // First fill from empty baseline only (not stale full buffer).
                        if (baselinePayloadSha.isEmpty() && initialCount == 0
                                && count >= DMR_RX_TRIGGER_MIN_UNITS) {
                            byte[] probe = readMemory(input, output,
                                    TAPE_DATA_BASE, probeLen);
                            if (looksLikeDmrChanD(probe)) {
                                observedTransition = true;
                                payloadChanged = true;
                            }
                        }
                    }
                } catch (IOException ignored) {
                    // memread glitch — keep polling
                }
            }

            long now = SystemClock.elapsedRealtime();
            if (now - lastUiMs >= 1000) {
                lastUiMs = now;
                long leftSec = Math.max(0, (deadline - now) / 1000);
                phase("WAITING_TAPE", "等待过门…请发射",
                        String.format(Locale.US,
                                "count=%d max=%d 新RX=%s 剩%ds",
                                count, maximumCount,
                                observedTransition ? "是" : "否", leftSec));
            }

            if (!observedTransition || count < DMR_RX_TRIGGER_MIN_UNITS) {
                SystemClock.sleep(LIVE_CAPTURE_POLL_MS);
                continue;
            }
            int dataLength = count * unitLength;
            if (dataLength <= 0 || dataLength > TAPE_DATA_CAPACITY) {
                throw new IOException("DMR RX trigger data length out of range: "
                        + dataLength);
            }
            byte[] marker = readMemory(input, output,
                    TAPE_BASE + TAPE_HEADER_SIZE, TAPE_BLOCK_MARKER_SIZE);
            if (u32le(marker, 0) != TAPE_BLOCK_MARKER) {
                throw new IOException("DMR RX trigger marker mismatch");
            }
            byte[] data = readMemory(input, output, TAPE_DATA_BASE, dataLength);
            byte[] after = readMemory(input, output, TAPE_BASE, TAPE_HEADER_SIZE);
            int countAfter = after[0x28] & 0xff;
            if (!sameTapeMetadata(before, after) || countAfter < count) {
                SystemClock.sleep(LIVE_CAPTURE_POLL_MS);
                continue;
            }
            if (!looksLikeDmrChanD(data)) {
                throw new IOException("Captured RX trigger does not match 27-byte DMR shape");
            }

            File captureFile = uniqueFile("h13_dmr_rx_milestone_chan_d_", ".bin");
            writeFile(captureFile, data);
            append(report, "DMR RX trigger units", count);
            append(report, "DMR RX trigger bytes", data.length);
            append(report, "DMR RX trigger SHA-256", sha256(data));
            append(report, "Tape gate via payload change", payloadChanged);
            append(report, "Tape gate via header transition", headerTransition
                    || count != initialCount);

            String recordDisable = String.format(Locale.US,
                    "AT+DMOSETRECORDSW=0,%d,%d,%d,%d",
                    u32le(after, 0x00), u16le(after, 0x12),
                    u16le(after, 0x04), u16le(after, 0x06));
            String disableResponse = query(input, output, recordDisable);
            append(report, "Tape pause command", recordDisable);
            append(report, "Tape pause response", printable(disableResponse));
            if (!disableResponse.contains("+DMOSETRECORDSW:0")) {
                throw new IOException("Record disable response not recognized");
            }

            SystemClock.sleep(250);
            byte[] stableFirst = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS,
                    DMR_RX_COMMAND_TAIL_STABILITY_LENGTH);
            SystemClock.sleep(250);
            byte[] stableSecond = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS,
                    DMR_RX_COMMAND_TAIL_STABILITY_LENGTH);
            if (!Arrays.equals(stableFirst, stableSecond)) {
                throw new IOException("Command-tail bridge window is not stable");
            }
            append(report, "Stable command-tail window SHA-256", sha256(stableSecond));
            return new DmrRxMilestoneTrigger(count, captureFile, stableSecond);
        }
        throw new IOException(String.format(Locale.US,
                "No new DMR RX trigger within %d ms; baseline=%d last=%d max=%d "
                        + "transition=%s payloadChanged=%s",
                DMR_RX_TRIGGER_TIMEOUT_MS, initialCount, lastCount, maximumCount,
                observedTransition, payloadChanged));
    }

    private ProbeResult runSctReadMemFixedTemplate() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        boolean externalRebootRequired = false;

        append(report, "Mode", "mode0/User Flash + fixed vendor READ_MEM template");
        append(report, "Device", DEVICE_PATH);
        append(report, "Wire command", hex(HPI_READ_MEM_FIXED));
        append(report, "Memory operation", "single read-only field 0x3f request");
        append(report, "Flash operations", "none");
        append(report, "SCT loader/mode change", "none");
        append(report, "RF transmit", "not requested");
        append(report, "Runtime strategy", "mode0 unchanged + bounded 57600 UART-HPI bridge");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            synchronized (lock) {
                closeLocked(report);
                serialPort = new SerialPort(device, BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
            }
            SystemClock.sleep(250);
            append(report, "Startup", printable(readResponse(input, STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect response not recognized");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66;V2.01.07I3")) {
                throw new IOException("Unexpected MCU/SCT baseline version");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            readBytes(input, SHORT_READ_TIMEOUT_MS);

            byte[] modeBefore = readMemory(input, output, SCT_BOOT_MODE_ADDRESS, 1);
            byte[] readyBefore = readMemory(input, output, SCT_BOOT_READY_ADDRESS, 1);
            append(report, "SCT boot mode before", modeBefore[0] & 0xff);
            append(report, "SCT boot ready before", readyBefore[0] & 0xff);
            if ((modeBefore[0] & 0xff) != SCT_BASELINE_MODE
                    || (readyBefore[0] & 0xff) != 2) {
                throw new IOException("SCT is not in ready mode0 baseline");
            }

            byte[] tickFirstBytes = readMemory(
                    input, output, MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(
                    input, output, MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickFirst = u32le(tickFirstBytes, 0) & 0xffffffffL;
            long tickSecond = u32le(tickSecondBytes, 0) & 0xffffffffL;
            long tickDelta = (tickSecond - tickFirst) & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            append(report, "Measured tick Hz",
                    String.format(Locale.US, "%.2f", tickRateHz));
            if (tickRateHz < 10.0 || tickRateHz > 100000.0) {
                throw new IOException("Implausible MCU tick rate");
            }
            int timeoutTicks = bridgeTicks(tickRateHz, SCT_READ_MEM_BRIDGE_MS);
            append(report, "Bridge timeout ticks", timeoutTicks);
            append(report, "Bridge target ms", SCT_READ_MEM_BRIDGE_MS);

            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            String handlerHash = sha256(handler);
            append(report, "Handler length", handler.length);
            append(report, "Handler SHA-256", handlerHash);
            if (!"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(handlerHash)) {
                throw new IOException("Embedded timeout handler hash mismatch");
            }

            byte[] originalCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            byte[] originalCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            byte[] originalMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            byte[] originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            byte[] originalFlag = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            append(report, "SysTick vector before", String.format(
                    Locale.US, "0x%08x", u32le(originalVector, 0)));
            append(report, "Bridge flag before", originalFlag[0] & 0xff);
            append(report, "Temporary code empty", allZero(originalCode));
            append(report, "Counter empty", allZero(originalCounter));
            append(report, "Marker empty", allZero(originalMarker));
            if (u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER
                    || (originalFlag[0] & 0xff) != 0
                    || !allZero(originalCode)
                    || !allZero(originalCounter)
                    || !allZero(originalMarker)) {
                throw new IOException("Unexpected temporary SRAM/bridge baseline");
            }

            for (int offset = 0; offset < handler.length; offset += 4) {
                writeMemoryWord(input, output,
                        UART_HPI_TIMEOUT_CODE_ADDRESS + offset,
                        u32le(handler, offset));
            }
            externalRebootRequired = true;
            byte[] uploaded = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            append(report, "Handler upload verified", Arrays.equals(handler, uploaded));
            if (!Arrays.equals(handler, uploaded)) {
                throw new IOException("Timeout handler upload mismatch");
            }

            disableLogLevel(input, output, report);
            drainAvailable(input);
            long bridgeArmedAt = armBridge(input, output, timeoutTicks);
            append(report, "Bridge armed at elapsed ms", bridgeArmedAt);
            SystemClock.sleep(100);

            appendRaw(report, "READ_MEM request", HPI_READ_MEM_FIXED);
            output.write(HPI_READ_MEM_FIXED);
            output.flush();
            byte[] raw = readForDuration(input, SCT_READ_MEM_CAPTURE_MS);
            preserveRawEvidence(report, "READ_MEM raw",
                    "sct_read_mem_v052_fixed_raw_", raw);
            append(report, "READ_MEM response captured", raw.length > 0);
            append(report, "Further requests", "stopped after fixed template");
            append(report, "Post-probe recovery", "external ADB reboot required");
            return finish(raw.length > 0, report,
                    raw.length > 0 ? "CAPTURED: reboot required" : "NO RESPONSE: reboot required");
        } catch (Throwable error) {
            Log.e(TAG, "SCT3258 fixed READ_MEM probe failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            return finish(false, report, "FAIL");
        } finally {
            if (externalRebootRequired) {
                synchronized (lock) {
                    logLevelMayBeEnabled = false;
                }
            }
            close();
        }
    }

    private ProbeResult runSctFlashDumpMode0Runtime() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        boolean externalRebootRequired = false;
        File imageFile = null;
        File rawFile = null;
        File indexFile = null;

        append(report, "Mode", "mode0/User Flash runtime + verified 512 KiB Flash dump");
        append(report, "Device", DEVICE_PATH);
        append(report, "Flash range", "0x000000..0x07ffff");
        append(report, "Flash operations", "read-only 0x23/0x90,0x92,0x94");
        append(report, "RF transmit", "not requested");
        append(report, "Runtime strategy", "mode0 unchanged + bounded 57600 UART-HPI bridge");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            synchronized (lock) {
                closeLocked(report);
                serialPort = new SerialPort(device, BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
            }
            SystemClock.sleep(250);
            append(report, "Startup", printable(readResponse(input, STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect response not recognized");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66;V2.01.07I3")) {
                throw new IOException("Unexpected MCU/SCT baseline version");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            readBytes(input, SHORT_READ_TIMEOUT_MS);

            byte[] modeBefore = readMemory(input, output, SCT_BOOT_MODE_ADDRESS, 1);
            byte[] readyBefore = readMemory(input, output, SCT_BOOT_READY_ADDRESS, 1);
            append(report, "SCT boot mode before", modeBefore[0] & 0xff);
            append(report, "SCT boot ready before", readyBefore[0] & 0xff);
            if ((modeBefore[0] & 0xff) != SCT_BASELINE_MODE
                    || (readyBefore[0] & 0xff) != 2) {
                throw new IOException("SCT is not in ready mode0 baseline");
            }

            byte[] tickFirstBytes = readMemory(
                    input, output, MCU_TICK_COUNTER_ADDRESS, 4);
            long tickStarted = SystemClock.elapsedRealtime();
            SystemClock.sleep(250);
            byte[] tickSecondBytes = readMemory(
                    input, output, MCU_TICK_COUNTER_ADDRESS, 4);
            long tickElapsed = SystemClock.elapsedRealtime() - tickStarted;
            long tickFirst = u32le(tickFirstBytes, 0) & 0xffffffffL;
            long tickSecond = u32le(tickSecondBytes, 0) & 0xffffffffL;
            long tickDelta = (tickSecond - tickFirst) & 0xffffffffL;
            double tickRateHz = tickElapsed > 0
                    ? tickDelta * 1000.0 / tickElapsed : 0.0;
            append(report, "Measured tick Hz",
                    String.format(Locale.US, "%.2f", tickRateHz));
            if (tickRateHz < 10.0 || tickRateHz > 100000.0) {
                throw new IOException("Implausible MCU tick rate");
            }
            int timeoutTicks = bridgeTicks(tickRateHz, SCT_FLASH_DUMP_BRIDGE_MS);
            append(report, "Bridge timeout ticks", timeoutTicks);
            append(report, "Bridge target ms", SCT_FLASH_DUMP_BRIDGE_MS);

            byte[] handler = wordsToBytes(UART_HPI_TIMEOUT_WORDS);
            String handlerHash = sha256(handler);
            append(report, "Handler length", handler.length);
            append(report, "Handler SHA-256", handlerHash);
            if (!"5c531f291c56481a120b59d5244826797d9575e7c24e8935ca8ad8db00339cd7"
                    .equals(handlerHash)) {
                throw new IOException("Embedded timeout handler hash mismatch");
            }

            byte[] originalCode = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            byte[] originalCounter = readMemory(input, output,
                    UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
            byte[] originalMarker = readMemory(input, output,
                    UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
            byte[] originalVector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
            byte[] originalFlag = readMemory(input, output,
                    UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
            append(report, "SysTick vector before", String.format(
                    Locale.US, "0x%08x", u32le(originalVector, 0)));
            append(report, "Bridge flag before", originalFlag[0] & 0xff);
            append(report, "Temporary code empty", allZero(originalCode));
            append(report, "Counter empty", allZero(originalCounter));
            append(report, "Marker empty", allZero(originalMarker));
            if (u32le(originalVector, 0) != ORIGINAL_SYSTICK_HANDLER
                    || (originalFlag[0] & 0xff) != 0
                    || !allZero(originalCode)
                    || !allZero(originalCounter)
                    || !allZero(originalMarker)) {
                throw new IOException("Unexpected temporary SRAM/bridge baseline");
            }

            for (int offset = 0; offset < handler.length; offset += 4) {
                writeMemoryWord(input, output,
                        UART_HPI_TIMEOUT_CODE_ADDRESS + offset,
                        u32le(handler, offset));
            }
            externalRebootRequired = true;
            byte[] uploaded = readMemory(input, output,
                    UART_HPI_TIMEOUT_CODE_ADDRESS, handler.length);
            append(report, "Handler upload verified", Arrays.equals(handler, uploaded));
            if (!Arrays.equals(handler, uploaded)) {
                throw new IOException("Timeout handler upload mismatch");
            }

            disableLogLevel(input, output, report);
            drainAvailable(input);
            long bridgeArmedAt = armBridge(input, output, timeoutTicks);
            append(report, "Bridge armed at elapsed ms", bridgeArmedAt);
            SystemClock.sleep(100);

            output.write(HPI_RD_FLASH_START);
            output.flush();
            byte[] startRaw = readForDuration(input, 500);
            preserveRawEvidence(report, "RD_FLASH_START raw",
                    "sct_flash_v049_start_raw_", startRaw);

            output.write(HPI_RD_FLASH_HEADER);
            output.flush();
            byte[] headerRaw = readForDuration(input, 500);
            preserveRawEvidence(report, "RD_FLASH_HEADER raw",
                    "sct_flash_v049_header_raw_", headerRaw);

            FlashPageResult[] proofPages = new FlashPageResult[
                    SCT_FLASH_PROOF_ADDRESSES.length];
            for (int index = 0; index < SCT_FLASH_PROOF_ADDRESSES.length; index++) {
                int address = SCT_FLASH_PROOF_ADDRESSES[index];
                FlashPageResult page = captureFlashPage(input, output, address);
                proofPages[index] = page;
                String label = String.format(Locale.US,
                        "Flash proof %d at 0x%06x raw", index + 1, address);
                String prefix = String.format(Locale.US,
                        "sct_flash_v049_proof_%d_%06x_raw_", index + 1, address);
                preserveRawEvidence(report, label, prefix, page.raw);
                requireFlashPageData(page, address);
            }
            if (!Arrays.equals(proofPages[0].data, proofPages[1].data)
                    || !Arrays.equals(proofPages[2].data, proofPages[3].data)) {
                throw new IOException("Repeated Flash proof pages are not stable");
            }
            append(report, "Flash 0x03f000 SHA-256", sha256(proofPages[0].data));
            append(report, "Flash 0x000000 SHA-256", sha256(proofPages[2].data));

            long captureStamp = System.currentTimeMillis();
            imageFile = uniqueFile("sct3258_flash_512k_v049_" + captureStamp + "_", ".bin");
            rawFile = uniqueFile("sct3258_flash_raw_v049_" + captureStamp + "_", ".bin");
            indexFile = uniqueFile("sct3258_flash_index_v049_" + captureStamp + "_", ".csv");
            append(report, "Flash image file", imageFile.getAbsolutePath());
            append(report, "Flash raw file", rawFile.getAbsolutePath());
            append(report, "Flash index file", indexFile.getAbsolutePath());

            long dumpStarted = SystemClock.elapsedRealtime();
            MessageDigest imageDigest = MessageDigest.getInstance("SHA-256");
            MessageDigest rawDigest = MessageDigest.getInstance("SHA-256");
            int pageCount = 0;
            try (FileOutputStream imageStream = new FileOutputStream(imageFile, false);
                    FileOutputStream rawStream = new FileOutputStream(rawFile, false);
                    FileOutputStream indexStream = new FileOutputStream(indexFile, false)) {
                indexStream.write("address,raw_length,raw_sha256,data_sha256\n"
                        .getBytes(StandardCharsets.US_ASCII));
                for (int address = 0; address < SCT_FLASH_SIZE;
                        address += SCT_FLASH_PAGE_SIZE) {
                    FlashPageResult page = readFlashPage(input, output, address);
                    imageStream.write(page.data);
                    rawStream.write(page.raw);
                    imageDigest.update(page.data);
                    rawDigest.update(page.raw);
                    String line = String.format(Locale.US,
                            "0x%06x,%d,%s,%s\n", address, page.raw.length,
                            sha256(page.raw), sha256(page.data));
                    indexStream.write(line.getBytes(StandardCharsets.US_ASCII));
                    pageCount++;
                    if ((pageCount & 0xff) == 0) {
                        imageStream.flush();
                        rawStream.flush();
                        indexStream.flush();
                        Log.i(TAG, String.format(Locale.US,
                                "SCT_FLASH_PROGRESS pages=%d/%d address=0x%06x",
                                pageCount, SCT_FLASH_SIZE / SCT_FLASH_PAGE_SIZE,
                                address));
                    }
                }
            }
            append(report, "Flash pages", pageCount + "/"
                    + (SCT_FLASH_SIZE / SCT_FLASH_PAGE_SIZE));
            append(report, "Flash dump elapsed ms",
                    SystemClock.elapsedRealtime() - dumpStarted);
            append(report, "Flash image SHA-256", hexCompact(imageDigest.digest()));
            append(report, "Flash raw SHA-256", hexCompact(rawDigest.digest()));
            append(report, "Flash image bytes", imageFile.length());
            append(report, "Flash raw bytes", rawFile.length());
            if (pageCount != SCT_FLASH_SIZE / SCT_FLASH_PAGE_SIZE
                    || imageFile.length() != SCT_FLASH_SIZE) {
                throw new IOException("Flash dump length mismatch");
            }
            append(report, "Post-dump recovery", "external ADB reboot required");
            return finish(true, report,
                    "PASS: complete 512 KiB SCT3258 Flash exported; reboot required");
        } catch (Throwable error) {
            Log.e(TAG, "SCT3258 mode0-runtime Flash dump failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            if (imageFile != null) {
                append(report, "Partial image bytes", imageFile.length());
            }
            return finish(false, report, "FAIL");
        } finally {
            if (externalRebootRequired) {
                synchronized (lock) {
                    logLevelMayBeEnabled = false;
                }
            }
            close();
        }
    }

    private ProbeResult runSctFlashDumpSystemRuntime() {
        StringBuilder report = new StringBuilder();
        File device = new File(DEVICE_PATH);
        InputStream input = null;
        OutputStream output = null;
        boolean externalRebootRequired = false;
        File imageFile = null;
        File rawFile = null;
        File indexFile = null;

        append(report, "Mode", "system-DMR runtime + verified 512 KiB Flash dump");
        append(report, "Device", DEVICE_PATH);
        append(report, "Flash range", "0x000000..0x07ffff");
        append(report, "Flash operations", "read-only 0x23/0x90,0x92,0x94");
        append(report, "RF transmit", "not requested");
        append(report, "Runtime strategy", "vendor sct3258dspupdate + 115200 raw bridge");
        if (!device.canRead() || !device.canWrite()) {
            return finish(false, report, "Serial device permission denied");
        }

        try {
            synchronized (lock) {
                closeLocked(report);
                serialPort = new SerialPort(device, BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
            }
            SystemClock.sleep(250);
            append(report, "Startup", printable(readResponse(input, STARTUP_TIMEOUT_MS)));
            String connect = query(input, output, "AT+DMOCONNECT");
            append(report, "Handshake", printable(connect));
            if (!connect.contains("+DMOCONNECT:0")) {
                throw new IOException("Connect response not recognized");
            }
            String version = query(input, output, "AT+DMOGETSOFTVERSION");
            append(report, "Version", printable(version));
            if (!version.contains("+DMOGETSOFTVERSION:0.3.66;V2.01.07I3")) {
                throw new IOException("Unexpected MCU/SCT baseline version");
            }

            synchronized (lock) {
                logLevelMayBeEnabled = true;
            }
            writeCommand(output, LOG_ENABLE_COMMAND);
            readBytes(input, SHORT_READ_TIMEOUT_MS);
            byte[] modeBefore = readMemory(input, output, SCT_BOOT_MODE_ADDRESS, 1);
            byte[] readyBefore = readMemory(input, output, SCT_BOOT_READY_ADDRESS, 1);
            append(report, "SCT boot mode before", modeBefore[0] & 0xff);
            append(report, "SCT boot ready before", readyBefore[0] & 0xff);
            if ((modeBefore[0] & 0xff) != SCT_BASELINE_MODE
                    || (readyBefore[0] & 0xff) != 2) {
                throw new IOException("SCT is not in ready mode0 baseline");
            }
            byte[] hpiLoader = new byte[SCT_LOADER_LENGTH];
            for (int offset = 0; offset < hpiLoader.length;
                    offset += SCT_LOADER_READ_CHUNK) {
                int length = Math.min(SCT_LOADER_READ_CHUNK,
                        hpiLoader.length - offset);
                byte[] chunk = readMemory(input, output,
                        SCT_BASE_LOADER_ADDRESS + offset, length);
                System.arraycopy(chunk, 0, hpiLoader, offset, length);
            }
            String baseHash = sha256(hpiLoader);
            append(report, "Live base loader SHA-256", baseHash);
            append(report, "Live loader source patch", hex(Arrays.copyOfRange(
                    hpiLoader, 0x45c, 0x45e)));
            if (!SCT_BASE_LOADER_SHA256.equals(baseHash)
                    || (hpiLoader[0x45c] & 0xff) != 0xfb
                    || (hpiLoader[0x45d] & 0xff) != 0x44) {
                throw new IOException("Live base loader mismatch");
            }

            disableLogLevel(input, output, report);
            drainAvailable(input);
            externalRebootRequired = true;
            writeCommand(output, SCT_DSP_UPDATE_COMMAND);
            byte[] updateRaw = readForDuration(input, SCT_DSP_UPDATE_WAIT_MS);
            preserveRawEvidence(report, "Vendor DSP update output at 57600",
                    "sct_flash_v048_update_57600_raw_", updateRaw);

            synchronized (lock) {
                logLevelMayBeEnabled = false;
                closeLocked(report);
                serialPort = new SerialPort(device, HPI_BRIDGE_BAUD_RATE, 0);
                serialPort.enableClock();
                outputStream = serialPort.getOutputStream();
                input = serialPort.getInputStream();
                output = outputStream;
            }
            SystemClock.sleep(250);
            byte[] startupRaw = readForDuration(input, 500);
            preserveRawEvidence(report, "System-DMR raw bridge startup at 115200",
                    "sct_flash_v048_startup_115200_raw_", startupRaw);

            output.write(HPI_RD_FLASH_START);
            output.flush();
            byte[] startRaw = readForDuration(input, 500);
            preserveRawEvidence(report, "RD_FLASH_START raw",
                    "sct_flash_v048_start_raw_", startRaw);

            output.write(HPI_RD_FLASH_HEADER);
            output.flush();
            byte[] headerRaw = readForDuration(input, 500);
            preserveRawEvidence(report, "RD_FLASH_HEADER raw",
                    "sct_flash_v048_header_raw_", headerRaw);

            FlashPageResult[] proofPages = new FlashPageResult[
                    SCT_FLASH_PROOF_ADDRESSES.length];
            for (int index = 0; index < SCT_FLASH_PROOF_ADDRESSES.length; index++) {
                int address = SCT_FLASH_PROOF_ADDRESSES[index];
                FlashPageResult page = captureFlashPage(input, output, address);
                proofPages[index] = page;
                String label = String.format(Locale.US,
                        "Flash proof %d at 0x%06x raw", index + 1, address);
                String prefix = String.format(Locale.US,
                        "sct_flash_v048_proof_%d_%06x_raw_", index + 1, address);
                preserveRawEvidence(report, label, prefix, page.raw);
                requireFlashPageData(page, address);
            }
            if (!Arrays.equals(proofPages[0].data, proofPages[1].data)
                    || !Arrays.equals(proofPages[2].data, proofPages[3].data)) {
                throw new IOException("Repeated Flash proof pages are not stable");
            }
            append(report, "Flash 0x03f000 SHA-256", sha256(proofPages[0].data));
            append(report, "Flash 0x000000 SHA-256", sha256(proofPages[2].data));

            long captureStamp = System.currentTimeMillis();
            imageFile = uniqueFile("sct3258_flash_512k_v048_" + captureStamp + "_", ".bin");
            rawFile = uniqueFile("sct3258_flash_raw_v048_" + captureStamp + "_", ".bin");
            indexFile = uniqueFile("sct3258_flash_index_v048_" + captureStamp + "_", ".csv");
            append(report, "Flash image file", imageFile.getAbsolutePath());
            append(report, "Flash raw file", rawFile.getAbsolutePath());
            append(report, "Flash index file", indexFile.getAbsolutePath());

            long dumpStarted = SystemClock.elapsedRealtime();
            MessageDigest imageDigest = MessageDigest.getInstance("SHA-256");
            MessageDigest rawDigest = MessageDigest.getInstance("SHA-256");
            int pageCount = 0;
            try (FileOutputStream imageStream = new FileOutputStream(imageFile, false);
                    FileOutputStream rawStream = new FileOutputStream(rawFile, false);
                    FileOutputStream indexStream = new FileOutputStream(indexFile, false)) {
                indexStream.write("address,raw_length,raw_sha256,data_sha256\n"
                        .getBytes(StandardCharsets.US_ASCII));
                output.write(HPI_RD_FLASH_START);
                output.flush();
                byte[] dumpStartRaw = readForDuration(input, 500);
                rawStream.write(dumpStartRaw);
                rawDigest.update(dumpStartRaw);
                output.write(HPI_RD_FLASH_HEADER);
                output.flush();
                byte[] dumpHeaderRaw = readForDuration(input, 500);
                rawStream.write(dumpHeaderRaw);
                rawDigest.update(dumpHeaderRaw);

                for (int address = 0; address < SCT_FLASH_SIZE;
                        address += SCT_FLASH_PAGE_SIZE) {
                    FlashPageResult page = readFlashPage(input, output, address);
                    imageStream.write(page.data);
                    rawStream.write(page.raw);
                    imageDigest.update(page.data);
                    rawDigest.update(page.raw);
                    String line = String.format(Locale.US,
                            "0x%06x,%d,%s,%s\n", address, page.raw.length,
                            sha256(page.raw), sha256(page.data));
                    indexStream.write(line.getBytes(StandardCharsets.US_ASCII));
                    pageCount++;
                    if ((pageCount & 0xff) == 0) {
                        imageStream.flush();
                        rawStream.flush();
                        indexStream.flush();
                        Log.i(TAG, String.format(Locale.US,
                                "SCT_FLASH_PROGRESS pages=%d/%d address=0x%06x",
                                pageCount, SCT_FLASH_SIZE / SCT_FLASH_PAGE_SIZE,
                                address));
                    }
                }
            }
            append(report, "Flash pages", pageCount + "/"
                    + (SCT_FLASH_SIZE / SCT_FLASH_PAGE_SIZE));
            append(report, "Flash dump elapsed ms",
                    SystemClock.elapsedRealtime() - dumpStarted);
            append(report, "Flash image SHA-256", hexCompact(imageDigest.digest()));
            append(report, "Flash raw SHA-256", hexCompact(rawDigest.digest()));
            append(report, "Flash image bytes", imageFile.length());
            append(report, "Flash raw bytes", rawFile.length());
            if (pageCount != SCT_FLASH_SIZE / SCT_FLASH_PAGE_SIZE
                    || imageFile.length() != SCT_FLASH_SIZE) {
                throw new IOException("Flash dump length mismatch");
            }
            append(report, "Post-dump recovery", "external ADB reboot required");
            return finish(true, report,
                    "PASS: complete 512 KiB SCT3258 Flash exported; reboot required");
        } catch (Throwable error) {
            Log.e(TAG, "SCT3258 system-runtime Flash dump failed", error);
            append(report, "Error", error.getClass().getSimpleName()
                    + ": " + error.getMessage());
            if (imageFile != null) {
                append(report, "Partial image bytes", imageFile.length());
            }
            return finish(false, report, "FAIL");
        } finally {
            if (externalRebootRequired) {
                synchronized (lock) {
                    logLevelMayBeEnabled = false;
                }
            }
            close();
        }
    }

