    /**
     * 从0x080177B0生产路径离线重建的external/privacy合同。
     * 本对象不持有串口或设备句柄；输入不完整或privacy-off时禁止序列化帧。
     */
    static final class ExternalDmrStep0Contract {
        static final int CALL_TYPE_ALL = 0;
        static final int CALL_TYPE_GROUP = 1;
        static final int OUTPUT_SLOT1 = 0;
        static final int OUTPUT_SLOT2 = 1;

        private static final int SETUP_COUNT = 5;
        /**
         * 固定固件 0x08024F64..0x080250F6 的逐项结果。
         * 第三项在 0x08024F88..0x08024FC4 清除低四位，故为 0x00；
         * 不能把第五项的 0x11 提前套到第三项。
         */
        private static final int[] VLC_BASE_MODES =
                new int[] {0x01, 0x01, 0x00, 0x1f, 0x11};

        private final int ownId;
        private final int calledId;
        private final int callType;
        private final int record17;
        private final int record18;
        private final int outputSequence;
        private final int signaling0d;
        private final int signaling0e;
        private final byte[] sessionAddress;

        private ExternalDmrStep0Contract(int ownId, int calledId,
                int callType, int record17, int record18, int outputSequence,
                int signaling0d, int signaling0e, byte[] sessionAddress) {
            this.ownId = ownId;
            this.calledId = calledId;
            this.callType = callType;
            this.record17 = record17;
            this.record18 = record18;
            this.outputSequence = outputSequence;
            this.signaling0d = signaling0d;
            this.signaling0e = signaling0e;
            this.sessionAddress = sessionAddress.clone();
        }

        static ExternalDmrStep0Contract forProducer080177b0(int ownId,
                int calledId, int callType, int record17, int record18,
                boolean directMode, int outputSequence, int encryptOnOff,
                Integer signaling0d, Integer signaling0e,
                byte[] sessionAddress) {
            requireU24(ownId, "own ID");
            requireU24(calledId, "called ID");
            if (callType != CALL_TYPE_ALL && callType != CALL_TYPE_GROUP) {
                throw new IllegalArgumentException("Unknown call type");
            }
            if (callType == CALL_TYPE_ALL && calledId != 0xffffff) {
                throw new IllegalArgumentException("All-call requires called ID 0xffffff");
            }
            if (record17 != 0 || record18 != 0) {
                throw new IllegalArgumentException(
                        "Selected 0x080177b0 producer requires record+17/+18 = 0");
            }
            if (!directMode) {
                throw new IllegalArgumentException(
                        "Selected producer mapping is closed only for direct mode");
            }
            if (outputSequence != OUTPUT_SLOT1
                    && outputSequence != OUTPUT_SLOT2) {
                throw new IllegalArgumentException("Unknown outputSequence");
            }
            if (encryptOnOff != 1) {
                throw new IllegalArgumentException(
                        "Stock 0x60/five-VLC branch requires privacy on");
            }
            if (signaling0d == null || signaling0e == null
                    || sessionAddress == null || sessionAddress.length != 4) {
                throw new IllegalArgumentException(
                        "Complete 0x2000040d/0e and 0x20004cd3..d6 snapshot required");
            }
            requireU8(signaling0d, "0x2000040d");
            requireU8(signaling0e, "0x2000040e");
            return new ExternalDmrStep0Contract(ownId, calledId, callType,
                    record17, record18, outputSequence, signaling0d,
                    signaling0e, sessionAddress);
        }

        int callSlot() {
            return 0x80 | ((record17 & 1) << 6) | (outputSequence + 1);
        }

        int setupCount() {
            return SETUP_COUNT;
        }

        /**
         * 与合同字段自洽：仅核对 VLC/producer 实际读取的字段
         * flags[1]=0x2000040D、flags[2]=0x2000040E、session[5..8]=0x20004CD3..D6。
         * <p>
         * 2026-08-10 真机预检：privacy-on 实测为
         * {@code 01 01 01 00 | 00 | 12 34 56 78 90 12 34 56 78}，
         * dataGate 与 flags[3] 均非夹具 1。禁止再把编译期 dataGate/flags[3]
         * 硬门当成“本机必达”。
         */
        boolean matchesPrivacyRuntime(byte[] flags, byte[] privacyDataGate,
                byte[] session) {
            return flags != null && flags.length == 4
                    && privacyDataGate != null && privacyDataGate.length == 1
                    && session != null && session.length == 9
                    && (flags[1] & 0xff) == signaling0d
                    && (flags[2] & 0xff) == signaling0e
                    && Arrays.equals(Arrays.copyOfRange(session, 5, 9),
                    sessionAddress);
        }

        byte[] setupFrame(int index) {
            switch (index) {
            case 0:
                return createHpiFrame(0, new byte[] {0x19, 0x00});
            case 1:
                return createHpiFrame(0, new byte[] {0x02, 0x18});
            case 2:
                return createHpiFrame(0, new byte[] {0x3e, 0x60});
            case 3:
                return createHpiFrame(5,
                        new byte[] {0x6f, (byte) callSlot()});
            case 4:
                return createHpiFrame(0,
                        new byte[] {0x18, 0x02, 0x00, 0x00});
            default:
                throw new IndexOutOfBoundsException("setup index");
            }
        }

        int setupPacketType(int index) {
            if (index < 0 || index >= SETUP_COUNT) {
                throw new IndexOutOfBoundsException("setup index");
            }
            return index == 3 ? 5 : 0;
        }

        int setupAckField(int index) {
            return setupFrame(index)[6] & 0xff;
        }

        int vlcMode(int index) {
            if (index < 0 || index >= EXTERNAL_DMR_SESSION_ACK_COUNT) {
                throw new IndexOutOfBoundsException("VLC index");
            }
            return VLC_BASE_MODES[index] | (outputSequence << 7);
        }

        byte[] vlcPayload(int index) {
            switch (index) {
            case 0:
            case 1:
            case 4:
                return lc9Payload();
            case 2:
                return signaling10Payload();
            case 3:
                return signaling2Payload();
            default:
                throw new IndexOutOfBoundsException("VLC index");
            }
        }

        byte[] vlcFrame(int index) {
            return createDmrVlcSessionFrame(vlcMode(index),
                    vlcPayload(index));
        }

        private byte[] lc9Payload() {
            byte[] payload = new byte[9];
            payload[0] = (byte) (callType == CALL_TYPE_ALL ? 0x03 : 0x00);
            payload[2] = (byte) (((record18 & 1) << 7)
                    | 0x40 | ((record17 & 1) << 3));
            putU24Be(payload, 3, calledId);
            putU24Be(payload, 6, ownId);
            return payload;
        }

        private byte[] signaling10Payload() {
            byte[] payload = new byte[10];
            int allCall = callType == CALL_TYPE_ALL ? 1 : 0;
            payload[0] = (byte) ((allCall << 5) | (signaling0d & 0x07));
            payload[1] = 0x10;
            payload[2] = (byte) signaling0e;
            System.arraycopy(sessionAddress, 0, payload, 3,
                    sessionAddress.length);
            putU24Be(payload, 7, calledId);
            return payload;
        }

        private byte[] signaling2Payload() {
            return new byte[] {
                    (byte) (signaling0e >>> 5),
                    (byte) (((signaling0e << 3) & 0xf8)
                            | (signaling0d & 0x07))
            };
        }

        private static void putU24Be(byte[] target, int offset, int value) {
            target[offset] = (byte) (value >>> 16);
            target[offset + 1] = (byte) (value >>> 8);
            target[offset + 2] = (byte) value;
        }

        private static void requireU24(int value, String label) {
            if (value < 0 || value > 0xffffff) {
                throw new IllegalArgumentException(label + " outside 24 bits");
            }
        }

        private static void requireU8(int value, String label) {
            if (value < 0 || value > 0xff) {
                throw new IllegalArgumentException(label + " outside one byte");
            }
        }
    }

    /**
     * 步骤1离线序列校验器。每个请求必须绑定一个发送前已排空、发送后新打开的
     * 一次性交换窗口；调用方必须先证明连续静默窗口。窗口按本会话单调编号且只能消费一次。模型不持有
     * OutputStream，不能序列化 data36。任一门失败后本实例永久终止。
     */
    static final class ExternalDmrTxModel {
        enum Phase {
            SETUP,
            VLC_SESSION,
            COMPLETE,
            FAILED
        }

        private final ExternalDmrStep0Contract contract;
        private Phase phase = Phase.SETUP;
        private int setupAcks;
        private int vlcAcks;
        private long nextWindowSequence = 1;
        private ExchangeWindow activeWindow;
        /** v1.91：setup0 严格双空后是否已允许过一次原样重试。 */
        private boolean setup0EmptyRetryConsumed;

        static final class ExchangeWindow {
            private final ExternalDmrTxModel owner;
            private final long sequence;
            private final byte[] request;
            private boolean consumed;

            private ExchangeWindow(ExternalDmrTxModel owner, long sequence,
                    byte[] request) {
                this.owner = owner;
                this.sequence = sequence;
                this.request = request.clone();
            }

            long sequence() {
                return sequence;
            }
        }

        /**
         * setup 已在独立 bridge 完成且确认后，仅用于 VLC 阶段的新模型。
         */
        static ExternalDmrTxModel forVlcPhaseAfterSetup(
                ExternalDmrStep0Contract contract) {
            ExternalDmrTxModel model = new ExternalDmrTxModel(contract);
            model.phase = Phase.VLC_SESSION;
            model.setupAcks = contract.setupCount();
            return model;
        }

        ExternalDmrTxModel(ExternalDmrStep0Contract contract) {
            if (contract == null) {
                throw new IllegalArgumentException("需要完整步骤0合同");
            }
            this.contract = contract;
        }

        Phase phase() {
            return phase;
        }

        int setupAcks() {
            return setupAcks;
        }

        int vlcAcks() {
            return vlcAcks;
        }

        boolean canEmitRequest() {
            return activeWindow == null
                    && (phase == Phase.SETUP || phase == Phase.VLC_SESSION);
        }

        /** 步骤1/3 握手模型禁止 data36；步骤4 使用独立 OneUnit 模型。 */
        boolean canSerializeData36() {
            return false;
        }

        byte[] expectedRequest() {
            if (activeWindow != null) {
                return null;
            }
            if (phase == Phase.SETUP) {
                return contract.setupFrame(setupAcks);
            }
            if (phase == Phase.VLC_SESSION) {
                return contract.vlcFrame(vlcAcks);
            }
            return null;
        }

        /**
         * 调用方只能在取得连续静默窗口、写出并flush当前expectedRequest后调用本方法。
         * 返回的窗口代表其后新打开的独立接收区间。
         */
        ExchangeWindow openPostSendWindow(byte[] request,
                QuietWindowProof quietWindowProof) {
            byte[] expected = expectedRequest();
            if (quietWindowProof == null
                    || !quietWindowProof.consumeFor(this)
                    || expected == null
                    || request == null
                    || !Arrays.equals(request, expected)) {
                fail();
                return null;
            }
            activeWindow = new ExchangeWindow(this, nextWindowSequence++,
                    request);
            return activeWindow;
        }

        boolean acceptSetupExchange(ExchangeWindow window, byte[] rawAck) {
            if (phase != Phase.SETUP || !consumeActiveWindow(window)) {
                fail();
                return false;
            }
            if (rawAck == null
                    || !Arrays.equals(window.request,
                    contract.setupFrame(setupAcks))
                    || !isExactSingleControlStatusAck(rawAck,
                    contract.setupPacketType(setupAcks),
                    contract.setupAckField(setupAcks))) {
                fail();
                return false;
            }
            setupAcks++;
            if (setupAcks == contract.setupCount()) {
                phase = Phase.VLC_SESSION;
            }
            return true;
        }

        boolean acceptVlcExchange(ExchangeWindow window, byte[] rawAck) {
            if (phase != Phase.VLC_SESSION || !consumeActiveWindow(window)) {
                fail();
                return false;
            }
            if (rawAck == null
                    || !Arrays.equals(window.request,
                    contract.vlcFrame(vlcAcks))
                    || !containsDmrVlcSessionAck(rawAck)) {
                fail();
                return false;
            }
            vlcAcks++;
            if (vlcAcks == EXTERNAL_DMR_SESSION_ACK_COUNT) {
                phase = Phase.COMPLETE;
            }
            return true;
        }

        /** 超时或空窗口：硬失败，禁止继续。 */
        boolean acceptTimeout(ExchangeWindow window) {
            consumeActiveWindow(window);
            fail();
            return false;
        }

        /**
         * v1.91：仅当仍处于 setup0（setupAcks==0）且尚未消费过空重试时，
         * 释放活动窗口但保持 SETUP 相位，允许原样重发同一 setup0 帧。
         * 成功返回 true 后 {@link #setup0EmptyRetryConsumed} 为 true，禁止第三次。
         */
        boolean abandonActiveWindowForSetup0EmptyRetry(ExchangeWindow window) {
            if (phase != Phase.SETUP || setupAcks != 0
                    || setup0EmptyRetryConsumed) {
                fail();
                return false;
            }
            if (!consumeActiveWindow(window)) {
                fail();
                return false;
            }
            setup0EmptyRetryConsumed = true;
            return true;
        }

        boolean setup0EmptyRetryConsumed() {
            return setup0EmptyRetryConsumed;
        }

        void fail() {
            if (activeWindow != null) {
                activeWindow.consumed = true;
                activeWindow = null;
            }
            phase = Phase.FAILED;
        }

        private boolean consumeActiveWindow(ExchangeWindow window) {
            if (window == null || window.owner != this || window.consumed
                    || window != activeWindow) {
                return false;
            }
            window.consumed = true;
            activeWindow = null;
            return true;
        }
    }

    /**
     * v2.02实时relay状态机。它在每个独立串口捕获内增量解析完整HPI帧；
     * 第三个type=0x20/field=1/length=27单元完整到达时，以连续9字节AMBE
     * 边界取前36字节，用本次运行快照加密并只写一次。写后所有后续捕获中的
     * vendor短帧都作为credit候选，最终必须恰好一个。
     */
    static final class ExternalDmrRealtimeRelayContext {
        private final OutputStream output;
        private final List<Step3EvidenceRecord> evidenceRecords;
        private final ByteArrayOutputStream transcript;
        private final long transcriptStartedNanos;
        private final StringBuilder report;
        private final byte[] measuredRuntime14;
        private final FrozenAmbeAsset fixedAsset;
        private final byte[] softwarePlain36;
        private final byte[] softwareRequest44;
        private final ByteArrayOutputStream data27Stream =
                new ByteArrayOutputStream(256);
        private final List<byte[]> creditCandidates = new ArrayList<>();

        private int data27Count;
        private int writeCount;
        private boolean writeAttempted;
        private long thirdUnitObservedAtMs = -1L;
        private long writeAttemptedAtMs = -1L;
        private long flushCompletedAtMs = -1L;
        private long creditObservedAtMs = -1L;
        private long vlc2WireTxAtMs = -1L;
        private long preVlc2WaitMs = -1L;
        private long postObservationWindowMs = -1L;
        private byte[] combined81 = new byte[0];
        private byte[] realtimeCandidate36 = new byte[0];
        private byte[] plain36 = new byte[0];
        private byte[] encrypted36 = new byte[0];
        private byte[] request44 = new byte[0];
        private boolean evidenceFinalized;

        ExternalDmrRealtimeRelayContext(OutputStream output,
                List<Step3EvidenceRecord> evidenceRecords,
                ByteArrayOutputStream transcript, long transcriptStartedNanos,
                StringBuilder report, byte[] measuredRuntime14,
                byte[] fixedAssetBytes)
                throws IOException {
            this(output, evidenceRecords, transcript, transcriptStartedNanos,
                    report, measuredRuntime14, fixedAssetBytes, null, null);
        }

        ExternalDmrRealtimeRelayContext(OutputStream output,
                List<Step3EvidenceRecord> evidenceRecords,
                ByteArrayOutputStream transcript, long transcriptStartedNanos,
                StringBuilder report, byte[] measuredRuntime14,
                byte[] fixedAssetBytes, byte[] approvedSoftwarePlain36,
                byte[] approvedSoftwareRequest44)
                throws IOException {
            if (output == null || evidenceRecords == null || transcript == null
                    || report == null || measuredRuntime14 == null
                    || measuredRuntime14.length != 14) {
                throw new IOException("实时relay上下文依赖不完整");
            }
            this.output = output;
            this.evidenceRecords = evidenceRecords;
            this.transcript = transcript;
            this.transcriptStartedNanos = transcriptStartedNanos;
            this.report = report;
            this.measuredRuntime14 = measuredRuntime14.clone();
            fixedAsset = fixedAssetBytes == null ? null
                    : FrozenAmbeAsset.require(fixedAssetBytes);
            if ((approvedSoftwarePlain36 == null)
                    != (approvedSoftwareRequest44 == null)) {
                throw new IOException("软件AMBE实时触发明文和信封必须成对提供");
            }
            if (fixedAsset != null && approvedSoftwarePlain36 != null) {
                throw new IOException("固定资产与软件AMBE实时触发来源互斥");
            }
            if (approvedSoftwarePlain36 != null
                    && (approvedSoftwarePlain36.length != 36
                    || approvedSoftwareRequest44.length != 44
                    || !looksLikeExternalData36Frame(
                    approvedSoftwareRequest44)
                    || !Arrays.equals(approvedSoftwareRequest44,
                    createRealtimeRelayEncryptedData36Frame(
                            approvedSoftwarePlain36, measuredRuntime14)))) {
                throw new IOException("软件AMBE实时触发明文或44字节信封非法");
            }
            softwarePlain36 = approvedSoftwarePlain36 == null ? null
                    : approvedSoftwarePlain36.clone();
            softwareRequest44 = approvedSoftwareRequest44 == null ? null
                    : approvedSoftwareRequest44.clone();
            this.evidenceRecords.add(new Step3EvidenceRecord(
                    "实时relay实测运行快照14字节",
                    "h13_ext_dmr_realtime_runtime14_",
                    this.measuredRuntime14));
            if (fixedAsset != null) {
                byte[] completeAsset = fixedAsset.range(0,
                        REAL_RX_CHAN_D_STREAM_BYTES);
                this.evidenceRecords.add(new Step3EvidenceRecord(
                        "固定AMBE资产完整原件",
                        "h13_ext_dmr_fixed_asset_complete_", completeAsset));
                append(report, "固定资产来源", "APK assets/v090_chan_d_244units.bin");
                append(report, "固定资产字节数", completeAsset.length);
                append(report, "固定资产SHA-256", requireSha256(completeAsset));
                append(report, "固定资产单元索引", 0);
                append(report, "固定资产字节偏移", 0);
            }
            if (softwarePlain36 != null) {
                this.evidenceRecords.add(new Step3EvidenceRecord(
                        "软件AMBE实时触发选定明文36字节",
                        "h13_ext_dmr_software_selected_plain36_",
                        softwarePlain36));
                this.evidenceRecords.add(new Step3EvidenceRecord(
                        "软件AMBE实时触发批准信封44字节",
                        "h13_ext_dmr_software_approved_request44_",
                        softwareRequest44));
                append(report, "软件AMBE实时触发明文SHA-256",
                        requireSha256(softwarePlain36));
                append(report, "软件AMBE实时触发信封SHA-256",
                        requireSha256(softwareRequest44));
            }
        }

        IncrementalCapture newCapture(String source) throws IOException {
            if (source == null || source.length() == 0) {
                throw new IOException("实时relay捕获来源为空");
            }
            return new IncrementalCapture(this, source,
                    flushCompletedAtMs >= 0 ? 0 : Integer.MAX_VALUE);
        }

        void acceptCompleteCapture(byte[] raw, String source)
                throws Exception {
            byte[] safe = raw != null ? raw : new byte[0];
            IncrementalCapture capture = newCapture(source);
            capture.accept(safe, safe.length);
            capture.finish(safe);
        }

        void onVlcWireTx(int index, long wireTxAtMs) throws IOException {
            if (index == 2) {
                vlc2WireTxAtMs = wireTxAtMs;
                if (writeCount != 1 || flushCompletedAtMs < 0
                        || flushCompletedAtMs >= vlc2WireTxAtMs) {
                    throw new IOException("第三个实时单元未在vlc2上线前触发唯一data36");
                }
            }
        }

        void recordPreVlc2Wait(byte[] raw, long elapsedMs,
                boolean waitNeeded) throws Exception {
            if (preVlc2WaitMs >= 0) {
                throw new IOException("vlc2前有界接收窗重复记录");
            }
            if (elapsedMs < 0 || (!waitNeeded && elapsedMs > 100)) {
                throw new IOException("vlc2前有界接收窗计时无效: " + elapsedMs);
            }
            preVlc2WaitMs = elapsedMs;
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                    "realtime pre-vlc2 wait raw",
                    "h13_ext_dmr_realtime_pre_vlc2_wait_",
                    raw != null ? raw : new byte[0], true);
            append(report, "Realtime relay pre-vlc2 wait needed", waitNeeded);
            append(report, "Realtime relay pre-vlc2 wait ms", elapsedMs);
            append(report, "Realtime relay pre-vlc2 wait bytes",
                    raw != null ? raw.length : 0);
        }

        void recordPostObservation(byte[] raw, long elapsedMs)
                throws Exception {
            postObservationWindowMs = elapsedMs;
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_RX,
                    "realtime data36 post-VLC observation raw",
                    "h13_ext_dmr_realtime_post_vlc_observation_",
                    raw != null ? raw : new byte[0], true);
        }

        void finalizeEvidence() throws IOException {
            if (evidenceFinalized) {
                return;
            }
            evidenceFinalized = true;
            byte[] canonical = new byte[0];
            for (byte[] candidate : creditCandidates) {
                canonical = concatBytes(canonical, candidate);
            }
            evidenceRecords.add(new Step3EvidenceRecord(
                    "实时relay data36 credit候选合并原件",
                    "h13_ext_dmr_realtime_data36_credit_rsp_", canonical));
            append(report, "Realtime relay data27 count", data27Count);
            append(report, "Realtime relay ready", data27Count >= 3);
            append(report, "Realtime relay third unit monoMs",
                    thirdUnitObservedAtMs);
            append(report, "Realtime relay write attempted monoMs",
                    writeAttemptedAtMs);
            append(report, "Realtime relay flush monoMs",
                    flushCompletedAtMs);
            append(report, "Realtime relay vlc2 wire tx monoMs",
                    vlc2WireTxAtMs);
            append(report, "Realtime relay pre-vlc2 wait ms",
                    preVlc2WaitMs);
            append(report, "Realtime relay credit candidates",
                    creditCandidates.size());
            append(report, "Realtime relay credit observed monoMs",
                    creditObservedAtMs);
            append(report, "Realtime relay post observation window ms",
                    postObservationWindowMs);
            append(report, "Data36 payload source",
                    payloadSource());
            if (fixedAssetPayload()) {
                append(report, "Fixed asset unit index", 0);
                append(report, "Fixed asset byte offset", 0);
                append(report, "Fixed asset full SHA-256", fixedAsset.sha256());
                append(report, "Realtime candidate SHA-256",
                        requireSha256(realtimeCandidate36));
                append(report, "Fixed plain SHA-256", requireSha256(plain36));
                append(report, "Fixed differs from realtime candidate",
                        !Arrays.equals(plain36, realtimeCandidate36));
            }
        }

        void requireStrictPass() throws IOException {
            if (data27Count < 3 || combined81.length != 81
                    || realtimeCandidate36.length != 36
                    || plain36.length != 36 || encrypted36.length != 36
                    || request44.length != 44) {
                throw new IOException("实时relay三个单元或派生证据不完整");
            }
            if (!writeAttempted || writeCount != 1
                    || thirdUnitObservedAtMs < 0 || writeAttemptedAtMs < 0
                    || flushCompletedAtMs < writeAttemptedAtMs
                    || preVlc2WaitMs < 0
                    || vlc2WireTxAtMs <= flushCompletedAtMs) {
                throw new IOException("实时relay触发/唯一写出/vlc2时序门失败");
            }
            if (creditCandidates.size() != 1 || creditObservedAtMs < 0
                    || creditObservedAtMs < flushCompletedAtMs) {
                throw new IOException("实时relay唯一post-flush短credit门失败，候选数="
                        + creditCandidates.size());
            }
            if (fixedAssetPayload()
                    && (Arrays.equals(plain36, realtimeCandidate36)
                    || !Arrays.equals(plain36, fixedAsset.data36(0)))) {
                throw new IOException("固定资产载荷独立性门失败");
            }
            if (softwarePayload()
                    && (Arrays.equals(plain36, realtimeCandidate36)
                    || !Arrays.equals(plain36, softwarePlain36)
                    || !Arrays.equals(request44, softwareRequest44))) {
                throw new IOException("软件AMBE载荷独立性或批准信封门失败");
            }
        }

        int data27Count() {
            return data27Count;
        }

        int writeCount() {
            return writeCount;
        }

        boolean writeCompleted() {
            return writeCount == 1;
        }

        boolean writeAttempted() {
            return writeAttempted;
        }

        boolean creditAccepted() {
            return creditCandidates.size() == 1
                    && creditObservedAtMs >= flushCompletedAtMs;
        }

        long flushCompletedAtMs() {
            return flushCompletedAtMs;
        }

        long creditObservedAtMs() {
            return creditObservedAtMs;
        }

        long creditLatencyMs() {
            return creditAccepted()
                    ? creditObservedAtMs - flushCompletedAtMs : -1L;
        }

        long thirdUnitObservedAtMs() {
            return thirdUnitObservedAtMs;
        }

        long vlc2WireTxAtMs() {
            return vlc2WireTxAtMs;
        }

        long preVlc2WaitMs() {
            return preVlc2WaitMs;
        }

        long postObservationWindowMs() {
            return postObservationWindowMs;
        }

        byte[] request44() {
            return request44.clone();
        }

        boolean fixedAssetPayload() {
            return fixedAsset != null;
        }

        boolean softwarePayload() {
            return softwarePlain36 != null;
        }

        String payloadSource() {
            if (softwarePayload()) {
                return "software_ambe";
            }
            return fixedAssetPayload() ? "fixed_asset" : "realtime_stream";
        }

        byte[] realtimeCandidate36() {
            return realtimeCandidate36.clone();
        }

        byte[] plain36() {
            return plain36.clone();
        }

        private void onFrame(byte[] raw, HpiWireFrame frame, String source,
                boolean postFlushEligible, int captureAvailableBoundary)
                throws Exception {
            int packetType = raw[frame.offset + 5] & 0xff;
            if (packetType == 0x20 && frame.payloadLength == 29
                    && (raw[frame.offset + 6] & 0xff) == 0x01
                    && (raw[frame.offset + 7] & 0xff) == 27) {
                byte[] unit = Arrays.copyOfRange(raw, frame.offset + 8,
                        frame.offset + 35);
                int sequence = data27Count;
                data27Count++;
                data27Stream.write(unit);
                evidenceRecords.add(new Step3EvidenceRecord(
                        "实时relay data27 #" + sequence + " 来源=" + source
                                + " 帧偏移=" + frame.offset,
                        String.format(Locale.US,
                                "h13_ext_dmr_realtime_data27_%02d_", sequence),
                        unit));
                append(report, "Realtime relay data27 #" + sequence
                        + " source", source);
                append(report, "Realtime relay data27 #" + sequence
                        + " frame offset", frame.offset);
                append(report, "Realtime relay data27 #" + sequence
                        + " SHA-256", sha256(unit));
                if (data27Count == 3) {
                    thirdUnitObservedAtMs = monotonicNowMs();
                    triggerOneData36(captureAvailableBoundary);
                }
            }
            if (postFlushEligible && isExternalEncodedTxCreditPayload(raw,
                    frame.offset, frame.payloadLength)) {
                byte[] candidate = Arrays.copyOfRange(raw, frame.offset,
                        frame.offset + frame.wireLength);
                creditCandidates.add(candidate);
                if (creditObservedAtMs < 0) {
                    creditObservedAtMs = monotonicNowMs();
                }
                evidenceRecords.add(new Step3EvidenceRecord(
                        "实时relay post-flush credit候选 #"
                                + creditCandidates.size() + " 来源=" + source
                                + " 帧偏移=" + frame.offset,
                        String.format(Locale.US,
                                "h13_ext_dmr_realtime_credit_candidate_%02d_",
                                creditCandidates.size()), candidate));
            }
        }

        private void triggerOneData36(int captureAvailableBoundary)
                throws Exception {
            if (writeAttempted || writeCount != 0) {
                throw new IOException("实时relay禁止第二次data36写出");
            }
            byte[] stream = data27Stream.toByteArray();
            if (stream.length < 81) {
                throw new IOException("第三个实时单元到达时81字节流不完整");
            }
            combined81 = Arrays.copyOf(stream, 81);
            realtimeCandidate36 = createFirstRealtimeRelayPlain36(combined81);
            plain36 = softwarePayload()
                    ? softwarePlain36.clone()
                    : (fixedAssetPayload()
                    ? fixedAsset.data36(0) : realtimeCandidate36.clone());
            if ((fixedAssetPayload() || softwarePayload())
                    && Arrays.equals(plain36, realtimeCandidate36)) {
                throw new IOException("独立载荷与本次实时前36字节相同，"
                        + "无法证明音源独立性，禁止写出");
            }
            request44 = softwarePayload()
                    ? softwareRequest44.clone()
                    : createRealtimeRelayEncryptedData36Frame(plain36,
                    measuredRuntime14);
            encrypted36 = Arrays.copyOfRange(request44, 8, 44);
            evidenceRecords.add(new Step3EvidenceRecord(
                    "实时relay前三单元合并81字节",
                    "h13_ext_dmr_realtime_combined81_", combined81));
            evidenceRecords.add(new Step3EvidenceRecord(
                    "实时relay前36字节负对照候选",
                    "h13_ext_dmr_realtime_candidate36_", realtimeCandidate36));
            evidenceRecords.add(new Step3EvidenceRecord(
                    softwarePayload()
                            ? "软件AMBE第一单元发送明文36字节"
                            : (fixedAssetPayload()
                            ? "固定资产unit0发送明文36字节"
                            : "实时relay重组明文36字节"),
                    "h13_ext_dmr_realtime_plain36_", plain36));
            if (fixedAssetPayload()) {
                evidenceRecords.add(new Step3EvidenceRecord(
                        "固定资产unit0选择原件，索引0，偏移0",
                        "h13_ext_dmr_fixed_asset_unit000_offset000000_",
                        plain36));
            }
            evidenceRecords.add(new Step3EvidenceRecord(
                    "实时relay本次快照派生密文36字节",
                    "h13_ext_dmr_realtime_encrypted36_", encrypted36));
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_TX,
                    "realtime data36 request TX attempt",
                    "h13_ext_dmr_realtime_data36_req_", request44, true);
            writeAttempted = true;
            writeAttemptedAtMs = monotonicNowMs();
            output.write(request44);
            output.flush();
            flushCompletedAtMs = monotonicNowMs();
            writeCount = 1;
            recordStep3Evidence(evidenceRecords, transcript,
                    transcriptStartedNanos, STEP3_TRANSCRIPT_TX_COMPLETE,
                    "realtime data36 request TX complete", "",
                    new byte[0], false);
            append(report, "Realtime relay trigger capture boundary",
                    captureAvailableBoundary);
            append(report, "Realtime relay combined81 SHA-256",
                    sha256(combined81));
            append(report, "Realtime relay candidate36 SHA-256",
                    sha256(realtimeCandidate36));
            append(report, "Realtime relay plain36 SHA-256", sha256(plain36));
            append(report, "Realtime relay encrypted36 SHA-256",
                    sha256(encrypted36));
            append(report, "Realtime relay request44 SHA-256",
                    sha256(request44));
            platformLogInfo(String.format(Locale.US,
                    "REALTIME_RELAY_TRIGGER thirdMs=%d writeMs=%d flushMs=%d requestSha=%s",
                    thirdUnitObservedAtMs, writeAttemptedAtMs,
                    flushCompletedAtMs, sha256(request44)));
        }

        private static final class IncrementalCapture {
            private final ExternalDmrRealtimeRelayContext owner;
            private final String source;
            private int parsedOffset;
            private int postFlushEligibleOffset;

            IncrementalCapture(ExternalDmrRealtimeRelayContext owner,
                    String source, int postFlushEligibleOffset) {
                this.owner = owner;
                this.source = source;
                this.postFlushEligibleOffset = postFlushEligibleOffset;
            }

            void accept(byte[] raw, int captureAvailableBoundary)
                    throws Exception {
                if (raw == null || captureAvailableBoundary < 0
                        || captureAvailableBoundary > raw.length
                        || parsedOffset > captureAvailableBoundary) {
                    throw new IOException("实时relay增量捕获参数无效");
                }
                while (captureAvailableBoundary - parsedOffset >= 6) {
                    int offset = parsedOffset;
                    if ((raw[offset] & 0xff) != 0x84
                            || (raw[offset + 1] & 0xff) != 0xa9
                            || (raw[offset + 2] & 0xff) != 0x61) {
                        throw new IOException("实时relay捕获出现非HPI边界字节，来源="
                                + source + " 偏移=" + offset);
                    }
                    int payloadLength = ((raw[offset + 3] & 0xff) << 8)
                            | (raw[offset + 4] & 0xff);
                    int declaredLength = 6 + payloadLength;
                    int wireLength = declaredLength + (declaredLength & 1);
                    if (wireLength > captureAvailableBoundary - offset) {
                        break;
                    }
                    if (wireLength != declaredLength
                            && raw[offset + declaredLength] != 0) {
                        throw new IOException("实时relay HPI补齐字节非零，来源="
                                + source + " 偏移=" + offset);
                    }
                    HpiWireFrame frame = new HpiWireFrame(offset,
                            payloadLength, declaredLength, wireLength);
                    int writesBefore = owner.writeCount;
                    owner.onFrame(raw, frame, source,
                            offset >= postFlushEligibleOffset,
                            captureAvailableBoundary);
                    if (writesBefore == 0 && owner.writeCount == 1) {
                        // 当前read()返回的全部字节都早于本次write；只有下一次read
                        // 新增的字节才有资格成为post-flush credit。
                        postFlushEligibleOffset = captureAvailableBoundary;
                    }
                    parsedOffset += wireLength;
                }
            }

            void finish(byte[] raw) throws IOException {
                if (raw == null || parsedOffset != raw.length) {
                    throw new IOException("实时relay捕获存在截断尾，来源="
                            + source + " parsed=" + parsedOffset
                            + " bytes=" + (raw == null ? -1 : raw.length));
                }
            }
        }
    }

    /**
     * v2.04完整冻结资产门。调用者只能交入APK内随包的原始6588字节资产；
     * 长度、总哈希和9/36字节分组任一不一致都失败关闭。
     */
    static final class FrozenAmbeAsset {
        private final byte[] bytes;

        private FrozenAmbeAsset(byte[] source) {
            bytes = source.clone();
        }

        static FrozenAmbeAsset require(byte[] source) throws IOException {
            if (source == null || source.length != REAL_RX_CHAN_D_STREAM_BYTES) {
                throw new IOException("冻结AMBE资产长度必须为6588字节");
            }
            String hash = requireSha256(source);
            if (!REAL_RX_CHAN_D_STREAM_SHA256.equals(hash)) {
                throw new IOException("冻结AMBE资产SHA-256不符: " + hash);
            }
            if (source.length % REAL_RX_AMBE_FRAME_BYTES != 0
                    || source.length % EXT_ENC_TX_UNIT_BYTES != 0
                    || source.length / REAL_RX_AMBE_FRAME_BYTES
                    != REAL_RX_AMBE_FRAME_COUNT
                    || source.length / EXT_ENC_TX_UNIT_BYTES
                    != REAL_RX_DATA36_UNIT_COUNT) {
                throw new IOException("冻结AMBE资产分组总账不一致");
            }
            return new FrozenAmbeAsset(source);
        }

        int frameCount() {
            return bytes.length / REAL_RX_AMBE_FRAME_BYTES;
        }

        int data36Count() {
            return bytes.length / EXT_ENC_TX_UNIT_BYTES;
        }

        byte[] frame9(int frameIndex) {
            if (frameIndex < 0 || frameIndex >= frameCount()) {
                throw new IllegalArgumentException("AMBE帧索引越界");
            }
            return Arrays.copyOfRange(bytes,
                    frameIndex * REAL_RX_AMBE_FRAME_BYTES,
                    (frameIndex + 1) * REAL_RX_AMBE_FRAME_BYTES);
        }

        byte[] data36(int unitIndex) {
            if (unitIndex < 0 || unitIndex >= data36Count()) {
                throw new IllegalArgumentException("data36资产索引越界");
            }
            return Arrays.copyOfRange(bytes,
                    unitIndex * EXT_ENC_TX_UNIT_BYTES,
                    (unitIndex + 1) * EXT_ENC_TX_UNIT_BYTES);
        }

        byte[] range(int offset, int length) {
            if (offset < 0 || length < 0 || offset > bytes.length - length) {
                throw new IllegalArgumentException("冻结AMBE资产范围越界");
            }
            return Arrays.copyOfRange(bytes, offset, offset + length);
        }

        String sha256() {
            return REAL_RX_CHAN_D_STREAM_SHA256;
        }
    }

    /** 标准RC4流状态；S盒和i/j在AMBE帧之间连续保留。 */
    static final class StatefulRc4 {
        private final int[] box = new int[256];
        private int i;
        private int j;

        StatefulRc4(byte[] key5, byte[] mi) {
            if (key5 == null || key5.length != 5
                    || mi == null || mi.length != 4) {
                throw new IllegalArgumentException("RC4状态要求key5和4字节MI");
            }
            byte[] key9 = concatBytes(key5, mi);
            for (int index = 0; index < box.length; index++) {
                box[index] = index;
            }
            int keyJ = 0;
            for (int index = 0; index < box.length; index++) {
                keyJ = (keyJ + box[index]
                        + (key9[index % key9.length] & 0xff)) & 0xff;
                swap(index, keyJ);
            }
            for (int discard = 0; discard < 256; discard++) {
                nextByte();
            }
        }

        private void swap(int left, int right) {
            int value = box[left];
            box[left] = box[right];
            box[right] = value;
        }

        int nextByte() {
            i = (i + 1) & 0xff;
            j = (j + box[i]) & 0xff;
            swap(i, j);
            return box[(box[i] + box[j]) & 0xff];
        }

        byte[] apply49Bits(byte[] plain9) {
            if (plain9 == null || plain9.length != REAL_RX_AMBE_FRAME_BYTES) {
                throw new IllegalArgumentException("RC4单帧必须为9字节");
            }
            byte[] encrypted = plain9.clone();
            for (int item = 0; item < 7; item++) {
                int stream = nextByte();
                if (item < 6) {
                    encrypted[item] ^= (byte) stream;
                } else {
                    encrypted[item] ^= (byte) (stream & 0x80);
                }
            }
            return encrypted;
        }

        String stateSha256() throws IOException {
            byte[] raw = new byte[258];
            for (int index = 0; index < box.length; index++) {
                raw[index] = (byte) box[index];
            }
            raw[256] = (byte) i;
            raw[257] = (byte) j;
            return requireSha256(raw);
        }

        int i() {
            return i;
        }

        int j() {
            return j;
        }
    }

    /**
     * v2.04离线DMR privacy连续上下文。每18个AMBE帧推进MI并重建RC4，
     * data36边界不影响超帧边界。
     */
    static final class DmrPrivacyStreamContext {
        private final byte[] key5;
        private byte[] currentMi;
        private byte[] nextMi;
        private byte[] lateEntryFragments;
        private StatefulRc4 rc4;
        private int globalFrameIndex;
        private int frameInSuperframe;

        DmrPrivacyStreamContext(byte[] key5, byte[] initialMi) {
            if (key5 == null || key5.length != 5
                    || initialMi == null || initialMi.length != 4) {
                throw new IllegalArgumentException("连续privacy参数长度错误");
            }
            this.key5 = key5.clone();
            currentMi = initialMi.clone();
            nextMi = evolveDmrPrivacyMi(currentMi);
            lateEntryFragments = createDmrLateEntryFragments(nextMi);
            rc4 = new StatefulRc4(this.key5, currentMi);
        }

        static DmrPrivacyStreamContext fromMeasuredRuntime(byte[] runtime14) {
            if (runtime14 == null || runtime14.length != 14) {
                throw new IllegalArgumentException("连续privacy必须绑定14字节实测快照");
            }
            return new DmrPrivacyStreamContext(
                    Arrays.copyOfRange(runtime14, 5, 10),
                    Arrays.copyOfRange(runtime14, 10, 14));
        }

        byte[] encrypt(byte[] plainFrames) {
            if (plainFrames == null || plainFrames.length == 0
                    || plainFrames.length % REAL_RX_AMBE_FRAME_BYTES != 0) {
                throw new IllegalArgumentException("连续privacy输入必须为非空9字节帧序列");
            }
            byte[] result = new byte[plainFrames.length];
            int frameCount = plainFrames.length / REAL_RX_AMBE_FRAME_BYTES;
            for (int frame = 0; frame < frameCount; frame++) {
                int offset = frame * REAL_RX_AMBE_FRAME_BYTES;
                byte[] encrypted = rc4.apply49Bits(Arrays.copyOfRange(
                        plainFrames, offset, offset + REAL_RX_AMBE_FRAME_BYTES));
                setDmrC3HighNibble(encrypted, 0,
                        lateEntryFragments[frameInSuperframe] & 0x0f);
                System.arraycopy(encrypted, 0, result, offset,
                        REAL_RX_AMBE_FRAME_BYTES);
                frameInSuperframe++;
                globalFrameIndex++;
                if (frameInSuperframe == 18) {
                    currentMi = nextMi;
                    nextMi = evolveDmrPrivacyMi(currentMi);
                    lateEntryFragments = createDmrLateEntryFragments(nextMi);
                    rc4 = new StatefulRc4(key5, currentMi);
                    frameInSuperframe = 0;
                }
            }
            return result;
        }

        byte[] encryptData36(byte[] plain36) {
            if (plain36 == null || plain36.length != EXT_ENC_TX_UNIT_BYTES) {
                throw new IllegalArgumentException("连续privacy单元必须为36字节");
            }
            return encrypt(plain36);
        }

        String stateSummary() throws IOException {
            return String.format(Locale.US,
                    "frame=%d superframe_pos=%d mi_sha256=%s next_mi_sha256=%s "
                            + "late_entry_sha256=%s rc4_i=%d rc4_j=%d rc4_sha256=%s",
                    globalFrameIndex, frameInSuperframe,
                    requireSha256(currentMi), requireSha256(nextMi),
                    requireSha256(lateEntryFragments), rc4.i(), rc4.j(),
                    rc4.stateSha256());
        }

        int globalFrameIndex() {
            return globalFrameIndex;
        }

        int frameInSuperframe() {
            return frameInSuperframe;
        }

        int completedData36Units() {
            return globalFrameIndex / 4;
        }

        byte[] currentMi() {
            return currentMi.clone();
        }

        byte[] nextMi() {
            return nextMi.clone();
        }

        byte[] lateEntryFragments() {
            return lateEntryFragments.clone();
        }
    }

    static void requireMatchingContinuousPrivacy(byte[] plain,
            byte[] candidate, byte[] key5, byte[] initialMi) throws IOException {
        byte[] expected = new DmrPrivacyStreamContext(key5, initialMi)
                .encrypt(plain);
        if (candidate == null || !Arrays.equals(expected, candidate)) {
            throw new IOException("连续privacy密文与有状态参考不一致");
        }
    }

    /** 仅离线使用的逐单元证据对象，不持有串口或设备句柄。 */
    static final class ContinuousData36Evidence {
        final int unitIndex;
        final int firstGlobalFrame;
        final String plainSha256;
        final String privacyBefore;
        final String encryptedSha256;
        final String requestSha256;
        final byte[] request44;
        final long flushCompletedAtMs;
        long creditEventSequence = -1L;
        long creditObservedAtMs = -1L;
        long creditLatencyMs = -1L;
        byte[] creditRaw = new byte[0];

        ContinuousData36Evidence(int unitIndex, int firstGlobalFrame,
                String plainSha256, String privacyBefore,
                String encryptedSha256, String requestSha256,
                byte[] request44, long flushCompletedAtMs) {
            this.unitIndex = unitIndex;
            this.firstGlobalFrame = firstGlobalFrame;
            this.plainSha256 = plainSha256;
            this.privacyBefore = privacyBefore;
            this.encryptedSha256 = encryptedSha256;
            this.requestSha256 = requestSha256;
            this.request44 = request44.clone();
            this.flushCompletedAtMs = flushCompletedAtMs;
        }
    }

    /**
     * v2.04失败关闭的连续发送纯离线模型。首单元只由第三个实时27字节单元放行；
     * 此后每个单元只由前一单元的新鲜post-flush credit放行。
     */
    static final class ContinuousData36TxModel {
        enum Phase {
            WAITING_REALTIME_TRIGGER,
            READY,
            WAITING_CREDIT,
            RECOVERY_REQUIRED,
            RECOVERED,
            FAILED
        }

        private final FrozenAmbeAsset asset;
        private final DmrPrivacyStreamContext privacy;
        private final int firstAssetUnit;
        private final int maximumUnits;
        private final List<ContinuousData36Evidence> evidence =
                new ArrayList<>();
        private Phase phase = Phase.WAITING_REALTIME_TRIGGER;
        private int realtimeUnitCount;
        private long lastFlushAtMs = -1L;
        private long lastCreditAtMs = -1L;
        private long lastCreditEventSequence = -1L;

        ContinuousData36TxModel(FrozenAmbeAsset asset,
                byte[] measuredRuntime14, int firstAssetUnit,
                int maximumUnits) {
            if (asset == null || maximumUnits <= 0 || firstAssetUnit < 0
                    || firstAssetUnit > asset.data36Count() - maximumUnits) {
                throw new IllegalArgumentException("连续发送资产范围或单元上限无效");
            }
            this.asset = asset;
            privacy = DmrPrivacyStreamContext.fromMeasuredRuntime(
                    measuredRuntime14);
            this.firstAssetUnit = firstAssetUnit;
            this.maximumUnits = maximumUnits;
        }

        Phase phase() {
            return phase;
        }

        void onRealtimeData27() {
            if (phase == Phase.FAILED || phase == Phase.RECOVERED
                    || phase == Phase.RECOVERY_REQUIRED) {
                fail();
                return;
            }
            realtimeUnitCount++;
            if (phase == Phase.WAITING_REALTIME_TRIGGER
                    && realtimeUnitCount == 3) {
                phase = Phase.READY;
            }
        }

        ContinuousData36Evidence writeNext(long flushCompletedAtMs)
                throws IOException {
            if (phase != Phase.READY || evidence.size() >= maximumUnits
                    || flushCompletedAtMs < 0
                    || flushCompletedAtMs < lastCreditAtMs) {
                fail();
                throw new IOException("连续发送当前状态禁止写出下一单元");
            }
            int unitIndex = firstAssetUnit + evidence.size();
            byte[] plain = asset.data36(unitIndex);
            String before = privacy.stateSummary();
            int firstFrame = privacy.globalFrameIndex();
            byte[] encrypted = privacy.encryptData36(plain);
            byte[] request = createExternalEncodedTxFrame(encrypted, 0);
            ContinuousData36Evidence record = new ContinuousData36Evidence(
                    unitIndex, firstFrame, requireSha256(plain), before,
                    requireSha256(encrypted), requireSha256(request), request,
                    flushCompletedAtMs);
            evidence.add(record);
            lastFlushAtMs = flushCompletedAtMs;
            phase = Phase.WAITING_CREDIT;
            return record;
        }

        boolean acceptCredit(long eventSequence, byte[] rawCredit,
                long observedAtMs) {
            if (phase != Phase.WAITING_CREDIT || evidence.isEmpty()
                    || eventSequence <= lastCreditEventSequence
                    || observedAtMs < lastFlushAtMs
                    || observedAtMs < lastCreditAtMs
                    || !isStrictPostSendExternalEncodedTxCredit(rawCredit)) {
                fail();
                return false;
            }
            ContinuousData36Evidence record = evidence.get(evidence.size() - 1);
            record.creditEventSequence = eventSequence;
            record.creditObservedAtMs = observedAtMs;
            record.creditLatencyMs = observedAtMs - record.flushCompletedAtMs;
            record.creditRaw = rawCredit.clone();
            lastCreditEventSequence = eventSequence;
            lastCreditAtMs = observedAtMs;
            phase = evidence.size() == maximumUnits
                    ? Phase.RECOVERY_REQUIRED : Phase.READY;
            return true;
        }

        boolean acceptTimeout() {
            fail();
            return false;
        }

        boolean finishRecovery(boolean restored) {
            if (phase != Phase.RECOVERY_REQUIRED || !restored) {
                fail();
                return false;
            }
            phase = Phase.RECOVERED;
            return true;
        }

        int writtenUnitCount() {
            return evidence.size();
        }

        int acceptedCreditCount() {
            int count = 0;
            for (ContinuousData36Evidence record : evidence) {
                if (record.creditEventSequence >= 0) {
                    count++;
                }
            }
            return count;
        }

        List<ContinuousData36Evidence> evidence() {
            return new ArrayList<>(evidence);
        }

        private void fail() {
            phase = Phase.FAILED;
        }
    }

    /**
     * 步骤4：握手 COMPLETE 之后仅允许发送1个由步骤2冻结unit0派生的固定密文。
     * 模型不持有 OutputStream；{@link #acceptWriteCompletedWithoutCredit}
     * 恒失败，防止把 Android 写成功当成模块接受。
     */
    static final class ExternalDmrStep4OneUnitModel {
        enum Phase {
            NEED_HANDSHAKE,
            READY,
            WAITING_CREDIT,
            ACCEPTED,
            FAILED
        }

        static final class ExchangeWindow {
            private final ExternalDmrStep4OneUnitModel owner;
            private final long sequence;
            private final byte[] request;
            private boolean consumed;

            private ExchangeWindow(ExternalDmrStep4OneUnitModel owner,
                    long sequence, byte[] request) {
                this.owner = owner;
                this.sequence = sequence;
                this.request = request.clone();
            }

            long sequence() {
                return sequence;
            }
        }

        private final byte[] frozenFrame;
        private Phase phase = Phase.NEED_HANDSHAKE;
        private long nextWindowSequence = 1;
        private ExchangeWindow activeWindow;

        private ExternalDmrStep4OneUnitModel(byte[] frozenFrame) {
            this.frozenFrame = frozenFrame.clone();
        }

        static ExternalDmrStep4OneUnitModel forVerifiedHostEncryptedUnit0() {
            try {
                return new ExternalDmrStep4OneUnitModel(
                        requireHostEncryptedExternalTxFrameUnit0());
            } catch (IOException error) {
                throw new IllegalStateException(
                        "无法构造privacy运行态的主机密文unit0: "
                                + error.getMessage(), error);
            }
        }

        Phase phase() {
            return phase;
        }

        void markHandshakeComplete() {
            if (phase != Phase.NEED_HANDSHAKE) {
                fail();
                return;
            }
            phase = Phase.READY;
        }

        byte[] expectedFrame() {
            if (phase != Phase.READY || activeWindow != null) {
                return null;
            }
            return frozenFrame.clone();
        }

        ExchangeWindow openPostSendWindow(byte[] request,
                QuietWindowProof quietWindowProof) {
            byte[] expected = expectedFrame();
            if (phase != Phase.READY || quietWindowProof == null
                    || !quietWindowProof.consumeFor(this)
                    || expected == null || request == null
                    || !Arrays.equals(request, expected)) {
                fail();
                return null;
            }
            activeWindow = new ExchangeWindow(this, nextWindowSequence++,
                    request);
            phase = Phase.WAITING_CREDIT;
            return activeWindow;
        }

        /**
         * 明确拒绝“只写成功”路径。任何调用都使本会话失败。
         */
        boolean acceptWriteCompletedWithoutCredit(ExchangeWindow window) {
            consumeActiveWindow(window);
            fail();
            return false;
        }

        boolean acceptCredit(ExchangeWindow window, byte[] rawCredit) {
            if (phase != Phase.WAITING_CREDIT
                    || !consumeActiveWindow(window)) {
                fail();
                return false;
            }
            // 严格 post-send 门：比“缓冲中任意位置存在 credit”更严，
            // 要求发送后首帧即为 credit，且整段可按完整帧边界走完。
            if (rawCredit == null
                    || !Arrays.equals(window.request, frozenFrame)
                    || !isStrictPostSendExternalEncodedTxCredit(rawCredit)) {
                fail();
                return false;
            }
            phase = Phase.ACCEPTED;
            return true;
        }

        boolean acceptTimeout(ExchangeWindow window) {
            consumeActiveWindow(window);
            fail();
            return false;
        }

        void fail() {
            if (activeWindow != null) {
                activeWindow.consumed = true;
                activeWindow = null;
            }
            phase = Phase.FAILED;
        }

        private boolean consumeActiveWindow(ExchangeWindow window) {
            if (window == null || window.owner != this || window.consumed
                    || window != activeWindow) {
                return false;
            }
            window.consumed = true;
            activeWindow = null;
            return true;
        }
    }

