    /**
     * 步骤4唯一真机数据单元执行器。前置状态、静默窗口、单次写入、flush和
     * 严格单credit均在同一处失败关闭；本方法没有任何循环或第二帧路径。
     */
    static ExternalDmrStep4OneUnitExecution executeExternalDmrStep4OneUnit(
            boolean bridgeActive, boolean handshakeComplete,
            boolean privacyRuntimeVerified, byte[] approvedEncryptedFrame,
            ExternalDmrStep4OneUnitIo io,
            ExternalDmrStep4OneUnitEvidence evidence,
            ExternalDmrStep4OneUnitExecution execution) throws Exception {
        return executeExternalDmrStep4OneUnit(bridgeActive, handshakeComplete,
                privacyRuntimeVerified, approvedEncryptedFrame, io, evidence,
                execution, true);
    }

    interface HpiFrameMatcher {
        boolean matches(byte[] frame);
    }

    static final class ActiveHpiRead {
        final byte[] observed;
        final byte[] matchedFrame;

        ActiveHpiRead(byte[] observed, byte[] matchedFrame) {
            this.observed = observed == null ? new byte[0] : observed.clone();
            this.matchedFrame = matchedFrame == null
                    ? null : matchedFrame.clone();
        }
    }

    /**
     * 主动TX期间的增量HPI帧路由器。它保留跨read的半帧，并只在完整帧边界
     * 建立请求时间边界；异步帧归入observed，匹配帧单独交给严格状态机。
     */
    static final class ActiveHpiStreamRouter {
        private byte[] carry = new byte[0];

        ActiveHpiRead drainToFrameBoundary(InputStream input, long timeoutMs)
                throws Exception {
            if (input == null || timeoutMs <= 0) {
                throw new IllegalArgumentException("活动HPI边界参数无效");
            }
            ByteArrayOutputStream observed = new ByteArrayOutputStream();
            long deadline = SystemClock.elapsedRealtime() + timeoutMs;
            while (true) {
                int frameLength = firstCompleteFrameLength(carry);
                if (frameLength > 0) {
                    observed.write(carry, 0, frameLength);
                    carry = Arrays.copyOfRange(carry, frameLength, carry.length);
                    continue;
                }
                if (carry.length == 0 && input.available() <= 0) {
                    return new ActiveHpiRead(observed.toByteArray(), null);
                }
                if (SystemClock.elapsedRealtime() >= deadline) {
                    throw new IOException("活动HPI流未在期限内到达完整帧边界，残留="
                            + carry.length);
                }
                readAvailableIntoCarry(input);
                SystemClock.sleep(2);
            }
        }

        ActiveHpiRead readUntil(InputStream input, long timeoutMs,
                HpiFrameMatcher matcher) throws Exception {
            if (input == null || timeoutMs <= 0 || matcher == null) {
                throw new IllegalArgumentException("活动HPI匹配参数无效");
            }
            ByteArrayOutputStream observed = new ByteArrayOutputStream();
            long deadline = SystemClock.elapsedRealtime() + timeoutMs;
            while (SystemClock.elapsedRealtime() < deadline) {
                int frameLength = firstCompleteFrameLength(carry);
                if (frameLength > 0) {
                    byte[] frame = Arrays.copyOfRange(carry, 0, frameLength);
                    carry = Arrays.copyOfRange(carry, frameLength, carry.length);
                    observed.write(frame);
                    if (matcher.matches(frame)) {
                        return new ActiveHpiRead(observed.toByteArray(), frame);
                    }
                    continue;
                }
                readAvailableIntoCarry(input);
                SystemClock.sleep(2);
            }
            return new ActiveHpiRead(observed.toByteArray(), null);
        }

        private void readAvailableIntoCarry(InputStream input) throws IOException {
            int available = input.available();
            if (available <= 0) {
                return;
            }
            byte[] chunk = new byte[Math.min(available, 4096)];
            int count = input.read(chunk);
            if (count > 0) {
                carry = concatBytes(carry, Arrays.copyOf(chunk, count));
                if (carry.length > 8192) {
                    throw new IOException("活动HPI路由缓冲超过8192字节");
                }
            }
        }

        static int firstCompleteFrameLength(byte[] raw)
                throws IOException {
            if (raw == null || raw.length == 0) {
                return 0;
            }
            if (raw.length < 6) {
                return 0;
            }
            if ((raw[0] & 0xff) != 0x84 || (raw[1] & 0xff) != 0xa9
                    || (raw[2] & 0xff) != 0x61) {
                throw new IOException("活动HPI流失去帧同步");
            }
            int payloadLength = ((raw[3] & 0xff) << 8) | (raw[4] & 0xff);
            int declared = 6 + payloadLength;
            int wire = declared + (declared & 1);
            if (wire > 4096) {
                throw new IOException("活动HPI帧声明长度异常: " + wire);
            }
            if (raw.length < wire) {
                return 0;
            }
            if (wire != declared && raw[declared] != 0) {
                throw new IOException("活动HPI帧补齐字节非零");
            }
            return wire;
        }
    }

    /**
     * setup发生在RF准备和异步语音流开始之前，必须沿用已验证的连续静默门。
     * 活动帧边界只允许VLC阶段及其后的持续HPI流使用。
     */
    static boolean shouldUseActiveFrameBoundary(boolean setupPhase,
            boolean activeRouterAvailable) {
        return !setupPhase && activeRouterAvailable;
    }

    static ExternalDmrStep4OneUnitExecution
            executeExternalDmrStep4OneUnit(
            boolean bridgeActive, boolean handshakeComplete,
            boolean privacyRuntimeVerified, byte[] approvedEncryptedFrame,
            ExternalDmrStep4OneUnitIo io,
            ExternalDmrStep4OneUnitEvidence evidence,
            ExternalDmrStep4OneUnitExecution execution,
            boolean requireHistoricalFrozenUnit0) throws Exception {
        if (!bridgeActive) {
            throw new IOException("步骤4写入前bridge未确认激活");
        }
        if (!handshakeComplete) {
            throw new IOException("步骤4写入前握手未完整完成");
        }
        if (!privacyRuntimeVerified) {
            throw new IOException("步骤4写入前privacy运行态未逐项验证");
        }
        if (io == null || evidence == null || execution == null) {
            throw new IllegalArgumentException("步骤4执行依赖不完整");
        }
        if (execution.writeAttempted || execution.writeCompleted
                || execution.creditShapeAccepted
                || execution.flushCompletedAtMs != -1L
                || execution.responseCapturedAtMs != -1L
                || execution.responseAfterFlushMs != -1L
                || execution.creditShape != null
                || execution.drainedRaw.length != 0
                || execution.responseRaw.length != 0) {
            throw new IOException("步骤4执行对象已使用，禁止第二次发送");
        }
        byte[] forbiddenPlainFrame = requirePlainExternalTxFrameUnit0();
        if (approvedEncryptedFrame != null
                && Arrays.equals(approvedEncryptedFrame, forbiddenPlainFrame)) {
            throw new IOException("步骤4拒绝明文帧，raw bridge绕过MCU普通privacy链");
        }
        if (approvedEncryptedFrame == null
                || !looksLikeExternalData36Frame(approvedEncryptedFrame)) {
            throw new IOException("步骤4只接受完整44字节加密data36信封");
        }
        if (requireHistoricalFrozenUnit0) {
            byte[] expectedEncryptedFrame =
                    requireHostEncryptedExternalTxFrameUnit0();
            if (!Arrays.equals(approvedEncryptedFrame,
                    expectedEncryptedFrame)) {
                throw new IOException("步骤4只接受冻结明文派生的固定哈希密文单元");
            }
        }
        ExternalDmrStep4OneUnitModel model = new ExternalDmrStep4OneUnitModel(
                approvedEncryptedFrame);
        model.markHandshakeComplete();
        byte[] frame = model.expectedFrame();
        if (frame == null || !looksLikeExternalData36Frame(frame)) {
            model.fail();
            throw new IOException("步骤4固定主机密文data36帧不可用");
        }

        QuietDrainResult quiet = io.establishQuietWindow();
        if (quiet == null) {
            model.fail();
            throw new IOException("步骤4静默窗口结果为空");
        }
        if (quiet.proof == null || !quiet.proof.isVerifiedCapture()
                || quiet.proof.quietDurationMs()
                < EXTERNAL_DMR_PRE_SEND_QUIET_MS) {
            model.fail();
            throw new IOException("步骤4缺少足量连续静默的真实证明");
        }
        execution.drainedRaw = quiet.raw.clone();
        evidence.onDrain(quiet.raw, quiet.elapsedMs);
        evidence.onWriteAttempt(frame.clone());
        execution.writeAttempted = true;
        io.write(frame.clone());
        io.flush();
        execution.writeCompleted = true;
        execution.flushCompletedAtMs = io.nowMs();
        if (execution.flushCompletedAtMs < quiet.proof.establishedAtMs()) {
            model.fail();
            throw new IOException("步骤4 flush 时刻早于静默窗口成立时刻");
        }
        evidence.onWriteComplete();

        ExternalDmrStep4OneUnitModel.ExchangeWindow window =
                model.openPostSendWindow(frame, quiet.proof);
        if (window == null) {
            throw new IOException("步骤4发送后接收窗口未建立");
        }
        byte[] response = io.readCredit();
        execution.responseCapturedAtMs = io.nowMs();
        execution.responseRaw = response == null
                ? new byte[0] : response.clone();
        evidence.onResponse(execution.responseRaw.clone());
        if (execution.responseCapturedAtMs < execution.flushCompletedAtMs) {
            model.fail();
            throw new IOException("步骤4响应捕获时刻早于flush完成时刻");
        }
        execution.responseAfterFlushMs = execution.responseCapturedAtMs
                - execution.flushCompletedAtMs;
        if (response == null || response.length == 0) {
            model.acceptTimeout(window);
            throw new IOException("步骤4短响应超时或为空");
        }
        execution.creditShape = parseStrictExternalEncodedTxCredit(response);
        if (!model.acceptCredit(window, response)) {
            throw new IOException("步骤4短响应未通过严格单帧credit门");
        }
        if (execution.creditShape == null) {
            model.fail();
            throw new IOException("步骤4短响应字段解析与严格门不一致");
        }
        execution.creditShapeAccepted = true;
        if (model.phase() != ExternalDmrStep4OneUnitModel.Phase.ACCEPTED
                || model.expectedFrame() != null) {
            model.fail();
            throw new IOException("步骤4单单元完成状态异常");
        }
        return execution;
    }

    /**
     * Offline-only model of the vendor analogue/FM VoiceIn TX contract. It has
     * no device writer. The first PCM block follows accepted CALL_START;
     * every later block requires one short 0/1 input credit.
     */
    static final class AnalogVoiceInTxModel {
        enum Compatibility {
            VENDOR_EXTENSION_UNCONFIRMED,
            CONTROL_ACKED_DATA_PLANE_UNCONFIRMED
        }

        enum Phase {
            CODEC_PAGE1_REG10,
            CODEC_PAGE1_REG3B,
            CODEC_PAGE0_REG56,
            CODEC_PAGE0_REG57,
            CODEC_PAGE0_REG58,
            VOICE_IN_ROUTE,
            PROCESS_MODE,
            WORK_MODE,
            SUB_AUDIO,
            CALL_START,
            FIRST_BLOCK_READY,
            WAITING_DATA_CREDIT,
            DATA_BLOCK_READY,
            STOP_CALL,
            WORK_MODE_IDLE,
            STOPPED,
            FAILED
        }

        private Phase phase = Phase.CODEC_PAGE1_REG10;
        private final byte[] subaudioFrame;
        private final byte[][] codecFrames;
        private int serializedBlocks;
        private Compatibility compatibility =
                Compatibility.VENDOR_EXTENSION_UNCONFIRMED;

        AnalogVoiceInTxModel() {
            this(0, 0, 0, 0, 10);
        }

        AnalogVoiceInTxModel(int outputCtType, int ctcssIndex,
                int dcsIndex, int dcsPolarity) {
            this(outputCtType, ctcssIndex, dcsIndex, dcsPolarity, 10);
        }

        AnalogVoiceInTxModel(int outputCtType, int ctcssIndex,
                int dcsIndex, int dcsPolarity, int codecGain) {
            subaudioFrame = createAnalogSubaudioFrame(outputCtType,
                    ctcssIndex, dcsIndex, dcsPolarity);
            codecFrames = createAnalogTxCodecFrames(codecGain);
        }

        Phase phase() {
            return phase;
        }

        int serializedBlocks() {
            return serializedBlocks;
        }

        Compatibility compatibility() {
            return compatibility;
        }

        byte[] expectedControlFrame() {
            switch (phase) {
                case CODEC_PAGE1_REG10:
                    return codecFrames[0].clone();
                case CODEC_PAGE1_REG3B:
                    return codecFrames[1].clone();
                case CODEC_PAGE0_REG56:
                    return codecFrames[2].clone();
                case CODEC_PAGE0_REG57:
                    return codecFrames[3].clone();
                case CODEC_PAGE0_REG58:
                    return codecFrames[4].clone();
                case VOICE_IN_ROUTE:
                    return createAnalogVoiceInRouteFrame();
                case PROCESS_MODE:
                    return createAnalogVoiceInProcessModeFrame();
                case WORK_MODE:
                    return createAnalogVoiceInWorkModeFrame();
                case SUB_AUDIO:
                    return subaudioFrame.clone();
                case CALL_START:
                    return createAnalogCallStartFrame();
                case STOP_CALL:
                    return createAnalogStopCallFrame();
                case WORK_MODE_IDLE:
                    return createAnalogWorkModeIdleFrame();
                default:
                    return null;
            }
        }

        boolean acceptControlResponse(byte[] request, byte[] response) {
            byte[] expected = expectedControlFrame();
            if (expected == null || !Arrays.equals(request, expected)) {
                return false;
            }
            boolean codecWrite = (request[5] & 0xff) == 0x40;
            boolean accepted = codecWrite
                    ? containsAnalogCodecWriteAck(response)
                    : containsAnalogControlAck(response, request);
            if (!accepted) {
                phase = Phase.FAILED;
                return false;
            }
            switch (phase) {
                case CODEC_PAGE1_REG10:
                    phase = Phase.CODEC_PAGE1_REG3B;
                    break;
                case CODEC_PAGE1_REG3B:
                    phase = Phase.CODEC_PAGE0_REG56;
                    break;
                case CODEC_PAGE0_REG56:
                    phase = Phase.CODEC_PAGE0_REG57;
                    break;
                case CODEC_PAGE0_REG57:
                    phase = Phase.CODEC_PAGE0_REG58;
                    break;
                case CODEC_PAGE0_REG58:
                    phase = Phase.VOICE_IN_ROUTE;
                    break;
                case VOICE_IN_ROUTE:
                    compatibility = Compatibility.CONTROL_ACKED_DATA_PLANE_UNCONFIRMED;
                    phase = Phase.PROCESS_MODE;
                    break;
                case PROCESS_MODE:
                    phase = Phase.WORK_MODE;
                    break;
                case WORK_MODE:
                    phase = Phase.SUB_AUDIO;
                    break;
                case SUB_AUDIO:
                    phase = Phase.CALL_START;
                    break;
                case CALL_START:
                    phase = Phase.FIRST_BLOCK_READY;
                    break;
                case STOP_CALL:
                    phase = Phase.WORK_MODE_IDLE;
                    break;
                case WORK_MODE_IDLE:
                    phase = Phase.STOPPED;
                    break;
                default:
                    throw new AssertionError("Unhandled analogue VoiceIn control");
            }
            return true;
        }

        boolean acceptDataCredit(byte[] raw) {
            if (phase != Phase.WAITING_DATA_CREDIT
                    || !containsAnalogVoiceInCredit(raw)) {
                return false;
            }
            phase = Phase.DATA_BLOCK_READY;
            return true;
        }

        byte[] serializeNextBlock(byte[] pcmS16Le, int blockIndex) {
            if (phase != Phase.FIRST_BLOCK_READY
                    && phase != Phase.DATA_BLOCK_READY) {
                throw new IllegalStateException(
                        "First block requires CALL_START; later blocks require credit");
            }
            byte[] frame = createAnalogVoiceInPcmFrame(pcmS16Le, blockIndex);
            serializedBlocks++;
            phase = Phase.WAITING_DATA_CREDIT;
            return frame;
        }

        void fail() {
            phase = Phase.FAILED;
        }

        boolean requestStop() {
            if (phase != Phase.FIRST_BLOCK_READY
                    && phase != Phase.WAITING_DATA_CREDIT
                    && phase != Phase.DATA_BLOCK_READY) {
                return false;
            }
            phase = Phase.STOP_CALL;
            return true;
        }

        void recover() {
            phase = Phase.CODEC_PAGE1_REG10;
            serializedBlocks = 0;
            compatibility = Compatibility.VENDOR_EXTENSION_UNCONFIRMED;
        }
    }

    static final class PowerCalibrationAnchor {
        final long frequencyHz;
        final int dacCode;

        PowerCalibrationAnchor(long frequencyHz, int dacCode) {
            this.frequencyHz = frequencyHz;
            this.dacCode = dacCode;
        }
    }

    /** Parse one immutable 412-byte RF calibration snapshot. */
    static PowerCalibrationAnchor[] parsePowerCalibrationTable(byte[] record,
            boolean highPower) {
        if (record == null || record.length != RF_CALIBRATION_RECORD_BYTES) {
            throw new IllegalArgumentException("RF calibration record must be 412 bytes");
        }
        if ((int) u32leUnsigned(record, 0) != RF_CALIBRATION_MAGIC) {
            throw new IllegalArgumentException("RF calibration magic mismatch");
        }
        int countOffset = highPower
                ? POWER_HIGH_COUNT_OFFSET : POWER_LOW_COUNT_OFFSET;
        int tableOffset = highPower
                ? POWER_HIGH_TABLE_OFFSET : POWER_LOW_TABLE_OFFSET;
        int count = record[countOffset] & 0xff;
        if (count < 1 || count > MAX_POWER_ANCHORS) {
            throw new IllegalArgumentException("Power anchor count outside 1..8");
        }
        PowerCalibrationAnchor[] anchors = new PowerCalibrationAnchor[count];
        long priorFrequency = -1;
        for (int index = 0; index < count; index++) {
            int offset = tableOffset + index * POWER_ANCHOR_BYTES;
            long frequency = u32leUnsigned(record, offset);
            int dacCode = u16le(record, offset + 4);
            if (frequency <= priorFrequency) {
                throw new IllegalArgumentException("Power frequencies must increase");
            }
            anchors[index] = new PowerCalibrationAnchor(frequency, dacCode);
            priorFrequency = frequency;
        }
        return anchors;
    }

    /** Select the same discrete nearest anchor as the production midpoint code. */
    static int selectNearestPowerCode(PowerCalibrationAnchor[] anchors,
            long frequencyHz) {
        if (anchors == null || anchors.length == 0) {
            throw new IllegalArgumentException("At least one power anchor is required");
        }
        for (int index = 1; index < anchors.length; index++) {
            if (anchors[index].frequencyHz <= anchors[index - 1].frequencyHz) {
                throw new IllegalArgumentException("Power frequencies must increase");
            }
        }
        if (frequencyHz <= anchors[0].frequencyHz) {
            return anchors[0].dacCode;
        }
        for (int index = 0; index + 1 < anchors.length; index++) {
            long current = anchors[index].frequencyHz;
            long next = anchors[index + 1].frequencyHz;
            long midpoint = current + ((next - current) >>> 1);
            if (frequencyHz <= midpoint) {
                return anchors[index].dacCode;
            }
        }
        return anchors[anchors.length - 1].dacCode;
    }

    private static LocalChanDInjection injectLocalChanD(InputStream input,
            OutputStream output, byte[] source, int unitCount) throws Exception {
        if (unitCount < 1 || source == null
                || source.length < unitCount * LOCAL_CHAN_D_UNIT_BYTES) {
            throw new IllegalArgumentException("Insufficient CHAN_D units");
        }
        ByteArrayOutputStream raw = new ByteArrayOutputStream(64 * 1024);
        int acked = 0;
        int sentBytes = 0;
        long maxAckLatencyMs = 0;
        for (int unit = 0; unit < unitCount; unit++) {
            byte[] frame = createChanDInputFrame(source, unit);
            long sentAt = SystemClock.elapsedRealtime();
            output.write(frame);
            output.flush();
            sentBytes += frame.length;
            byte[] response = readUntilLocalChanDBackpressure(input,
                    LOCAL_CHAN_D_ACK_TIMEOUT_MS);
            raw.write(response);
            if (containsBytes(response, HPI_ERROR_PROCESSING_FIELD)) {
                break;
            }
            if (!containsLocalChanDBackpressure(response)) {
                break;
            }
            long latencyMs = SystemClock.elapsedRealtime() - sentAt;
            maxAckLatencyMs = Math.max(maxAckLatencyMs, latencyMs);
            acked++;
        }
        raw.write(readForDuration(input, LOCAL_CHAN_D_TAIL_CAPTURE_MS));
        return new LocalChanDInjection(raw.toByteArray(), acked, sentBytes,
                maxAckLatencyMs);
    }

    private static byte[] readUntilShortHpiResponse(InputStream input,
            long timeoutMs) throws Exception {
        ByteArrayOutputStream raw = new ByteArrayOutputStream(2048);
        byte[] buffer = new byte[8192];
        long deadline = SystemClock.elapsedRealtime() + timeoutMs;
        while (SystemClock.elapsedRealtime() < deadline) {
            int available = input.available();
            if (available > 0) {
                int count = input.read(buffer, 0,
                        Math.min(buffer.length, available));
                if (count > 0) {
                    raw.write(buffer, 0, count);
                    if (containsShortHpiResponse(raw.toByteArray())) {
                        break;
                    }
                    continue;
                }
            }
            SystemClock.sleep(1);
        }
        return raw.toByteArray();
    }

    /**
     * Vendor DMR_T2 treats type 0x20, body 0x01 as the CH_D input credit.
     * It is a data-plane backpressure response, not a generic control ACK.
     */
    private static byte[] readUntilLocalChanDBackpressure(InputStream input,
            long timeoutMs) throws Exception {
        ByteArrayOutputStream raw = new ByteArrayOutputStream(2048);
        byte[] buffer = new byte[8192];
        long deadline = SystemClock.elapsedRealtime() + timeoutMs;
        while (SystemClock.elapsedRealtime() < deadline) {
            int available = input.available();
            if (available > 0) {
                int count = input.read(buffer, 0,
                        Math.min(buffer.length, available));
                if (count > 0) {
                    raw.write(buffer, 0, count);
                    if (containsLocalChanDBackpressure(raw.toByteArray())) {
                        break;
                    }
                    continue;
                }
            }
            SystemClock.sleep(1);
        }
        return raw.toByteArray();
    }

    static boolean containsShortHpiResponse(byte[] raw) {
        if (raw == null) {
            return false;
        }
        for (int offset = 0; offset + 7 <= raw.length; offset++) {
            if ((raw[offset] & 0xff) != 0x84
                    || (raw[offset + 1] & 0xff) != 0xa9
                    || (raw[offset + 2] & 0xff) != 0x61) {
                continue;
            }
            int payloadLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            int packetType = raw[offset + 5] & 0xff;
            if ((packetType == 0 || packetType == 2 || packetType == 3
                    || packetType == 5)
                    && (payloadLength == 1 || payloadLength == 2)
                    && offset + 6 + payloadLength <= raw.length) {
                return true;
            }
        }
        return false;
    }

    static boolean containsLocalChanDBackpressure(byte[] raw) {
        if (raw == null) {
            return false;
        }
        for (int offset = 0; offset + 7 <= raw.length; offset++) {
            if ((raw[offset] & 0xff) != 0x84
                    || (raw[offset + 1] & 0xff) != 0xa9
                    || (raw[offset + 2] & 0xff) != 0x61) {
                continue;
            }
            int payloadLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            if ((raw[offset + 5] & 0xff) == 0x20
                    && (payloadLength == 1 || payloadLength == 2)
                    && offset + 6 + payloadLength <= raw.length
                    && (raw[offset + 6] & 0xff) == 0x01) {
                return true;
            }
        }
        return false;
    }

    /** 严格识别H13实测的36线字节、27载荷字节CHAN_D输出帧。 */
    static boolean isStrictChanD27Frame(byte[] frame) {
        return frame != null && frame.length == 36
                && (frame[0] & 0xff) == 0x84
                && (frame[1] & 0xff) == 0xa9
                && (frame[2] & 0xff) == 0x61
                && (frame[3] & 0xff) == 0x00
                && (frame[4] & 0xff) == 0x1d
                && (frame[5] & 0xff) == 0x20
                && (frame[6] & 0xff) == 0x01
                && (frame[7] & 0xff) == 0x1b
                && frame[35] == 0;
    }

    /**
     * The vendor external-TX stream dispatches only a complete one/two-byte
     * response whose first body byte is 0 or 1. Packet type is intentionally
     * not constrained: the vendor parser gates on this short-body contract.
     *
     * Unlike the vendor ReadRespond(), this method receives a raw stream that
     * can contain several frames. Walk only declared frame boundaries so an
     * HPI-looking byte sequence inside a data payload cannot create credit.
     */
    static boolean containsExternalEncodedTxCredit(byte[] raw) {
        return extractFirstExternalEncodedTxCreditFrame(raw) != null;
    }

    /**
     * 步骤4 post-send 严格 credit 门：
     * 1) 缓冲必须恰好包含一个完整HPI线帧（无前导噪声、无截断尾、补齐正确）；
     * 2) 该帧必须是vendor短credit（payload 1/2，首body 0/1）；
     * 3) 不声称射频或注入语义。
     */
    static boolean isStrictPostSendExternalEncodedTxCredit(byte[] raw) {
        return parseStrictExternalEncodedTxCredit(raw) != null;
    }

    /**
     * 步骤4严格短响应的字段级证据。packet type只记录、不附加未经证明的语义门。
     */
    static final class ExternalEncodedTxCreditShape {
        final int packetType;
        final int payloadLength;
        final int responseValue;
        final int secondPayloadByte;
        final int declaredFrameLength;
        final int wireLength;
        final boolean paddingPresent;

        private ExternalEncodedTxCreditShape(int packetType, int payloadLength,
                int responseValue, int secondPayloadByte,
                int declaredFrameLength, int wireLength,
                boolean paddingPresent) {
            this.packetType = packetType;
            this.payloadLength = payloadLength;
            this.responseValue = responseValue;
            this.secondPayloadByte = secondPayloadByte;
            this.declaredFrameLength = declaredFrameLength;
            this.wireLength = wireLength;
            this.paddingPresent = paddingPresent;
        }
    }

    static ExternalEncodedTxCreditShape parseStrictExternalEncodedTxCredit(
            byte[] raw) {
        List<HpiWireFrame> frames = parseCompleteHpiWireFrames(raw);
        if (frames == null || frames.size() != 1) {
            return null;
        }
        HpiWireFrame frame = frames.get(0);
        if (!isExternalEncodedTxCreditPayload(raw, frame.offset,
                frame.payloadLength)) {
            return null;
        }
        return new ExternalEncodedTxCreditShape(
                raw[frame.offset + 5] & 0xff,
                frame.payloadLength,
                raw[frame.offset + 6] & 0xff,
                frame.payloadLength == 2 ? raw[frame.offset + 7] & 0xff : -1,
                frame.declaredLength,
                frame.wireLength,
                frame.wireLength != frame.declaredLength);
    }

    private static boolean isExternalEncodedTxCreditPayload(byte[] raw,
            int offset, int payloadLength) {
        if (payloadLength != 1 && payloadLength != 2) {
            return false;
        }
        if (offset + 6 >= raw.length) {
            return false;
        }
        int response = raw[offset + 6] & 0xff;
        return response == 0 || response == 1;
    }

    /**
     * 沿完整 HPI 帧边界提取首个 vendor 短 credit 帧（payload 长 1 或 2，
     * 首 body 字节为 0 或 1）。找不到返回 null。不声称射频语义。
     */
    static byte[] extractFirstExternalEncodedTxCreditFrame(byte[] raw) {
        List<HpiWireFrame> frames = parseCompleteHpiWireFrames(raw);
        if (frames == null) {
            return null;
        }
        for (HpiWireFrame frame : frames) {
            if (isExternalEncodedTxCreditPayload(raw, frame.offset,
                    frame.payloadLength)) {
                return Arrays.copyOfRange(raw, frame.offset,
                        frame.offset + frame.wireLength);
            }
        }
        return null;
    }

    static boolean containsAnalogVoiceInCredit(byte[] raw) {
        return containsExternalEncodedTxCredit(raw);
    }

    /**
     * VLC/session 同步确认。
     * <p>
     * 静态/夹具期望：单帧 packet type 5、body {@code 0x43}。
     * 2026-08-10 步骤3真机 vlc0：首帧为 type {@code 0x20}、body {@code 0x43}，
     * 其后可粘连更多 type {@code 0x20} 事件帧。因此：
     * <ul>
     *   <li>必须完整解析 HPI 线流；</li>
     *   <li>首帧 payload 长度 1、首字节 0x43；</li>
     *   <li>packet type 允许 5（夹具）或 0x20（本机实测）；</li>
     *   <li>允许首帧后附加完整帧，但不得把 0x43 当 data36 credit。</li>
     * </ul>
     */
    static boolean containsDmrVlcSessionAck(byte[] raw) {
        List<HpiWireFrame> frames = parseCompleteHpiWireFrames(raw);
        if (frames == null || frames.isEmpty()) {
            return false;
        }
        // 真机 v1.67：vlc1 响应先到 CHAN_D/事件，后到 type0x20 body 0x43。
        // 必须在任意完整帧中找 ACK，不得只认首帧。
        for (HpiWireFrame frame : frames) {
            if (frame.payloadLength != 1) {
                continue;
            }
            if ((raw[frame.offset + 6] & 0xff) != 0x43) {
                continue;
            }
            int packetType = raw[frame.offset + 5] & 0xff;
            if (packetType == 5 || packetType == 0x20) {
                return true;
            }
        }
        return false;
    }



    private static long u32leUnsigned(byte[] value, int offset) {
        return ((long) value[offset] & 0xff)
                | (((long) value[offset + 1] & 0xff) << 8)
                | (((long) value[offset + 2] & 0xff) << 16)
                | (((long) value[offset + 3] & 0xff) << 24);
    }

    static final class LocalChanDInjection {
        final byte[] raw;
        final int ackedUnits;
        final int sentBytes;
        final long maxAckLatencyMs;

        LocalChanDInjection(byte[] raw, int ackedUnits, int sentBytes,
                long maxAckLatencyMs) {
            this.raw = raw;
            this.ackedUnits = ackedUnits;
            this.sentBytes = sentBytes;
            this.maxAckLatencyMs = maxAckLatencyMs;
        }
    }

    private static byte[] createSpeechSamplesFrame(byte[] pcm) {
        if (pcm.length != 1280) {
            throw new IllegalArgumentException("PCM payload must be 1280 bytes");
        }
        byte[] payload = new byte[3 + pcm.length];
        payload[0] = 0x00;
        payload[1] = 0x02;
        payload[2] = (byte) 0x80;
        System.arraycopy(pcm, 0, payload, 3, pcm.length);
        return createPaddedHpiFrame(2, payload);
    }

    private static boolean mode0ReloadAccepted(byte[] response) {
        return containsAscii(response, "+DMOSTARTUP:0")
                || containsAscii(response, "sct3258 change protocol cmp")
                || containsAscii(response, "change protocol cmp");
    }

    private static int countOccurrences(byte[] value, byte[] token) {
        int count = 0;
        int offset = 0;
        while (offset <= value.length - token.length) {
            int found = indexOf(value, token, offset);
            if (found < 0) {
                break;
            }
            count++;
            offset = found + token.length;
        }
        return count;
    }

    private static int indexOf(byte[] value, byte[] token, int start) {
        for (int offset = start; offset <= value.length - token.length; offset++) {
            boolean match = true;
            for (int index = 0; index < token.length; index++) {
                if (value[offset + index] != token[index]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                return offset;
            }
        }
        return -1;
    }

    private static TimedHpiCapture captureFirstCompleteHpiFrame(InputStream input,
            long timeoutMs, long sentAtNanos) throws Exception {
        ByteArrayOutputStream raw = new ByteArrayOutputStream(64);
        byte[] buffer = new byte[2048];
        long deadline = SystemClock.elapsedRealtime() + timeoutMs;
        while (SystemClock.elapsedRealtime() < deadline) {
            int available = input.available();
            if (available <= 0) {
                SystemClock.sleep(1);
                continue;
            }
            int count = input.read(buffer, 0, Math.min(buffer.length, available));
            if (count <= 0) {
                continue;
            }
            raw.write(buffer, 0, count);
            byte[] current = raw.toByteArray();
            int end = firstCompleteHpiFrameEnd(current);
            if (end > 0) {
                long elapsedUs = (SystemClock.elapsedRealtimeNanos()
                        - sentAtNanos) / 1000L;
                return new TimedHpiCapture(current, end, elapsedUs);
            }
        }
        return new TimedHpiCapture(raw.toByteArray(), -1, -1);
    }

    private static int firstCompleteHpiFrameEnd(byte[] raw) {
        for (int offset = 0; offset + 6 <= raw.length; offset++) {
            if ((raw[offset] & 0xff) != 0x84
                    || (raw[offset + 1] & 0xff) != 0xa9
                    || (raw[offset + 2] & 0xff) != 0x61) {
                continue;
            }
            int payloadLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            if (payloadLength > 4096) {
                continue;
            }
            int end = offset + 6 + payloadLength;
            if (end <= raw.length) {
                return end;
            }
        }
        return -1;
    }

    private static boolean isShortPcmBackpressureResponse(byte[] raw) {
        for (int offset = 0; offset + 6 <= raw.length; offset++) {
            if ((raw[offset] & 0xff) != 0x84
                    || (raw[offset + 1] & 0xff) != 0xa9
                    || (raw[offset + 2] & 0xff) != 0x61) {
                continue;
            }
            int payloadLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            int packetType = raw[offset + 5] & 0xff;
            return (packetType == 0 || packetType == 2
                    || packetType == 3 || packetType == 5)
                    && (payloadLength == 1 || payloadLength == 2)
                    && offset + 6 + payloadLength <= raw.length;
        }
        return false;
    }

    private static int bridgeTicks(double tickRateHz, long windowMs)
            throws Exception {
        long ticks = Math.round(tickRateHz * (windowMs + 2500L) / 1000.0);
        if (ticks < 50 || ticks > 0x7fffffffL) {
            throw new IOException("Bridge timeout counter out of range: " + ticks);
        }
        return (int) ticks;
    }

    private long armBridge(InputStream input, OutputStream output,
            int timeoutTicks) throws Exception {
        writeMemoryWord(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS, 0);
        writeMemoryWord(input, output,
                UART_HPI_TIMEOUT_COUNTER_ADDRESS, timeoutTicks);
        writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                UART_HPI_TIMEOUT_ENTRY);
        synchronized (lock) {
            // closeLocked must never send ASCII while the UART is bridged to SCT HPI.
            logLevelMayBeEnabled = false;
        }
        writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
        return SystemClock.elapsedRealtime();
    }

    private static BridgeRecovery awaitBridgeRecovery(InputStream input,
            OutputStream output, long armedAt, long windowMs) throws Exception {
        long safeReadAt = armedAt + windowMs + 4500L;
        long remaining = safeReadAt - SystemClock.elapsedRealtime();
        if (remaining > 0) {
            SystemClock.sleep(remaining);
        }
        return readBridgeRecovery(input, output);
    }

    private static BridgeRecovery readBridgeRecovery(InputStream input,
            OutputStream output) throws Exception {
        byte[] flag = readMemory(input, output,
                UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
        byte[] vector = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
        byte[] counter = readMemory(input, output,
                UART_HPI_TIMEOUT_COUNTER_ADDRESS, 4);
        byte[] marker = readMemory(input, output,
                UART_HPI_TIMEOUT_MARKER_ADDRESS, 4);
        return new BridgeRecovery(flag[0] & 0xff,
                u32le(vector, 0), u32le(counter, 0), u32le(marker, 0));
    }

    private static byte[] reloadMode0(InputStream input, OutputStream output)
            throws Exception {
        drainAvailable(input);
        writeCommand(output, SCT_RELOAD_BASELINE_COMMAND);
        return readForDuration(input, 9000);
    }

    private File uniqueFile(String prefix, String suffix) throws Exception {
        for (int attempt = 0; attempt < 1000; attempt++) {
            File file = new File(outputDirectory, prefix
                    + System.currentTimeMillis()
                    + (attempt == 0 ? "" : "_" + attempt) + suffix);
            if (!file.exists()) {
                return file;
            }
        }
        throw new IOException("Unable to allocate unique capture filename");
    }

    private static FlashPageResult readFlashPage(InputStream input,
            OutputStream output, int address) throws Exception {
        FlashPageResult result = captureFlashPage(input, output, address);
        requireFlashPageData(result, address);
        return result;
    }

    private static FlashPageResult captureFlashPage(InputStream input,
            OutputStream output, int address) throws Exception {
        if (address < 0 || address + SCT_FLASH_PAGE_SIZE > 0x1000000) {
            throw new IllegalArgumentException("Flash address out of 24-bit range");
        }
        byte[] request = createPaddedHpiFrame(0x23, new byte[] {
                (byte) 0x94,
                (byte) (address >>> 16),
                (byte) (address >>> 8),
                (byte) address,
                (byte) SCT_FLASH_PAGE_SIZE
        });
        output.write(request);
        output.flush();

        ByteArrayOutputStream raw = new ByteArrayOutputStream(96);
        byte[] buffer = new byte[256];
        long deadline = SystemClock.elapsedRealtime() + SCT_FLASH_PAGE_TIMEOUT_MS;
        while (SystemClock.elapsedRealtime() < deadline) {
            int available = input.available();
            if (available > 0) {
                int count = input.read(buffer, 0, Math.min(buffer.length, available));
                if (count > 0) {
                    raw.write(buffer, 0, count);
                    byte[] current = raw.toByteArray();
                    byte[] data = extractFlashData64(current);
                    if (data != null) {
                        return new FlashPageResult(data, current);
                    }
                }
            } else {
                SystemClock.sleep(1);
            }
        }
        byte[] response = raw.toByteArray();
        return new FlashPageResult(null, response);
    }

    private static void requireFlashPageData(FlashPageResult result, int address)
            throws IOException {
        if (result.data != null) {
            return;
        }
        throw new IOException(String.format(Locale.US,
                "No valid Flash response at 0x%06x (raw=%d, prefix=%s)",
                address, result.raw.length,
                hex(Arrays.copyOf(result.raw, Math.min(result.raw.length, 32)))));
    }

    private File preserveRawEvidence(StringBuilder report, String label,
            String filePrefix, byte[] raw) throws Exception {
        File file = uniqueFile(filePrefix, ".bin");
        writeFile(file, raw);
        appendRaw(report, label, raw);
        append(report, label + " bytes", raw.length);
        append(report, label + " file", file.getAbsolutePath());
        return file;
    }

    /** 保存大文件原件，只在报告写长度、哈希和路径，避免logcat截断。 */
    private File preserveRawEvidenceSummary(StringBuilder report, String label,
            String filePrefix, byte[] raw) throws Exception {
        File file = uniqueFile(filePrefix, ".bin");
        writeFile(file, raw);
        append(report, label + " bytes", raw.length);
        append(report, label + " SHA-256", sha256(raw));
        append(report, label + " file", file.getAbsolutePath());
        return file;
    }

    private static void appendStep3Transcript(ByteArrayOutputStream transcript,
            long elapsedUs, int direction, String label, byte[] raw)
            throws IOException {
        byte[] labelBytes = label.getBytes(StandardCharsets.UTF_8);
        if (labelBytes.length > 0xffff) {
            throw new IOException("步骤3时序标签过长");
        }
        transcript.write(new byte[] {'S', '3', 'R', '1'});
        for (int shift = 0; shift < 64; shift += 8) {
            transcript.write((byte) (elapsedUs >>> shift));
        }
        transcript.write(direction & 0xff);
        transcript.write(labelBytes.length & 0xff);
        transcript.write((labelBytes.length >>> 8) & 0xff);
        int rawLength = raw != null ? raw.length : 0;
        for (int shift = 0; shift < 32; shift += 8) {
            transcript.write((rawLength >>> shift) & 0xff);
        }
        transcript.write(labelBytes);
        if (raw != null) {
            transcript.write(raw);
        }
    }

    private boolean bestEffortStep3ControlPlaneReload(InputStream input,
            OutputStream output, StringBuilder report) {
        if (input == null || output == null) {
            append(report, "restore.step.finallyControlReload",
                    "fail: null streams");
            return false;
        }
        try {
            reloadSctBaselineTrafficPlane(input, output, report, 1);
            return true;
        } catch (Throwable error) {
            String msg = error.getMessage() != null ? error.getMessage() : "";
            append(report, "restore.step.finallyControlReload",
                    "fail: " + error.getClass().getSimpleName() + ": " + msg);
            append(report, "controlPlaneRestored", false);
            Log.w(TAG, "步骤3单次控制面reload失败", error);
            return false;
        }
    }

    private static void recordStep3Evidence(List<Step3EvidenceRecord> records,
            ByteArrayOutputStream transcript, long transcriptStartedNanos,
            int direction, String label, String filePrefix, byte[] raw,
            boolean preserveSeparately) throws IOException {
        long elapsedUs = Math.max(0L,
                (monotonicNowNanos() - transcriptStartedNanos) / 1000L);
        byte[] safeRaw = raw != null ? raw : new byte[0];
        appendStep3Transcript(transcript, elapsedUs, direction, label, safeRaw);
        if (preserveSeparately) {
            records.add(new Step3EvidenceRecord(label, filePrefix, safeRaw));
        }
    }

    private static void queueStep3SramEvidence(
            List<Step3EvidenceRecord> records, String stage,
            String field, int address, byte[] raw) throws IOException {
        if (records == null || stage == null || stage.isEmpty()
                || field == null || field.isEmpty() || raw == null) {
            throw new IOException("SRAM证据记录参数不完整");
        }
        String addressText = String.format(Locale.US, "0x%08x", address);
        String label = "SRAM " + stage + " " + field + " @" + addressText;
        String prefix = "h13_ext_dmr_sram_" + stage + "_" + field
                + "_" + addressText + "_";
        records.add(new Step3EvidenceRecord(label, prefix, raw,
                stage, address));
    }

    private static void queueStep3SramSnapshot(
            List<Step3EvidenceRecord> records, String stage,
            byte[] combinedCode, byte[] prepMarker, byte[] prepCounter,
            byte[] absCounter, byte[] exitMarker, byte[] prepPhase,
            byte[] prepCursor, byte[] mirrorCode, byte[] runtimeMirror,
            byte[] dataGate, byte[] sessionState,
            byte[] ptrA, byte[] ptrB, byte[] flag1c, byte[] count,
            byte[] queueA, byte[] queueB, byte[] vector, byte[] bridgeFlag,
            byte[] bootReady, byte[] bootMode)
            throws IOException {
        queueStep3SramEvidence(records, stage, "combined_code",
                COMBINED_DUAL_COUNTER_CODE_ADDRESS, combinedCode);
        queueStep3SramEvidence(records, stage, "prep_marker",
                COMBINED_PREP_MARKER_ADDRESS, prepMarker);
        queueStep3SramEvidence(records, stage, "prep_counter",
                COMBINED_PREP_COUNTER_ADDRESS, prepCounter);
        queueStep3SramEvidence(records, stage, "abs_counter",
                COMBINED_ABS_COUNTER_ADDRESS, absCounter);
        queueStep3SramEvidence(records, stage, "exit_marker",
                COMBINED_EXIT_MARKER_ADDRESS, exitMarker);
        queueStep3SramEvidence(records, stage, "prep_phase",
                COMBINED_PREP_PHASE_ADDRESS, prepPhase);
        queueStep3SramEvidence(records, stage, "prep_cursor",
                COMBINED_PREP_CURSOR_ADDRESS, prepCursor);
        queueStep3SramEvidence(records, stage, "mirror_code",
                RUNTIME_MIRROR_HELPER_ADDRESS, mirrorCode);
        queueStep3SramEvidence(records, stage, "runtime_mirror",
                RUNTIME_MIRROR_ADDRESS, runtimeMirror);
        queueStep3SramEvidence(records, stage, "data_gate",
                EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, dataGate);
        queueStep3SramEvidence(records, stage, "session_state",
                EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, sessionState);
        queueStep3SramEvidence(records, stage, "session_ptr_a",
                EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, ptrA);
        queueStep3SramEvidence(records, stage, "session_ptr_b",
                EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, ptrB);
        queueStep3SramEvidence(records, stage, "session_flag_1c",
                EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, flag1c);
        queueStep3SramEvidence(records, stage, "session_count",
                EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, count);
        queueStep3SramEvidence(records, stage, "queue_a",
                EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS, queueA);
        queueStep3SramEvidence(records, stage, "queue_b",
                EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS, queueB);
        queueStep3SramEvidence(records, stage, "systick_vector",
                RAM_VECTOR_SYSTICK, vector);
        queueStep3SramEvidence(records, stage, "bridge_flag",
                UART_HPI_BRIDGE_FLAG_ADDRESS, bridgeFlag);
        // v1.95：只读 E4/E5 进入四相证据；禁止写回/改 settle。
        queueStep3SramEvidence(records, stage, "boot_ready",
                SCT_BOOT_READY_ADDRESS, bootReady);
        queueStep3SramEvidence(records, stage, "boot_mode",
                SCT_BOOT_MODE_ADDRESS, bootMode);
    }

    private void persistStep3Evidence(List<Step3EvidenceRecord> records,
            ByteArrayOutputStream transcript, StringBuilder report) throws Exception {
        for (Step3EvidenceRecord record : records) {
            preserveRawEvidence(report, record.label, record.filePrefix, record.raw);
            if (record.sramAddress >= 0) {
                append(report, record.label + " 阶段", record.sramStage);
                append(report, record.label + " 地址",
                        String.format(Locale.US, "0x%08x",
                                record.sramAddress));
                append(report, record.label + " 长度", record.raw.length);
                append(report, record.label + " SHA-256", sha256(record.raw));
            }
        }
        byte[] transcriptBytes = transcript.toByteArray();
        File transcriptFile = uniqueFile("h13_ext_dmr_step3_transcript_", ".bin");
        writeFile(transcriptFile, transcriptBytes);
        append(report, "Step3 transcript format", "S3R1有向分帧时序");
        append(report, "Step3 transcript directions",
                "1=发送尝试，2=接收，3=发送前排空，4=发送完成");
        append(report, "Step3 separately preserved records", records.size());
        append(report, "Step3 transcript bytes", transcriptBytes.length);
        append(report, "Step3 transcript SHA-256", sha256(transcriptBytes));
        append(report, "Step3 transcript file", transcriptFile.getAbsolutePath());
    }

    private boolean bestEffortHardwareEncoderControlPlaneReload(
            InputStream input, OutputStream output, StringBuilder report,
            String originalDigitalChannel) {
        if (input == null || output == null) {
            append(report, "restore.step.finallyControlReload",
                    "fail: null streams");
            return false;
        }
        if (originalDigitalChannel == null) {
            append(report, "restore.step.finallyControlReload",
                    "fail: 缺少实测原频道");
            return false;
        }
        try {
            reloadSctBaselineTrafficPlanePreservingDigitalChannel(
                    input, output, report, 1, originalDigitalChannel);
            return true;
        } catch (Throwable error) {
            String msg = error.getMessage() != null ? error.getMessage() : "";
            append(report, "restore.step.finallyControlReload",
                    "fail: " + error.getClass().getSimpleName() + ": " + msg);
            append(report, "controlPlaneRestored", false);
            Log.w(TAG, "硬件编码器原频道控制面reload失败", error);
            return false;
        }
    }

    private void persistHardwareEncoderEvidence(
            List<Step3EvidenceRecord> records,
            List<HardwareEncoderCaptureRecord> captures,
            List<UartDiagnosticRecord> uartDiagnostics,
            List<HardwareEncoderReadChunk> pcmReadChunks,
            List<HardwareEncoderWriteChunk> pcmWriteChunks,
            ByteArrayOutputStream transcript, File transcriptFile,
            StringBuilder report)
            throws Exception {
        for (Step3EvidenceRecord record : records) {
            preserveRawEvidence(report, record.label, record.filePrefix,
                    record.raw);
        }
        if (captures != null) {
            for (HardwareEncoderCaptureRecord capture : captures) {
                persistHardwareEncoderCaptureExpansion(capture, report);
            }
        }
        persistUartDiagnostics(uartDiagnostics, pcmReadChunks, pcmWriteChunks,
                report);
        byte[] transcriptBytes = transcript.toByteArray();
        if (transcriptFile == null) {
            throw new IOException("硬件编码器transcript文件未在会话前创建");
        }
        if (transcriptFile.length() != transcriptBytes.length
                || !Arrays.equals(readBoundedFile(transcriptFile,
                        transcriptBytes.length + 1), transcriptBytes)) {
            throw new IOException("硬件编码器增量transcript与内存副本不一致");
        }
        append(report, "硬件编码器transcript格式", "S3R1有向分帧时序");
        append(report, "硬件编码器transcript方向",
                "1=发送尝试，2=接收，3=发送前排空，4=发送完成");
        append(report, "硬件编码器独立原件数", records.size());
        append(report, "硬件编码器transcript字节数",
                transcriptBytes.length);
        append(report, "硬件编码器transcript SHA-256",
                sha256(transcriptBytes));
        append(report, "硬件编码器transcript文件",
                transcriptFile.getAbsolutePath());
    }

    private void recordHardwareEncoderOutbound(
            List<Step3EvidenceRecord> records, File transcriptFile,
            ByteArrayOutputStream transcript, long transcriptStartedNanos,
            int direction, String label, String filePrefix, byte[] raw,
            StringBuilder report) throws Exception {
        recordStep3Evidence(new ArrayList<>(), transcript,
                transcriptStartedNanos, direction, label, filePrefix, raw,
                false);
        persistHardwareEncoderTranscriptCheckpoint(transcriptFile, transcript);
        if (records == null) {
            throw new IOException("硬件编码器发送原件队列为空");
        }
        records.add(new Step3EvidenceRecord(label, filePrefix, raw));
    }

    private void recordHardwareEncoderCapture(
            List<HardwareEncoderCaptureRecord> captures,
            File transcriptFile,
            ByteArrayOutputStream transcript, long transcriptStartedNanos,
            int direction, String label, String filePrefix,
            String windowToken, byte[] raw, StringBuilder report)
            throws Exception {
        byte[] safeRaw = raw != null ? raw : new byte[0];
        recordStep3Evidence(new ArrayList<>(), transcript,
                transcriptStartedNanos, direction, label, filePrefix, safeRaw,
                false);
        persistHardwareEncoderTranscriptCheckpoint(transcriptFile, transcript);
        // bridge活动期间只做整窗一次落盘；逐事件/AMBE9展开必须等自动退桥和恢复。
        preserveRawEvidence(report, label, filePrefix, safeRaw);
        if (captures != null) {
            captures.add(new HardwareEncoderCaptureRecord(
                    label, windowToken, safeRaw));
        }
    }

    private static void persistHardwareEncoderTranscriptCheckpoint(
            File transcriptFile, ByteArrayOutputStream transcript)
            throws Exception {
        if (transcriptFile == null || transcript == null) {
            throw new IOException("硬件编码器transcript检查点参数不完整");
        }
        byte[] complete = transcript.toByteArray();
        long existingLength = transcriptFile.length();
        if (existingLength < 0 || existingLength > complete.length) {
            throw new IOException("硬件编码器transcript原件长度非法");
        }
        if (existingLength == complete.length) {
            return;
        }
        try (FileOutputStream output = new FileOutputStream(transcriptFile, true)) {
            output.write(complete, (int) existingLength,
                    complete.length - (int) existingLength);
            output.getFD().sync();
        }
    }

    private void persistHardwareEncoderCaptureExpansion(
            HardwareEncoderCaptureRecord capture, StringBuilder report)
            throws Exception {
        String label = capture.label;
        String windowToken = capture.windowToken;
        HpiEvidenceParse parsed = parseHpiEvidence(capture.raw);
        append(report, label + " 事件数", parsed.events.size());
        append(report, label + " 控制确认", parsed.controlAcks);
        append(report, label + " 输入信用", parsed.inputCredits);
        append(report, label + " 候选27/36",
                parsed.candidate27 + "/" + parsed.candidate36);
        append(report, label + " 异步/畸形",
                parsed.asyncEvents + "/" + parsed.malformedEvents);
        for (int eventIndex = 0; eventIndex < parsed.events.size();
                eventIndex++) {
            HpiEvidenceEvent event = parsed.events.get(eventIndex);
            String eventPrefix = String.format(Locale.US,
                    "h13_hw_encoder_%s_event%03d_%s_offset%06d_",
                    windowToken, eventIndex,
                    event.type.name().toLowerCase(Locale.US), event.offset);
            preserveRawEvidence(report, label + " 事件" + eventIndex
                            + " 线帧", eventPrefix + "wire_",
                    event.wireFrame);
            preserveRawEvidence(report, label + " 事件" + eventIndex
                            + " 载荷", eventPrefix + "payload_",
                    event.payload);
            preserveRawEvidence(report, label + " 事件" + eventIndex
                            + " 补位", eventPrefix + "padding_",
                    event.padding);
            String metadata = "窗口=" + windowToken + "\n"
                    + "事件序号=" + eventIndex + "\n"
                    + "起始偏移=" + event.offset + "\n"
                    + "分类=" + event.type + "\n"
                    + "包类型=" + event.packetType + "\n"
                    + "字段=" + event.field + "\n"
                    + "声明体长=" + event.declaredBodyLength + "\n"
                    + "声明数据长=" + event.declaredDataLength + "\n"
                    + "补位长=" + event.paddingLength + "\n"
                    + "说明=" + event.detail + "\n";
            File metadataFile = uniqueFile(eventPrefix + "meta_", ".txt");
            writeFile(metadataFile, metadata.getBytes(StandardCharsets.UTF_8));
            append(report, label + " 事件" + eventIndex + " 元数据文件",
                    metadataFile.getAbsolutePath());
            for (int frameIndex = 0; frameIndex < event.ambeFrames9.length;
                    frameIndex++) {
                preserveRawEvidence(report, label + " 事件" + eventIndex
                                + " AMBE9-" + frameIndex,
                        eventPrefix + String.format(Locale.US,
                                "ambe9_%02d_", frameIndex),
                        event.ambeFrames9[frameIndex]);
            }
        }
    }

    /**
     * v1.84：永久禁用文本面清零 combined 窗。
     * 历史实现曾清 0x20001700，与生产 config@0x200017b4 重叠，已造成控制面事故。
     */
    private void zeroCombinedTemporaryWindows(InputStream input,
            OutputStream output, int codeLength) throws Exception {
        throw new IOException(
                "zeroCombinedTemporaryWindows 已永久禁用；"
                        + "禁止清零 0x20001700..0x2000184F 及任何 combined 窗");
    }

    private void assertNotForbiddenProductionWindow(int address, int length)
            throws IOException {
        long begin = address & 0xffffffffL;
        long end = (address + length) & 0xffffffffL;
        long f0 = FORBIDDEN_PROD_WINDOW_BEGIN & 0xffffffffL;
        long f1 = FORBIDDEN_PROD_WINDOW_END & 0xffffffffL;
        if (!(end <= f0 || begin >= f1)) {
            throw new IOException(String.format(Locale.US,
                    "拒绝写入禁止生产区 [0x%08x,0x%08x) 与 [0x%08x,0x%08x) 重叠",
                    address, address + length,
                    FORBIDDEN_PROD_WINDOW_BEGIN, FORBIDDEN_PROD_WINDOW_END));
        }
    }

    /**
     * v1.71：恢复 combined 窗口 + 完整 0x08024F42 相关 RAM + dataGate + 向量/bridge。
     */
    private boolean restoreCombinedFullPrepState(InputStream input,
            OutputStream output, byte[] originalCombined, byte[] originalPrepMarker,
            byte[] originalPrepCounter, byte[] originalAbsCounter,
            byte[] originalExitMarker, byte[] originalPrepPhase,
            byte[] originalPrepCursor, byte[] originalMirrorHelper,
            byte[] originalRuntimeMirror, byte[] originalDataGate,
            byte[] originalSessionState, byte[] originalPtrA, byte[] originalPtrB,
            byte[] originalFlag1c, byte[] originalCount, byte[] originalQueueA,
            byte[] originalQueueB, byte[] originalVector, byte[] originalFlag,
            List<Step3EvidenceRecord> evidenceRecords,
            StringBuilder report, boolean requirePrepMarkerObserved)
            throws Exception {
        if (originalCombined == null || originalPrepMarker == null
                || originalPrepCounter == null || originalAbsCounter == null
                || originalExitMarker == null || originalDataGate == null
                || originalMirrorHelper == null || originalRuntimeMirror == null
                || originalSessionState == null || originalPtrA == null
                || originalPtrB == null || originalFlag1c == null
                || originalCount == null || originalQueueA == null
                || originalQueueB == null || originalVector == null
                || originalFlag == null) {
            throw new IOException("combined/fullprep 原始备份不完整，禁止猜测恢复");
        }
        if (originalMirrorHelper.length
                != wordsToBytes(RUNTIME_MIRROR_HELPER_WORDS).length
                || originalRuntimeMirror.length != RUNTIME_MIRROR_LENGTH) {
            throw new IOException("运行镜像原始备份长度不符，禁止猜测恢复");
        }
        if (originalPrepPhase == null) {
            originalPrepPhase = new byte[4];
        }
        if (originalPrepCursor == null) {
            originalPrepCursor = new byte[4];
        }
        restoreWords(input, output, COMBINED_DUAL_COUNTER_CODE_ADDRESS,
                originalCombined);
        restoreWords(input, output, COMBINED_PREP_MARKER_ADDRESS,
                originalPrepMarker);
        restoreWords(input, output, COMBINED_PREP_COUNTER_ADDRESS,
                originalPrepCounter);
        restoreWords(input, output, COMBINED_ABS_COUNTER_ADDRESS,
                originalAbsCounter);
        restoreWords(input, output, COMBINED_EXIT_MARKER_ADDRESS,
                originalExitMarker);
        restoreWords(input, output, COMBINED_PREP_PHASE_ADDRESS,
                originalPrepPhase);
        restoreWords(input, output, COMBINED_PREP_CURSOR_ADDRESS,
                originalPrepCursor);
        restoreWords(input, output, RUNTIME_MIRROR_HELPER_ADDRESS,
                originalMirrorHelper);
        restoreWords(input, output, RUNTIME_MIRROR_ADDRESS,
                originalRuntimeMirror);
        writeMemoryByte(input, output, EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS,
                originalDataGate[0] & 0xff);
        writeMemoryByte(input, output, EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS,
                originalSessionState[0] & 0xff);
        writeMemoryWord(input, output, EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS,
                u32le(originalPtrA, 0));
        writeMemoryWord(input, output, EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS,
                u32le(originalPtrB, 0));
        writeMemoryByte(input, output, EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS,
                originalFlag1c[0] & 0xff);
        writeMemoryWord(input, output, EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS,
                u32le(originalCount, 0));
        // 队列：按备份写回（v1.73 默认为全零占位）
        for (int i = 0; i < originalQueueA.length; i++) {
            writeMemoryByte(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS + i,
                    originalQueueA[i] & 0xff);
        }
        for (int i = 0; i < originalQueueB.length; i++) {
            writeMemoryByte(input, output,
                    EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS + i,
                    originalQueueB[i] & 0xff);
        }
        writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                u32le(originalVector, 0));
        writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                originalFlag[0] & 0xff);

        // v1.77：回读比较覆盖代码窗+全部元数据+会话标量+指针+计数+两队列+向量+flag。
        byte[] codeRb = readMemory(input, output,
                COMBINED_DUAL_COUNTER_CODE_ADDRESS, originalCombined.length);
        byte[] prepMarkerRb = readMemory(input, output,
                COMBINED_PREP_MARKER_ADDRESS, 4);
        byte[] prepCounterRb = readMemory(input, output,
                COMBINED_PREP_COUNTER_ADDRESS, 4);
        byte[] absCounterRb = readMemory(input, output,
                COMBINED_ABS_COUNTER_ADDRESS, 4);
        byte[] exitMarkerRb = readMemory(input, output,
                COMBINED_EXIT_MARKER_ADDRESS, 4);
        byte[] prepPhaseRb = readMemory(input, output,
                COMBINED_PREP_PHASE_ADDRESS, 4);
        byte[] prepCursorRb = readMemory(input, output,
                COMBINED_PREP_CURSOR_ADDRESS, 4);
        byte[] mirrorHelperRb = readMemory(input, output,
                RUNTIME_MIRROR_HELPER_ADDRESS, originalMirrorHelper.length);
        byte[] runtimeMirrorRb = readMemory(input, output,
                RUNTIME_MIRROR_ADDRESS, originalRuntimeMirror.length);
        byte[] dgRb = readMemory(input, output,
                EXTERNAL_DMR_PRIVACY_DATA_GATE_ADDRESS, 1);
        byte[] stateRb = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_STATE_ADDRESS, 1);
        byte[] ptrARb = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_PTR_A_ADDRESS, 4);
        byte[] ptrBRb = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_PTR_B_ADDRESS, 4);
        byte[] flag1cRb = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_FLAG_1C_ADDRESS, 1);
        byte[] countRb = readMemory(input, output,
                EXTERNAL_DMR_TX_SESSION_COUNT_ADDRESS, 4);
        byte[] queueARb = readMemory(input, output,
                EXTERNAL_DMR_TX_WORK_QUEUE_A_ADDRESS, originalQueueA.length);
        byte[] queueBRb = readMemory(input, output,
                EXTERNAL_DMR_TX_WORK_QUEUE_B_ADDRESS, originalQueueB.length);
        byte[] vecRb = readMemory(input, output, RAM_VECTOR_SYSTICK, 4);
        byte[] flagRb = readMemory(input, output,
                UART_HPI_BRIDGE_FLAG_ADDRESS, 1);
        byte[] bootReadyRb = readMemory(input, output,
                SCT_BOOT_READY_ADDRESS, 1);
        byte[] bootModeRb = readMemory(input, output,
                SCT_BOOT_MODE_ADDRESS, 1);
        // v1.90：恢复判定使用的同一批逐字节回读必须作为原始证据落盘。
        // v1.95：E4/E5 只读入证，不参与 restore 写回比较。
        queueStep3SramSnapshot(evidenceRecords, "restored",
                codeRb, prepMarkerRb, prepCounterRb, absCounterRb,
                exitMarkerRb, prepPhaseRb, prepCursorRb, mirrorHelperRb,
                runtimeMirrorRb, dgRb, stateRb,
                ptrARb, ptrBRb, flag1cRb, countRb, queueARb, queueBRb,
                vecRb, flagRb, bootReadyRb, bootModeRb);
        Log.i(TAG, String.format(Locale.US,
                "SCT_READY_RESTORED E4=%d E5=%d bridge=%d",
                bootReadyRb[0] & 0xff, bootModeRb[0] & 0xff,
                flagRb[0] & 0xff));
        boolean restored = Arrays.equals(originalCombined, codeRb)
                && Arrays.equals(originalPrepMarker, prepMarkerRb)
                && Arrays.equals(originalPrepCounter, prepCounterRb)
                && Arrays.equals(originalAbsCounter, absCounterRb)
                && Arrays.equals(originalExitMarker, exitMarkerRb)
                && Arrays.equals(originalPrepPhase, prepPhaseRb)
                && Arrays.equals(originalPrepCursor, prepCursorRb)
                && Arrays.equals(originalMirrorHelper, mirrorHelperRb)
                && Arrays.equals(originalRuntimeMirror, runtimeMirrorRb)
                && Arrays.equals(originalDataGate, dgRb)
                && Arrays.equals(originalSessionState, stateRb)
                && Arrays.equals(originalPtrA, ptrARb)
                && Arrays.equals(originalPtrB, ptrBRb)
                && Arrays.equals(originalFlag1c, flag1cRb)
                && Arrays.equals(originalCount, countRb)
                && Arrays.equals(originalQueueA, queueARb)
                && Arrays.equals(originalQueueB, queueBRb)
                && Arrays.equals(originalVector, vecRb)
                && Arrays.equals(originalFlag, flagRb);
        append(report, "Combined+fullprep restored", restored);
        append(report, "dataGate restored to", dgRb[0] & 0xff);
        append(report, "sessionState restored to", stateRb[0] & 0xff);
        append(report, "queueA restored", Arrays.equals(originalQueueA, queueARb));
        append(report, "queueB restored", Arrays.equals(originalQueueB, queueBRb));
        append(report, "meta fields restored",
                Arrays.equals(originalPrepMarker, prepMarkerRb)
                        && Arrays.equals(originalPrepCounter, prepCounterRb)
                        && Arrays.equals(originalAbsCounter, absCounterRb)
                        && Arrays.equals(originalExitMarker, exitMarkerRb)
                        && Arrays.equals(originalPrepPhase, prepPhaseRb)
                        && Arrays.equals(originalPrepCursor, prepCursorRb));
        append(report, "Datagate oneshot window restored", restored);
        Log.i(TAG, String.format(Locale.US,
                "RESTORE_COMBINED ok=%s dataGate=%d state=%d flag=%d vector=0x%08x "
                        + "queueA=%s queueB=%s",
                restored, dgRb[0] & 0xff, stateRb[0] & 0xff, flagRb[0] & 0xff,
                u32le(vecRb, 0),
                Arrays.equals(originalQueueA, queueARb),
                Arrays.equals(originalQueueB, queueBRb)));
        if (!restored) {
            throw new IOException(
                    "combined/fullprep 逐字节恢复不一致（含元数据/队列/标量）");
        }
        if (requirePrepMarkerObserved) {
            append(report, "DGAT required on success path", true);
        }
        return true;
    }

    /** 将完整残留字节落盘为 .bin + 报告 HEX/SHA；供只读取证与拒绝 arm 使用。 */
    private void persistResidualDump(StringBuilder report, String label,
            byte[] data, int baseAddress) throws Exception {
        if (data == null) {
            append(report, label + " dump", "null");
            return;
        }
        File bin = new File(outputDirectory, "h13_residual_" + label + ".bin");
        writeFile(bin, data);
        String hex = bytesToHex(data);
        File hexFile = new File(outputDirectory, "h13_residual_" + label + ".hex.txt");
        writeFile(hexFile, hex.getBytes(StandardCharsets.UTF_8));
        append(report, label + " addr",
                String.format(Locale.US, "0x%08x", baseAddress));
        append(report, label + " length", data.length);
        append(report, label + " SHA-256", sha256(data));
        append(report, label + " HEX", hex);
        append(report, label + " bin", bin.getAbsolutePath());
        Log.i(TAG, "RESIDUAL_DUMP " + label + " addr=0x"
                + Integer.toHexString(baseAddress)
                + " len=" + data.length + " sha=" + sha256(data));
    }

    private static int firstNonZeroOffset(byte[] data) {
        if (data == null) {
            return -1;
        }
        for (int i = 0; i < data.length; i++) {
            if (data[i] != 0) {
                return i;
            }
        }
        return -1;
    }

    private static boolean metaCleanAfter(byte[] prepMarker, byte[] prepCounter,
            byte[] absCounter, byte[] exitMarker, byte[] prepPhase,
            byte[] prepCursor) {
        return allZero(prepMarker) && allZero(prepCounter) && allZero(absCounter)
                && allZero(exitMarker) && allZero(prepPhase)
                && allZero(prepCursor);
    }

    private static byte[] concatBytes(byte[]... parts) {
        int total = 0;
        for (byte[] part : parts) {
            total += part == null ? 0 : part.length;
        }
        byte[] out = new byte[total];
        int o = 0;
        for (byte[] part : parts) {
            if (part == null) {
                continue;
            }
            System.arraycopy(part, 0, out, o, part.length);
            o += part.length;
        }
        return out;
    }

    /**
     * 宿主优先读取的原子结果文件（先写 .tmp 再 rename）。
     * logcat 仅作证据，不再作为唯一完成信号。
     */
    // 启动拒绝也必须落原子结果，且带回宿主生成的唯一会话标识。
    void writeLaunchAtomic(boolean success, String status, String extraLines) {
        writeAtomicProbeSessionResult(success, false, status, "LAUNCH",
                true, true, extraLines);
    }

    static long epochSecondsForMonotonicTarget(long wallClockMs,
            long monotonicNowMs, long monotonicTargetMs) {
        if (wallClockMs <= 0L || monotonicNowMs < 0L
                || monotonicTargetMs < monotonicNowMs) {
            throw new IllegalArgumentException("RF目标时钟参数非法");
        }
        return Math.max(1L,
                (wallClockMs + monotonicTargetMs - monotonicNowMs) / 1000L);
    }

    static String buildProductionRfPreparationAttestation(String sessionId,
            long mayStartEpochSeconds, long mayStartMonotonicMs) {
        if (sessionId == null || !sessionId.matches("[0-9a-f]{32}")
                || mayStartEpochSeconds <= 0L || mayStartMonotonicMs < 0L) {
            throw new IllegalArgumentException("RF准备凭证参数非法");
        }
        return "build=" + probeBuildName() + "\n"
                + "versionCode=" + BuildConfig.VERSION_CODE + "\n"
                + "launch_session_id=" + sessionId + "\n"
                + "rf_preparation_armed=true\n"
                + "rf_may_start_epoch=" + mayStartEpochSeconds + "\n"
                + "rf_may_start_monotonic_ms=" + mayStartMonotonicMs + "\n"
                + "rf_timeout_sec="
                + (SOFTWARE_AMBE_PTT_WATCHDOG_TIMEOUT_MS / 1000L) + "\n";
    }

    static String buildProductionRfWindowStartAttestation(String sessionId,
            long epochSeconds, long monotonicMs) {
        if (sessionId == null || !sessionId.matches("[0-9a-f]{32}")
                || epochSeconds <= 0L || monotonicMs < 0L) {
            throw new IllegalArgumentException("RF起点凭证参数非法");
        }
        return "build=" + probeBuildName() + "\n"
                + "versionCode=" + BuildConfig.VERSION_CODE + "\n"
                + "launch_session_id=" + sessionId + "\n"
                + "rf_window_started=true\n"
                + "rf_window_started_epoch=" + epochSeconds + "\n"
                + "rf_window_started_monotonic_ms=" + monotonicMs + "\n"
                + "rf_timeout_sec="
                + (SOFTWARE_AMBE_PTT_WATCHDOG_TIMEOUT_MS / 1000L) + "\n";
    }

    /** 在SysTick武装前落盘；只声明最早可能RF时刻，不声明RF已经开始。 */
    private void persistProductionRfPreparationAttestation(long epochSeconds,
            long monotonicMs) throws Exception {
        String body = buildProductionRfPreparationAttestation(launchSessionId,
                epochSeconds, monotonicMs);
        File target = new File(outputDirectory,
                PRODUCTION_RF_PREPARATION_ATTESTATION_FILE);
        File temporary = new File(outputDirectory,
                PRODUCTION_RF_PREPARATION_ATTESTATION_FILE + ".tmp");
        if (target.exists() || temporary.exists()) {
            throw new IOException("RF准备凭证未在宿主准入阶段清除");
        }
        try (FileOutputStream stream = new FileOutputStream(temporary, false)) {
            stream.write(body.getBytes(StandardCharsets.UTF_8));
            stream.getFD().sync();
        }
        replaceFileAtomically(temporary, target);
        byte[] actual = readBoundedFile(target, 4096);
        if (!Arrays.equals(body.getBytes(StandardCharsets.UTF_8), actual)) {
            throw new IOException("RF准备凭证写后逐字回读不一致");
        }
        Log.i(TAG, "PRODUCTION_RF_PREPARATION persisted mayStartEpoch="
                + epochSeconds + " mayStartMonoMs=" + monotonicMs);
    }

    /** 已越过计划RF起点且setup完整通过后落盘的设备侧起点凭证。 */
    private void persistProductionRfWindowStartAttestation(long epochSeconds,
            long monotonicMs) throws Exception {
        String body = buildProductionRfWindowStartAttestation(launchSessionId,
                epochSeconds, monotonicMs);
        File target = new File(outputDirectory,
                PRODUCTION_RF_WINDOW_START_ATTESTATION_FILE);
        File temporary = new File(outputDirectory,
                PRODUCTION_RF_WINDOW_START_ATTESTATION_FILE + ".tmp");
        if (target.exists() || temporary.exists()) {
            throw new IOException("RF起点凭证未在宿主准入阶段清除");
        }
        try (FileOutputStream stream = new FileOutputStream(temporary, false)) {
            stream.write(body.getBytes(StandardCharsets.UTF_8));
            stream.getFD().sync();
        }
        replaceFileAtomically(temporary, target);
        byte[] actual = readBoundedFile(target, 4096);
        if (!Arrays.equals(body.getBytes(StandardCharsets.UTF_8), actual)) {
            throw new IOException("RF起点凭证写后逐字回读不一致");
        }
        Log.i(TAG, "PRODUCTION_RF_WINDOW_START persisted epoch="
                + epochSeconds + " monoMs=" + monotonicMs);
    }

    /** RF关闭一经三重回读确认便立即落盘，宿主无需等待后续长取证。 */
    private void persistProductionRfReleaseAttestation(byte[] marker,
            byte[] activeGate, byte[] vector) throws Exception {
        if (marker == null || marker.length != 4
                || activeGate == null || activeGate.length != 4
                || vector == null || vector.length != 4
                || u32le(marker, 0) != EXTERNAL_DMR_RF_OFF_MARKER
                || u32le(activeGate, 0) != 0
                || u32le(vector, 0) != ORIGINAL_SYSTICK_HANDLER) {
            throw new IOException("RF关闭凭证输入不满足三重回读门");
        }
        String body = "build=" + probeBuildName() + "\n"
                + "versionCode=" + BuildConfig.VERSION_CODE + "\n"
                + "launch_session_id=" + launchSessionId + "\n"
                + "production_rf_off_confirmed=true\n"
                + "rf_off_marker=" + String.format(Locale.US, "0x%08x",
                u32le(marker, 0)) + "\n"
                + "rf_active_gate=0\n"
                + "systick_vector=" + String.format(Locale.US, "0x%08x",
                u32le(vector, 0)) + "\n"
                + "dmoptt_forbidden=true\n";
        File target = new File(outputDirectory,
                PRODUCTION_RF_RELEASE_ATTESTATION_FILE);
        File temporary = new File(outputDirectory,
                PRODUCTION_RF_RELEASE_ATTESTATION_FILE + ".tmp");
        try (FileOutputStream stream = new FileOutputStream(temporary, false)) {
            stream.write(body.getBytes(StandardCharsets.UTF_8));
            stream.getFD().sync();
        }
        replaceFileAtomically(temporary, target);
        byte[] actual = readBoundedFile(target, 4096);
        if (!Arrays.equals(body.getBytes(StandardCharsets.UTF_8), actual)) {
            throw new IOException("RF关闭凭证写后逐字回读不一致");
        }
    }

    private void writeAtomicProbeSessionResult(boolean success,
            boolean rebootRequired, String status, String transportState,
            boolean sramRestored, boolean controlRestored) {
        writeAtomicProbeSessionResult(success, rebootRequired, status,
                transportState, sramRestored, controlRestored, "");
    }

    private void writeAtomicProbeSessionResult(boolean success,
            boolean rebootRequired, String status, String transportState,
            boolean sramRestored, boolean controlRestored, String extraLines) {
        try {
            String targetName = atomicResultFileName == null
                    || atomicResultFileName.isEmpty()
                    ? PROBE_SESSION_RESULT_FILE : atomicResultFileName;
            File tmp = new File(outputDirectory, targetName + ".tmp");
            File out = new File(outputDirectory, targetName);
            String body = "build=" + probeBuildName() + "\n"
                    + "versionCode=" + BuildConfig.VERSION_CODE + "\n"
                    + "launch_session_id=" + launchSessionId + "\n"
                    + "result=" + (success ? "PASS" : "FAIL") + "\n"
                    + "status=" + (status == null ? "" : status) + "\n"
                    + "reboot_required=" + rebootRequired + "\n"
                    + "transport=" + (transportState == null ? ""
                    : transportState) + "\n"
                    + "sram_restored=" + sramRestored + "\n"
                    + "control_plane_restored=" + controlRestored + "\n"
                    + "phase=" + (success ? "DONE_PASS" : "DONE_FAIL") + "\n"
                    + (extraLines == null ? "" : extraLines);
            try (FileOutputStream fos = new FileOutputStream(tmp, false)) {
                fos.write(body.getBytes(StandardCharsets.UTF_8));
                fos.getFD().sync();
            }
            if (out.exists() && !out.delete()) {
                Log.w(TAG, "ATOMIC_RESULT could not delete old file");
            }
            if (!tmp.renameTo(out)) {
                // 回退：直接写最终文件
                try (FileOutputStream fos = new FileOutputStream(out, false)) {
                    fos.write(body.getBytes(StandardCharsets.UTF_8));
                    fos.getFD().sync();
                }
                //noinspection ResultOfMethodCallIgnored
                tmp.delete();
            }
            logAtomicResult(Log.INFO,
                    "ATOMIC_RESULT " + body.replace('\n', ' '));
        } catch (Throwable error) {
            logAtomicResult(Log.ERROR,
                    "ATOMIC_RESULT write failed: " + error.getMessage());
        }
    }

    private static void logAtomicResult(int priority, String message) {
        try {
            Log.println(priority, TAG, message);
        } catch (Throwable ignored) {
            // 原子结果落盘不得因日志后端不可用而反向失败。
        }
    }

    private boolean restoreStep3TemporaryStateAndVerify(InputStream input,
            OutputStream output, byte[] originalCode, byte[] originalCounter,
            byte[] originalMarker, byte[] originalVector, byte[] originalFlag,
            StringBuilder report) throws Exception {
        if (originalCode == null || originalCounter == null
                || originalMarker == null || originalVector == null
                || originalFlag == null) {
            throw new IOException("步骤3原始临时状态不完整，禁止猜测恢复");
        }
        restoreWords(input, output, UART_HPI_TIMEOUT_CODE_ADDRESS, originalCode);
        restoreWords(input, output, UART_HPI_TIMEOUT_COUNTER_ADDRESS,
                originalCounter);
        restoreWords(input, output, UART_HPI_TIMEOUT_MARKER_ADDRESS,
                originalMarker);
        writeMemoryWord(input, output, RAM_VECTOR_SYSTICK,
                u32le(originalVector, 0));
        writeMemoryByte(input, output, UART_HPI_BRIDGE_FLAG_ADDRESS,
                originalFlag[0] & 0xff);

        byte[] restoredCode = readMemory(input, output,
                UART_HPI_TIMEOUT_CODE_ADDRESS, originalCode.length);
        byte[] restoredCounter = readMemory(input, output,
                UART_HPI_TIMEOUT_COUNTER_ADDRESS, originalCounter.length);
        byte[] restoredMarker = readMemory(input, output,
                UART_HPI_TIMEOUT_MARKER_ADDRESS, originalMarker.length);
        byte[] restoredVector = readMemory(input, output,
                RAM_VECTOR_SYSTICK, originalVector.length);
        byte[] restoredFlag = readMemory(input, output,
                UART_HPI_BRIDGE_FLAG_ADDRESS, originalFlag.length);
        boolean restored = Arrays.equals(originalCode, restoredCode)
                && Arrays.equals(originalCounter, restoredCounter)
                && Arrays.equals(originalMarker, restoredMarker)
                && Arrays.equals(originalVector, restoredVector)
                && Arrays.equals(originalFlag, restoredFlag);
        append(report, "Temporary state restored", restored);
        if (!restored) {
            throw new IOException("步骤3临时状态逐字节恢复不一致");
        }
        return true;
    }

    private static byte[] extractFlashData64(byte[] raw) {
        int frameLength = 6 + 1 + SCT_FLASH_PAGE_SIZE;
        for (int offset = 0; offset <= raw.length - frameLength; offset++) {
            if ((raw[offset] & 0xff) == 0x84
                    && (raw[offset + 1] & 0xff) == 0xa9
                    && (raw[offset + 2] & 0xff) == 0x61
                    && (raw[offset + 3] & 0xff) == 0x00
                    && (raw[offset + 4] & 0xff) == 0x41
                    && (raw[offset + 5] & 0xff) == 0x23
                    && (raw[offset + 6] & 0xff) == 0x94) {
                return Arrays.copyOfRange(raw, offset + 7,
                        offset + 7 + SCT_FLASH_PAGE_SIZE);
            }
        }
        return null;
    }

    private static byte[] createHpiFrame(int packetType, byte[] payload) {
        byte[] frame = new byte[6 + payload.length];
        frame[0] = (byte) 0x84;
        frame[1] = (byte) 0xa9;
        frame[2] = 0x61;
        frame[3] = (byte) (payload.length >>> 8);
        frame[4] = (byte) payload.length;
        frame[5] = (byte) packetType;
        System.arraycopy(payload, 0, frame, 6, payload.length);
        return frame;
    }

    private static byte[] createHpiWriteCommand(int packetType, byte[] payload) {
        byte[] command = new byte[4 + payload.length];
        command[0] = 0x61;
        command[1] = (byte) (payload.length >>> 8);
        command[2] = (byte) payload.length;
        command[3] = (byte) packetType;
        System.arraycopy(payload, 0, command, 4, payload.length);
        return command;
    }

    private static byte[] createPaddedHpiFrame(int packetType, byte[] payload) {
        byte[] frame = createHpiFrame(packetType, payload);
        return (frame.length & 1) == 0
                ? frame : Arrays.copyOf(frame, frame.length + 1);
    }

    /**
     * Count complete vs partial SPEECH_SAMPLES frames (160-sample PCM).
     * Complete = body length 323 with full payload present (wire 329 or 330).
     * Partial = SPEECH header seen but truncated before full 320-byte payload.
     */
    private static PcmFrameStats analyzeSpeechSamplesFrames(byte[] raw) {
        PcmFrameStats stats = new PcmFrameStats();
        int offset = 0;
        while (offset + 9 <= raw.length) {
            if ((raw[offset] & 0xff) != 0x84
                    || (raw[offset + 1] & 0xff) != 0xa9
                    || (raw[offset + 2] & 0xff) != 0x61) {
                offset++;
                continue;
            }
            int bodyLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            int type = raw[offset + 5] & 0xff;
            if (type != 0x30 || bodyLength < 1) {
                offset++;
                continue;
            }
            int field = raw[offset + 6] & 0xff;
            if (field != 0x00) {
                offset++;
                continue;
            }
            // SPEECH_SAMPLES field; sample count at bytes 7..8 when present.
            boolean looksSpeech = bodyLength >= 3
                    && (((raw[offset + 7] & 0xff) << 8)
                    | (raw[offset + 8] & 0xff)) == 160;
            if (!looksSpeech && bodyLength != 323) {
                offset++;
                continue;
            }
            stats.speechHeaders++;
            int unpaddedLength = 6 + bodyLength;
            int frameLength = unpaddedLength;
            if ((unpaddedLength & 1) != 0
                    && offset + unpaddedLength < raw.length
                    && raw[offset + unpaddedLength] == 0) {
                frameLength = unpaddedLength + 1;
            }
            frameLength = resolveHpiFrameWireLength(raw, offset, bodyLength,
                    frameLength);
            // Full declared body present (rare on H13@230400).
            if (bodyLength == 323 && offset + unpaddedLength <= raw.length
                    && frameLength >= unpaddedLength) {
                stats.complete160++;
                offset += frameLength;
            } else if (frameLength == 328 && bodyLength == 323) {
                // Systematic packed SPEECH: 159 s16 usable + trailing pad.
                stats.wire328++;
                offset += frameLength;
            } else if (offset + 9 >= raw.length) {
                stats.partialOrTruncated++;
                break;
            } else {
                stats.partialOrTruncated++;
                offset += Math.min(frameLength, raw.length - offset);
            }
        }
        return stats;
    }

    private static final class PcmFrameStats {
        int speechHeaders;
        int complete160;
        int wire328;
        int partialOrTruncated;

        double completeRatio() {
            int denom = complete160 + wire328 + partialOrTruncated;
            if (denom <= 0) {
                return 0.0;
            }
            // Count wire328 as structurally recovered SPEECH (159/160 samples).
            return (complete160 + wire328) / (double) denom;
        }
    }

    private static HpiCaptureSummary summarizeHpiCapture(byte[] raw) {
        HpiCaptureSummary summary = new HpiCaptureSummary();
        int offset = 0;
        while (offset + 6 <= raw.length) {
            if ((raw[offset] & 0xff) != 0x84
                    || (raw[offset + 1] & 0xff) != 0xa9
                    || (raw[offset + 2] & 0xff) != 0x61) {
                offset++;
                continue;
            }
            int bodyLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            if (bodyLength > 8192) {
                summary.invalidHeaders++;
                offset++;
                continue;
            }
            // Packet Interface: even wire length; odd frames may pad 0x00.
            // H13 Voice OUT @230400 SPEECH is special: LENGTH=323 (expect 330)
            // but consecutive SYNC is always at +328 (wire −2). Advancing by
            // 329/330 desyncs the walker and invents huge unframed tails.
            int unpaddedLength = 6 + bodyLength;
            int frameLength = unpaddedLength;
            if ((unpaddedLength & 1) != 0
                    && offset + unpaddedLength < raw.length
                    && raw[offset + unpaddedLength] == 0) {
                frameLength = unpaddedLength + 1;
            }
            frameLength = resolveHpiFrameWireLength(raw, offset, bodyLength,
                    frameLength);
            if (offset + 6 > raw.length) {
                summary.truncatedFrames++;
                break;
            }
            // Allow short final frame body when stream ends mid-declaration.
            int type = raw[offset + 5] & 0xff;
            int field = bodyLength > 0 && offset + 6 < raw.length
                    ? (raw[offset + 6] & 0xff) : -1;
            summary.frames++;
            summary.framedBytes += Math.min(frameLength, raw.length - offset);
            if (type == 0x00) {
                summary.type0++;
            } else if (type == 0x20) {
                summary.type20++;
            } else if (type == 0x30) {
                summary.type30++;
            } else {
                summary.otherTypes++;
            }
            if (bodyLength == 29 && field == 0x01
                    && offset + 7 < raw.length
                    && (raw[offset + 7] & 0xff) == 27) {
                summary.chanD27++;
            } else if (bodyLength == 323 && field == 0x00
                    && offset + 8 < raw.length
                    && ((raw[offset + 7] & 0xff) << 8
                    | (raw[offset + 8] & 0xff)) == 160) {
                // Declared 160-sample SPEECH (may be wire328 on this platform).
                summary.pcm160++;
                if (frameLength == 328) {
                    summary.pcm160Wire328++;
                }
            } else if (bodyLength == 2 && field == 0x7f) {
                summary.dmrSlotFound++;
                summary.controlFrames++;
            } else if (bodyLength == 1 || bodyLength == 2) {
                summary.controlFrames++;
            } else if (bodyLength == 38) {
                summary.short36++;
            } else if (bodyLength == 50) {
                summary.short48++;
            } else if (bodyLength == 1283) {
                summary.long1280++;
            } else if (bodyLength > 2) {
                summary.otherDataFrames++;
            }
            int bodyEnd = Math.min(offset + unpaddedLength, raw.length);
            for (int index = offset + 6; index < bodyEnd; index++) {
                if (raw[index] != 0) {
                    summary.nonzeroPayloadBytes++;
                }
            }
            offset += frameLength;
        }
        summary.unframedBytes = raw.length - summary.framedBytes;
        return summary;
    }

    /**
     * P1: candidate HPI header must validate LENGTH/type/field — not SYNC alone.
     * Prevents payload false cuts on accidental 84 A9 61 sequences.
     */
    static boolean isPlausibleHpiHeader(byte[] raw, int offset) {
        if (raw == null || offset < 0 || offset + 9 > raw.length) {
            return false;
        }
        if ((raw[offset] & 0xff) != 0x84
                || (raw[offset + 1] & 0xff) != 0xa9
                || (raw[offset + 2] & 0xff) != 0x61) {
            return false;
        }
        int bodyLength = ((raw[offset + 3] & 0xff) << 8) | (raw[offset + 4] & 0xff);
        int packetType = raw[offset + 5] & 0xff;
        int field = raw[offset + 6] & 0xff;
        if (packetType != 0x00 && packetType != 0x20 && packetType != 0x30) {
            return false;
        }
        if (bodyLength < 1 || bodyLength > 2048) {
            return false;
        }
        // Known project shapes (prefer).
        if (bodyLength == 2 && (field == 0x01 || field == 0x3e || field == 0x7f
                || field == 0x18 || field == 0x1a || field == 0x1b)) {
            return true;
        }
        if (bodyLength == 29 && field == 0x01) {
            return true;
        }
        if (bodyLength == 323 && field == 0x00) {
            int count = ((raw[offset + 7] & 0xff) << 8) | (raw[offset + 8] & 0xff);
            return count == 160;
        }
        if (bodyLength <= 4) {
            return true;
        }
        // Generic bounded HPI body (vendor long blocks up to 1283).
        return bodyLength <= 1283;
    }

    /**
     * P2 product recovery: SPEECH frames → 160-sample s16le product PCM.
     * wire328 → 159 samples + zero_pad one sample; record gaps.
     */
    static final class ProductPcmRecovery {
        final byte[] productPcm;
        final byte[] availablePcm;
        final int speechFrames;
        final int wire328Frames;
        final int complete160Frames;
        final int gapFrames;
        final int missingSamplesTotal;
        final String gapsCsv;

        ProductPcmRecovery(byte[] productPcm, byte[] availablePcm,
                int speechFrames, int wire328Frames, int complete160Frames,
                int gapFrames, int missingSamplesTotal, String gapsCsv) {
            this.productPcm = productPcm;
            this.availablePcm = availablePcm;
            this.speechFrames = speechFrames;
            this.wire328Frames = wire328Frames;
            this.complete160Frames = complete160Frames;
            this.gapFrames = gapFrames;
            this.missingSamplesTotal = missingSamplesTotal;
            this.gapsCsv = gapsCsv;
        }
    }

    /**
     * Count vendor-style SPEECH_SAMPLES frames: type 0x20/0x30, field 0x00,
     * body length 1283 (count word 0x0280 + 1280 payload bytes).
     * Historical Voice OUT captures under VOCODER_IO=0x01 had zero of these.
     */
    static int countSpeechSamples1280Frames(byte[] raw) {
        int count = 0;
        int offset = 0;
        while (offset + 9 <= raw.length) {
            int found = -1;
            for (int i = offset; i + 9 <= raw.length; i++) {
                if (isPlausibleHpiHeader(raw, i)) {
                    found = i;
                    break;
                }
            }
            if (found < 0) {
                break;
            }
            offset = found;
            int bodyLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            int packetType = raw[offset + 5] & 0xff;
            int field = raw[offset + 6] & 0xff;
            int unpadded = 6 + bodyLength;
            int paper = unpadded + (unpadded & 1);
            int wire = resolveHpiFrameWireLength(raw, offset, bodyLength, paper);
            if (field == 0x00 && bodyLength == 1283
                    && (packetType == 0x20 || packetType == 0x30)) {
                count++;
            }
            if (wire <= 0) {
                break;
            }
            offset += wire;
        }
        return count;
    }

    static ProductPcmRecovery recoverProductPcm(byte[] raw) {
        ByteArrayOutputStream product = new ByteArrayOutputStream();
        ByteArrayOutputStream available = new ByteArrayOutputStream();
        StringBuilder gaps = new StringBuilder();
        gaps.append("frame_index,offset,wire,missing_samples,method\n");
        int speech = 0;
        int wire328 = 0;
        int complete160 = 0;
        int gapFrames = 0;
        int missingTotal = 0;
        int offset = 0;
        while (offset + 9 <= raw.length) {
            int found = -1;
            for (int i = offset; i + 9 <= raw.length; i++) {
                if (isPlausibleHpiHeader(raw, i)) {
                    found = i;
                    break;
                }
            }
            if (found < 0) {
                break;
            }
            offset = found;
            int bodyLength = ((raw[offset + 3] & 0xff) << 8)
                    | (raw[offset + 4] & 0xff);
            int packetType = raw[offset + 5] & 0xff;
            int field = raw[offset + 6] & 0xff;
            int unpadded = 6 + bodyLength;
            int paper = unpadded + (unpadded & 1);
            int wire = resolveHpiFrameWireLength(raw, offset, bodyLength, paper);
            if (bodyLength == 323 && field == 0x00 && packetType == 0x30) {
                int end = Math.min(raw.length, offset + wire);
                int sampleStart = offset + 9;
                int sampleLen = Math.max(0, end - sampleStart);
                // Drop trailing pad 0x00 when odd length (wire328).
                if (sampleLen > 0 && end > sampleStart
                        && (raw[end - 1] & 0xff) == 0
                        && (sampleLen & 1) != 0) {
                    sampleLen--;
                }
                if ((sampleLen & 1) != 0) {
                    sampleLen--;
                }
                if (sampleLen > 320) {
                    sampleLen = 320;
                }
                int samples = sampleLen / 2;
                // Ignore header-only / empty SPEECH tails (no usable PCM).
                if (samples >= 100) {
                    try {
                        available.write(raw, sampleStart, sampleLen);
                        product.write(raw, sampleStart, sampleLen);
                        int missing = 160 - samples;
                        String method = "none";
                        if (missing > 0) {
                            method = "zero_pad";
                            byte[] zeros = new byte[missing * 2];
                            product.write(zeros);
                            gapFrames++;
                            missingTotal += missing;
                            gaps.append(speech).append(',').append(offset)
                                    .append(',').append(wire).append(',')
                                    .append(missing).append(',').append(method)
                                    .append('\n');
                        }
                    } catch (IOException ignored) {
                        // ByteArrayOutputStream does not throw in practice.
                    }
                    if (wire == 328) {
                        wire328++;
                    }
                    if (samples >= 160) {
                        complete160++;
                    }
                    speech++;
                }
            }
            if (wire <= 0) {
                break;
            }
            offset += wire;
        }
        return new ProductPcmRecovery(product.toByteArray(), available.toByteArray(),
                speech, wire328, complete160, gapFrames, missingTotal,
                gaps.toString());
    }

    /**
     * Prefer the next <b>plausible</b> 0x84A961 header when it arrives earlier
     * than LENGTH implies. Empirically SPEECH LENGTH=323 streams at +328 on
     * H13 UART-HPI @230400 (159 s16 + pad), not random UART loss.
     */
    private static int resolveHpiFrameWireLength(byte[] raw, int offset,
            int bodyLength, int lengthBasedFrameLength) {
        int searchFrom = offset + 6;
        int searchTo = Math.min(raw.length - 2,
                offset + Math.max(lengthBasedFrameLength, bodyLength + 6) + 4);
        int earliestSync = -1;
        for (int i = searchFrom; i < searchTo; i++) {
            if (isPlausibleHpiHeader(raw, i)) {
                earliestSync = i;
                break;
            }
        }
        if (earliestSync > offset) {
            int syncStride = earliestSync - offset;
            // Pull stride earlier than LENGTH when next header is tightly packed
            // (H13 SPEECH: LENGTH→330 but next header at +328). Reject only if
            // the "next" header is impossibly short (< header+min body).
            if (syncStride < lengthBasedFrameLength && syncStride >= 8) {
                return syncStride;
            }
        }
        if (offset + lengthBasedFrameLength > raw.length) {
            return Math.max(1, raw.length - offset);
        }
        return lengthBasedFrameLength;
    }

